function escapeHTML(s) { if (s === null || s === undefined) return ""; return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;"); }

// ─── Funciones de gestión de cursos ───────────────────────────────
function eliminarCurso(id) {
  const curso = calState.cursos[id];
  if (!curso) return;
  if (!confirm(`¿Eliminar el curso "${curso.nombre}" y todas sus calificaciones?`)) return;
  delete calState.cursos[id];
  if (calState.cursoActivoId === id) {
    const ids = Object.keys(calState.cursos);
    calState.cursoActivoId = ids.length ? ids[0] : null;
  }
  guardarCalificaciones();
  renderizarCalificaciones();
  registrarCambio(`Curso eliminado: "${curso.nombre}"`);
  mostrarToast(`Curso eliminado`, 'success');
}

// ─── Funciones de estudiantes ─────────────────────────────────────
function agregarEstudiantes() {
  const raw = document.getElementById('input-estudiantes')?.value || '';
  const nombres = raw.split('\n').map(n => n.trim()).filter(n => n.length > 0);
  if (!nombres.length) { mostrarToast('Escribe al menos un nombre', 'error'); return; }
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) { mostrarToast('Selecciona un curso primero', 'error'); return; }
  if (!curso.estudiantes) curso.estudiantes = [];
  nombres.forEach(nombre => {
    curso.estudiantes.push({ id: uid(), nombre });
  });
  guardarCalificaciones();
  if (document.getElementById('input-estudiantes'))
    document.getElementById('input-estudiantes').value = '';
  renderizarTablaCalificaciones();
  registrarCambio(`${nombres.length} estudiante(s) agregado(s) al curso "${curso.nombre}": ${nombres.slice(0, 3).join(', ')}${nombres.length > 3 ? '...' : ''}`);
  mostrarToast(`${nombres.length} estudiante(s) agregado(s)`, 'info');
}

function importarAlumnosCSV(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    const texto = e.target.result;
    const lineas = texto.split(/\r?\n/).map(l => l.trim()).filter(l => l.length > 0);
    const nombres = lineas.map(l => {
      const partes = l.split(/[,;]/);
      return partes[0].replace(/^"+|"+$/g, '').trim();
    }).filter(n => n.length > 0);
    const cabeceras = ['nombre', 'alumno', 'estudiante', 'name', 'student'];
    const inicio = cabeceras.includes((nombres[0] || '').toLowerCase()) ? 1 : 0;
    const nombresFinales = nombres.slice(inicio);
    if (!nombresFinales.length) { mostrarToast('No se encontraron nombres en el archivo', 'error'); return; }
    document.getElementById('input-estudiantes').value = nombresFinales.join('\n');
    agregarEstudiantes();
    input.value = '';
  };
  reader.readAsText(file, 'UTF-8');
}

function exportarAlumnosCSV() {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !curso.estudiantes?.length) { mostrarToast('No hay estudiantes en este curso', 'error'); return; }

  const planActiva = _getPlanActivaDeCurso();
  const raKey = planActiva ? _getRaKey() : null;
  const actividades = planActiva?.actividades?.filter(a => !a.esComplementario) || [];
  const raInfo = raKey ? curso.ras?.[raKey] : null;

  let csv, filename;

  if (raKey && actividades.length && raInfo) {
    // Exportar con notas del RA activo
    const dg = planActiva.datosGenerales || {};
    const ra = planActiva.ra || {};
    const raLabel = ra.descripcion || [dg.moduloFormativo, ra.resultado].filter(Boolean).join(' · ') || raKey;

    // Encabezados: Nombre, RA, Act X.X.1, Act X.X.2, ..., Total RA
    const ecCounters = {};
    const actHeaders = actividades.map(a => {
      const ecBase = a.ecCodigo
        ? a.ecCodigo.replace(/^E\.C\./i, '').replace(/^EC/i, '').trim()
        : '?';
      ecCounters[ecBase] = (ecCounters[ecBase] || 0) + 1;
      const actLabel = 'Act ' + ecBase + '.' + ecCounters[ecBase];
      const max = raInfo.valores?.[a.id] ?? '';
      return '"' + (actLabel + (max !== '' ? ' (' + max + 'pts)' : '')).replace(/"/g, '""') + '"';
    });
    const header = ['"Nombre"', '"RA"', ...actHeaders, '"Total RA"', '"Valor máximo RA"'].join(',');

    const filas = curso.estudiantes.map(est => {
      const notasEst = curso.notas?.[est.id]?.[raKey] || {};
      const actNotas = actividades.map(a => {
        const n = notasEst[a.id];
        return (n !== undefined && n !== null) ? n : '';
      });
      const total = _calcNotaRA(curso, est.id, raKey, actividades);
      return [
        '"' + est.nombre.replace(/"/g, '""') + '"',
        '"' + raLabel.replace(/"/g, '""') + '"',
        ...actNotas,
        total !== null ? total : '',
        raInfo.valorTotal ?? ''
      ].join(',');
    });

    csv = [header, ...filas].join('\n');
    filename = 'notas-' + (curso.nombre || 'curso').replace(/\s+/g, '_') + '-' + raKey + '.csv';
    mostrarToast('Notas del RA exportadas', 'success');
  } else {
    // Sin RA activo: solo nombres
    csv = 'Nombre\n' + curso.estudiantes.map(e => '"' + e.nombre.replace(/"/g, '""') + '"').join('\n');
    filename = 'alumnos-' + (curso.nombre || 'curso').replace(/\s+/g, '_') + '.csv';
    mostrarToast('Lista exportada', 'success');
  }

  const blob = new Blob(['\uFEFF' + csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url; a.download = filename;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

function eliminarEstudiante(estudianteId) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const est = curso.estudiantes.find(e => e.id === estudianteId);
  if (!est) return;
  if (!confirm(`¿Eliminar a "${est.nombre}"?`)) return;
  registrarCambio(`Estudiante eliminado: ${est.nombre}`);
  curso.estudiantes = curso.estudiantes.filter(e => e.id !== estudianteId);
  // Limpiar notas
  if (curso.notas && curso.notas[estudianteId]) delete curso.notas[estudianteId];
  guardarCalificaciones();
  renderizarTablaCalificaciones();
}

function _toggleEstMenu(e, estId) {
  e.stopPropagation();
  _cerrarEstMenus();
  const menuOrig = document.getElementById('est-menu-' + estId);
  if (!menuOrig) return;
  // Clonar menú y ponerlo en body para que quede encima de todo
  const menu = menuOrig.cloneNode(true);
  menu.id = 'est-menu-flotante';
  menu.style.display = 'flex';
  // Cerrar el menú flotante al hacer clic en cualquier opción
  menu.querySelectorAll('button').forEach(btn => {
    btn.addEventListener('click', () => _cerrarEstMenus(), { once: true });
  });
  document.body.appendChild(menu);
  const btn = e.currentTarget;
  const rect = btn.getBoundingClientRect();
  let top = rect.bottom + 4;
  let left = rect.right - menu.offsetWidth;
  if (top + menu.offsetHeight > window.innerHeight) top = rect.top - menu.offsetHeight - 4;
  if (left < 8) left = 8;
  menu.style.top = top + 'px';
  menu.style.left = left + 'px';
}
function _cerrarEstMenus() {
  const f = document.getElementById('est-menu-flotante');
  if (f) f.remove();
}
document.addEventListener('click', function(e) {
  if (!e.target.closest('.est-overflow-wrap') && !e.target.closest('#est-menu-flotante')) {
    _cerrarEstMenus();
  }
});
// Cerrar al hacer scroll en la tabla
document.addEventListener('scroll', _cerrarEstMenus, true);

function _toggleNombreMobile(span) {
  if (window.innerWidth > 600) return; // Solo en móvil
  const td = span.closest('.td-nombre');
  if (!td) return;
  const wasExpanded = td.classList.contains('mobile-expanded');
  // Cerrar todos los demás expandidos
  document.querySelectorAll('.td-nombre.mobile-expanded').forEach(el => el.classList.remove('mobile-expanded'));
  if (!wasExpanded) td.classList.add('mobile-expanded');
}

function editarNombreEstudiante(estudianteId) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const est = curso.estudiantes.find(e => e.id === estudianteId);
  if (!est) return;
  const nombreAnterior = est.nombre;
  const nuevoNombre = prompt('Nuevo nombre:', est.nombre);
  if (!nuevoNombre || !nuevoNombre.trim()) return;
  est.nombre = nuevoNombre.trim();
  registrarCambio(`Nombre editado: "${nombreAnterior}" → "${est.nombre}"`);
  guardarCalificaciones();
  const el = document.getElementById('nombre-' + estudianteId);
  if (el) el.querySelector('span').textContent = est.nombre;
}

// ─── Helpers de notas ─────────────────────────────────────────────
function _clsNota(nota, max) {
  if (nota === null || nota === undefined) return '';
  const pct = max > 0 ? (nota / max) * 100 : 0;
  if (pct >= 70) return 'nota-aprobado';
  if (pct >= 60) return 'nota-regular';
  return 'nota-reprobado';
}

function _clsProm(prom) {
  if (prom === null || prom === undefined) return '';
  if (prom >= 70) return 'prom-aprobado';
  if (prom >= 60) return 'prom-regular';
  return 'prom-reprobado';
}

function _calcNotaRA(curso, estudianteId, raKey, actividadesVisibles) {
  const raInfo = curso.ras?.[raKey];
  if (!raInfo) return null;
  const notasEst = curso.notas?.[estudianteId]?.[raKey] || {};
  // Si se proveen las actividades visibles, usar solo esas IDs para evitar
  // contar notas huérfanas de actividades viejas/duplicadas que ya no existen
  const idsAUsar = actividadesVisibles ? actividadesVisibles.map(a => a.id) : raInfo.actividades;
  let total = 0, hayNotas = false;
  idsAUsar.forEach(actId => {
    const n = notasEst[actId];
    if (n !== undefined && n !== null) { total += n; hayNotas = true; }
  });
  return hayNotas ? Math.round(total * 10) / 10 : null;
}

function _calcNotaFinal(curso, estudianteId) {
  const rasKeys = Object.keys(curso.ras || {});
  if (!rasKeys.length) return null;
  let total = 0, hayNotas = false;
  rasKeys.forEach(rk => {
    const n = _calcNotaRA(curso, estudianteId, rk);
    if (n !== null) { total += n; hayNotas = true; }
  });
  return hayNotas ? Math.round(total * 10) / 10 : null;
}

function _promedioColRA(curso, raKey) {
  if (!curso.estudiantes?.length) return null;
  const notas = curso.estudiantes
    .map(e => _calcNotaRA(curso, e.id, raKey))
    .filter(n => n !== null);
  if (!notas.length) return null;
  return Math.round((notas.reduce((s, n) => s + n, 0) / notas.length) * 10) / 10;
}

function _promedioFinal(curso) {
  if (!curso.estudiantes?.length) return null;
  const notas = curso.estudiantes
    .map(e => _calcNotaFinal(curso, e.id))
    .filter(n => n !== null);
  if (!notas.length) return null;
  return Math.round((notas.reduce((s, n) => s + n, 0) / notas.length) * 10) / 10;
}

function _actualizarFilaRA(estudianteId, raKey) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  // Usar las actividades de la planificación activa para no contar notas huérfanas
  const planActiva = _getPlanActivaDeCurso();
  const actsVisibles = (planActiva?.actividades?.length ? planActiva.actividades : null);
  const notaRA = _calcNotaRA(curso, estudianteId, raKey, actsVisibles);
  const raInfo = curso.ras?.[raKey];
  const el = document.getElementById(`total-ra-${estudianteId}-${raKey}`);
  if (el) {
    el.textContent = notaRA !== null ? notaRA.toFixed(1) : '—';
    el.className = 'td-total-ra ' + _clsNota(notaRA, raInfo?.valorTotal || 100);
  }
  const notaFinal = _calcNotaFinal(curso, estudianteId);
  const elFinal = document.getElementById(`final-${estudianteId}`);
  if (elFinal) {
    elFinal.textContent = notaFinal !== null ? notaFinal.toFixed(1) : '—';
    elFinal.className = 'td-promedio ' + _clsProm(notaFinal);
  }
}

function _actualizarFooterRA(raKey) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  renderizarTablaCalificaciones(); // re-render completo del footer
}



