// ── Date picker de días de clase ──────────────────────────────────────
let _fpActIdx = null;
let _fpViewDate = null;
const _FP_MAPA_DIA = { domingo:0, lunes:1, martes:2, miercoles:3, jueves:4, viernes:5, sabado:6 };

function _fpGetClaseDow() {
  // 1. Buscar el nombre del curso vinculado a esta planificación via calState.cursos.planIds
  let nombreCurso = '';
  const planId = planificacion._id;
  if (planId && typeof calState !== 'undefined' && calState.cursos) {
    const curso = Object.values(calState.cursos).find(c => (c.planIds || []).includes(planId));
    if (curso) nombreCurso = curso.nombre;
  }

  // 2. Buscar en el horario real los días de esta materia + curso
  if (nombreCurso && typeof cargarHorario === 'function') {
    const horario = cargarHorario();
    let entradas = horario.filter(e => e.seccion === nombreCurso && e.materia);
    // Filtrar por materia de esta planificación si es posible
    const materia = ((planificacion.datosGenerales || {}).moduloFormativo || '').toLowerCase().trim();
    if (materia && entradas.length > 0) {
      const filtradas = entradas.filter(e => (e.materia || '').toLowerCase().includes(materia.substring(0, 20)));
      if (filtradas.length > 0) entradas = filtradas;
    }
    if (entradas.length > 0) {
      const dow = new Set();
      // e.dia: 0=Lunes … 4=Viernes → jsDay (getDay): Lu=1, Ma=2, Mi=3, Ju=4, Vi=5
      entradas.forEach(e => { if (typeof e.dia === 'number') dow.add(e.dia + 1); });
      if (dow.size > 0) return dow;
    }
  }

  // 3. Fallback: diasClase de datosGenerales (guardado en localStorage)
  const diasClase = (planificacion.datosGenerales || {}).diasClase || {};
  const dow = new Set();
  Object.entries(diasClase).forEach(([dia, cfg]) => {
    if (cfg && cfg.activo && _FP_MAPA_DIA[dia] !== undefined) dow.add(_FP_MAPA_DIA[dia]);
  });
  return dow;
}

function _fpParseIso(str) {
  if (!str) return null;
  const d = new Date(str + 'T12:00:00');
  return isNaN(d.getTime()) ? null : d;
}

function _abrirFechaPicker(actIdx, anchorEl) {
  _fpActIdx = actIdx;
  const act = planificacion.actividades[actIdx];
  const dg = planificacion.datosGenerales || {};

  // Centrar el mes: fecha de la actividad → fechaInicio del plan → hoy
  let base = _fpParseIso(act && act.fecha ? act.fecha : null)
          || _fpParseIso(dg.fechaInicio)
          || new Date();
  _fpViewDate = new Date(base.getFullYear(), base.getMonth(), 1);

  let popup = document.getElementById('_fp-popup');
  if (!popup) {
    popup = document.createElement('div');
    popup.id = '_fp-popup';
    popup.style.cssText = 'position:fixed;z-index:10000;background:#fff;border-radius:14px;box-shadow:0 8px 36px rgba(0,0,0,.2);padding:14px 14px 10px;width:268px;display:none;';
    document.body.appendChild(popup);
  }

  const rect = anchorEl.getBoundingClientRect();
  let top = rect.bottom + 6;
  let left = rect.left - 120;
  if (left < 8) left = 8;
  if (left + 268 > window.innerWidth - 8) left = window.innerWidth - 276;
  if (top + 310 > window.innerHeight) top = rect.top - 316;
  popup.style.top = top + 'px';
  popup.style.left = left + 'px';
  popup.style.display = 'block';

  _renderFpMes();

  const handler = function(e) {
    const p = document.getElementById('_fp-popup');
    if (!p || p.style.display === 'none') { document.removeEventListener('click', handler); return; }
    const path = e.composedPath ? e.composedPath() : [e.target];
    if (!path.includes(p) && !path.includes(anchorEl)) {
      p.style.display = 'none';
      document.removeEventListener('click', handler);
    }
  };
  setTimeout(() => document.addEventListener('click', handler), 50);
}

function _renderFpMes() {
  const popup = document.getElementById('_fp-popup');
  if (!popup || !_fpViewDate || isNaN(_fpViewDate.getTime())) return;
  const yr = _fpViewDate.getFullYear();
  const mo = _fpViewDate.getMonth();
  const dg = planificacion.datosGenerales || {};

  // Días de semana que son clases (desde diasClase — siempre disponible)
  const claseDow = _fpGetClaseDow();

  // Rango del semestre (opcional, para no destacar fuera del rango)
  const fechaIni = _fpParseIso(dg.fechaInicio);
  const fechaFin = _fpParseIso(dg.fechaTermino);

  // Fecha seleccionada actual
  const act = _fpActIdx !== null ? planificacion.actividades[_fpActIdx] : null;
  const sel = act && act.fecha ? act.fecha : null;

  const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  const dsem = ['Do','Lu','Ma','Mi','Ju','Vi','Sá'];
  const firstDow = new Date(yr, mo, 1).getDay();
  const diasEnMes = new Date(yr, mo + 1, 0).getDate();
  const hoy = new Date();
  const hoyStr = yr + '-' + String(mo+1).padStart(2,'0'); // solo para comparar mes

  let celdas = '';
  for (let i = 0; i < firstDow; i++) celdas += '<div></div>';
  for (let d = 1; d <= diasEnMes; d++) {
    const date = new Date(yr, mo, d);
    const dow = date.getDay();
    const ds = yr + '-' + String(mo+1).padStart(2,'0') + '-' + String(d).padStart(2,'0');
    const enRango = (!fechaIni || date >= fechaIni) && (!fechaFin || date <= fechaFin);
    const esClase = claseDow.has(dow);
    const esSel = ds === sel;
    const esHoy = date.toDateString() === hoy.toDateString();
    let st;
    if (esSel) {
      st = 'background:#1565C0;color:#fff;font-weight:700;';
    } else if (esClase) {
      st = 'background:#DBEAFE;color:#1565C0;font-weight:600;border:1.5px solid #93C5FD;';
    } else if (esHoy) {
      st = 'color:#E65100;font-weight:600;';
    } else {
      st = 'color:#9E9E9E;';
    }
    celdas += `<div onclick="_selFpDia('${ds}')" style="width:32px;height:32px;display:flex;align-items:center;justify-content:center;border-radius:50%;font-size:.8rem;margin:1px auto;cursor:pointer;${st}">${d}</div>`;
  }

  // Nombre de días de clase para el pie
  const nombDias = ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
  const diasLabel = [...claseDow].sort().map(n => nombDias[n]).join(', ');
  const planId2 = planificacion._id;
  let cursoLabel = '';
  if (planId2 && typeof calState !== 'undefined' && calState.cursos) {
    const c2 = Object.values(calState.cursos).find(c => (c.planIds || []).includes(planId2));
    if (c2) cursoLabel = c2.nombre;
  }

  popup.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
      <button onclick="_fpNav(-1)" style="background:none;border:none;cursor:pointer;padding:4px;border-radius:6px;color:#424242;display:flex;"><span class="material-icons" style="font-size:20px;">chevron_left</span></button>
      <span style="font-size:.87rem;font-weight:700;color:#1A1A2E;">${meses[mo]} ${yr}</span>
      <button onclick="_fpNav(1)" style="background:none;border:none;cursor:pointer;padding:4px;border-radius:6px;color:#424242;display:flex;"><span class="material-icons" style="font-size:20px;">chevron_right</span></button>
    </div>
    <div style="display:grid;grid-template-columns:repeat(7,1fr);text-align:center;margin-bottom:4px;">
      ${dsem.map(d => `<div style="font-size:.67rem;font-weight:700;color:#9E9E9E;padding:2px 0;">${d}</div>`).join('')}
    </div>
    <div style="display:grid;grid-template-columns:repeat(7,1fr);">${celdas}</div>
    <div style="margin-top:8px;border-top:1px solid #F0F4F8;padding-top:7px;font-size:.7rem;color:#757575;">
      ${cursoLabel ? `<div style="font-weight:700;color:#1565C0;margin-bottom:3px;">${_eHtml(cursoLabel)}</div>` : ''}
      <div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap;">
        <span style="width:11px;height:11px;background:#DBEAFE;border:1.5px solid #93C5FD;border-radius:50%;display:inline-block;flex-shrink:0;"></span>
        ${diasLabel || 'Días de clase'}
      </div>
    </div>`;
}

function _fpNav(dir) {
  if (!_fpViewDate) return;
  _fpViewDate = new Date(_fpViewDate.getFullYear(), _fpViewDate.getMonth() + dir, 1);
  _renderFpMes();
}

function _selFpDia(dateStr) {
  const input = document.querySelector(`.act-fecha-input[data-idx="${_fpActIdx}"]`);
  if (input) {
    input.value = dateStr;
    input.dispatchEvent(new Event('change', { bubbles: true }));
  }
  const popup = document.getElementById('_fp-popup');
  if (popup) popup.style.display = 'none';
  _fpActIdx = null;
}

function _actualizarResumenValores(listaActividades) {
  // Eliminar resumen anterior y su sub-label si existen
  document.getElementById('resumen-valores-act')?.remove();
  document.getElementById('resumen-ia-gen-label')?.remove();

  const tbody = document.getElementById('tabla-actividades-body');
  if (!tbody || !listaActividades || listaActividades.length === 0) return;

  const valorRA = parseFloat(planificacion?.datosGenerales?.valorRA) || 0;
  const sumaTotal = listaActividades.reduce((s, a) => s + (parseFloat(a.valor) || 0), 0);
  const sumRedondeada = Math.round(sumaTotal * 100) / 100;
  const diff = Math.round((sumRedondeada - valorRA) * 100) / 100;
  const excede = diff > 0;
  const falta = diff < 0;

  let color = '#2E7D32';
  let bgColor = '#E8F5E9';
  let borderColor = '#A5D6A7';
  let icon = 'check_circle';
  let mensaje = `Total asignado: ${sumRedondeada} / ${valorRA} pts — ✓ Correcto`;

  if (excede) {
    color = '#C62828';
    bgColor = '#FFEBEE';
    borderColor = '#EF9A9A';
    icon = 'error';
    mensaje = `Total asignado: ${sumRedondeada} / ${valorRA} pts — ¡Excede por ${Math.abs(diff)} pts!`;
  } else if (falta) {
    color = '#E65100';
    bgColor = '#FFF3E0';
    borderColor = '#FFE0B2';
    icon = 'warning';
    mensaje = `Total asignado: ${sumRedondeada} / ${valorRA} pts — Faltan ${Math.abs(diff)} pts`;
  }

  const totalActs = listaActividades.filter(a => !a.esComplementario).length;
  const totalComp = listaActividades.filter(a => a.esComplementario).length;
  const conteoLabel = `${totalActs} actividad${totalActs !== 1 ? 'es' : ''}${totalComp > 0 ? ` + ${totalComp} complementaria${totalComp !== 1 ? 's' : ''}` : ''}`;

  const divResumen = document.createElement('div');
  divResumen.id = 'resumen-valores-act';
  divResumen.style.cssText = `display:flex;align-items:center;gap:8px;padding:12px 16px;margin-top:12px;border-radius:10px;font-size:0.88rem;font-weight:600;background:${bgColor};color:${color};border:1.5px solid ${borderColor};flex-wrap:wrap;`;
  divResumen.innerHTML = `<span class="material-icons" style="font-size:20px;">${icon}</span> ${mensaje} <span style="margin-left:auto;font-size:0.8rem;font-weight:500;opacity:0.8;"><span class="material-icons" style="font-size:14px;vertical-align:middle;">assignment</span> ${conteoLabel}</span>`;

  // Insertar después de la tabla
  const tabla = tbody.closest('table');
  if (tabla && tabla.parentNode) {
    tabla.parentNode.insertBefore(divResumen, tabla.nextSibling);

    // Mostrar sub-label de origen de generación
    if (_iaProveedorLabel) {
      const esIA = _iaProveedorLabel !== 'local';
      const labelColor = esIA ? '#1565C0' : '#546E7A';
      const labelBg    = esIA ? '#E3F2FD' : '#ECEFF1';
      const labelBorde = esIA ? '#90CAF9' : '#CFD8DC';
      const labelIcono = esIA ? 'smart_toy' : 'code';
      const labelTexto = esIA
        ? `Generado con IA — <strong>${_iaProveedorLabel}</strong>`
        : 'Generado localmente (sin IA)';
      const subLabel = document.createElement('div');
      subLabel.id = 'resumen-ia-gen-label';
      subLabel.style.cssText = `display:flex;align-items:center;gap:6px;padding:5px 14px;border-radius:20px;font-size:0.75rem;font-weight:600;color:${labelColor};background:${labelBg};border:1.5px solid ${labelBorde};margin-top:6px;width:fit-content;`;
      subLabel.innerHTML = `<span class="material-icons" style="font-size:14px;">${labelIcono}</span> ${labelTexto}`;
      tabla.parentNode.insertBefore(subLabel, divResumen.nextSibling);
    }
  }
}

// Sincronizar valor de actividad desde la tabla de planificación → calificaciones
function _sincronizarValorActEnCalificaciones(act) {
  if (!act || !act.id) return;
  const nuevoValor = act.valor != null ? parseFloat(act.valor) : 0;
  let cambio = false;

  // Buscar en todos los cursos qué RA tienen esta actividad
  Object.values(calState?.cursos || {}).forEach(curso => {
    Object.values(curso.ras || {}).forEach(raInfo => {
      if (raInfo.valores && raInfo.actividades && raInfo.actividades.includes(act.id)) {
        if (raInfo.valores[act.id] !== nuevoValor) {
          raInfo.valores[act.id] = nuevoValor;
          cambio = true;
        }
      }
    });
  });

  if (cambio) {
    guardarCalificaciones();
  }
}

// Sincronizar valor de actividad desde calificaciones → planificación (biblioteca)
function _sincronizarValorCalifEnPlanificacion(actividadId, nuevoValor) {
  const curso = calState?.cursos?.[calState.cursoActivoId];
  if (!curso || !curso.planActivaId) return;
  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === curso.planActivaId);
  if (!reg || !reg.planificacion || !reg.planificacion.actividades) return;
  const act = reg.planificacion.actividades.find(a => a.id === actividadId);
  if (!act) return;
  if (act.valor === nuevoValor) return;
  act.valor = nuevoValor;
  persistirBiblioteca(biblio);
}

