    borrador: localStorage.getItem(STORAGE_KEY) || 'null',
    groqKey: localStorage.getItem(GROQ_KEY_STORAGE) || '',
    openrouterKey: localStorage.getItem(OPENROUTER_KEY_STORAGE) || '',
    notasDocente: localStorage.getItem(NOTAS_DOCENTE_KEY) || '',
