/** Rellena el selector de curso en Paso 1 y pre-selecciona el curso asignado */
function _mostrarCursoAsignado() {
  const grupo = document.getElementById('grupo-curso-asignado');
  const sel = document.getElementById('sel-curso-paso1');
  if (!grupo || !sel) return;

  const cursos = Object.values(calState.cursos || {});

  // Ocultar si no hay cursos creados
  if (cursos.length === 0) {
    grupo.style.display = 'none';
    return;
  }
  grupo.style.display = '';

  // Reconstruir opciones
  const valorActual = sel.value;
  sel.innerHTML = '<option value="">— Selecciona un curso —</option>';
  cursos.forEach(c => {
    const opt = document.createElement('option');
    opt.value = c.id;
    opt.textContent = c.nombre;
    sel.appendChild(opt);
  });

  // Pre-seleccionar el curso que ya tiene asignada esta planificación
  const planId = planificacion._id;
  if (planId) {
    const cursoAsignado = cursos.find(c => (c.planIds || []).includes(planId));
    if (cursoAsignado) {
      sel.value = cursoAsignado.id;
      return;
    }
  }
  // Restaurar selección previa si sigue siendo válida
  if (valorActual && cursos.some(c => c.id === valorActual)) {
    sel.value = valorActual;
  }
}

/** Mini-calendario que muestra los días de clase del curso seleccionado */
function _actualizarCalendarioDiasClase() {
  const contenedor = document.getElementById('dias-clase-calendario');
  if (!contenedor) return;

  const cursoId = document.getElementById('sel-curso-paso1')?.value;
  const curso = cursoId ? calState.cursos[cursoId] : null;
  const nombreCurso = curso?.nombre || '';

  if (!nombreCurso) { contenedor.style.display = 'none'; return; }

  const horario = cargarHorario();
  const entradasCurso = horario.filter(e => e.seccion === nombreCurso && e.materia);
  if (entradasCurso.length === 0) { contenedor.style.display = 'none'; return; }

  // Agrupar por materia → { materia: Set<dia> }
  const porMateria = {};
  entradasCurso.forEach(e => {
    if (!porMateria[e.materia]) porMateria[e.materia] = new Set();
    porMateria[e.materia].add(e.dia);
  });
  const materias = Object.keys(porMateria);

  // Paleta de colores por materia
  const PALETA = [
    { bg: '#E3F2FD', border: '#90CAF9', text: '#1565C0', dot: '#1565C0' },
    { bg: '#F3E5F5', border: '#CE93D8', text: '#6A1B9A', dot: '#6A1B9A' },
    { bg: '#E8F5E9', border: '#A5D6A7', text: '#2E7D32', dot: '#2E7D32' },
    { bg: '#FFF3E0', border: '#FFCC80', text: '#E65100', dot: '#E65100' },
    { bg: '#FCE4EC', border: '#F48FB1', text: '#AD1457', dot: '#AD1457' },
  ];
  const colorDe = {}; // materia → color objeto
  materias.forEach((m, i) => { colorDe[m] = PALETA[i % PALETA.length]; });

  // Mapa dia → [materias] (soporte multi-materia para días compartidos)
  const diaAMaterias = {}; // jsDay → [materia, ...]
  materias.forEach(m => {
    porMateria[m].forEach(d => {
      const jsDay = d + 1;
      if (!diaAMaterias[jsDay]) diaAMaterias[jsDay] = [];
      diaAMaterias[jsDay].push(m);
    });
  });

  const DIAS_SHORT_LABEL = ['Lu', 'Ma', 'Mi', 'Ju', 'Vi'];
  const diasSemana = ['Do', 'Lu', 'Ma', 'Mi', 'Ju', 'Vi', 'Sá'];
  const mesesNombres = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

  const fechaVal = document.getElementById('fecha-inicio')?.value;
  let base = fechaVal ? new Date(fechaVal + 'T12:00:00') : new Date();
  const anio = base.getFullYear();
  const mes = base.getMonth();
  const primerDia = new Date(anio, mes, 1).getDay();
  const totalDias = new Date(anio, mes + 1, 0).getDate();
  const hoyISO = new Date().toISOString().slice(0, 10);
  const selISO = fechaVal || '';

  // ── Leyenda por materia ──
  let html = `<div style="background:#F8F9FA;border:1px solid #E0E0E0;border-radius:10px;padding:10px 14px;font-size:0.78rem;">`;

  // Header del curso
  html += `<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;">
    <span class="material-icons" style="font-size:14px;color:#455A64;">calendar_today</span>
    <span style="font-weight:700;color:#37474F;">${escapeHTML(nombreCurso)}</span>
    <span style="color:#90A4AE;font-size:0.72rem;">— ${materias.length > 1 ? materias.length + ' materias' : '1 materia'}</span>
  </div>`;

  // Leyenda: una fila por materia
  materias.forEach(m => {
    const c = colorDe[m];
    const dias = [...porMateria[m]].sort().map(d => DIAS_SHORT_LABEL[d]).join(' · ');
    html += `<div style="display:flex;align-items:center;gap:6px;margin-bottom:5px;padding:4px 8px;background:${c.bg};border-left:3px solid ${c.dot};border-radius:6px;">
      <span style="font-weight:700;color:${c.text};flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${escapeHTML(m)}">${escapeHTML(m.length > 40 ? m.substring(0,40)+'…' : m)}</span>
      <span style="font-weight:700;color:${c.text};white-space:nowrap;font-size:0.75rem;">${dias}</span>
    </div>`;
  });

  // ── Mini calendario ──
  html += `<div style="font-weight:700;color:#455A64;text-align:center;margin:10px 0 6px;">${mesesNombres[mes]} ${anio}</div>`;
  html += `<div style="display:grid;grid-template-columns:repeat(7,1fr);gap:2px;text-align:center;">`;

  // Cabecera
  diasSemana.forEach((d, i) => {
    const mats = diaAMaterias[i] || [];
    if (mats.length === 0) {
      html += `<div style="font-size:0.68rem;font-weight:700;padding:2px 0;color:#B0BEC5;">${d}</div>`;
    } else if (mats.length === 1) {
      html += `<div style="font-size:0.68rem;font-weight:700;padding:2px 0;color:${colorDe[mats[0]].text};">${d}</div>`;
    } else {
      const c1 = colorDe[mats[0]], c2 = colorDe[mats[1]];
      html += `<div style="font-size:0.68rem;font-weight:700;padding:2px 0;background:linear-gradient(135deg,${c1.text} 50%,${c2.text} 50%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;">${d}</div>`;
    }
  });

  // Celdas vacías
  for (let i = 0; i < primerDia; i++) html += `<div></div>`;

  // Días del mes
  for (let dia = 1; dia <= totalDias; dia++) {
    const fecha = new Date(anio, mes, dia);
    const jsDay = fecha.getDay();
    const mats = diaAMaterias[jsDay] || [];
    const iso = fecha.toISOString().slice(0, 10);
    const esHoy = iso === hoyISO;
    const esSel = iso === selISO;

    let style;
    if (esSel) {
      style = `background:#1565C0;color:#fff;font-weight:700;border:none;`;
    } else if (esHoy) {
      style = `background:#E3F2FD;color:#1565C0;font-weight:700;border:1.5px solid #1565C0;`;
    } else if (mats.length >= 2) {
      const c1 = colorDe[mats[0]], c2 = colorDe[mats[1]];
      style = `background:linear-gradient(135deg,${c1.bg} 50%,${c2.bg} 50%);color:${c1.text};font-weight:700;border:1px solid ${c1.border};`;
    } else if (mats.length === 1) {
      const c = colorDe[mats[0]];
      style = `background:${c.bg};color:${c.text};font-weight:700;border:1px solid ${c.border};`;
    } else {
      style = `color:#CFD8DC;`;
    }

    html += `<div style="padding:3px 1px;border-radius:50%;font-size:0.72rem;${style}">${dia}</div>`;
  }

  html += `</div></div>`;
  contenedor.innerHTML = html;
  contenedor.style.display = '';
}

// ── Date picker de Datos Generales (multi-materia) ───────────────────
let _dgFpFieldId = null;
let _dgFpViewDate = null;
const _DG_PALETA = [
  { bg:'#E3F2FD', border:'#90CAF9', text:'#1565C0' },
  { bg:'#F3E5F5', border:'#CE93D8', text:'#6A1B9A' },
  { bg:'#E8F5E9', border:'#A5D6A7', text:'#2E7D32' },
  { bg:'#FFF3E0', border:'#FFCC80', text:'#E65100' },
  { bg:'#FCE4EC', border:'#F48FB1', text:'#AD1457' },
];

function _dgFpGetMaterias() {
  const cursoId = document.getElementById('sel-curso-paso1')?.value;
  const curso = cursoId && typeof calState !== 'undefined' ? calState.cursos?.[cursoId] : null;
  const nombreCurso = curso?.nombre || '';
  if (!nombreCurso || typeof cargarHorario !== 'function') return { materias:[], colorDe:{}, diaAMaterias:{} };
  const horario = cargarHorario();
  const entradas = horario.filter(e => e.seccion === nombreCurso && e.materia);
  const porMateria = {};
  entradas.forEach(e => {
    if (!porMateria[e.materia]) porMateria[e.materia] = new Set();
    porMateria[e.materia].add(e.dia);
  });
  const materias = Object.keys(porMateria);
  const colorDe = {};
  materias.forEach((m, i) => { colorDe[m] = _DG_PALETA[i % _DG_PALETA.length]; });
  const diaAMaterias = {};
  materias.forEach(m => {
    porMateria[m].forEach(d => {
      const jsDay = d + 1;
      if (!diaAMaterias[jsDay]) diaAMaterias[jsDay] = [];
      diaAMaterias[jsDay].push(m);
    });
  });
  return { materias, colorDe, diaAMaterias };
}

function _abrirDgFechaPicker(fieldId, anchorEl) {
  _dgFpFieldId = fieldId;
  const input = document.getElementById(fieldId);
  const val = input?.value;
  let base = val ? new Date(val + 'T12:00:00') : new Date();
  if (isNaN(base.getTime())) base = new Date();
  _dgFpViewDate = new Date(base.getFullYear(), base.getMonth(), 1);

  let popup = document.getElementById('_dg-fp-popup');
  if (!popup) {
    popup = document.createElement('div');
    popup.id = '_dg-fp-popup';
    popup.style.cssText = 'position:fixed;background:#fff;border:1.5px solid #90CAF9;border-radius:12px;box-shadow:0 4px 20px rgba(0,0,0,.15);padding:14px;z-index:9999;width:290px;';
    document.body.appendChild(popup);
  }
  const rect = anchorEl.getBoundingClientRect();
  let top = rect.bottom + 6, left = rect.left;
  if (left + 290 > window.innerWidth - 10) left = window.innerWidth - 300;
  if (top + 300 > window.innerHeight - 10) top = rect.top - 310;
  popup.style.top = top + 'px';
  popup.style.left = left + 'px';
  popup.style.display = 'block';
  _renderDgFpMes();

  const handler = function(e) {
    const p = document.getElementById('_dg-fp-popup');
    if (!p || p.style.display === 'none') { document.removeEventListener('click', handler); return; }
    const path = e.composedPath ? e.composedPath() : [e.target];
    if (!path.includes(p) && !path.includes(anchorEl)) {
      p.style.display = 'none';
      document.removeEventListener('click', handler);
    }
  };
  setTimeout(() => document.addEventListener('click', handler), 50);
}

function _renderDgFpMes() {
  const popup = document.getElementById('_dg-fp-popup');
  if (!popup || !_dgFpViewDate || isNaN(_dgFpViewDate.getTime())) return;
  const yr = _dgFpViewDate.getFullYear();
  const mo = _dgFpViewDate.getMonth();
  const { materias, colorDe, diaAMaterias } = _dgFpGetMaterias();
  const input = _dgFpFieldId ? document.getElementById(_dgFpFieldId) : null;
  const sel = input?.value || null;
  const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
  const dsem = ['Do','Lu','Ma','Mi','Ju','Vi','Sá'];
  const firstDow = new Date(yr, mo, 1).getDay();
  const diasEnMes = new Date(yr, mo + 1, 0).getDate();
  const hoy = new Date();

  // Cabecera días de semana con color por materia
  const cabecera = dsem.map((d, i) => {
    const mats = diaAMaterias[i] || [];
    if (mats.length === 0) return `<div style="font-size:.68rem;font-weight:700;padding:2px 0;color:#B0BEC5;">${d}</div>`;
    if (mats.length === 1) return `<div style="font-size:.68rem;font-weight:700;padding:2px 0;color:${colorDe[mats[0]].text};">${d}</div>`;
    const c1 = colorDe[mats[0]], c2 = colorDe[mats[1]];
    return `<div style="font-size:.68rem;font-weight:700;padding:2px 0;background:linear-gradient(135deg,${c1.text} 50%,${c2.text} 50%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;">${d}</div>`;
  }).join('');

  // Celdas del mes
  let celdas = '';
  for (let i = 0; i < firstDow; i++) celdas += '<div></div>';
  for (let d = 1; d <= diasEnMes; d++) {
    const date = new Date(yr, mo, d);
    const dow = date.getDay();
    const ds = yr + '-' + String(mo+1).padStart(2,'0') + '-' + String(d).padStart(2,'0');
    const esSel = ds === sel;
    const esHoy = date.toDateString() === hoy.toDateString();
    const mats = diaAMaterias[dow] || [];
    let st;
    if (esSel) {
      st = 'background:#1565C0;color:#fff;font-weight:700;';
    } else if (esHoy) {
      st = 'background:#E3F2FD;color:#1565C0;font-weight:700;border:1.5px solid #1565C0;';
    } else if (mats.length >= 2) {
      const c1 = colorDe[mats[0]], c2 = colorDe[mats[1]];
      st = `background:linear-gradient(135deg,${c1.bg} 50%,${c2.bg} 50%);color:${c1.text};font-weight:700;border:1px solid ${c1.border};`;
    } else if (mats.length === 1) {
      const c = colorDe[mats[0]];
      st = `background:${c.bg};color:${c.text};font-weight:700;border:1.5px solid ${c.border};`;
    } else {
      st = 'color:#9E9E9E;';
    }
    celdas += `<div onclick="_selDgFpDia('${ds}')" style="width:32px;height:32px;display:flex;align-items:center;justify-content:center;border-radius:50%;font-size:.8rem;margin:1px auto;cursor:pointer;${st}">${d}</div>`;
  }

  // Leyenda de materias
  let leyenda = materias.map(m => {
    const c = colorDe[m];
    return `<div style="display:flex;align-items:center;gap:5px;margin-top:4px;">
      <span style="width:10px;height:10px;background:${c.bg};border:1.5px solid ${c.border};border-radius:50%;flex-shrink:0;display:inline-block;"></span>
      <span style="font-size:.68rem;color:${c.text};font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="${_eHtml(m)}">${_eHtml(m.length>38?m.substring(0,38)+'…':m)}</span>
    </div>`;
  }).join('');

  popup.innerHTML = `
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;">
      <button onclick="_dgFpNav(-1)" style="background:none;border:none;cursor:pointer;padding:4px;border-radius:6px;color:#424242;display:flex;"><span class="material-icons" style="font-size:20px;">chevron_left</span></button>
      <span style="font-size:.87rem;font-weight:700;color:#1A1A2E;">${meses[mo]} ${yr}</span>
      <button onclick="_dgFpNav(1)" style="background:none;border:none;cursor:pointer;padding:4px;border-radius:6px;color:#424242;display:flex;"><span class="material-icons" style="font-size:20px;">chevron_right</span></button>
    </div>
    <div style="display:grid;grid-template-columns:repeat(7,1fr);text-align:center;margin-bottom:4px;">${cabecera}</div>
    <div style="display:grid;grid-template-columns:repeat(7,1fr);">${celdas}</div>
    ${leyenda ? `<div style="margin-top:8px;border-top:1px solid #F0F4F8;padding-top:7px;">${leyenda}</div>` : ''}`;
}

function _dgFpNav(dir) {
  if (!_dgFpViewDate) return;
  _dgFpViewDate = new Date(_dgFpViewDate.getFullYear(), _dgFpViewDate.getMonth() + dir, 1);
  _renderDgFpMes();
}

function _selDgFpDia(dateStr) {
  const input = _dgFpFieldId ? document.getElementById(_dgFpFieldId) : null;
  if (input) {
    input.value = dateStr;
    _actualizarDgFechaLabels();
    input.dispatchEvent(new Event('input', { bubbles: true }));
    input.dispatchEvent(new Event('change', { bubbles: true }));
  }
  const p = document.getElementById('_dg-fp-popup');
  if (p) p.style.display = 'none';
}

function _actualizarDgFechaLabels() {
  ['fecha-inicio', 'fecha-termino'].forEach(id => {
    const val = document.getElementById(id)?.value;
    const lbl = document.getElementById(id + '-label');
    if (lbl) lbl.textContent = val ? val.split('-').reverse().join('/') : '—';
  });
}

/** Llena los campos del formulario desde el estado restaurado */



function poblarFormularioDesdeEstado() {



  const dg = planificacion.datosGenerales;



  const ra = planificacion.ra;







  const setVal = (id, val) => { const el = document.getElementById(id); if (el) el.value = val != null ? val : ''; };







  setVal('familia-profesional', dg.familiaProfesional);



  setVal('codigo-fp', dg.codigoFP);



  setVal('nombre-bachillerato', dg.nombreBachillerato);



  setVal('codigo-titulo', dg.codigoTitulo);



  setVal('modulo-formativo', dg.moduloFormativo);



  setVal('codigo-modulo', dg.codigoModulo);



  setVal('nombre-docente', dg.nombreDocente);
  setVal('unidad-competencia', dg.unidadCompetencia);
  setVal('codigo-uc', dg.codigoUC);

  // Mostrar curso asignado si la planificación tiene _id
  _mostrarCursoAsignado();

  setVal('cantidad-ra', dg.cantidadRA);
  setVal('cantidad-ec', dg.cantidadEC || 4);
  setVal('cantidad-act-por-ec', dg.cantidadActPorEC || 1);

  setVal('valor-ra', dg.valorRA);

  // Renderizar tabla de priorización
  _renderTablaPriorizacion(parseInt(dg.cantidadRA) || 0, dg.priorizacion);



  setVal('horas-semana', dg.horasSemana);



  setVal('fecha-inicio', dg.fechaInicio);
  setVal('fecha-termino', dg.fechaTermino);
  _actualizarDgFechaLabels();



  setVal('descripcion-ra', ra.descripcion);



  setVal('criterios-referencia', ra.criterios);



  setVal('recursos-didacticos', ra.recursos);
  setVal('contenidos-conceptuales', ra.contenidosConceptuales);
  setVal('contenidos-procedimentales', ra.contenidosProcedimentales);
  setVal('contenidos-actitudinales', ra.contenidosActitudinales);
  // Mostrar sección contenidos si hay datos
  if (ra.contenidosConceptuales || ra.contenidosProcedimentales || ra.contenidosActitudinales) {
    const wrap = document.getElementById('contenidos-wrap');
    if (wrap) wrap.classList.remove('hidden');
  }





  // Restaurar días de clase



  if (dg.diasClase) {



    Object.entries(dg.diasClase).forEach(([dia, cfg]) => {



      const checkbox = document.getElementById('dia-' + dia);
      if (!checkbox) return;



      if (cfg.activo) {



        checkbox.checked = true;



        const wrap = document.getElementById('horas-' + dia + '-wrap');



        const horasInput = document.getElementById('horas-' + dia);



        if (wrap) wrap.classList.remove('hidden');



        if (horasInput) horasInput.value = cfg.horas;



        document.getElementById('dia-card-' + dia)?.classList.add('seleccionado');



      } else {

        checkbox.checked = false;

        const wrap = document.getElementById('horas-' + dia + '-wrap');
        if (wrap) wrap.classList.add('hidden');

        document.getElementById('dia-card-' + dia)?.classList.remove('seleccionado');

      }



    });



    actualizarResumenHoras();



  }







  // Detectar nivel Bloom en paso 2



  if (ra.descripcion) actualizarBloomBadge(ra.descripcion);







  // Habilitar botón siguiente del paso 2



  if (planificacion.elementosCapacidad?.length) {



    document.getElementById('btn-paso2-siguiente').disabled = false;



  }







  mostrarToast('Borrador restaurado correctamente', 'success');



}







/** Limpia todo y reinicia la app */



function nuevaPlanificacion() {
  if (!confirm('¿Deseas iniciar una nueva planificación? Se perderán los datos actuales.')) return;
  localStorage.removeItem(STORAGE_KEY);
  sessionStorage.setItem('planificador_goto', 'step1');
  location.reload();
}







// ================================================================



// --- SECCIÓN: UI ?" STEPPER Y NAVEGACIÓN ---



// ================================================================







let pasoActual = 1;



const TOTAL_PASOS = 6;







/**



 * Navega al paso indicado con validación opcional



 * @param {number} nuevoPaso



 * @param {boolean} validar - si debe validar el paso actual antes de avanzar



 */



function irAlPaso(nuevoPaso, validar = true) {



  if (validar && nuevoPaso > pasoActual) {



    if (!validarPasoActual()) return;



  }







  // Guardar datos del formulario al avanzar



  if (nuevoPaso > pasoActual || nuevoPaso === pasoActual) {



    guardarDatosFormulario();



  }







  // Si veníamos del paso 5 (Plan. Diaria en stepper), guardar y ocultar panel-diarias
  if (pasoActual === 5 && nuevoPaso !== 5) {
    guardarTodasDiarias();
    document.getElementById('panel-diarias')?.classList.add('hidden');
  }

  // PASO 5: Planificación Diaria → muestra panel-diarias inline dentro del stepper
  if (nuevoPaso === 5) {
    document.querySelectorAll('.step-section').forEach(s => s.classList.remove('active'));
    actualizarStepper(5);
    ['panel-calificaciones', 'panel-planificaciones', 'panel-dashboard', 'panel-horario', 'panel-tareas', 'panel-notas'].forEach(id => {
      document.getElementById(id)?.classList.add('hidden');
    });
    document.getElementById('panel-diarias')?.classList.remove('hidden');
    const navBtns = document.querySelector('#panel-diarias .nav-buttons');
    if (navBtns) navBtns.innerHTML = `
      <button class="btn-anterior" onclick="cerrarDiariasContextual()">
        <span class="material-icons">arrow_back</span> Anterior
      </button>
      <button class="btn-guardar-paso" onclick="guardarPlanificacionActual(true)">
        <span class="material-icons">save</span> Guardar
      </button>
      <button class="btn-siguiente" onclick="guardarTodasDiarias(); irAlPaso(6, false)">
        Ver Vista Previa <span class="material-icons">preview</span>
      </button>`;
    cargarDiarias();
    const tieneActividades = (planificacion.actividades || []).length > 0;
    _actualizarSelectorPlanDiarias(tieneActividades);
    renderizarDiarias();
    pasoActual = 5;
    guardarBorrador();
    window.scrollTo({ top: 0, behavior: 'smooth' });
    return;
  }

  // Actualizar secciones visibles
  document.querySelectorAll('.step-section').forEach(s => s.classList.remove('active'));



  const seccion = document.getElementById('section-' + nuevoPaso);



  if (seccion) seccion.classList.add('active');







  // Actualizar stepper visual



  actualizarStepper(nuevoPaso);







  // Acciones al entrar en pasos específicos
  if (nuevoPaso === 1) _mostrarCursoAsignado();
  if (nuevoPaso === 4) renderizarActividades(planificacion.actividades);
  if (nuevoPaso === 6) {
    renderizarVistaPrevia();
    // Auto-guardar en biblioteca al llegar a Vista Previa
    const dgCheck = planificacion.datosGenerales || {};
    const raCheck = planificacion.ra || {};
    if (dgCheck.moduloFormativo || raCheck.descripcion) {
      guardarPlanificacionActual(true); // silencioso: sin modal de curso
    }
  }







  pasoActual = nuevoPaso;

  // Autoguardar borrador al cambiar de paso
  guardarDatosFormulario();
  guardarBorrador();




  // Scroll al top



  window.scrollTo({ top: 0, behavior: 'smooth' });







  guardarBorrador();



}







/** Cierra Plan. Diaria de forma contextual: vuelve al paso 4 si estamos en el stepper, o al dashboard si no */
function cerrarDiariasContextual() {
  guardarTodasDiarias();
  if (pasoActual === 5) {
    irAlPaso(4, false);
  } else {
    abrirDashboard();
  }
}

/** Actualiza el estado visual del stepper */



function actualizarStepper(pasoActivo) {



  const steps = document.querySelectorAll('.step');



  const lines = document.querySelectorAll('.step-line');







  steps.forEach((step, idx) => {



    const numPaso = idx + 1;



    step.classList.remove('active', 'completed');



    if (numPaso < pasoActivo) step.classList.add('completed');



    if (numPaso === pasoActivo) step.classList.add('active');



  });







  lines.forEach((line, idx) => {



    line.classList.toggle('completed', idx + 1 < pasoActivo);



  });



}







