function guardarDatosFormulario() {



  const getVal = id => document.getElementById(id)?.value?.trim() || '';







  // Datos generales



  planificacion.datosGenerales = {



    familiaProfesional: getVal('familia-profesional'),



    codigoFP: getVal('codigo-fp'),



    nombreBachillerato: getVal('nombre-bachillerato'),



    codigoTitulo: getVal('codigo-titulo'),



    moduloFormativo: getVal('modulo-formativo'),



    codigoModulo: getVal('codigo-modulo'),



    nombreDocente: getVal('nombre-docente'),

    unidadCompetencia: getVal('unidad-competencia'),
    codigoUC: getVal('codigo-uc'),

    cantidadRA: getVal('cantidad-ra'),
    cantidadEC: getVal('cantidad-ec'),
    cantidadActPorEC: getVal('cantidad-act-por-ec'),
    valorRA: getVal('valor-ra'),



    horasSemana: getVal('horas-semana'),



    fechaInicio: getVal('fecha-inicio'),



    fechaTermino: getVal('fecha-termino'),



    diasClase: obtenerDiasClase(),
    priorizacion: _recogerPriorizacion()



  };







  // Datos del RA



  planificacion.ra = {



    descripcion: getVal('descripcion-ra'),



    criterios: getVal('criterios-referencia'),



    recursos: getVal('recursos-didacticos'),



    contenidosConceptuales: getVal('contenidos-conceptuales'),
    contenidosProcedimentales: getVal('contenidos-procedimentales'),
    contenidosActitudinales: getVal('contenidos-actitudinales'),

    nivelBloom: planificacion.ra?.nivelBloom || ''



  };



}







/** Extrae la configuración de días de clase del formulario */



/** Renderiza la tabla de priorización y ponderación de RA */
function _renderTablaPriorizacion(cantRA, datos) {
  const seccion = document.getElementById('seccion-priorizacion');
  const thead = document.getElementById('priorizacion-thead');
  const tbody = document.getElementById('priorizacion-tbody');
  if (!seccion || !thead || !tbody) return;

  cantRA = parseInt(cantRA) || 0;
  if (cantRA < 1) { seccion.style.display = 'none'; return; }
  seccion.style.display = '';

  const arr = datos || [];
  const headerStyle = 'padding:6px 10px;background:#D6E4F0;color:#1F3864;font-weight:700;text-align:center;border:1px solid #B0BEC5;font-size:0.82rem;';
  const labelStyle = 'padding:8px 12px;background:#ECEFF1;font-weight:700;font-size:0.9rem;border:1px solid #B0BEC5;';
  const cellStyle = 'padding:4px;border:1px solid #B0BEC5;text-align:center;';
  const inputStyle = 'width:100%;text-align:center;border:1px solid #CFD8DC;border-radius:4px;padding:6px 4px;font-size:0.85rem;box-sizing:border-box;';
  const totalStyle = 'padding:6px 10px;background:#D6E4F0;font-weight:700;text-align:center;border:1px solid #B0BEC5;font-size:0.85rem;';

  // Header
  let hdr = '<tr><th style="' + headerStyle + 'min-width:100px;">No. del RA</th>';
  for (let i = 1; i <= cantRA; i++) hdr += '<th style="' + headerStyle + '">RA' + i + '</th>';
  hdr += '<th style="' + headerStyle + '">Total</th></tr>';
  thead.innerHTML = hdr;

  // Tiempo row
  let trTiempo = '<tr><td style="' + labelStyle + '">Tiempo</td>';
  for (let i = 0; i < cantRA; i++) {
    const val = (arr[i] && arr[i].tiempo) || '';
    trTiempo += '<td style="' + cellStyle + '"><input type="text" class="prio-tiempo" data-idx="' + i + '" value="' + (val || '').toString().replace(/"/g, '&quot;') + '" placeholder="Ej: 3 Sem." style="' + inputStyle + '"></td>';
  }
  trTiempo += '<td id="prio-total-tiempo" style="' + totalStyle + '">—</td></tr>';

  // Valor row
  let trValor = '<tr><td style="' + labelStyle + '">Valor</td>';
  for (let i = 0; i < cantRA; i++) {
    const val = (arr[i] && arr[i].valor) || '';
    trValor += '<td style="' + cellStyle + '"><input type="number" class="prio-valor" data-idx="' + i + '" value="' + (val || '') + '" placeholder="Ej: 10" min="0" max="100" style="' + inputStyle + '"></td>';
  }
  trValor += '<td id="prio-total-valor" style="' + totalStyle + '">—</td></tr>';

  tbody.innerHTML = trTiempo + trValor;

  // Recalcular totales en tiempo real
  tbody.querySelectorAll('.prio-valor').forEach(inp => inp.addEventListener('input', _calcTotalesPriorizacion));
  tbody.querySelectorAll('.prio-tiempo').forEach(inp => inp.addEventListener('input', _calcTotalesPriorizacion));
  _calcTotalesPriorizacion();
}

function _calcTotalesPriorizacion() {
  // Total valor
  let totalVal = 0;
  document.querySelectorAll('.prio-valor').forEach(inp => { totalVal += parseFloat(inp.value) || 0; });
  const tdVal = document.getElementById('prio-total-valor');
  if (tdVal) tdVal.textContent = totalVal || '—';

  // Total tiempo (concatenar o sumar si son numéricos)
  let totalTiempo = 0;
  let allNumeric = true;
  document.querySelectorAll('.prio-tiempo').forEach(inp => {
    const v = inp.value.trim();
    const n = parseFloat(v);
    if (v && isNaN(n)) allNumeric = false;
    else totalTiempo += n || 0;
  });
  const tdTiempo = document.getElementById('prio-total-tiempo');
  if (tdTiempo) tdTiempo.textContent = allNumeric && totalTiempo ? totalTiempo : '—';
}

/** Recoge los datos de la tabla de priorización */
function _recogerPriorizacion() {
  const result = [];
  const tiempos = document.querySelectorAll('.prio-tiempo');
  const valores = document.querySelectorAll('.prio-valor');
  for (let i = 0; i < tiempos.length; i++) {
    result.push({
      tiempo: tiempos[i]?.value?.trim() || '',
      valor: valores[i]?.value?.trim() || ''
    });
  }
  return result.length ? result : undefined;
}

function obtenerDiasClase() {



  const dias = ['lunes', 'martes', 'miercoles', 'jueves', 'viernes'];



  const config = {};



  dias.forEach(d => {



    const checkbox = document.getElementById('dia-' + d);



    const horas = document.getElementById('horas-' + d);



    config[d] = {



      activo: checkbox?.checked || false,



      horas: parseInt(horas?.value || '2', 10)



    };



  });



  return config;



}







// ================================================================



// --- SECCIÓN: ORQUESTADOR PRINCIPAL ?" GENERAR PLANIFICACIÓN ---



// ================================================================







/**



 * Función principal: recolecta datos, genera EC, actividades e instrumentos



 */



let _generandoPlanificacion = false;
function generarPlanificacion() {
  if (_generandoPlanificacion) { mostrarToast('Ya hay una generación en curso, espera...', 'warning'); return; }
  _generandoPlanificacion = true;

  // Validar paso 2



  const raTexto = document.getElementById('descripcion-ra').value.trim();



  if (raTexto.length < 20) {



    document.getElementById('descripcion-ra').classList.add('error');
    mostrarToast('Escribe una descripción más completa del RA', 'error');
    _generandoPlanificacion = false;
    return;



  }







  // Animación de carga



  const btn = document.getElementById('btn-generar');



  const txt = document.getElementById('btn-generar-texto');



  const ico = btn.querySelector('.btn-generar-icon');



  btn.disabled = true;



  btn.classList.add('loading');



  ico.textContent = 'cached';



  txt.textContent = 'Generando...';







  // Guardar datos antes de procesar



  guardarDatosFormulario();







  setTimeout(() => {



    try {



      const dg = planificacion.datosGenerales;



      const ra = planificacion.ra;







      // 1. Detectar nivel Bloom del RA



      const nivelRA = analizarNivelBloom(ra.descripcion);



      planificacion.ra.nivelBloom = nivelRA;



      actualizarBloomBadge(ra.descripcion);







      // 2. Calcular fechas de clase reales



      planificacion.fechasClase = calcularFechasClase(



        dg.diasClase, dg.fechaInicio, dg.fechaTermino,
        typeof _calEscGetFestivosAdmin === 'function' ? _calEscGetFestivosAdmin() : []



      );







      // 3. Calcular horas totales y semanas



      planificacion.horasTotal = planificacion.fechasClase.reduce((s, f) => s + f.horas, 0);



      planificacion.semanas = calcularSemanas(dg.fechaInicio, dg.fechaTermino);

      // Mostrar nota de festivos excluidos
      _mostrarNotaFestivosExcluidos(dg.diasClase, dg.fechaInicio, dg.fechaTermino);






      // 4. Generar EC



      const _cantEC = parseInt(dg.cantidadEC) || 4;
      const _cantActPorEC = parseInt(dg.cantidadActPorEC) || 1;
      let ec = generarElementosCapacidad(ra.descripcion, ra.criterios, dg, _cantEC);







      planificacion.elementosCapacidad = ec;





      // 6. Generar actividades con fechas reales
      // Preservar IDs anteriores por posición y EC para no perder diarias guardadas
      const _actsAnteriores = planificacion.actividades || [];
      planificacion.actividades = generarActividades(ec, planificacion.fechasClase, _cantActPorEC);
      // Reasignar IDs previos según EC + posición para mantener vínculo con estadoDiarias
      const _idxPorEC = {};
      planificacion.actividades.forEach(a => {
        const k = a.ecCodigo || '';
        _idxPorEC[k] = (_idxPorEC[k] || 0);
        const pos = _idxPorEC[k]++;
        const anterior = _actsAnteriores.filter(x => x.ecCodigo === k)[pos];
        if (anterior && anterior.id) a.id = anterior.id;
      });

      // 5b. Distribuir horas por EC según actividades × horas por sesión
      const _diasAct = Object.values(dg.diasClase || {}).filter(d => d.activo);
      const _hPS = _diasAct.length > 0
        ? _diasAct.reduce((s, d) => s + d.horas, 0) / _diasAct.length
        : 2;
      ec.forEach(e => {
        const numActs = planificacion.actividades.filter(a => a.ecCodigo === e.codigo).length;
        e.horasAsignadas = Math.round(numActs * _hPS);
      });




      // 7. Renderizar UI



      renderizarEC(ec);



      renderizarActividades(planificacion.actividades);







      // 8. Habilitar navegación



      document.getElementById('btn-paso2-siguiente').disabled = false;







      // 9. Guardar borrador



      guardarBorrador();







      registrarCambio(`Planificación generada: "${planificacion.dg?.moduloFormativo || 'Sin módulo'}" — ${planificacion.elementosCapacidad?.length || 0} EC(s), ${planificacion.actividades?.length || 0} actividades`);
      mostrarToast('¡Planificación generada exitosamente!', 'success');







    } catch (e) {



      console.error('Error generando planificación:', e);



      mostrarToast('Ocurrió un error al generar. Revisa los datos ingresados.', 'error');



    } finally {



      btn.disabled = false;



      btn.classList.remove('loading');



      ico.textContent = 'auto_awesome';



      txt.textContent = 'Generar Planificación';

      _generandoPlanificacion = false;

    }



  }, 900); // pequeño delay para mostrar animación



}







// ================================================================



// --- SECCIÓN: UI ?" HELPERS ---



// ================================================================







/** Muestra/actualiza el badge de nivel Bloom detectado */



function actualizarBloomBadge(textoRA) {



  const badge = document.getElementById('nivel-bloom-detectado');



  const wrap = document.getElementById('bloom-badge-wrap');
  if (!textoRA || textoRA.length < 5) { if (wrap) wrap.classList.add('hidden'); badge.classList.add('hidden'); return; }







  const nivel = analizarNivelBloom(textoRA);



  const info = {



    conocimiento: { label: 'Nivel Bloom Detectado: Conocimiento', color: '#1565C0', bg: '#E3F2FD' },



    comprension: { label: 'Nivel Bloom Detectado: Comprensión', color: '#2E7D32', bg: '#E8F5E9' },



    aplicacion: { label: 'Nivel Bloom Detectado: Aplicación', color: '#E65100', bg: '#FFF3E0' },



    actitudinal: { label: 'Nivel Bloom Detectado: Actitudinal', color: '#6A1B9A', bg: '#F3E5F5' }



  }[nivel];







  badge.textContent = info.label;



  badge.style.color = info.color;
  badge.style.background = info.bg;
  badge.style.border = `1px solid ${info.color}33`;
  badge.classList.remove('hidden');
  const wrap2 = document.getElementById('bloom-badge-wrap');
  if (wrap2) { wrap2.classList.remove('hidden'); wrap2.style.display = 'flex'; }
  const sel = document.getElementById('bloom-selector');
  if (sel) sel.value = nivel;
  planificacion.ra.nivelBloom = nivel;
}

function toggleBloomSelector() {
  const sel = document.getElementById('bloom-selector');
  if (!sel) return;
  sel.style.display = sel.style.display === 'none' ? 'inline-block' : 'none';
}

function cambiarNivelBloomManual(nivel) {
  const colores = {
    conocimiento: { label: 'Nivel Bloom: Conocimiento', color: '#1565C0', bg: '#E3F2FD' },
    comprension:  { label: 'Nivel Bloom: Comprensión',  color: '#2E7D32', bg: '#E8F5E9' },
    aplicacion:   { label: 'Nivel Bloom: Aplicación',   color: '#E65100', bg: '#FFF3E0' },
    analisis:     { label: 'Nivel Bloom: Análisis',     color: '#00695C', bg: '#E0F2F1' },
    sintesis:     { label: 'Nivel Bloom: Síntesis',     color: '#4527A0', bg: '#EDE7F6' },
    evaluacion:   { label: 'Nivel Bloom: Evaluación',   color: '#AD1457', bg: '#FCE4EC' },
    actitudinal:  { label: 'Nivel Bloom: Actitudinal',  color: '#6A1B9A', bg: '#F3E5F5' }
  };
  const inf = colores[nivel]; if (!inf) return;
  const b = document.getElementById('nivel-bloom-detectado');
  if (b) { b.textContent = inf.label; b.style.color = inf.color; b.style.background = inf.bg; b.style.border = `1px solid ${inf.color}33`; }
  planificacion.ra.nivelBloom = nivel;
  const sel = document.getElementById('bloom-selector');
  if (sel) sel.style.display = 'none';
  guardarBorrador();
}







/** Actualiza el resumen de horas calculadas en paso 1 */



function actualizarResumenHoras() {



  const horasSemana = parseInt(document.getElementById('horas-semana')?.value || '0', 10);



  const fechaInicio = document.getElementById('fecha-inicio')?.value;



  const fechaFin = document.getElementById('fecha-termino')?.value;







  if (!fechaInicio || !fechaFin || !horasSemana) return;







  const sem = calcularSemanas(fechaInicio, fechaFin);



  if (sem <= 0) return;







  const totalH = horasSemana * sem;



  const resumen = document.getElementById('resumen-horas');



  const texto = document.getElementById('resumen-horas-texto');



  if (!resumen || !texto) return;







  texto.textContent = `Aprox. ${sem} semanas · ${totalH} horas totales estimadas`;



  resumen.classList.remove('hidden');



}







