// ════════════════════════════════════════════════════════════════════
// BITÁCORA DE CAMBIOS
// ════════════════════════════════════════════════════════════════════
const BITACORA_KEY = 'planificadorRA_bitacora_v1';
let _auditLastMsg  = '';
let _auditLastTime = 0;

function registrarCambio(mensaje) {
  try {
    // Deduplicar: mismo mensaje dentro de 600 ms → ignorar
    const ahora = Date.now();
    if (mensaje === _auditLastMsg && ahora - _auditLastTime < 600) return;
    _auditLastMsg  = mensaje;
    _auditLastTime = ahora;

    const log = JSON.parse(localStorage.getItem(BITACORA_KEY) || '[]');
    log.push({
      fecha: new Date().toISOString(),
      accion: mensaje
    });
    // Limitar a 500 entradas
    if (log.length > 500) log.splice(0, log.length - 500);
    localStorage.setItem(BITACORA_KEY, JSON.stringify(log));
    if (window._syncFirebase) _syncFirebase('bitacora', JSON.stringify(log));
  } catch (e) { /* silenciar errores de storage */ }
}

function exportarBitacora() {
  const log = JSON.parse(localStorage.getItem(BITACORA_KEY) || '[]');
  if (!log.length) {
    mostrarToast('No hay cambios registrados aún', 'info');
    return;
  }
  const lineas = [
    '═══════════════════════════════════════════════════════════',
    '  BITÁCORA DE CAMBIOS — El Gran Planificador Educativo',
    '  Exportado: ' + new Date().toLocaleString('es-DO'),
    '  Total de registros: ' + log.length,
    '═══════════════════════════════════════════════════════════',
    ''
  ];
  // Agrupar por día
  let diaActual = '';
  log.forEach(entry => {
    const d = new Date(entry.fecha);
    const dia = d.toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
    if (dia !== diaActual) {
      diaActual = dia;
      lineas.push('───────────────────────────────────────');
      lineas.push('  📅 ' + dia);
      lineas.push('───────────────────────────────────────');
    }
    const hora = d.toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
    lineas.push('  [' + hora + ']  ' + entry.accion);
  });
  lineas.push('');
  lineas.push('═══════════════════════════════════════════════════════════');
  lineas.push('  Fin de la bitácora');
  lineas.push('═══════════════════════════════════════════════════════════');

  const texto = lineas.join('\n');
  const blob = new Blob([texto], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'bitacora-cambios-' + new Date().toISOString().slice(0, 10) + '.txt';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);
  mostrarToast('Bitácora descargada ✓', 'success');
}

// ════════════════════════════════════════════════════════════════════
// AUDITORÍA — Panel de actividad
// ════════════════════════════════════════════════════════════════════
function abrirAuditoria() {
  _mostrarPanel('panel-auditoria');
  // Defaults: hoy como hasta, hace 30 días como desde
  const hoy = new Date().toISOString().slice(0, 10);
  const hace30 = new Date(Date.now() - 30 * 24 * 3600 * 1000).toISOString().slice(0, 10);
  const desde = document.getElementById('audit-fecha-desde');
  const hasta = document.getElementById('audit-fecha-hasta');
  if (desde && !desde.value) desde.value = hace30;
  if (hasta && !hasta.value) hasta.value = hoy;
  renderizarAuditoria();
}

function renderizarAuditoria() {
  const log = JSON.parse(localStorage.getItem(BITACORA_KEY) || '[]');
  const desde = document.getElementById('audit-fecha-desde')?.value;
  const hasta = document.getElementById('audit-fecha-hasta')?.value;
  const buscar = (document.getElementById('audit-buscar')?.value || '').toLowerCase();

  let filtrado = log.filter(e => {
    const fecha = e.fecha.slice(0, 10);
    if (desde && fecha < desde) return false;
    if (hasta && fecha > hasta) return false;
    if (buscar && !e.accion.toLowerCase().includes(buscar)) return false;
    return true;
  }).reverse(); // más reciente primero

  // Stats
  const statsEl = document.getElementById('audit-stats');
  if (statsEl) {
    const bloqueos = filtrado.filter(e => e.accion.includes('bloqueada') || e.accion.includes('desbloqueada')).length;
    const logins   = filtrado.filter(e => e.accion.includes('Sesión iniciada') || e.accion.includes('Sesión cerrada')).length;
    const total    = filtrado.length;
    statsEl.innerHTML = [
      ['history', total + ' eventos', '#1565C0', '#E3F2FD'],
      ['lock', bloqueos + ' bloqueos', '#6A1B9A', '#F3E5F5'],
      ['login', logins + ' sesiones', '#1B5E20', '#E8F5E9'],
    ].map(([icon, label, color, bg]) =>
      `<span style="display:inline-flex;align-items:center;gap:5px;background:${bg};color:${color};
        border-radius:20px;padding:4px 12px;font-size:0.78rem;font-weight:700;">
        <span class="material-icons" style="font-size:14px;">${icon}</span>${label}</span>`
    ).join('');
  }

  const lista = document.getElementById('audit-lista');
  if (!lista) return;
  if (!filtrado.length) {
    lista.innerHTML = '<div style="text-align:center;padding:40px;color:#9E9E9E;font-size:0.85rem;">No hay actividad en este periodo</div>';
    return;
  }

  // Agrupar por día
  const grupos = {};
  filtrado.forEach(e => {
    const dia = e.fecha.slice(0, 10);
    if (!grupos[dia]) grupos[dia] = [];
    grupos[dia].push(e);
  });

  lista.innerHTML = Object.entries(grupos).map(([dia, entries]) => {
    const diaLabel = new Date(dia + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long' });
    const rows = entries.map(e => {
      const hora = new Date(e.fecha).toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit', second: '2-digit' });
      const { icon, color } = _auditIcono(e.accion);
      return `<div style="display:flex;align-items:flex-start;gap:10px;padding:8px 12px;border-bottom:1px solid #F5F5F5;">
        <span class="material-icons" style="font-size:16px;color:${color};flex-shrink:0;margin-top:1px;">${icon}</span>
        <div style="flex:1;min-width:0;">
          <div class="audit-entry-text" style="font-size:0.83rem;line-height:1.4;">${e.accion}</div>
          <div style="font-size:0.72rem;color:#9E9E9E;margin-top:2px;">${hora}</div>
        </div>
      </div>`;
    }).join('');
    return `<div style="margin-bottom:12px;background:#fff;border-radius:10px;border:1px solid #E0E0E0;overflow:hidden;">
      <div style="padding:8px 12px;background:#F5F5F5;font-size:0.75rem;font-weight:700;color:#546E7A;text-transform:capitalize;">${diaLabel}</div>
      ${rows}
    </div>`;
  }).join('');
}

function _auditIcono(accion) {
  if (accion.includes('bloqueada'))        return { icon: 'lock',             color: '#7B1FA2' };
  if (accion.includes('desbloqueada'))     return { icon: 'lock_open',        color: '#2E7D32' };
  if (accion.includes('Sesión iniciada'))  return { icon: 'login',            color: '#1565C0' };
  if (accion.includes('Sesión cerrada'))   return { icon: 'logout',           color: '#BF360C' };
  if (accion.includes('Sesión diaria'))    return { icon: 'today',            color: '#00695C' };
  if (accion.includes('Planificación generada')) return { icon: 'auto_awesome', color: '#AD1457' };
  if (accion.includes('Planificación eliminada')) return { icon: 'delete',    color: '#C62828' };
  if (accion.includes('Planificación'))    return { icon: 'description',      color: '#E65100' };
  if (accion.includes('Curso creado'))     return { icon: 'add_circle',       color: '#1565C0' };
  if (accion.includes('Curso eliminado'))  return { icon: 'delete',           color: '#C62828' };
  if (accion.includes('Tarea creada'))     return { icon: 'add_task',         color: '#2E7D32' };
  if (accion.includes('Tarea eliminada'))  return { icon: 'delete',           color: '#C62828' };
  if (accion.includes('Tarea entregada'))  return { icon: 'task_alt',         color: '#2E7D32' };
  if (accion.includes('Tarea no entregada')) return { icon: 'cancel',         color: '#C62828' };
  if (accion.includes('Tarea'))            return { icon: 'task',             color: '#1565C0' };
  if (accion.includes('estudiante'))       return { icon: 'person_add',       color: '#0277BD' };
  if (accion.includes('Estudiante'))       return { icon: 'person_remove',    color: '#C62828' };
  if (accion.includes('calificaci') || accion.includes('Nota registrada')) return { icon: 'grade', color: '#F57F17' };
  if (accion.includes('asistencia') || accion.includes('Asistencia')) return { icon: 'how_to_reg', color: '#00695C' };
  if (accion.includes('blog') || accion.includes('Blog') || accion.includes('Post')) return { icon: 'article', color: '#006064' };
  if (accion.includes('Backup') || accion.includes('backup') || accion.includes('restaurad')) return { icon: 'backup', color: '#E65100' };
  if (accion.includes('nota') || accion.includes('Nota')) return { icon: 'sticky_note_2', color: '#F9A825' };
  if (accion.includes('Reporte'))          return { icon: 'assessment',       color: '#6A1B9A' };
  if (accion.includes('presentación') || accion.includes('Presentación')) return { icon: 'cast_for_education', color: '#E65100' };
  if (accion.includes('config') || accion.includes('Modo'))  return { icon: 'settings', color: '#546E7A' };
  if (accion.includes('export') || accion.includes('descarg')) return { icon: 'download', color: '#1565C0' };
  if (accion.includes('Enlace') || accion.includes('enlace')) return { icon: 'link',      color: '#0277BD' };
  return { icon: 'radio_button_checked', color: '#9E9E9E' };
}

function limpiarAuditoria() {
  if (!confirm('¿Eliminar todo el historial de actividad? Esta acción no se puede deshacer.')) return;
  localStorage.setItem(BITACORA_KEY, '[]');
  if (window._syncFirebase) _syncFirebase('bitacora', '[]');
  renderizarAuditoria();
  mostrarToast('Historial eliminado', 'success');
}

// ════════════════════════════════════════════════════════════════════
// PANTALLA DE BLOQUEO — Inactividad automática
// ════════════════════════════════════════════════════════════════════
const INACTIVITY_MS        = 3 * 60 * 1000; // 3 minutos
const _LOCK_KEY            = 'tinclass_locked';
const _LAST_ACT_KEY        = 'tinclass_last_activity';
let _lastActivity          = Date.now();
let _pantallaBloqueada     = false;
let _inactivityInterval    = null;
let _lastActivityWriteTime = 0;
let _pinBuffer             = '';

function _iniciarVigilanciaInactividad() {
  ['mousemove', 'mousedown', 'keydown', 'scroll', 'touchstart', 'click'].forEach(ev => {
    document.addEventListener(ev, _resetActividad, { passive: true });
  });
  _inactivityInterval = setInterval(() => {
    if (!window.currentUser || _pantallaBloqueada) return;
    if (Date.now() - _lastActivity > INACTIVITY_MS) _bloquearPantalla();
  }, 15000); // verificar cada 15 s
}

function _resetActividad() {
  const now = Date.now();
  _lastActivity = now;
  // Persistir en sessionStorage con throttle de 5 s para no saturar escrituras
  if (now - _lastActivityWriteTime > 5000) {
    sessionStorage.setItem(_LAST_ACT_KEY, String(now));
    _lastActivityWriteTime = now;
  }
}

// Determina si al recargar la página la sesión debe estar bloqueada
function _debeBloquearsePorRefresco() {
  // Método 1: flag explícito guardado al bloquear
  if (sessionStorage.getItem(_LOCK_KEY) === '1') return true;
  // Método 2: el tiempo desde la última actividad registrada supera el umbral
  const lastAct = parseInt(sessionStorage.getItem(_LAST_ACT_KEY) || '0');
  return lastAct > 0 && (Date.now() - lastAct) > INACTIVITY_MS;
}

function _bloquearPantalla() {
  if (_pantallaBloqueada || !window.currentUser) return;
  _pantallaBloqueada = true;

  const user = window.currentUser;
  const inicial = (user.displayName || user.email || 'U')[0].toUpperCase();
  const nombre  = user.displayName || user.email?.split('@')[0] || '';

  const avatar = document.getElementById('lock-avatar');
  if (avatar) avatar.textContent = inicial;
  const username = document.getElementById('lock-username');
  if (username) username.textContent = nombre + ' · ' + (user.email || '');
  const lockTime = document.getElementById('lock-time');
  if (lockTime) {
    const ahora = new Date().toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit' });
    lockTime.textContent = 'Bloqueado a las ' + ahora + ' por inactividad';
  }

  const esGoogle = user.providerData?.some(p => p.providerId === 'google.com');
  const passSection   = document.getElementById('lock-pass-section');
  const googleSection = document.getElementById('lock-google-section');
  const pinSection    = document.getElementById('lock-pin-section');
  const hasPIN = !!localStorage.getItem('_tinclass_pin');

  if (hasPIN) {
    if (pinSection)    pinSection.style.display    = 'block';
    if (passSection)   passSection.style.display   = 'none';
    if (googleSection) googleSection.style.display = 'none';
    _pinBuffer = '';
    _actualizarPinDots();
  } else {
    if (pinSection)    pinSection.style.display    = 'none';
    if (passSection)   passSection.style.display   = esGoogle ? 'none' : 'block';
    if (googleSection) googleSection.style.display = esGoogle ? 'block' : 'none';
  }

  const input = document.getElementById('lock-pass-input');
  if (input) input.value = '';
  const err = document.getElementById('lock-error');
  if (err) err.textContent = '';

  document.getElementById('lock-overlay')?.classList.remove('hidden');
  if (!hasPIN) setTimeout(() => input?.focus(), 120);
  if (hasPIN) document.addEventListener('keydown', _lockPinKeyHandler);
  sessionStorage.setItem(_LOCK_KEY, '1');
  registrarCambio('Pantalla bloqueada por inactividad');
}

async function desbloquearPantalla() {
  const pass  = document.getElementById('lock-pass-input')?.value;
  const err   = document.getElementById('lock-error');
  const btn   = document.getElementById('lock-btn-unlock');
  if (!pass) { if (err) err.textContent = 'Ingresa tu contraseña.'; return; }

  if (btn) btn.disabled = true;
  try {
    const credential = firebase.auth.EmailAuthProvider.credential(window.currentUser.email, pass);
    await window.currentUser.reauthenticateWithCredential(credential);
    _completarDesbloqueo();
  } catch (e) {
    if (err) err.textContent = 'Contraseña incorrecta. Intenta de nuevo.';
    const input = document.getElementById('lock-pass-input');
    if (input) { input.value = ''; input.focus(); }
  }
  if (btn) btn.disabled = false;
}

async function _desbloquearConGoogle() {
  const err = document.getElementById('lock-error');
  try {
    const provider = new firebase.auth.GoogleAuthProvider();
    await window.currentUser.reauthenticateWithPopup(provider);
    _completarDesbloqueo();
  } catch (e) {
    if (e.code !== 'auth/popup-closed-by-user') {
      if (err) err.textContent = 'Error al verificar. Intenta de nuevo.';
    }
  }
}

function _completarDesbloqueo() {
  const now = Date.now();
  _pantallaBloqueada = false;
  _lastActivity = now;
  sessionStorage.removeItem(_LOCK_KEY);
  // Reiniciar el timestamp de actividad para que no vuelva a bloquear inmediatamente
  sessionStorage.setItem(_LAST_ACT_KEY, String(now));
  _lastActivityWriteTime = now;
  document.getElementById('lock-overlay')?.classList.add('hidden');
  document.removeEventListener('keydown', _lockPinKeyHandler);
  registrarCambio('Pantalla desbloqueada');
}

// ── Teclado para el PIN ─────────────────────────────────────────────────
function _lockPinKeyHandler(e) {
  if (!_pantallaBloqueada) return;
  const pinSection = document.getElementById('lock-pin-section');
  if (!pinSection || pinSection.style.display === 'none') return;
  if (e.key >= '0' && e.key <= '9') { e.preventDefault(); _lockPinDigito(e.key); }
  else if (e.key === 'Backspace')    { e.preventDefault(); _lockPinBorrar(); }
}

// ── PIN numérico de desbloqueo ──────────────────────────────────────────
function _lockPinDigito(d) {
  if (_pinBuffer.length >= 4) return;
  _pinBuffer += d;
  _actualizarPinDots();
  if (_pinBuffer.length === 4) setTimeout(_verificarLockPin, 150);
}

function _lockPinBorrar() {
  if (!_pinBuffer.length) return;
  _pinBuffer = _pinBuffer.slice(0, -1);
  _actualizarPinDots();
  const err = document.getElementById('lock-error');
  if (err) err.textContent = '';
}

function _actualizarPinDots() {
  for (let i = 0; i < 4; i++) {
    const dot = document.getElementById('pin-dot-' + i);
    if (dot) dot.classList.toggle('pin-dot-filled', i < _pinBuffer.length);
  }
}

function _verificarLockPin() {
  const pin = localStorage.getItem('_tinclass_pin');
  if (_pinBuffer === pin) {
    _pinBuffer = '';
    _actualizarPinDots();
    _completarDesbloqueo();
  } else {
    const err = document.getElementById('lock-error');
    if (err) err.textContent = 'PIN incorrecto. Intenta de nuevo.';
    const dotsEl = document.getElementById('lock-pin-dots');
    if (dotsEl) {
      dotsEl.classList.add('pin-shake');
      setTimeout(() => dotsEl.classList.remove('pin-shake'), 400);
    }
    _pinBuffer = '';
    setTimeout(_actualizarPinDots, 160);
  }
}

function _lockMostrarContrasena() {
  document.getElementById('lock-pin-section').style.display = 'none';
  const user = window.currentUser;
  const esGoogle = user?.providerData?.some(p => p.providerId === 'google.com');
  const passSection   = document.getElementById('lock-pass-section');
  const googleSection = document.getElementById('lock-google-section');
  if (passSection)   passSection.style.display   = esGoogle ? 'none' : 'block';
  if (googleSection) googleSection.style.display = esGoogle ? 'block' : 'none';
  setTimeout(() => document.getElementById('lock-pass-input')?.focus(), 60);
}

// ── Configurar PIN desde el modal de ajustes ────────────────────────────
function _cfgActualizarEstadoPin() {
  const pin = localStorage.getItem('_tinclass_pin');
  const statusEl  = document.getElementById('cfg-pin-status');
  const quitarRow = document.getElementById('cfg-pin-quitar-row');
  if (statusEl)  statusEl.textContent  = pin ? 'Activo — 4 dígitos configurados' : 'No configurado — se usará contraseña para desbloquear';
  if (quitarRow) quitarRow.style.display = pin ? 'block' : 'none';
}

function _cfgAbrirSetPin() {
  const form = document.getElementById('cfg-pin-form');
  if (form) form.style.display = 'block';
  const input = document.getElementById('cfg-pin-input');
  if (input) { input.value = ''; input.focus(); }
  const err = document.getElementById('cfg-pin-err');
  if (err) err.textContent = '';
}

function _cfgGuardarPin() {
  const val = document.getElementById('cfg-pin-input')?.value || '';
  const err = document.getElementById('cfg-pin-err');
  if (!/^\d{4}$/.test(val)) {
    if (err) err.textContent = 'El PIN debe tener exactamente 4 dígitos numéricos.';
    return;
  }
  localStorage.setItem('_tinclass_pin', val);
  if (window.currentUser) {
    db.collection('usuarios').doc(window.currentUser.uid)
      .set({ pin: val }, { merge: true })
      .catch(e => console.warn('Error guardando PIN en Firebase:', e));
  }
  document.getElementById('cfg-pin-form').style.display = 'none';
  _cfgActualizarEstadoPin();
  mostrarToast('PIN de bloqueo configurado', 'success');
}

function _cfgPinCancelar() {
  const form = document.getElementById('cfg-pin-form');
  if (form) form.style.display = 'none';
}

function _cfgQuitarPin() {
  if (!confirm('¿Quitar el PIN? Se usará la contraseña para desbloquear la pantalla.')) return;
  localStorage.removeItem('_tinclass_pin');
  if (window.currentUser) {
    db.collection('usuarios').doc(window.currentUser.uid)
      .set({ pin: firebase.firestore.FieldValue.delete() }, { merge: true })
      .catch(e => console.warn('Error eliminando PIN en Firebase:', e));
  }
  _cfgActualizarEstadoPin();
  mostrarToast('PIN eliminado', 'info');
}

function mostrarToast(mensaje, tipo = 'success') {



  const toast = document.getElementById('toast');



  const icono = document.getElementById('toast-icon');



  const texto = document.getElementById('toast-mensaje');







  const iconos = { success: 'check_circle', error: 'error', info: 'info' };



  icono.textContent = iconos[tipo] || 'info';



  texto.textContent = mensaje;



  toast.className = `toast toast-${tipo}`;







  // Mostrar



  requestAnimationFrame(() => { toast.classList.add('visible'); });







  // Registrar en bitácora las acciones exitosas
  if (tipo === 'success' && mensaje && !mensaje.includes('Bitácora descargada')) {
    registrarCambio(mensaje);
  }

  // Ocultar después de 3.5 segundos



  clearTimeout(toast._timer);



  toast._timer = setTimeout(() => { toast.classList.remove('visible'); }, 3500);



}







