// MÓDULO: LIBRETA / AGENDA VIRTUAL
// ════════════════════════════════════════════════════════════════════
const LIBRETA_KEY = 'planificadorRA_libreta_v1';
let _libretaDiaSeleccionado = null;

function cargarLibreta() {
  try { return JSON.parse(localStorage.getItem(LIBRETA_KEY) || '{"entries":[]}'); } catch { return { entries: [] }; }
}

function _guardarLibreta(data) {
  localStorage.setItem(LIBRETA_KEY, JSON.stringify(data));
  if (window._syncFirebase) _syncFirebase('libreta', data);
}

function abrirLibreta() {
  _mostrarPanel('panel-libreta');
  _libretaDiaSeleccionado = new Date().toISOString().split('T')[0];
  renderizarLibreta();
}

function cerrarLibreta() { abrirDashboard(); }

function renderizarLibreta() {
  _renderizarListaDiasLibreta();
  _renderizarEntradasDia(_libretaDiaSeleccionado);
}

function _libretaFechaLabel(fechaISO) {
  const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
  const ayer = new Date(hoy); ayer.setDate(hoy.getDate() - 1);
  const d = new Date(fechaISO + 'T12:00:00'); d.setHours(0, 0, 0, 0);
  if (d.getTime() === hoy.getTime()) return 'Hoy';
  if (d.getTime() === ayer.getTime()) return 'Ayer';
  return d.toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short' });
}

function _seleccionarDiaLibreta(fecha) {
  _libretaDiaSeleccionado = fecha;
  renderizarLibreta();
}

function _renderizarListaDiasLibreta() {
  const cont = document.getElementById('libreta-lista-dias');
  if (!cont) return;
  const data = cargarLibreta();
  const diasMap = {};
  data.entries.forEach(e => {
    if (!diasMap[e.fecha]) diasMap[e.fecha] = [];
    diasMap[e.fecha].push(e);
  });
  const hoy = new Date().toISOString().split('T')[0];
  const fechas = Object.keys(diasMap).sort((a, b) => b.localeCompare(a));
  if (!diasMap[hoy]) fechas.unshift(hoy);

  cont.innerHTML = fechas.map(fecha => {
    const entries = diasMap[fecha] || [];
    const activo = fecha === _libretaDiaSeleccionado;
    const preview = entries[0]?.titulo || (entries[0]?.texto || '').substring(0, 40) || '—';
    return `<div onclick="_seleccionarDiaLibreta('${fecha}')" style="
        padding:12px 14px;cursor:pointer;border-bottom:1px solid #E0E0E0;
        background:${activo ? '#E0F2F1' : 'transparent'};
        border-left:3px solid ${activo ? '#00695C' : 'transparent'};transition:background 0.15s;">
      <div style="font-size:0.75rem;font-weight:700;color:${activo ? '#00695C' : '#546E7A'};">${_libretaFechaLabel(fecha)}</div>
      <div style="font-size:0.72rem;color:#78909C;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHTML(preview)}</div>
      ${entries.length ? `<div style="font-size:0.68rem;color:#90A4AE;margin-top:2px;">${entries.length} nota${entries.length > 1 ? 's' : ''}</div>` : ''}
    </div>`;
  }).join('');
}

const _LIBRETA_TIPOS = [
  { value: 'general',        label: 'General',               icon: 'edit_note',         color: '#546E7A' },
  { value: 'comportamiento', label: 'Comportamiento',         icon: 'warning',           color: '#E65100' },
  { value: 'academico',      label: 'Académico',              icon: 'school',            color: '#1565C0' },
  { value: 'asistencia',     label: 'Asistencia',             icon: 'event_busy',        color: '#6A1B9A' },
  { value: 'logro',          label: 'Logro / Reconocimiento', icon: 'emoji_events',      color: '#2E7D32' },
  { value: 'comunicacion',   label: 'Comunicación con padres',icon: 'forum',             color: '#00695C' },
  { value: 'otro',           label: 'Otro',                   icon: 'more_horiz',        color: '#78909C' },
];

function _renderizarEntradasDia(fecha) {
  const cont = document.getElementById('libreta-panel-dia');
  if (!cont) return;
  const data = cargarLibreta();
  const entries = data.entries.filter(e => e.fecha === fecha).sort((a, b) => (a.hora || '').localeCompare(b.hora || ''));
  const fechaLabel = new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' });

  cont.innerHTML = `
    <div style="margin-bottom:16px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
      <span style="font-size:1rem;font-weight:700;color:#00695C;">${_libretaFechaLabel(fecha)}</span>
      <span style="font-size:0.78rem;color:#90A4AE;">${fechaLabel}</span>
    </div>
    ${entries.length === 0 ? `
      <div style="text-align:center;padding:40px 20px;color:#9E9E9E;">
        <span class="material-icons" style="font-size:2.5rem;opacity:0.3;display:block;">edit_note</span>
        <p style="margin-top:8px;font-size:0.85rem;">Sin anotaciones para este día.<br>
          Haz clic en <strong>+ Nueva anotación</strong> para comenzar.</p>
      </div>` :
      entries.map(e => {
        const tipoInfo = _LIBRETA_TIPOS.find(t => t.value === (e.tipo || 'general')) || _LIBRETA_TIPOS[0];
        return `
        <div style="background:#fff;border:1.5px solid #B2DFDB;border-left:4px solid ${tipoInfo.color};border-radius:10px;padding:14px 16px;margin-bottom:12px;">
          <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;">
            <div style="flex:1;min-width:0;">
              <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:6px;">
                <span style="display:inline-flex;align-items:center;gap:4px;font-size:0.7rem;font-weight:700;color:${tipoInfo.color};background:${tipoInfo.color}18;border-radius:20px;padding:2px 8px;">
                  <span class="material-icons" style="font-size:12px;">${tipoInfo.icon}</span>${tipoInfo.label}
                </span>
                ${e.cursoNombre ? `<span style="font-size:0.7rem;color:#546E7A;background:#ECEFF1;border-radius:20px;padding:2px 8px;">
                  <span class="material-icons" style="font-size:11px;vertical-align:middle;">class</span> ${escapeHTML(e.cursoNombre)}
                </span>` : ''}
              </div>
              ${e.titulo ? `<div style="font-weight:700;color:#00695C;font-size:0.92rem;margin-bottom:6px;">${escapeHTML(e.titulo)}</div>` : ''}
              <div style="font-size:0.85rem;color:#37474F;line-height:1.6;white-space:pre-wrap;">${escapeHTML(e.texto || '')}</div>
            </div>
            <div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px;flex-shrink:0;">
              <span style="font-size:0.68rem;color:#90A4AE;">${e.hora || ''}</span>
              <div style="display:flex;gap:2px;">
                <button onclick="_abrirFormLibreta('${e.id}')" title="Editar"
                  style="background:none;border:none;cursor:pointer;color:#0277BD;padding:4px;border-radius:4px;">
                  <span class="material-icons" style="font-size:16px;">edit</span>
                </button>
                <button onclick="_eliminarEntradaLibreta('${e.id}')" title="Eliminar"
                  style="background:none;border:none;cursor:pointer;color:#C62828;padding:4px;border-radius:4px;">
                  <span class="material-icons" style="font-size:16px;">delete</span>
                </button>
              </div>
            </div>
          </div>
        </div>`;
      }).join('')
    }`;
}

function _abrirFormLibreta(entryId) {
  const data = cargarLibreta();
  const entry = entryId ? data.entries.find(e => e.id === entryId) : null;
  const fechaDefault = _libretaDiaSeleccionado || new Date().toISOString().split('T')[0];

  const cursos = Object.values(calState.cursos || {}).sort((a, b) => (a.nombre || '').localeCompare(b.nombre || ''));
  const cursosOpts = `<option value="">— Sin curso específico —</option>` +
    cursos.map(c => `<option value="${c.id}" ${entry?.cursoId === c.id ? 'selected' : ''}>${escapeHTML(c.nombre)}</option>`).join('');

  const tiposOpts = _LIBRETA_TIPOS.map(t =>
    `<option value="${t.value}" ${(entry?.tipo || 'general') === t.value ? 'selected' : ''}>${t.label}</option>`
  ).join('');

  const inputStyle = 'width:100%;padding:8px 10px;border:1.5px solid #B2DFDB;border-radius:8px;font-size:0.9rem;background:#fff;font-family:inherit;box-sizing:border-box;';

  document.getElementById('modal-title').textContent = entry ? 'Editar anotación' : 'Nueva anotación';
  document.getElementById('modal-body').innerHTML = `
    <div style="display:flex;flex-direction:column;gap:14px;">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div>
          <label style="font-size:0.78rem;font-weight:600;color:#546E7A;display:block;margin-bottom:4px;">Fecha</label>
          <input type="date" id="lib-fecha" value="${entry ? entry.fecha : fechaDefault}" style="${inputStyle}">
        </div>
        <div>
          <label style="font-size:0.78rem;font-weight:600;color:#546E7A;display:block;margin-bottom:4px;">Tipo de anotación</label>
          <select id="lib-tipo" style="${inputStyle}">${tiposOpts}</select>
        </div>
      </div>
      <div>
        <label style="font-size:0.78rem;font-weight:600;color:#546E7A;display:block;margin-bottom:4px;">Curso relacionado</label>
        <select id="lib-curso" style="${inputStyle}">${cursosOpts}</select>
      </div>
      <div>
        <label style="font-size:0.78rem;font-weight:600;color:#546E7A;display:block;margin-bottom:4px;">Título / Asunto</label>
        <input type="text" id="lib-titulo" value="${escapeHTML(entry?.titulo || '')}"
          placeholder="Ej: Reunión de departamento, Idea para clase..."
          maxlength="80" style="${inputStyle}">
      </div>
      <div>
        <label style="font-size:0.78rem;font-weight:600;color:#546E7A;display:block;margin-bottom:4px;">Anotación</label>
        <textarea id="lib-texto" rows="5" placeholder="Escribe tu anotación aquí..."
          style="width:100%;padding:10px;border:1.5px solid #B2DFDB;border-radius:8px;font-size:0.88rem;line-height:1.6;resize:vertical;font-family:inherit;box-sizing:border-box;">${escapeHTML(entry?.texto || '')}</textarea>
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;padding-top:4px;">
        <button class="btn-secundario" onclick="cerrarModalBtn()">Cancelar</button>
        <button class="btn-siguiente" onclick="_guardarEntradaLibreta('${entryId || ''}')">
          <span class="material-icons">save</span> Guardar
        </button>
      </div>
    </div>`;
  _usarFooterDinamico('');
  document.getElementById('modal-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  setTimeout(() => document.getElementById('lib-titulo')?.focus(), 100);
}

function _guardarEntradaLibreta(entryId) {
  const titulo   = (document.getElementById('lib-titulo')?.value || '').trim();
  const texto    = (document.getElementById('lib-texto')?.value || '').trim();
  const fecha    = document.getElementById('lib-fecha')?.value || new Date().toISOString().split('T')[0];
  const tipo     = document.getElementById('lib-tipo')?.value || 'general';
  const cursoId  = document.getElementById('lib-curso')?.value || '';
  if (!titulo && !texto) { mostrarToast('Escribe un título o anotación', 'error'); return; }

  const data = cargarLibreta();
  const hora = new Date().toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit' });
  const cursoNombre = cursoId ? (calState.cursos?.[cursoId]?.nombre || '') : '';

  if (entryId) {
    const idx = data.entries.findIndex(e => e.id === entryId);
    if (idx >= 0) data.entries[idx] = { ...data.entries[idx], titulo, texto, fecha, tipo, cursoId, cursoNombre };
  } else {
    data.entries.push({ id: uid(), fecha, titulo, texto, hora, tipo, cursoId, cursoNombre });
  }

  _guardarLibreta(data);
  _libretaDiaSeleccionado = fecha;
  cerrarModalBtn();
  renderizarLibreta();
  mostrarToast(entryId ? 'Anotación actualizada' : 'Anotación guardada', 'success');
}

function _eliminarEntradaLibreta(entryId) {
  if (!confirm('¿Eliminar esta anotación?')) return;
  const data = cargarLibreta();
  data.entries = data.entries.filter(e => e.id !== entryId);
  _guardarLibreta(data);
  renderizarLibreta();
  mostrarToast('Anotación eliminada', 'success');
}

// ═══════════════════════════════════════════════════════════════════
// RENDIMIENTO — Gráficas por curso
// ═══════════════════════════════════════════════════════════════════

function abrirRendimiento() {
  _mostrarPanel('panel-rendimiento');
  _rendCargarSelector();
}

function cerrarRendimiento() { abrirDashboard(); }

function _rendCambiarCurso() {
  const id = document.getElementById('rend-selector-curso')?.value;
  _renderizarGraficasRendimiento(id || null);
}

function _rendCargarSelector() {
  const sel = document.getElementById('rend-selector-curso');
  if (!sel) return;
  const cursos = Object.values(calState.cursos || {});
  if (!cursos.length) {
    sel.innerHTML = '<option value="">Sin cursos registrados</option>';
    _renderizarGraficasRendimiento(null);
    return;
  }
  sel.innerHTML = cursos.map(c => `<option value="${c.id}">${escapeHTML(c.nombre)}</option>`).join('');
  sel.value = cursos[0].id;
  _renderizarGraficasRendimiento(cursos[0].id);
}

function _rendColorPct(pct) {
  if (pct >= 0.7) return { fg: '#2E7D32', bg: 'rgba(46,125,50,0.12)', label: 'Aprobado' };
  if (pct >= 0.6) return { fg: '#F57F17', bg: 'rgba(245,127,23,0.12)', label: 'Regular' };
  return { fg: '#C62828', bg: 'rgba(198,40,40,0.12)', label: 'Reprobado' };
}

function _rendMaxTotal(curso) {
  return Object.values(curso.ras || {}).reduce((s, ra) => s + (ra.valorTotal || 0), 0);
}

function _rendDonutSVG(verde, amarillo, rojo) {
  const total = verde + amarillo + rojo;
  if (!total) return '<div class="rend-empty-small"><span class="material-icons">group_off</span>Sin estudiantes</div>';
  const segs = [
    { val: verde,    color: '#2E7D32', label: 'Aprobados' },
    { val: amarillo, color: '#F57F17', label: 'Regulares' },
    { val: rojo,     color: '#C62828', label: 'Reprobados' },
  ].filter(s => s.val > 0);
  const cx = 80, cy = 80, r = 62, ri = 40;
  let angle = -Math.PI / 2;
  const paths = segs.map(seg => {
    const sweep = (seg.val / total) * Math.PI * 2;
    const end = angle + sweep;
    const lg = sweep > Math.PI ? 1 : 0;
    const cos1 = Math.cos(angle), sin1 = Math.sin(angle);
    const cos2 = Math.cos(end),   sin2 = Math.sin(end);
    const d = `M${cx + r*cos1} ${cy + r*sin1} A${r} ${r} 0 ${lg} 1 ${cx + r*cos2} ${cy + r*sin2} L${cx + ri*cos2} ${cy + ri*sin2} A${ri} ${ri} 0 ${lg} 0 ${cx + ri*cos1} ${cy + ri*sin1}Z`;
    angle = end;
    return `<path d="${d}" fill="${seg.color}"/>`;
  });
  const legend = segs.map(s =>
    `<div class="rend-legend-row"><span class="rend-legend-dot" style="background:${s.color}"></span><span>${s.label}: <strong>${s.val}</strong></span></div>`
  ).join('');
  return `<div class="rend-donut-wrap">
    <svg viewBox="0 0 160 160" width="150" height="150" style="overflow:visible">
      ${paths.join('')}
      <text x="${cx}" y="${cy - 6}" text-anchor="middle" font-size="22" font-weight="700" fill="currentColor">${total}</text>
      <text x="${cx}" y="${cy + 13}" text-anchor="middle" font-size="10" fill="#9E9E9E">alumnos</text>
    </svg>
    <div class="rend-legend">${legend}</div>
  </div>`;
}

function _rendBarrasRA(raData) {
  if (!raData.length) return '<div class="rend-empty-small">Sin datos de RA</div>';
  return `<div class="rend-barras-ra">
    ${raData.map(d => {
      const pct = d.max > 0 ? d.avg / d.max : 0;
      const col = _rendColorPct(pct);
      const w = Math.min(pct * 100, 100).toFixed(1);
      const shortLabel = d.label.length > 40 ? d.label.substring(0, 40) + '…' : d.label;
      return `<div class="rend-barra-ra-row">
        <div class="rend-barra-ra-label" title="${escapeHTML(d.label)}">${escapeHTML(shortLabel)}</div>
        <div class="rend-barra-ra-track">
          <div class="rend-barra-ra-fill" style="width:${w}%;background:${col.fg};"></div>
          <span class="rend-barra-ra-pct">${(pct * 100).toFixed(0)}%</span>
        </div>
        <div class="rend-barra-ra-val" style="color:${col.fg};">${d.avg !== null ? d.avg.toFixed(1) : '—'}/${d.max}</div>
      </div>`;
    }).join('')}
  </div>`;
}

function _rendBarrasActividades(actData) {
  if (!actData.length) return '<div class="rend-empty-small">Sin actividades calificadas</div>';
  // Agrupar por RA
  const grupos = [];
  let currentRA = null;
  actData.forEach(d => {
    if (d.raLabel !== currentRA) {
      currentRA = d.raLabel;
      grupos.push({ raLabel: currentRA, items: [] });
    }
    grupos[grupos.length - 1].items.push(d);
  });

  return grupos.map(g => {
    const raShort = g.raLabel.length > 60 ? g.raLabel.substring(0, 60) + '…' : g.raLabel;
    const modulo = g.items[0]?.raModulo || '';
    return `<div style="margin-bottom:12px;">
      <div style="font-size:0.78rem;font-weight:700;color:#1565C0;padding:6px 8px;background:rgba(21,101,192,0.07);border-radius:6px;margin-bottom:6px;display:flex;align-items:center;gap:6px;flex-wrap:wrap;">
        <span class="material-icons" style="font-size:15px;">school</span>${escapeHTML(raShort)}${modulo ? '<span style="font-weight:500;color:#546E7A;font-size:0.72rem;margin-left:4px;">· ' + escapeHTML(modulo) + '</span>' : ''}
      </div>
      <div class="rend-barras-ra">
        ${g.items.map(d => {
          const pct = d.max > 0 && d.avg !== null ? d.avg / d.max : 0;
          const col = _rendColorPct(pct);
          const w = d.avg !== null ? Math.min(pct * 100, 100).toFixed(1) : 0;
          const shortLabel = d.label.length > 40 ? d.label.substring(0, 40) + '…' : d.label;
          return `<div class="rend-barra-ra-row">
            <div class="rend-barra-ra-label" title="${escapeHTML(d.label)}">${escapeHTML(shortLabel)}</div>
            <div class="rend-barra-ra-track">
              <div class="rend-barra-ra-fill" style="width:${w}%;background:${d.avg !== null ? col.fg : '#9E9E9E'};"></div>
              <span class="rend-barra-ra-pct">${d.avg !== null ? (pct * 100).toFixed(0) + '%' : 'Sin notas'}</span>
            </div>
            <div class="rend-barra-ra-val" style="color:${col.fg};">${d.avg !== null ? d.avg.toFixed(1) : '—'}/${d.max}</div>
          </div>`;
        }).join('')}
      </div>
    </div>`;
  }).join('');
}

function _renderizarGraficasRendimiento(cursoId) {
  const cont = document.getElementById('rend-contenido');
  if (!cont) return;

  if (!cursoId) {
    cont.innerHTML = `<div class="rend-empty"><span class="material-icons">bar_chart</span><p>Selecciona un curso para ver sus gráficas.</p></div>`;
    return;
  }

  const curso = calState.cursos[cursoId];
  if (!curso) {
    cont.innerHTML = `<div class="rend-empty"><span class="material-icons">error_outline</span><p>Curso no encontrado.</p></div>`;
    return;
  }

  const estudiantes = curso.estudiantes || [];
  if (!estudiantes.length) {
    cont.innerHTML = `<div class="rend-empty"><span class="material-icons">group</span><p>Este curso no tiene estudiantes registrados.</p></div>`;
    return;
  }

  const maxTotal = _rendMaxTotal(curso);

  // Nota final por estudiante
  const notasFinal = estudiantes.map(est => {
    const nota = _calcNotaFinal(curso, est.id);
    const pct = maxTotal > 0 && nota !== null ? nota / maxTotal : 0;
    return { id: est.id, nombre: est.nombre, nota, pct };
  });

  const conNotas = notasFinal.filter(e => e.nota !== null);
  const verdes    = conNotas.filter(e => e.pct >= 0.7);
  const amarillos = conNotas.filter(e => e.pct >= 0.6 && e.pct < 0.7);
  const rojos     = conNotas.filter(e => e.pct < 0.6);
  const sinNotas  = notasFinal.filter(e => e.nota === null);

  const promFinal = _promedioFinal(curso);
  const promPct   = maxTotal > 0 && promFinal !== null ? promFinal / maxTotal : null;
  const colProm   = promPct !== null ? _rendColorPct(promPct) : { fg: '#9E9E9E', bg: 'rgba(158,158,158,0.1)', label: 'Sin datos' };

  // Promedios por RA
  const raData = Object.entries(curso.ras || {}).map(([rk, ra]) => ({
    label: ra.label || ra.modulo || rk,
    avg:   _promedioColRA(curso, rk),
    max:   ra.valorTotal || 0,
  })).filter(d => d.max > 0);

  // Promedios por actividad (todas las actividades de todos los RAs)
  const biblio = cargarBiblioteca();
  const actData = [];
  Object.entries(curso.ras || {}).forEach(([rk, ra]) => {
    const snap = ra._actividadesSnapshot || [];
    const raLabel = ra.label || ra.modulo || rk;
    const raModulo = ra.modulo || '';
    (ra.actividades || []).forEach(actId => {
      const actInfo = snap.find(a => a.id === actId);
      const notas = estudiantes
        .map(est => curso.notas?.[est.id]?.[rk]?.[actId])
        .filter(n => n !== undefined && n !== null);
      const avg = notas.length ? Math.round(notas.reduce((s,n) => s+n, 0) / notas.length * 10) / 10 : null;
      actData.push({
        label: actInfo?.enunciado || actId,
        avg,
        max: ra.valores?.[actId] || 0,
        raLabel,
        raModulo,
      });
    });
  });

  cont.innerHTML = `
    <!-- Fila de KPIs -->
    <div class="rend-kpi-row">
      <div class="rend-kpi" style="border-color:${colProm.fg};background:${colProm.bg};">
        <div class="rend-kpi-num" style="color:${colProm.fg};">${promPct !== null ? (promPct * 100).toFixed(1) + '%' : '—'}</div>
        <div class="rend-kpi-label">Promedio del curso</div>
        <div class="rend-kpi-sub">${promFinal !== null ? promFinal.toFixed(1) + ' / ' + maxTotal + ' pts' : 'Sin calificaciones aún'}</div>
      </div>
      <div class="rend-kpi" style="border-color:#2E7D32;background:rgba(46,125,50,0.08);">
        <div class="rend-kpi-num" style="color:#2E7D32;">${verdes.length}</div>
        <div class="rend-kpi-label" style="color:#2E7D32;">Aprobados ≥ 70%</div>
        <div class="rend-kpi-sub">${conNotas.length ? Math.round(verdes.length/conNotas.length*100) : 0}% del curso</div>
      </div>
      <div class="rend-kpi" style="border-color:#F57F17;background:rgba(245,127,23,0.08);">
        <div class="rend-kpi-num" style="color:#F57F17;">${amarillos.length}</div>
        <div class="rend-kpi-label" style="color:#F57F17;">En riesgo 60–69%</div>
        <div class="rend-kpi-sub">${conNotas.length ? Math.round(amarillos.length/conNotas.length*100) : 0}% del curso</div>
      </div>
      <div class="rend-kpi" style="border-color:#C62828;background:rgba(198,40,40,0.08);">
        <div class="rend-kpi-num" style="color:#C62828;">${rojos.length}</div>
        <div class="rend-kpi-label" style="color:#C62828;">Reprobados < 60%</div>
        <div class="rend-kpi-sub">${conNotas.length ? Math.round(rojos.length/conNotas.length*100) : 0}% del curso</div>
      </div>
      ${sinNotas.length ? `<div class="rend-kpi" style="border-color:#9E9E9E;background:rgba(158,158,158,0.08);">
        <div class="rend-kpi-num" style="color:#9E9E9E;">${sinNotas.length}</div>
        <div class="rend-kpi-label" style="color:#9E9E9E;">Sin calificaciones</div>
        <div class="rend-kpi-sub">Pendientes de notas</div>
      </div>` : ''}
    </div>

    <!-- Fila gráficas: Donut + Barras RA -->
    <div class="rend-charts-row">
      <div class="rend-card">
        <div class="rend-card-title"><span class="material-icons">donut_large</span>Distribución del curso</div>
        ${_rendDonutSVG(verdes.length, amarillos.length, rojos.length)}
      </div>
      <div class="rend-card rend-card-grow">
        <div class="rend-card-title"><span class="material-icons">bar_chart</span>Promedio por Resultado de Aprendizaje</div>
        ${_rendBarrasRA(raData)}
      </div>
    </div>

    <!-- Barras de actividades -->
    ${actData.length ? `<div class="rend-card">
      <div class="rend-card-title"><span class="material-icons">assignment</span>Promedio por Actividad de Evaluación</div>
      ${_rendBarrasActividades(actData)}
    </div>` : ''}

    <!-- Estudiantes en riesgo -->
    ${(() => {
      const enRiesgo = _estudiantesEnRiesgo(curso);
      if (!enRiesgo.length) return `<div class="rend-card rend-sin-riesgo">
        <span class="material-icons" style="color:#2E7D32;font-size:20px;">check_circle</span>
        <span>Sin estudiantes en riesgo con los umbrales actuales</span>
      </div>`;
      return `<div class="rend-card rend-card-riesgo">
        <div class="rend-card-title rend-title-riesgo">
          <span class="material-icons">person_alert</span>
          Estudiantes en riesgo
          <span class="rend-riesgo-badge">${enRiesgo.length}</span>
          <span class="rend-riesgo-sub">Umbral: ${localStorage.getItem('cfg_umbral_riesgo')||'70'}% · ${localStorage.getItem('cfg_umbral_acts')||'3'}+ acts sin nota</span>
        </div>
        <div class="rend-riesgo-lista">
          ${enRiesgo.map(e => {
            const col = _rendColorPct(e.pct ?? 0);
            const w = e.pct !== null ? Math.min(e.pct * 100, 100).toFixed(1) : 0;
            return `<div class="rend-riesgo-row">
              <div class="rend-riesgo-info">
                <span class="rend-riesgo-nombre">${escapeHTML(e.nombre)}</span>
                <div class="rend-riesgo-tags">
                  ${e.razones.map(r => `<span class="rend-riesgo-tag">${escapeHTML(r)}</span>`).join('')}
                </div>
              </div>
              <div class="rend-riesgo-barra-wrap">
                <div class="rend-rank-barra-fill" style="width:${w}%;background:${col.fg};height:100%;border-radius:4px;"></div>
              </div>
              <span class="rend-riesgo-pct" style="color:${col.fg};">${e.pct !== null ? (e.pct*100).toFixed(1)+'%' : 'S/N'}</span>
            </div>`;
          }).join('')}
        </div>
      </div>`;
    })()}

    <!-- Ranking de estudiantes -->
    <div class="rend-card">
      <div class="rend-card-title"><span class="material-icons">format_list_numbered</span>Ranking de estudiantes</div>
      <div class="rend-ranking">
        ${[...notasFinal].sort((a, b) => (b.nota ?? -1) - (a.nota ?? -1)).map((e, i) => {
          const col = e.nota !== null ? _rendColorPct(e.pct) : { fg: '#9E9E9E', bg: 'rgba(0,0,0,0.04)', label: 'Sin notas' };
          const w = e.nota !== null ? Math.min(e.pct * 100, 100).toFixed(1) : 0;
          return `<div class="rend-rank-row">
            <span class="rend-rank-pos" style="color:${col.fg};">${e.nota !== null ? '#' + (i+1) : '—'}</span>
            <span class="rend-rank-nombre">${escapeHTML(e.nombre)}</span>
            <div class="rend-rank-barra-wrap">
              <div class="rend-rank-barra-fill" style="width:${w}%;background:${col.fg};"></div>
            </div>
            <span class="rend-rank-pct" style="color:${col.fg};">${e.nota !== null ? (e.pct*100).toFixed(1)+'%' : 'S/N'}</span>
            <span class="rend-rank-nota">${e.nota !== null ? e.nota.toFixed(1)+'/'+maxTotal : '—'}</span>
          </div>`;
        }).join('')}
      </div>
    </div>
  `;
}

const CAL_STORAGE_KEY = 'planificadorRA_calificaciones_v1';







/**



 * Estado global del módulo de calificaciones.



 * Estructura:



 * {



 *   cursos: {



 *     "id_curso": {



 *       id: "uuid",



 *       nombre: "2do Año Sección A",



 *       estudiantes: [{ id, nombre }],



 *       notas: { "idEstudiante": { "idActividad": valor } }



 *     }



 *   },



 *   cursoActivoId: null



 * }



 */



let calState = {



  cursos: {},



  cursoActivoId: null



};







/** Carga el estado de calificaciones desde localStorage */



function cargarCalificaciones() {



  try {



    const raw = localStorage.getItem(CAL_STORAGE_KEY);



    if (raw) calState = JSON.parse(raw);



  } catch (e) {



    calState = { cursos: {}, cursoActivoId: null };



  }



}







/** Guarda el estado completo de calificaciones en localStorage */



// ── Backups automáticos de calificaciones ────────────────────────
const CAL_BACKUP_KEY = 'planificadorRA_cal_backups_v1';
const CAL_BACKUP_MAX = 5;

function _guardarBackupCalificaciones() {
  try {
    const current = localStorage.getItem(CAL_STORAGE_KEY);
    if (!current || current === '{"cursos":{}}') return;
    const backups = JSON.parse(localStorage.getItem(CAL_BACKUP_KEY) || '[]');
    const ts = Date.now();
    // No guardar si el backup más reciente es idéntico
    if (backups.length && backups[0].data === current) return;
    const label = new Date(ts).toLocaleString('es-DO', {
      day: '2-digit', month: 'short', year: 'numeric',
      hour: '2-digit', minute: '2-digit'
    });
    backups.unshift({ ts, label, data: current });
    while (backups.length > CAL_BACKUP_MAX) backups.pop();
    localStorage.setItem(CAL_BACKUP_KEY, JSON.stringify(backups));
    if (window._syncFirebase) _syncFirebase('cal_backups', backups);
  } catch (e) { console.warn('Backup cal error:', e); }
}

function restaurarBackupCalificaciones(idx) {
  try {
    const backups = JSON.parse(localStorage.getItem(CAL_BACKUP_KEY) || '[]');
    const backup = backups[idx];
    if (!backup) return;
    const cal = JSON.parse(backup.data);
    const nCursos = Object.keys(cal.cursos || {}).length;
    if (!confirm(`¿Restaurar calificaciones del ${backup.label}?\n\nContiene ${nCursos} curso(s). Los datos actuales se reemplazarán.`)) return;
    // Guardar backup del estado actual antes de restaurar
    _guardarBackupCalificaciones();
    localStorage.setItem(CAL_STORAGE_KEY, backup.data);
    if (window._syncFirebase) _syncFirebase('calificaciones', cal);
    cargarCalificaciones();
    cerrarBackup();
    mostrarToast('Calificaciones restauradas correctamente', 'success');
  } catch (e) { mostrarToast('Error al restaurar: ' + e.message, 'error'); }
}

function guardarCalificaciones() {
  // Backup automático antes de sobrescribir
  _guardarBackupCalificaciones();

  // Limpiar planIds duplicados en todos los cursos antes de guardar
  Object.values(calState.cursos || {}).forEach(curso => {
    if (curso.planIds) curso.planIds = [...new Set(curso.planIds)];
  });

  calState._lastModified = Date.now();
  localStorage.setItem(CAL_STORAGE_KEY, JSON.stringify(calState));
  if (window._syncFirebase) _syncFirebase('calificaciones', calState);
}







/** Genera un ID único simple */



function uid() {



  return Date.now().toString(36) + Math.random().toString(36).slice(2, 7);



}







