function _confirmarAsignarPlan(planId) {
  const cursoId = document.getElementById('sel-curso-destino')?.value;
  if (!cursoId) return;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  if (!curso.planIds) curso.planIds = [];
  if (!curso.planIds.includes(planId)) {
    curso.planIds.push(planId);
    if (!curso.planActivaId) curso.planActivaId = planId;
  }
  guardarCalificaciones();
  cerrarModalBtn();
  renderizarBiblioteca();
  mostrarToast('Planificación asignada al curso', 'success');
}

function desasignarPlanDeCurso(planId) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  if (!confirm('¿Quitar esta planificación del curso? Las notas registradas no se eliminarán.')) return;
  curso.planIds = (curso.planIds || []).filter(id => id !== planId);
  if (curso.planActivaId === planId) {
    curso.planActivaId = curso.planIds[0] || null;
  }
  guardarCalificaciones();
  renderizarCalificaciones();
  mostrarToast('Planificación quitada del curso', 'info');
}

// ─── Obtener planificación activa del curso ───────────────────────
function _getPlanActivaDeCurso() {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !curso.planActivaId) return null;
  const biblio = cargarBiblioteca();
  const reg = biblio.items.find(i => i.id === curso.planActivaId);
  return reg ? reg.planificacion : null;
}

function _getPlanIdClave(planId) {
  // Clave estable para RA basada en el ID de planificación
  return 'ra_plan_' + String(planId).replace(/[^a-zA-Z0-9]/g, '_').substring(0, 20);
}

function _getRaKey() {
  const curso = calState.cursos[calState.cursoActivoId];
  if (curso && curso.planActivaId) return _getPlanIdClave(curso.planActivaId);
  // Fallback al sistema anterior
  const dg = planificacion.datosGenerales || {};
  const ra = planificacion.ra || {};
  const base = (dg.moduloFormativo || '') + '|' + (dg.codigoModulo || '') + '|' + (ra.descripcion || '').substring(0, 40);
  try { return 'ra_' + btoa(unescape(encodeURIComponent(base))).substring(0, 16).replace(/[^a-zA-Z0-9]/g, '_'); }
  catch (e) { return 'ra_' + Math.abs(base.split('').reduce((a, c) => a + c.charCodeAt(0), 0)) % 999999; }
}

function _ensureRA(curso, raKey) {
  if (!curso.ras) curso.ras = {};

  let plan = _getPlanActivaDeCurso();
  if (!plan) plan = planificacion;
  const acts = plan.actividades || [];

  const dg = plan.datosGenerales || {};
  const ra = plan.ra || {};
  const valorTotal = parseFloat(dg.valorRA) || 10;

  if (!curso.ras[raKey]) {
    // Primera vez: crear raInfo con las actividades actuales
    const valores = {};
    let sumaCustom = 0;
    acts.forEach(a => { if (a.valor) { valores[a.id] = a.valor; sumaCustom += a.valor; } });
    const sinValor = acts.filter(a => !a.valor);
    if (sinValor.length) {
      const resto = Math.max(0, valorTotal - sumaCustom);
      const porAct = Math.floor((resto / sinValor.length) * 10) / 10;
      sinValor.forEach((a, i) => {
        valores[a.id] = (i === sinValor.length - 1)
          ? Math.round((resto - porAct * (sinValor.length - 1)) * 10) / 10
          : porAct;
      });
    }
    curso.ras[raKey] = {
      raKey,
      label: (ra.descripcion || raKey).substring(0, 80),
      modulo: dg.moduloFormativo || '',
      valorTotal,
      actividades: acts.map(a => a.id),
      valores,
      _actividadesSnapshot: acts.map(a => ({
        id: a.id, enunciado: a.enunciado,
        ecCodigo: a.ecCodigo, fechaStr: a.fechaStr,
        esComplementario: a.esComplementario || false,
        complementarioIcono: a.complementarioIcono || ''
      }))
    };
  } else {
    // RA ya existe: detectar actividades nuevas y añadirlas sin borrar ninguna nota
    const raInfo = curso.ras[raKey];

    // Sincronizar valor total con la planificación (puede cambiar si el docente ajusta el RA)
    let cambioSync = false;
    if (raInfo.valorTotal !== valorTotal) {
      raInfo.valorTotal = valorTotal;
      cambioSync = true;
    }

    // Sincronizar snapshot de actividades (enunciado, fecha, etc.)
    if (raInfo._actividadesSnapshot) {
      acts.forEach(a => {
        const snap = raInfo._actividadesSnapshot.find(s => s.id === a.id);
        if (snap) {
          if (a.enunciado && snap.enunciado !== a.enunciado) snap.enunciado = a.enunciado;
          if (a.fechaStr && snap.fechaStr !== a.fechaStr) snap.fechaStr = a.fechaStr;
        }
      });
    }

    // Reconciliar valores individuales desde la planificación (fuente de verdad)
    acts.forEach(a => {
      if (a.valor != null && raInfo.valores[a.id] !== a.valor) {
        raInfo.valores[a.id] = a.valor;
        cambioSync = true;
      }
    });

    if (cambioSync) guardarCalificaciones();

    const idsExistentes = new Set(raInfo.actividades);
    const nuevas = acts.filter(a => !idsExistentes.has(a.id));
    if (nuevas.length > 0) {
      nuevas.forEach(a => {
        raInfo.actividades.push(a.id);
        raInfo.valores[a.id] = a.valor || 0;
        if (!raInfo._actividadesSnapshot) raInfo._actividadesSnapshot = [];
        raInfo._actividadesSnapshot.push({
          id: a.id, enunciado: a.enunciado,
          ecCodigo: a.ecCodigo, fechaStr: a.fechaStr,
          esComplementario: a.esComplementario || false,
          complementarioIcono: a.complementarioIcono || ''
        });
      });
      guardarCalificaciones();
    }
  }

  return curso.ras[raKey];
}

// ─── Renderizado principal ────────────────────────────────────────
function renderizarCalificaciones() {
  // Limpiar textarea de estudiantes al cambiar curso (bug fix)
  const inputEst = document.getElementById('input-estudiantes');
  if (inputEst) inputEst.value = '';
  renderizarTabsCursos();
  renderizarTabsPlanesDelCurso();
  renderizarTablaCalificaciones();
  _actualizarBadgePendientes();
}

// ── Pendientes por calificar ─────────────────────────────────────────────────

function abrirPendientes() {
  const overlay = document.getElementById('pendientes-overlay');
  if (!overlay) return;
  // Populate curso selector
  const sel = document.getElementById('pend-sel-curso');
  if (sel) {
    sel.innerHTML = '<option value="all">Todos los cursos</option>';
    Object.values(calState.cursos).forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id;
      opt.textContent = c.nombre;
      if (c.id === calState.cursoActivoId) opt.selected = true;
      sel.appendChild(opt);
    });
  }
  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  _renderPendientes();
}

function cerrarPendientes() {
  const overlay = document.getElementById('pendientes-overlay');
  if (overlay) overlay.classList.add('hidden');
  document.body.style.overflow = '';
}

function imprimirPendientes() {
  const selCurso = document.getElementById('pend-sel-curso');
  const selGrupo = document.getElementById('pend-sel-grupo');
  const cursoId = selCurso?.value === 'all' ? null : selCurso?.value;
  const grupoVal = selGrupo?.value || 'estudiante';
  const cursoNombreLabel = selCurso
    ? (selCurso.options[selCurso.selectedIndex]?.text || 'Todos los cursos')
    : 'Todos los cursos';

  const pending = _calcPendientes(cursoId);
  const fecha = new Date().toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' });

  // Agrupar por estudiante
  const byEst = {};
  pending.forEach(p => {
    const key = p.cursoId + '||' + p.estudianteId;
    if (!byEst[key]) byEst[key] = {
      nombre: p.estudianteNombre,
      cursoNombre: p.cursoNombre,
      total: 0,
      ras: {}
    };
    const e = byEst[key];
    e.total++;
    if (!e.ras[p.raKey]) e.ras[p.raKey] = { modulo: p.raModulo, desc: p.raDesc, acts: [] };
    e.ras[p.raKey].acts.push(p);
  });

  if (Object.keys(byEst).length === 0) {
    mostrarToast('No hay pendientes que imprimir', 'info');
    return;
  }

  const mostrarCurso = !cursoId;
  let filas = '';
  Object.values(byEst).forEach(e => {
    const rasRows = Object.values(e.ras).map(rg => {
      const actsRows = rg.acts.map(a => {
        const ecCorto = a.ecCodigo ? a.ecCodigo.replace('E.C.', '').replace('CE', '') : '';
        const label = a.esComplementario ? '★ Comp.' : (ecCorto || 'Act.' + a.actNum);
        const pts = a.actividadMax !== null ? ' (' + a.actividadMax + 'pts)' : '';
        let fechaFull = '';
        if (a.actividadFechaISO) {
          try {
            const d = new Date(a.actividadFechaISO + 'T12:00:00');
            fechaFull = d.toLocaleDateString('es', { weekday: 'long', day: 'numeric', month: 'long' }).replace(',', '');
          } catch(ex) { fechaFull = a.actividadFecha ? a.actividadFecha.replace(',', '') : ''; }
        } else if (a.actividadFecha) {
          fechaFull = a.actividadFecha.replace(',', '');
        }
        const nombre = a.actividadEnunciado || '';
        const tag0print = a.notaActual === 0 ? ' <span style="background:#C62828;color:#fff;border-radius:3px;padding:0 3px;font-size:7.5pt;font-weight:700;">nota 0</span>' : '';
        return '<tr class="act-row' + (a.notaActual === 0 ? ' act-row-cero' : '') + '"><td class="act-codigo">' + escHTML(label) + escHTML(pts) + tag0print + '</td>'
          + '<td class="act-nombre">' + escHTML(nombre) + '</td>'
          + '<td class="act-fecha">' + escHTML(fechaFull) + '</td></tr>';
      }).join('');
      return '<tr class="ra-row"><td colspan="3">'
        + '<span class="ra-modulo">' + escHTML(rg.modulo) + '</span>'
        + (rg.desc ? '<span class="ra-desc"> · ' + escHTML(rg.desc.substring(0, 70)) + (rg.desc.length > 70 ? '…' : '') + '</span>' : '')
        + '</td></tr>' + actsRows;
    }).join('');

    filas += '<tr class="est-header-row"><td colspan="3">'
      + '<span class="est-nombre">' + escHTML(e.nombre) + '</span>'
      + (mostrarCurso && e.cursoNombre ? ' <span class="est-curso">— ' + escHTML(e.cursoNombre) + '</span>' : '')
      + ' <span class="est-total">' + e.total + ' pendiente(s)</span>'
      + '</td></tr>'
      + rasRows;
  });

  const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<title>Pendientes por calificar — ${escHTML(cursoNombreLabel)}</title>
<style>
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: Arial, sans-serif; font-size: 10.5pt; color: #212121; padding: 16mm 14mm; }
  h1 { font-size: 13.5pt; color: #1565C0; margin-bottom: 2px; }
  .subtitulo { font-size: 9pt; color: #546E7A; margin-bottom: 14px; }
  table { width: 100%; border-collapse: collapse; }
  .est-header-row td { background: #E3F2FD; color: #0D47A1; font-weight: 700;
    padding: 5px 8px; border-top: 2.5px solid #90CAF9; font-size: 10.5pt; }
  .est-nombre { font-size: 10.5pt; }
  .est-curso { font-weight: 400; color: #37474F; }
  .est-total { float: right; background: #EF5350; color: #fff; border-radius: 10px;
    padding: 1px 9px; font-size: 8.5pt; font-weight: 700; }
  .ra-row td { background: #F5F7FA; padding: 3px 8px; font-size: 9pt; border-top: 1px solid #E0E0E0; }
  .ra-modulo { font-weight: 700; color: #1565C0; }
  .ra-desc { color: #78909C; font-size: 8.5pt; }
  .act-row td { padding: 3px 8px; border-bottom: 1px solid #F0F0F0; font-size: 9.5pt; vertical-align: top; }
  .act-codigo { width: 18%; color: #E65100; font-weight: 700; white-space: nowrap; }
  .act-row-cero td { background: #FFF5F5; }
  .act-row-cero .act-codigo { color: #C62828; }
  .act-nombre { width: 55%; color: #37474F; }
  .act-fecha { width: 27%; color: #78909C; font-size: 8.5pt; }
  @page { margin: 14mm; }
  @media print {
    body { padding: 0; }
    .est-header-row td, .ra-row td { -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  }
</style></head><body>
<h1>&#128203; Actividades Pendientes de Calificar</h1>
<div class="subtitulo">Curso: ${escHTML(cursoNombreLabel)} &nbsp;&middot;&nbsp; Generado: ${fecha}</div>
<table>
  <colgroup><col style="width:18%"><col style="width:55%"><col style="width:27%"></colgroup>
  ${filas}
</table>
</body></html>`;

  const win = window.open('', '_blank', 'width=800,height=650');
  if (!win) { mostrarToast('Permite ventanas emergentes para imprimir', 'error'); return; }
  win.document.write(html);
  win.document.close();
  win.focus();
  setTimeout(() => win.print(), 400);
}

function _idCortoLink() {
  const chars = 'abcdefghjkmnpqrstuvwxyz23456789'; // sin 0,o,l,1,i para evitar confusión
  return Array.from({length: 7}, () => chars[Math.floor(Math.random() * chars.length)]).join('');
}

function _construirDataPendiente(estudianteId, cursoId) {
  const curso = calState.cursos[cursoId];
  if (!curso) return null;
  const est = (curso.estudiantes || []).find(e => e.id === estudianteId);
  if (!est) return null;

  const pending = _calcPendientes(cursoId).filter(p => p.estudianteId === estudianteId);
  if (pending.length === 0) return null;

  const raGrupos = {};
  pending.forEach(p => {
    if (!raGrupos[p.raKey]) raGrupos[p.raKey] = { materia: p.raModulo, raDesc: p.raDesc, raKey: p.raKey, acts: [] };
    let fechaCorta = '';
    if (p.actividadFechaISO) {
      try {
        const d = new Date(p.actividadFechaISO + 'T12:00:00');
        fechaCorta = d.toLocaleDateString('es', { weekday: 'long', day: 'numeric', month: 'long' }).replace(',', '');
      } catch(e) { fechaCorta = p.actividadFecha ? p.actividadFecha.replace(',', '') : ''; }
    } else if (p.actividadFecha) {
      fechaCorta = p.actividadFecha.replace(',', '');
    }
    const ecCorto = p.ecCodigo ? p.ecCodigo.replace('E.C.', '').replace('CE', '') : ('Act.' + p.actNum);
    raGrupos[p.raKey].acts.push({
      ec: ecCorto,
      nombre: p.actividadEnunciado || '',
      pts: p.actividadMax || 0,
      fecha: fechaCorta,
      cero: p.notaActual === 0
    });
  });

  const biblio = cargarBiblioteca();
  return {
    n: est.nombre,
    c: curso.nombre || '',
    f: new Date().toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' }),
    p: Object.values(raGrupos).map(ra => {
      // Usar mismas actividades que la tabla de calificaciones para evitar contar notas huérfanas
      const planId = (curso.planIds || []).find(pid => _getPlanIdClave(pid) === ra.raKey);
      const planReg = planId ? biblio.items.find(i => i.id === planId) : null;
      const actsVisibles = planReg?.planificacion?.actividades;
      const notaAcum = _calcNotaRA(curso, estudianteId, ra.raKey, actsVisibles?.length ? actsVisibles : null);
      const valorTotal = curso.ras?.[ra.raKey]?.valorTotal ?? null;
      return {
        m: ra.materia,
        r: (ra.raDesc || '').substring(0, 80),
        s: notaAcum,        // nota acumulada
        v: valorTotal,      // valor total del RA
        a: ra.acts.map(a => ({
          e: a.ec,
          o: a.nombre,
          t: a.pts,
          d: a.fecha,
          z: a.cero
        }))
      };
    })
  };
}

async function _generarLinkAlumno(estudianteId, cursoId) {
  const data = _construirDataPendiente(estudianteId, cursoId);
  if (!data) return null;

  // Guardar en Firestore y devolver link corto
  if (typeof db !== 'undefined') {
    try {
      const id = _idCortoLink();
      await db.collection('links_alumno').doc(id).set({
        data,
        ts: firebase.firestore.FieldValue.serverTimestamp()
      });
      return window.location.origin + '/alumno.html#' + id;
    } catch(e) {
      console.warn('Firestore link fallido, usando fallback LZString:', e);
    }
  }

  // Fallback: LZString comprimido
  try {
    const encoded = (typeof LZString !== 'undefined')
      ? LZString.compressToEncodedURIComponent(JSON.stringify(data))
      : btoa(unescape(encodeURIComponent(JSON.stringify(data))));
    return window.location.origin + '/alumno.html#' + encoded;
  } catch(e) { return null; }
}

async function _copiarLinkAlumno(estudianteId, cursoId, btnEl) {
  let origHtml = '';
  if (btnEl) {
    origHtml = btnEl.innerHTML;
    btnEl.disabled = true;
    btnEl.innerHTML = '<span class="material-icons" style="font-size:13px;vertical-align:middle;">hourglass_empty</span> Generando…';
  }

  const link = await _generarLinkAlumno(estudianteId, cursoId);

  if (btnEl) { btnEl.disabled = false; btnEl.innerHTML = origHtml; }
  if (!link) { mostrarToast('Este estudiante no tiene actividades pendientes', 'info'); return; }

  const doFeedback = () => {
    mostrarToast('Link copiado — compártelo con el estudiante', 'ok');
    if (btnEl) {
      btnEl.innerHTML = '<span class="material-icons" style="font-size:13px;vertical-align:middle;">check</span> Copiado';
      btnEl.style.cssText = 'background:#E8F5E9;border-color:#81C784;color:#2E7D32;';
      setTimeout(() => { btnEl.innerHTML = origHtml; btnEl.removeAttribute('style'); }, 2200);
    }
  };
  if (navigator.clipboard) {
    navigator.clipboard.writeText(link).then(doFeedback).catch(() => {
      const ta = document.createElement('textarea');
      ta.value = link; document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta); doFeedback();
    });
  } else {
    const ta = document.createElement('textarea');
    ta.value = link; document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta); doFeedback();
  }
}

async function mostrarTodosLinks() {
  const selCurso = document.getElementById('pend-sel-curso');
  const cursoId = selCurso?.value === 'all' ? null : selCurso?.value;

  const pending = _calcPendientes(cursoId);

  const seen = new Set();
  const estudiantes = [];
  pending.forEach(p => {
    const key = p.cursoId + '||' + p.estudianteId;
    if (!seen.has(key)) {
      seen.add(key);
      estudiantes.push({ estudianteId: p.estudianteId, cursoId: p.cursoId, nombre: p.estudianteNombre });
    }
  });

  if (estudiantes.length === 0) {
    mostrarToast('No hay estudiantes con pendientes', 'info');
    return;
  }

  // Abrir modal de inmediato con estado de carga
  const overlay = document.createElement('div');
  overlay.setAttribute('data-links-overlay', '1');
  overlay.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,0.55);display:flex;align-items:center;justify-content:center;padding:20px;';

  const box = document.createElement('div');
  box.style.cssText = 'background:#fff;border-radius:14px;box-shadow:0 4px 32px rgba(0,0,0,0.22);width:100%;max-width:640px;display:flex;flex-direction:column;max-height:80vh;';
  box.innerHTML = `
    <div style="padding:16px 20px;border-bottom:1px solid #E0E0E0;display:flex;align-items:center;justify-content:space-between;">
      <h3 style="font-size:1rem;font-weight:700;color:#1B5E20;display:flex;align-items:center;gap:8px;">
        <span class="material-icons" style="font-size:20px;color:#2E7D32;">link</span>
        Links de estudiantes (${estudiantes.length})
      </h3>
      <button class="modal-close" onclick="document.querySelector('[data-links-overlay]').remove()">
        <span class="material-icons">close</span>
      </button>
    </div>
    <div style="padding:14px 20px;flex:1;overflow-y:auto;min-height:0;">
      <p style="font-size:0.8rem;color:#78909C;margin-bottom:10px;">Copia estos links y envíalos a cada estudiante por WhatsApp, email o el medio que prefieras.</p>
      <textarea id="todos-links-ta" readonly style="width:100%;height:220px;border:1.5px solid #E0E0E0;border-radius:8px;padding:10px;font-family:monospace;font-size:0.78rem;color:#37474F;resize:vertical;line-height:1.8;">Generando links cortos…</textarea>
    </div>
    <div style="padding:12px 20px;border-top:1px solid #E0E0E0;display:flex;justify-content:space-between;align-items:center;">
      <button id="btn-copiar-todos-links" disabled style="background:#9E9E9E;border:none;color:#fff;border-radius:8px;padding:8px 18px;font-size:0.85rem;font-weight:700;cursor:not-allowed;display:flex;align-items:center;gap:6px;">
        <span class="material-icons" style="font-size:16px;">hourglass_empty</span> Generando…
      </button>
      <button onclick="document.querySelector('[data-links-overlay]').remove()" style="background:#F5F5F5;border:1.5px solid #E0E0E0;color:#546E7A;border-radius:8px;padding:8px 16px;font-size:0.85rem;cursor:pointer;">Cerrar</button>
    </div>`;

  overlay.appendChild(box);
  overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);

  // Generar todos los links en paralelo
  const resultados = await Promise.all(
    estudiantes.map(e =>
      _generarLinkAlumno(e.estudianteId, e.cursoId)
        .then(link => ({ nombre: e.nombre, link }))
        .catch(() => ({ nombre: e.nombre, link: null }))
    )
  );

  const lineas = resultados.filter(r => r.link).map(r => r.nombre + ' - Link: ' + r.link);
  const ta = document.getElementById('todos-links-ta');
  const btnCopiar = document.getElementById('btn-copiar-todos-links');

  if (lineas.length === 0) {
    if (ta) ta.value = 'No se pudieron generar los links.';
    return;
  }

  const texto = lineas.join('\n');
  if (ta) ta.value = texto;

  if (btnCopiar) {
    btnCopiar.disabled = false;
    btnCopiar.style.cssText = 'background:#2E7D32;border:none;color:#fff;border-radius:8px;padding:8px 18px;font-size:0.85rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px;';
    btnCopiar.innerHTML = '<span class="material-icons" style="font-size:16px;">content_copy</span> Copiar todo';
    btnCopiar.addEventListener('click', () => {
      const textoActual = ta ? ta.value : texto;
      const doFeedback = () => {
        mostrarToast('¡Todos los links copiados!', 'ok');
        const orig = btnCopiar.innerHTML;
        btnCopiar.innerHTML = '<span class="material-icons" style="font-size:16px;">check</span> ¡Copiado!';
        btnCopiar.style.background = '#1B5E20';
        setTimeout(() => { btnCopiar.innerHTML = orig; btnCopiar.style.background = '#2E7D32'; }, 2200);
      };
      if (navigator.clipboard) {
        navigator.clipboard.writeText(textoActual).then(doFeedback).catch(() => {
          if (ta) { ta.select(); document.execCommand('copy'); }
          doFeedback();
        });
      } else {
        if (ta) { ta.select(); document.execCommand('copy'); }
        doFeedback();
      }
    });
  }
}

// ── Portal de Padres ─────────────────────────────────────────────────────────

async function _generarLinkPadre(estudianteId, cursoId) {
  const curso = calState.cursos[cursoId];
  if (!curso) return null;
  const est = (curso.estudiantes || []).find(e => e.id === estudianteId);
  if (!est) return null;
  if (typeof db === 'undefined' || !firebase.auth().currentUser) return null;

  const uid = firebase.auth().currentUser.uid;
  try {
    // Asegurar que los datos más recientes estén en Firestore antes de generar el link
    const comentarios = cargarComentarios();
    const reportes = cargarReportes();
    const ref = db.collection('public_blogs').doc(uid).collection('datos_padre').doc(estudianteId);
    await ref.set({
      comentarios: comentarios[estudianteId] || [],
      reportes: reportes[estudianteId] || [],
      nombre: est.nombre,
      curso: curso.nombre || '',
      ts: firebase.firestore.FieldValue.serverTimestamp()
    });

    const id = _idCortoLink();
    await db.collection('links_padre').doc(id).set({
      uid,
      estId: estudianteId,
      nombre: est.nombre,
      curso: curso.nombre || '',
      ts: firebase.firestore.FieldValue.serverTimestamp()
    });
    return window.location.origin + '/padre.html#' + id;
  } catch(e) {
    console.warn('_generarLinkPadre error:', e);
    return null;
  }
}

async function _copiarLinkPadre(estudianteId, cursoId, btnEl) {
  let origHtml = '';
  if (btnEl) {
    origHtml = btnEl.innerHTML;
    btnEl.disabled = true;
    btnEl.innerHTML = '<span class="material-icons" style="font-size:13px;vertical-align:middle;">hourglass_empty</span> Generando…';
  }

  const link = await _generarLinkPadre(estudianteId, cursoId);

  if (btnEl) { btnEl.disabled = false; btnEl.innerHTML = origHtml; }
  if (!link) { mostrarToast('No se pudo generar el link. Verifica tu conexión.', 'error'); return; }

  const doFeedback = () => {
    mostrarToast('Link para padres copiado', 'ok');
    if (btnEl) {
      btnEl.innerHTML = '<span class="material-icons" style="font-size:13px;vertical-align:middle;">check</span> Copiado';
      btnEl.style.cssText = 'background:#E8F5E9;border-color:#81C784;color:#2E7D32;';
      setTimeout(() => { btnEl.innerHTML = origHtml; btnEl.removeAttribute('style'); }, 2200);
    }
  };
  if (navigator.clipboard) {
    navigator.clipboard.writeText(link).then(doFeedback).catch(() => {
      const ta = document.createElement('textarea');
      ta.value = link; document.body.appendChild(ta); ta.select();
      document.execCommand('copy'); document.body.removeChild(ta); doFeedback();
    });
  } else {
    const ta = document.createElement('textarea');
    ta.value = link; document.body.appendChild(ta); ta.select();
    document.execCommand('copy'); document.body.removeChild(ta); doFeedback();
  }
}

function _calcPendientes(cursoId) {
  const result = [];
  const biblio = cargarBiblioteca();
  const cursosArr = cursoId
    ? (calState.cursos[cursoId] ? [calState.cursos[cursoId]] : [])
    : Object.values(calState.cursos);

  cursosArr.forEach(curso => {
    const estudiantes = curso.estudiantes || [];
    const ras = curso.ras || {};
    const notas = curso.notas || {};
    const planIds = curso.planIds || [];

    planIds.forEach(planId => {
      // Misma fuente que usa la tabla de calificaciones: biblioteca real, no snapshot
      const reg = biblio.items.find(i => i.id === planId);
      if (!reg) return;
      const actividades = reg.planificacion?.actividades || [];
      if (actividades.length === 0) return;

      const raKey = _getPlanIdClave(planId);
      const raInfo = ras[raKey];
      const planDg = reg.planificacion?.datosGenerales || {};
      const planRa = reg.planificacion?.ra || {};

      let counter = 0;
      const actNums = actividades.map(act => {
        if (act.esComplementario) return null;
        return ++counter;
      });

      actividades.forEach((act, i) => {
        const maxVal = raInfo?.valores ? raInfo.valores[act.id] : undefined;
        estudiantes.forEach(est => {
          const grade = notas[est.id] && notas[est.id][raKey]
            ? notas[est.id][raKey][act.id]
            : undefined;
          if (grade === undefined || grade === null || grade === 0) {
            result.push({
              cursoId: curso.id,
              cursoNombre: curso.nombre || '',
              raKey,
              raModulo: planDg.moduloFormativo || raInfo?.modulo || 'RA',
              raDesc: planRa.descripcion || raInfo?.label || '',
              raValorTotal: raInfo?.valorTotal || parseFloat(planDg.valorRA) || 0,
              estudianteId: est.id,
              estudianteNombre: est.nombre || est.id,
              actividadId: act.id,
              actividadEnunciado: act.enunciado || '',
              actividadFecha: act.fechaStr || '',
              actividadFechaISO: act.fecha ? String(act.fecha).split('T')[0] : '',
              ecCodigo: act.ecCodigo || '',
              actividadMax: maxVal !== undefined ? maxVal : (act.valor || null),
              actNum: actNums[i],
              esComplementario: act.esComplementario || false,
              notaActual: grade === 0 ? 0 : null   // null = sin nota, 0 = nota cero
            });
          }
        });
      });
    });
  });

  return result;
}

function _actualizarBadgePendientes() {
  const badge = document.getElementById('badge-pendientes-cal');
  if (!badge) return;
  const cursoId = calState.cursoActivoId;
  if (!cursoId) { badge.style.display = 'none'; return; }
  const n = _calcPendientes(cursoId).length;
  if (n > 0) {
    badge.textContent = n > 99 ? '99+' : n;
    badge.style.display = 'inline-flex';
  } else {
    badge.style.display = 'none';
  }
}

function _renderPendientes() {
  const body = document.getElementById('pendientes-body');
  if (!body) return;
  const selCurso = document.getElementById('pend-sel-curso')?.value || 'all';
  const selGrupo = document.getElementById('pend-sel-grupo')?.value || 'estudiante';
  const cursoId = selCurso === 'all' ? null : selCurso;
  const pending = _calcPendientes(cursoId);

  const counterEl = document.getElementById('pend-count-header');
  if (counterEl) {
    counterEl.textContent = pending.length > 0
      ? pending.length + ' pendiente' + (pending.length !== 1 ? 's' : '')
      : '';
  }

  if (pending.length === 0) {
    body.innerHTML = '<div style="text-align:center;padding:40px 20px;">'
      + '<span class="material-icons" style="font-size:52px;color:#4CAF50;display:block;margin-bottom:12px;">check_circle</span>'
      + '<strong style="color:#2E7D32;font-size:1.05rem;">¡Todo al día!</strong>'
      + '<p style="color:#78909C;font-size:0.88rem;margin-top:6px;">No hay actividades pendientes de calificar en este curso.</p>'
      + '</div>';
    return;
  }

  body.innerHTML = selGrupo === 'ra'
    ? _renderPendientesRA(pending, selCurso !== 'all')
    : _renderPendientesEstudiante(pending, selCurso !== 'all');
}

function _renderPendientesEstudiante(pending, ocultarCurso) {
  // Group: estudianteId → raKey → activities
  const byEst = {};
  pending.forEach(p => {
    const estKey = p.cursoId + '||' + p.estudianteId;
    if (!byEst[estKey]) byEst[estKey] = {
      nombre: p.estudianteNombre,
      cursoNombre: p.cursoNombre,
      estudianteId: p.estudianteId,
      cursoId: p.cursoId,
      total: 0,
      ras: {}
    };
    const e = byEst[estKey];
    e.total++;
    if (!e.ras[p.raKey]) e.ras[p.raKey] = { modulo: p.raModulo, desc: p.raDesc, acts: [] };
    e.ras[p.raKey].acts.push(p);
  });

  let html = '';
  Object.values(byEst).forEach(e => {
    const btnId = 'btn-link-' + e.estudianteId;
    html += '<div style="background:#fff;border:1px solid #E3E8EF;border-radius:10px;margin-bottom:12px;overflow:hidden;">'
      + '<div style="background:#E3F2FD;padding:10px 14px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
      + '<span class="material-icons" style="color:#1565C0;font-size:18px;">person</span>'
      + '<strong style="color:#1565C0;">' + escHTML(e.nombre) + '</strong>'
      + (!ocultarCurso && e.cursoNombre
        ? '<span style="font-size:0.76rem;color:#546E7A;background:#ECEFF1;padding:2px 9px;border-radius:8px;">' + escHTML(e.cursoNombre) + '</span>'
        : '')
      + '<span style="margin-left:auto;background:#EF5350;color:#fff;border-radius:12px;padding:2px 10px;font-size:0.75rem;font-weight:700;">'
      + e.total + ' pendiente' + (e.total !== 1 ? 's' : '') + '</span>'
      + '<button id="' + btnId + '" onclick="_copiarLinkAlumno(\'' + e.estudianteId + '\',\'' + e.cursoId + '\',document.getElementById(\'' + btnId + '\'))"'
      + ' style="background:#E3F2FD;border:1.5px solid #90CAF9;color:#1565C0;border-radius:8px;padding:4px 10px;font-size:0.74rem;cursor:pointer;display:inline-flex;align-items:center;gap:4px;font-weight:600;">'
      + '<span class="material-icons" style="font-size:13px;">link</span> Copiar link</button>'
      + '<button id="' + btnId + '-padre" onclick="_copiarLinkPadre(\'' + e.estudianteId + '\',\'' + e.cursoId + '\',document.getElementById(\'' + btnId + '-padre\'))"'
      + ' style="background:#FCE4EC;border:1.5px solid #F48FB1;color:#AD1457;border-radius:8px;padding:4px 10px;font-size:0.74rem;cursor:pointer;display:inline-flex;align-items:center;gap:4px;font-weight:600;">'
      + '<span class="material-icons" style="font-size:13px;">supervisor_account</span> Link padres</button>'
      + '</div>'
      + '<div style="padding:10px 14px;">';

    const curso = calState.cursos?.[e.cursoId];
    Object.entries(e.ras).forEach(([raKey, rg]) => {
      const raLabel = escHTML(rg.modulo)
        + (rg.desc
          ? ' <span style="font-weight:400;opacity:0.7;font-size:0.72rem;">· ' + escHTML(rg.desc.substring(0, 55)) + (rg.desc.length > 55 ? '…' : '') + '</span>'
          : '');

      // Nota acumulada en este RA (usando actividades reales del plan, igual que la tabla)
      let notaBadge = '';
      if (curso) {
        const _bib = cargarBiblioteca();
        const _pid = (curso.planIds || []).find(pid => _getPlanIdClave(pid) === raKey);
        const _preg = _pid ? _bib.items.find(i => i.id === _pid) : null;
        const _acts = _preg?.planificacion?.actividades;
        const notaAcum = _calcNotaRA(curso, e.estudianteId, raKey, _acts?.length ? _acts : null);
        const valorTotal = curso.ras?.[raKey]?.valorTotal ?? null;
        if (notaAcum !== null && valorTotal !== null) {
          const pct = Math.min(100, Math.round((notaAcum / valorTotal) * 100));
          const color = pct >= 70 ? '#2E7D32' : pct >= 50 ? '#E65100' : '#C62828';
          const bg    = pct >= 70 ? '#E8F5E9'  : pct >= 50 ? '#FFF3E0'  : '#FFEBEE';
          notaBadge = '<span style="margin-left:auto;background:' + bg + ';color:' + color + ';border-radius:8px;padding:1px 8px;font-size:0.72rem;font-weight:700;white-space:nowrap;">'
            + notaAcum + ' / ' + valorTotal + ' pts</span>';
        } else if (notaAcum !== null) {
          notaBadge = '<span style="margin-left:auto;background:#E3F2FD;color:#1565C0;border-radius:8px;padding:1px 8px;font-size:0.72rem;font-weight:700;white-space:nowrap;">'
            + notaAcum + ' pts</span>';
        }
      }

      html += '<div style="margin-bottom:8px;">'
        + '<div style="font-size:0.78rem;font-weight:700;color:#37474F;margin-bottom:5px;padding-bottom:3px;border-bottom:1px solid #F0F4F8;display:flex;align-items:center;gap:4px;">'
        + '<span class="material-icons" style="font-size:14px;vertical-align:middle;color:#1565C0;margin-right:3px;">assignment</span>'
        + raLabel + notaBadge + '</div>'
        + '<div style="display:flex;flex-wrap:wrap;gap:5px;">';

      rg.acts.forEach(a => {
        const ecCorto = a.ecCodigo ? a.ecCodigo.replace('E.C.', '').replace('CE', '') : '';
        const actLabel = a.esComplementario ? '★ Comp.' : (ecCorto || 'Act.' + a.actNum);
        const ptsLabel = a.actividadMax !== null ? ' (' + a.actividadMax + 'pts)' : '';
        const nombre = a.actividadEnunciado || '';
        const nombreCorto = nombre.length > 38 ? nombre.substring(0, 38) + '…' : nombre;
        let fechaFull = '';
        if (a.actividadFechaISO) {
          try {
            const d = new Date(a.actividadFechaISO + 'T12:00:00');
            fechaFull = d.toLocaleDateString('es', { weekday: 'long', day: 'numeric', month: 'long' }).replace(',', '');
          } catch(e) { fechaFull = a.actividadFecha || ''; }
        } else if (a.actividadFecha) {
          fechaFull = a.actividadFecha.replace(',', '');
        }
        const esNota0 = a.notaActual === 0;
        const chipBg = esNota0 ? '#FFEBEE' : '#FFF8E1';
        const chipBorder = esNota0 ? '#EF9A9A' : '#FFD54F';
        const chipColor = esNota0 ? '#C62828' : '#E65100';
        const etiqueta0 = esNota0 ? '<span style="font-size:0.65rem;font-weight:700;background:#C62828;color:#fff;border-radius:4px;padding:0 4px;margin-left:3px;">nota 0</span>' : '';
        html += '<span title="' + escHTML(nombre) + '" style="background:' + chipBg + ';border:1px solid ' + chipBorder + ';color:' + chipColor + ';border-radius:8px;padding:5px 9px;font-size:0.78rem;cursor:default;display:inline-flex;flex-direction:column;gap:1px;max-width:200px;">'
          + '<span style="font-weight:700;font-size:0.8rem;display:flex;align-items:center;gap:2px;">' + escHTML(actLabel) + escHTML(ptsLabel) + etiqueta0 + '</span>'
          + (nombreCorto ? '<span style="font-size:0.71rem;opacity:0.82;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + escHTML(nombreCorto) + '</span>' : '')
          + (fechaFull ? '<span style="font-size:0.68rem;opacity:0.62;">' + escHTML(fechaFull) + '</span>' : '')
          + '</span>';
      });

      html += '</div></div>';
    });

    html += '</div></div>';
  });
  return html;
}

function _renderPendientesRA(pending, ocultarCurso) {
  // Group: cursoId + raKey → actividadId → students
  const byRA = {};
  pending.forEach(p => {
    const raKey = p.cursoId + '||' + p.raKey;
    if (!byRA[raKey]) byRA[raKey] = {
      modulo: p.raModulo, desc: p.raDesc,
      cursoNombre: p.cursoNombre,
      total: 0,
      actividades: {}
    };
    const ra = byRA[raKey];
    ra.total++;
    if (!ra.actividades[p.actividadId]) ra.actividades[p.actividadId] = {
      enunciado: p.actividadEnunciado,
      fecha: p.actividadFecha,
      fechaISO: p.actividadFechaISO,
      ecCodigo: p.ecCodigo,
      max: p.actividadMax,
      actNum: p.actNum,
      esComp: p.esComplementario,
      estudiantes: []
    };
    ra.actividades[p.actividadId].estudiantes.push({ nombre: p.estudianteNombre, nota0: p.notaActual === 0 });
  });

  let html = '';
  Object.values(byRA).forEach(ra => {
    html += '<div style="background:#fff;border:1px solid #E3E8EF;border-radius:10px;margin-bottom:12px;overflow:hidden;">'
      + '<div style="background:#E8EAF6;padding:10px 14px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
      + '<span class="material-icons" style="color:#3949AB;font-size:18px;">assignment</span>'
      + '<div><strong style="color:#3949AB;">' + escHTML(ra.modulo) + '</strong>'
      + (ra.desc
        ? '<div style="font-size:0.72rem;color:#5C6BC0;">' + escHTML(ra.desc.substring(0, 70)) + (ra.desc.length > 70 ? '…' : '') + '</div>'
        : '')
      + '</div>'
      + (!ocultarCurso && ra.cursoNombre
        ? '<span style="font-size:0.76rem;color:#546E7A;background:#ECEFF1;padding:2px 9px;border-radius:8px;">' + escHTML(ra.cursoNombre) + '</span>'
        : '')
      + '<span style="margin-left:auto;background:#EF5350;color:#fff;border-radius:12px;padding:2px 10px;font-size:0.75rem;font-weight:700;">'
      + ra.total + ' pendiente' + (ra.total !== 1 ? 's' : '') + '</span>'
      + '</div><div style="padding:10px 14px;">';

    Object.values(ra.actividades).forEach(act => {
      const ecCorto = act.ecCodigo ? act.ecCodigo.replace('E.C.', '').replace('CE', '') : '';
      const actLabel = act.esComp ? '★ Complementario' : (ecCorto || 'Act.' + act.actNum);
      let fechaFull = '';
      if (act.fechaISO) {
        try {
          const d = new Date(act.fechaISO + 'T12:00:00');
          fechaFull = d.toLocaleDateString('es', { weekday: 'long', day: 'numeric', month: 'long' }).replace(',', '');
        } catch(e) { fechaFull = act.fecha ? act.fecha.replace(',', '') : ''; }
      } else if (act.fecha) {
        fechaFull = act.fecha.replace(',', '');
      }
      html += '<div style="margin-bottom:9px;padding:8px 10px;background:#F3E5F5;border-radius:8px;border-left:3px solid #AB47BC;">'
        + '<div style="font-size:0.8rem;font-weight:600;color:#6A1B9A;margin-bottom:3px;">'
        + escHTML(actLabel)
        + (act.max !== null ? ' · <span style="font-weight:400;">' + act.max + 'pts</span>' : '')
        + (fechaFull ? '<span style="font-weight:400;opacity:0.65;font-size:0.74rem;"> · ' + escHTML(fechaFull) + '</span>' : '')
        + '</div>'
        + (act.enunciado ? '<div style="font-size:0.76rem;color:#6A1B9A;opacity:0.8;margin-bottom:5px;">' + escHTML(act.enunciado.substring(0, 90)) + (act.enunciado.length > 90 ? '…' : '') + '</div>' : '')
        + '<div style="display:flex;flex-wrap:wrap;gap:4px;">';
      act.estudiantes.forEach(est => {
        const bg = est.nota0 ? '#FFEBEE' : '#FCE4EC';
        const bd = est.nota0 ? '#EF9A9A' : '#F48FB1';
        const col = est.nota0 ? '#B71C1C' : '#880E4F';
        const tag0 = est.nota0 ? ' <span style="font-size:0.62rem;background:#B71C1C;color:#fff;border-radius:3px;padding:0 3px;">0</span>' : '';
        html += '<span style="background:' + bg + ';border:1px solid ' + bd + ';color:' + col + ';border-radius:12px;padding:2px 9px;font-size:0.74rem;display:inline-flex;align-items:center;gap:3px;">'
          + escHTML(est.nombre) + tag0 + '</span>';
      });
      html += '</div></div>';
    });

    html += '</div></div>';
  });
  return html;
}

function renderizarTabsCursos() {
  const container = document.getElementById('cal-tabs');
  if (!container) return;
  container.innerHTML = '';
  const cursos = Object.values(calState.cursos);
  if (cursos.length === 0) {
    container.innerHTML = '<span style="color:#9E9E9E;font-size:0.85rem;">Sin cursos. Crea uno →</span>';
    return;
  }
  const biblioIds = new Set((cargarBiblioteca().items || []).map(i => i.id));
  cursos.forEach(curso => {
    const tab = document.createElement('button');
    tab.className = 'cal-tab' + (curso.id === calState.cursoActivoId ? ' activo' : '');
    const nPlanes = (curso.planIds || []).filter(id => biblioIds.has(id)).length;
    tab.innerHTML = '<span class="material-icons" style="font-size:16px;">class</span>'
      + escapeHTML(curso.nombre)
      + (nPlanes ? ` <span style="background:#E3F2FD;color:#1565C0;border-radius:10px;padding:1px 7px;font-size:0.7rem;font-weight:700;">${nPlanes}</span>` : '')
      + '<button class="cal-tab-edit" title="Renombrar curso" onclick="event.stopPropagation();renombrarCurso(\'' + curso.id + '\')">'
      + '<span class="material-icons" style="font-size:14px;">edit</span></button>'
      + '<button class="cal-tab-del" title="Eliminar curso" onclick="event.stopPropagation();eliminarCurso(\'' + curso.id + '\')">'
      + '<span class="material-icons" style="font-size:16px;">close</span></button>';
    tab.onclick = () => activarCurso(curso.id);
    container.appendChild(tab);
  });
}

function renderizarTabsPlanesDelCurso() {
  const area = document.getElementById('cal-planes-bar');
  if (!area) return;
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) { area.innerHTML = ''; return; }

  const planIds = curso.planIds || [];
  if (planIds.length === 0) {
    area.innerHTML = `
      <div style="padding:10px 0;font-size:0.85rem;color:#78909C;display:flex;align-items:center;gap:8px;">
        <span class="material-icons" style="font-size:18px;">info</span>
        Este curso no tiene planificaciones asignadas. 
        <button onclick="abrirPlanificaciones()" style="background:none;border:none;color:#1565C0;cursor:pointer;font-weight:600;font-size:0.85rem;text-decoration:underline;">Ir a Mis Planificaciones</button>
        para asignar una.
      </div>`;
    return;
  }

  const biblio = cargarBiblioteca();
  let html = '<div class="cal-planes-tabs">';
  planIds.forEach(pid => {
    const reg = biblio.items.find(i => i.id === pid);
    if (!reg) return;
    const dg = reg.planificacion?.datosGenerales || {};
    const activo = pid === curso.planActivaId;
    const raDesc = reg.planificacion?.ra?.descripcion || '';
    const raCorto = raDesc ? raDesc.substring(0, 40) + (raDesc.length > 40 ? '…' : '') : '';
    html += `<button class="cal-plan-tab${activo ? ' activo' : ''}" onclick="activarPlanEnCurso('${pid}')">
      <span class="material-icons" style="font-size:15px;">assignment</span>
      <span>${escHTML((dg.moduloFormativo || reg.nombre || pid).substring(0, 30))}</span>
      ${raCorto ? '<span style="font-size:0.68rem;opacity:0.75;margin-left:2px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">· ' + escHTML(raCorto) + '</span>' : ''}
      <span style="font-size:0.7rem;opacity:0.7;margin-left:2px;">${dg.valorRA ? dg.valorRA + 'pts' : ''}</span>
      <button onclick="event.stopPropagation();desasignarPlanDeCurso('${pid}')" title="Quitar del curso"
        style="background:none;border:none;cursor:pointer;color:#B0BEC5;margin-left:4px;padding:0;line-height:1;">
        <span class="material-icons" style="font-size:14px;">close</span>
      </button>
    </button>`;
  });
  html += '</div>';
  area.innerHTML = html;
}

// ─── abrirCalificaciones ──────────────────────────────────────────

// ─── Toggle panel asistencia ─────────────────────────────────────
let _asistPanelAbierto = false;

function toggleVistaAsistencia() {
  const panel = document.getElementById('cal-asist-panel');
  const btn = document.getElementById('btn-toggle-asistencia');
  if (!panel) return;
  _asistPanelAbierto = !_asistPanelAbierto;
  panel.classList.toggle('hidden', !_asistPanelAbierto);
  if (btn) {
    btn.style.background = _asistPanelAbierto ? '#1565C0' : '#E3F2FD';
    btn.style.color = _asistPanelAbierto ? '#fff' : '#1565C0';
    btn.style.borderColor = _asistPanelAbierto ? '#1565C0' : '#90CAF9';
  }
  if (_asistPanelAbierto) {
    _asistFechaSeleccionada = null;
    abrirAsistencia();
  }
}

function abrirCalificaciones(cursoId) {
  const preselect = cursoId || calState.cursoActivoId;
  cargarCalificaciones();
  if (preselect && calState.cursos[preselect]) calState.cursoActivoId = preselect;
  _mostrarPanel('panel-calificaciones');
  renderizarCalificaciones();
}

function _irACalificacionesPlan(cursoId, planId) {
  calState.cursoActivoId = cursoId;
  const curso = calState.cursos[cursoId];
  if (curso && planId) curso.planActivaId = planId;
  guardarCalificaciones();
  abrirCalificaciones();
}

// ─── Tooltip táctil para nombre de actividad (mobile) ────────────────
let _tooltipActTimer = null;
function _mostrarTooltipAct(e, th) {
  if (e.target.tagName === 'INPUT') return;
  e.stopPropagation();
  const nombre = th.dataset.actNombre || th.title || '';
  if (!nombre) return;
  const existing = document.getElementById('_act-tooltip');
  if (existing) { existing.remove(); clearTimeout(_tooltipActTimer); _tooltipActTimer = null; return; }
  if (_tooltipActTimer) clearTimeout(_tooltipActTimer);
  const tip = document.createElement('div');
  tip.id = '_act-tooltip';
  tip.style.cssText = 'position:fixed;background:#1A237E;color:#fff;padding:10px 14px;border-radius:10px;font-size:0.84rem;max-width:260px;z-index:9999;box-shadow:0 4px 16px rgba(0,0,0,0.35);pointer-events:none;line-height:1.45;word-break:break-word;text-align:center;';
  tip.textContent = nombre;
  document.body.appendChild(tip);
  const rect = th.getBoundingClientRect();
  const tipW = tip.offsetWidth;
  const tipH = tip.offsetHeight;
  const x = Math.min(Math.max(8, rect.left + rect.width / 2 - tipW / 2), window.innerWidth - tipW - 8);
  const y = rect.bottom + 8;
  tip.style.left = x + 'px';
  tip.style.top = Math.min(y, window.innerHeight - tipH - 8) + 'px';
  _tooltipActTimer = setTimeout(() => { tip.remove(); _tooltipActTimer = null; }, 4000);
  setTimeout(() => {
    document.addEventListener('click', function dismissTip() {
      const t = document.getElementById('_act-tooltip');
      if (t) t.remove();
      clearTimeout(_tooltipActTimer);
      _tooltipActTimer = null;
      document.removeEventListener('click', dismissTip);
    });
  }, 80);
}

// ─── Tabla de calificaciones (usa planificación activa del curso) ─
function renderizarTablaCalificaciones() {
  const thead = document.getElementById('cal-thead');
  const tbody = document.getElementById('cal-tbody');
  const tfoot = document.getElementById('cal-tfoot');
  const sinActs = document.getElementById('cal-sin-actividades');
  if (!thead || !tbody || !tfoot) return;

  const cursoId = calState.cursoActivoId;
  const curso = cursoId ? calState.cursos[cursoId] : null;

  if (!curso) {
    sinActs?.classList.remove('hidden');
    thead.innerHTML = ''; tbody.innerHTML = ''; tfoot.innerHTML = '';
    return;
  }

  // Obtener planificación activa del curso
  const planActiva = _getPlanActivaDeCurso();
  let actividades = (planActiva && planActiva.actividades) || [];

  // Fallback: snapshot guardado en el RA
  if (actividades.length === 0) {
    const raKey = _getRaKey();
    const raInfo = curso.ras && curso.ras[raKey];
    if (raInfo && raInfo._actividadesSnapshot) actividades = raInfo._actividadesSnapshot;
  }

  if (actividades.length === 0 || !curso.planActivaId) {
    sinActs?.classList.remove('hidden');
    thead.innerHTML = '';
    tbody.innerHTML = '<tr><td colspan="99" style="text-align:center;padding:2rem;color:#9E9E9E;">'
      + (curso.planIds && curso.planIds.length === 0
        ? 'Asigna una planificación a este curso para comenzar a registrar calificaciones.'
        : 'Selecciona una planificación arriba.')
      + '</td></tr>';
    tfoot.innerHTML = '';
    return;
  }
  sinActs?.classList.add('hidden');

  const raKey = _getRaKey();
  const raInfo = _ensureRA(curso, raKey);
  const planDg = planActiva?.datosGenerales || {};
  const planRa = planActiva?.ra || {};
  const rasKeys = Object.keys(curso.ras || {});

  // ─── Fila 1: encabezado del RA ───
  const raDescCorta = planRa.descripcion
    ? escapeHTML(planRa.descripcion.substring(0, 65)) + (planRa.descripcion.length > 65 ? '&hellip;' : '')
    : '';
  const raLabel = escapeHTML((planDg.moduloFormativo || 'RA').substring(0, 28))
    + ' &mdash; RA&nbsp;(' + raInfo.valorTotal + '&nbsp;pts)'
    + (raDescCorta ? '<br><small style="font-weight:400;opacity:0.88;font-size:0.72rem;">' + raDescCorta + '</small>' : '');

  const sumaAsignada = actividades.reduce((s, a) => s + (raInfo.valores[a.id] || 0), 0);
  const sumaDiff = Math.round((sumaAsignada - raInfo.valorTotal) * 100) / 100;
  const sumaColor = sumaDiff === 0 ? '#69F0AE' : (sumaDiff > 0 ? '#EF5350' : '#FF8F00');
  const sumaLabel = sumaDiff === 0
    ? '✓ ' + sumaAsignada.toFixed(1) + ' / ' + raInfo.valorTotal
    : (sumaDiff > 0 ? '+' + sumaDiff.toFixed(1) + ' excede' : sumaDiff.toFixed(1) + ' faltan');

  let h1 = '<tr class="tr-ec-header">'
    + '<th rowspan="2" style="min-width:32px;width:32px;text-align:center;background:#1565C0;color:#fff;font-size:0.75rem;">#</th>'
    + '<th class="th-nombre" rowspan="2">Estudiante</th>'
    + '<th colspan="' + actividades.length + '" style="text-align:start;background:#1565C0;color:#fff;padding:6px 8px;">'
    + raLabel + '</th>'
    + '<th rowspan="2" style="background:#0D47A1;color:#fff;min-width:72px;font-size:0.8rem;vertical-align:middle;text-align:center;white-space:nowrap;">Total RA<br><small style=\'font-weight:400;\'>' + raInfo.valorTotal + ' pts</small><br><small style=\'color:' + sumaColor + ';font-size:0.65rem;font-weight:700;\'>' + sumaLabel + '</small><br><button onclick="_copiarColumnaTotal(this)" title="Copiar columna Total RA" style="background:none;border:none;cursor:pointer;padding:1px 3px;color:#90CAF9;margin-top:2px;" tabindex="-1"><span class="material-icons" style="font-size:13px;">content_copy</span></button></th>'
    + '<th rowspan="2" style="background:#E65100;color:#fff;min-width:72px;font-size:0.8rem;vertical-align:middle;text-align:center;white-space:nowrap;">Recuper.<br><small style=\'font-weight:400;opacity:0.85;\'>2da oport.</small></th>'
    + '<th rowspan="2" style="background:#1B5E20;color:#fff;min-width:80px;font-size:0.8rem;vertical-align:middle;text-align:center;white-space:nowrap;">Total<br><small style=\'font-weight:400;\'>RA + Recup.</small></th></tr>';

  // ─── Fila 2: actividades con contador correcto por EC ───
  const _cntEC = {};
  actividades.forEach(a => { const ec = a.ecCodigo || ''; _cntEC[ec] = (_cntEC[ec] || 0) + 1; });
  const _idxEC = {};

  let h2 = '<tr>';
  let actNum = 0;
  actividades.forEach((a, i) => {
    const val = raInfo.valores[a.id] !== undefined ? raInfo.valores[a.id] : '';
    const esComp = a.esComplementario === true;
    if (!esComp) actNum++;

    if (esComp) {
      // Columna de ítem complementario
      const compIcono = a.complementarioIcono || 'star';
      const compLabel = (a.enunciado || '').substring(0, 20);
      h2 += '<th class="th-act th-act--comp" title="' + escapeHTML(a.enunciado) + '" style="min-width:90px;background:#FFF3E0;color:#BF360C;">'
        + '<div style="font-size:0.72rem;font-weight:600;color:#BF360C;"><span class="material-icons" style="font-size:13px;vertical-align:middle;color:#E65100;">' + compIcono + '</span> ' + escapeHTML(compLabel) + '</div>'
        + '<div style="font-size:0.68rem;color:#BF360C;opacity:0.75;margin:1px 0;">Complementario</div>'
        + '<input type="number" class="input-valor-act" value="' + val + '" min="0.1" max="100" step="0.5"'
        + ' title="Valor máximo de este ítem" placeholder="pts"'
        + ' onchange="actualizarValorActividad(\'' + a.id + '\',this.value,this)"'
        + ' style="width:44px;padding:2px 3px;font-size:0.72rem;border:1px solid #FFCC80;border-radius:4px;text-align:center;display:block;margin:2px auto 0;">'
        + '</th>';
    } else {
      // Columna de actividad normal
      const fechaCorta = a.fechaStr ? a.fechaStr.split(',')[0] : '';
      const fechaNum = a.fecha ? (() => { const p = String(a.fecha).split('T')[0].split('-'); return p[2] + '/' + p[1]; })() : '';
      const ecCorto = a.ecCodigo ? a.ecCodigo.replace('E.C.', '').replace('CE', '') : '';
      _idxEC[a.ecCodigo || ''] = (_idxEC[a.ecCodigo || ''] || 0) + 1;
      const numInEC = _idxEC[a.ecCodigo || ''];
      const labelEC = _cntEC[a.ecCodigo || ''] > 1 ? ecCorto + '.' + numInEC : ecCorto;
      h2 += '<th class="th-act" title="' + escapeHTML(a.enunciado) + '" data-act-nombre="' + escapeHTML(a.enunciado) + '" data-act-id="' + a.id + '" onclick="_mostrarTooltipAct(event,this)" style="min-width:80px;cursor:pointer;">'
        + '<div style="font-size:0.72rem;font-weight:600;display:flex;align-items:center;justify-content:space-between;gap:2px;">'
        + '<span>Act.' + actNum + ' <span style="opacity:0.65;font-weight:400;">' + labelEC + '</span></span>'
        + '<button onclick="event.stopPropagation();_copiarColumnaNotas(\'' + a.id + '\',this)" title="Copiar notas de esta columna" style="background:none;border:none;cursor:pointer;padding:0 1px;color:#90CAF9;display:flex;align-items:center;" tabindex="-1"><span class="material-icons" style="font-size:13px;">content_copy</span></button>'
        + '</div>'
        + '<div style="font-size:0.68rem;opacity:0.7;margin:1px 0;">' + escapeHTML(fechaCorta) + (fechaNum ? ' ' + fechaNum : '') + '</div>'
        + '<input type="number" class="input-valor-act" value="' + val + '" min="0.1" max="100" step="0.5"'
        + ' title="Valor máximo de esta actividad" placeholder="pts"'
        + ' onchange="actualizarValorActividad(\'' + a.id + '\',this.value,this)"'
        + ' style="width:44px;padding:2px 3px;font-size:0.72rem;border:1px solid #90CAF9;border-radius:4px;text-align:center;display:block;margin:2px auto 0;">'
        + '</th>';
    }
  });
  h2 += '</tr>';
  thead.innerHTML = h1 + h2;

  // ─── Cuerpo ───
  if (!curso.estudiantes || curso.estudiantes.length === 0) {
    tbody.innerHTML = '<tr><td colspan="99" style="text-align:center;padding:2rem;color:#9E9E9E;">Agrega estudiantes usando el formulario de arriba.</td></tr>';
    tfoot.innerHTML = '';
    return;
  }

  tbody.innerHTML = '';
  const recupCache = cargarRecuperaciones();
  curso.estudiantes.forEach((est, estIdx) => {
    const tr = document.createElement('tr');
    const recupMapEst = recupCache[cursoId]?.[est.id] || {};
    const nRecupPendiente = Object.values(recupMapEst).filter(r => r.estado === 'pendiente').length;
    let cells = '<td style="text-align:center;font-size:0.8rem;color:#90CAF9;font-weight:600;min-width:32px;width:32px;">' + (estIdx + 1) + '</td>'
      + '<td class="td-nombre" id="nombre-' + est.id + '">'
      + '<div class="td-nombre-inner">'
      + '<span onclick="_toggleNombreMobile(this)" ondblclick="editarNombreEstudiante(\'' + est.id + '\')" title="Toca para ver opciones · Doble clic para editar" style="cursor:pointer;flex:1;">' + escapeHTML(est.nombre) + '</span>'
      + '<div class="est-overflow-wrap" style="position:relative;">'
      + '<button class="btn-coment-est" onclick="_toggleEstMenu(event,\'' + est.id + '\')" title="Opciones" style="font-size:18px;font-weight:700;padding:2px 4px;">'
      + '<span class="material-icons" style="font-size:18px;">more_vert</span>'
      + (() => { const t = _getComentariosEst(est.id).length + _getIncidenciasEst(est.id).length + _getReportesEst(est.id).length + nRecupPendiente; return t ? '<span class="coment-count-badge">' + t + '</span>' : ''; })()
      + '</button>'
      + '<div class="est-overflow-menu" id="est-menu-' + est.id + '" style="display:none;">'
      + '<button onclick="abrirComentariosEstudiante(\'' + est.id + '\',\'' + est.id + '\')" data-nombre="' + escapeHTML(est.nombre) + '">'
      + '<span class="material-icons">comment</span> Comentarios'
      + (_getComentariosEst(est.id).length ? ' <span class="coment-count-badge">' + _getComentariosEst(est.id).length + '</span>' : '')
      + '</button>'
      + '<button onclick="abrirIncidencias(\'' + est.id + '\')" style="color:#00695C;">'
      + '<span class="material-icons">event_note</span> Eventos'
      + (_getIncidenciasEst(est.id).length ? ' <span class="coment-count-badge" style="background:#00695C;">' + _getIncidenciasEst(est.id).length + '</span>' : '')
      + '</button>'
      + '<button onclick="abrirReportes(\'' + est.id + '\',\'' + calState.cursoActivoId + '\')" style="color:#B71C1C;">'
      + '<span class="material-icons">description</span> Reportes'
      + (_getReportesEst(est.id).length ? ' <span class="coment-count-badge" style="background:#B71C1C;">' + _getReportesEst(est.id).length + '</span>' : '')
      + '</button>'
      + '<button onclick="abrirRecuperaciones(\'' + est.id + '\')" style="color:#E65100;">'
      + '<span class="material-icons">replay</span> Recuperaciones'
      + (nRecupPendiente ? ' <span class="coment-count-badge" style="background:#E65100;">' + nRecupPendiente + '</span>' : '')
      + '</button>'
      + '<button onclick="abrirVistaEstudiante(\'' + est.id + '\')" style="color:#00838F;">'
      + '<span class="material-icons">qr_code_2</span> Vista estudiante'
      + '</button>'
      + '<button onclick="abrirBoletin(\'' + est.id + '\')" style="color:#6A1B9A;">'
      + '<span class="material-icons">receipt_long</span> Boletín'
      + '</button>'
      + '<button id="btn-padre-perfil-' + est.id + '" onclick="_copiarLinkPadre(\'' + est.id + '\',\'' + calState.cursoActivoId + '\',document.getElementById(\'btn-padre-perfil-' + est.id + '\'))" style="color:#AD1457;">'
      + '<span class="material-icons">supervisor_account</span> Link padres'
      + '</button>'
      + '<div style="border-top:1px solid rgba(255,255,255,0.1);margin:4px 0;"></div>'
      + '<button onclick="eliminarEstudiante(\'' + est.id + '\')" style="color:#EF5350;">'
      + '<span class="material-icons">delete</span> Eliminar'
      + '</button>'
      + '</div>'
      + '</div>'
      + '</div></td>';

    actividades.forEach(a => {
      const nota = curso.notas?.[est.id]?.[raKey]?.[a.id];
      const val = nota !== undefined ? nota : '';
      const max = raInfo.valores[a.id] || 100;
      const cls = nota !== undefined ? _clsNota(nota, max) : '';
      const esCompCol = a.esComplementario === true;
      const recKey = raKey + '__' + a.id;
      const recup = recupMapEst[recKey];
      const tdStyle = recup
        ? (recup.estado === 'pendiente'
            ? ' style="position:relative;background:rgba(255,143,0,0.08);"'
            : ' style="position:relative;background:rgba(46,125,50,0.06);"')
        : (esCompCol ? ' style="position:relative;background:rgba(230,81,0,0.04);"' : '');
      const recupDot = recup
        ? '<span style="position:absolute;bottom:2px;right:2px;width:6px;height:6px;border-radius:50%;background:'
          + (recup.estado === 'pendiente' ? '#FF8F00' : '#2E7D32')
          + ';pointer-events:none;" title="' + (recup.estado === 'pendiente' ? 'Recuperación pendiente' : 'Recuperación completada') + '"></span>'
        : '';
      const isTouchMode = document.body.classList.contains('touch-mode');
      cells += '<td' + tdStyle + '><input type="number" class="input-nota ' + cls + '"'
        + ' id="nota-' + est.id + '-' + a.id + '"'
        + ' data-act-id="' + a.id + '"'
        + ' value="' + val + '" min="0" max="' + max + '" step="0.5" placeholder="—"'
        + (isTouchMode ? ' inputmode="none" readonly' : '')
        + ' onchange="registrarNota(\'' + est.id + '\',\'' + a.id + '\',this.value)"'
        + ' onkeydown="_notaKeyNav(event,this)"'
        + ' onwheel="event.preventDefault()"'
        + ' onfocus="_focusNotaInput(this)"'
        + ' onblur="_limpiarHighlightCeldas()"'
        + ' title="Máx: ' + max + ' pts | ' + escapeHTML((a.enunciado || '').substring(0, 40)) + '"'
        + '/>' + recupDot + '</td>';
    });

    const notaRA = _calcNotaRA(curso, est.id, raKey, actividades);
    cells += '<td class="td-total-ra ' + _clsNota(notaRA, raInfo.valorTotal) + '" id="total-ra-' + est.id + '-' + raKey + '">'
      + (notaRA !== null ? notaRA.toFixed(1) : '—') + '</td>';

    // Columna Recuperación: suma de notas de recuperación del RA activo
    const notaRecupSum = actividades.reduce((sum, a) => {
      const r = recupMapEst[raKey + '__' + a.id];
      return sum + (r?.notaRecuperacion != null ? r.notaRecuperacion : 0);
    }, 0);
    const hasRecup = actividades.some(a => recupMapEst[raKey + '__' + a.id]?.notaRecuperacion != null);
    cells += '<td class="td-total-ra ' + (hasRecup ? _clsNota(notaRecupSum, raInfo.valorTotal) : '') + '" style="' + (hasRecup ? '' : 'color:#555;') + '">'
      + (hasRecup ? notaRecupSum.toFixed(1) : '—') + '</td>';

    // Columna Total RA + Recuperación (capped al valorTotal del RA)
    const totalConRecupRaw = (notaRA !== null || hasRecup) ? (notaRA || 0) + notaRecupSum : null;
    const totalConRecup = totalConRecupRaw !== null ? Math.min(totalConRecupRaw, raInfo.valorTotal) : null;
    const excedido = totalConRecupRaw !== null && totalConRecupRaw > raInfo.valorTotal;
    cells += '<td class="td-promedio" style="font-weight:700;background:rgba(27,94,32,0.15);" title="' + (excedido ? 'Límite aplicado: máx. ' + raInfo.valorTotal + ' pts' : '') + '">'
      + (totalConRecup !== null ? totalConRecup.toFixed(1) : '—') + '</td>';
    tr.innerHTML = cells;
    tbody.appendChild(tr);
  });

  // ─── Footer ───
  let footCells = '<td style="min-width:32px;width:32px;"></td><td class="tf-label">Promedio</td>';
  actividades.forEach(a => {
    const notas = curso.estudiantes.map(e => curso.notas?.[e.id]?.[raKey]?.[a.id]).filter(n => n !== undefined && n !== null);
    const avg = notas.length ? notas.reduce((s, n) => s + n, 0) / notas.length : null;
    const max = raInfo.valores[a.id] || 100;
    footCells += '<td class="' + (avg !== null ? _clsNota(avg, max) : '') + '">'
      + (avg !== null ? avg.toFixed(1) : '—') + '</td>';
  });
  const avgRA = _promedioColRA(curso, raKey);
  footCells += '<td class="td-total-ra ' + (avgRA !== null ? _clsNota(avgRA, raInfo.valorTotal) : '') + '">'
    + (avgRA !== null ? avgRA.toFixed(1) : '—') + '</td>';
  // Footer Recuperación: promedio de sumas de recuperación
  const recupSumsFoot = curso.estudiantes.map(e => {
    const rm = recupCache[cursoId]?.[e.id] || {};
    const s = actividades.reduce((acc, a) => {
      const r = rm[raKey + '__' + a.id];
      return acc + (r?.notaRecuperacion != null ? r.notaRecuperacion : 0);
    }, 0);
    const has = actividades.some(a => rm[raKey + '__' + a.id]?.notaRecuperacion != null);
    return has ? s : null;
  }).filter(v => v !== null);
  const avgRecup = recupSumsFoot.length ? recupSumsFoot.reduce((s, v) => s + v, 0) / recupSumsFoot.length : null;
  footCells += '<td class="td-total-ra ' + (avgRecup !== null ? _clsNota(avgRecup, raInfo.valorTotal) : '') + '">'
    + (avgRecup !== null ? avgRecup.toFixed(1) : '—') + '</td>';
  // Footer Total+Recup: promedio de (Total RA + Recuperación) por estudiante
  const totalesConRecup = curso.estudiantes.map(e => {
    const notaRa2 = _calcNotaRA(curso, e.id, raKey);
    const rm = recupCache[cursoId]?.[e.id] || {};
    const s = actividades.reduce((acc, a) => {
      const r = rm[raKey + '__' + a.id];
      return acc + (r?.notaRecuperacion != null ? r.notaRecuperacion : 0);
    }, 0);
    const has = actividades.some(a => rm[raKey + '__' + a.id]?.notaRecuperacion != null);
    const raw = (notaRa2 !== null || has) ? (notaRa2 || 0) + s : null;
    return raw !== null ? Math.min(raw, raInfo.valorTotal) : null;
  }).filter(v => v !== null);
  const avgTotal = totalesConRecup.length ? totalesConRecup.reduce((s, v) => s + v, 0) / totalesConRecup.length : null;
  footCells += '<td class="td-promedio" style="font-weight:700;">'
    + (avgTotal !== null ? avgTotal.toFixed(1) : '—') + '</td>';
  tfoot.innerHTML = '<tr>' + footCells + '</tr>';
}

// ─── Actualizar notas (usa raKey del curso activo) ──────────────

// ── Navegación de teclado en inputs de nota ──────────────────────
function _notaKeyNav(e, el) {
  if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
    e.preventDefault();
    const delta = e.key === 'ArrowUp' ? 0.5 : -0.5;
    const max = parseFloat(el.max) || 100;
    const cur = parseFloat(el.value) || 0;
    const nv = Math.min(max, Math.max(0, Math.round((cur + delta) * 2) / 2));
    el.value = nv;
    el.dispatchEvent(new Event('input'));
    return;
  }

  // Enter o Tab → bajar al mismo campo del estudiante siguiente (misma columna)
  if (e.key === 'Enter' || (e.key === 'Tab' && !e.shiftKey)) {
    e.preventDefault();
    _moverNotaVertical(el, 1);
    return;
  }
  // Shift+Tab → subir al estudiante anterior (misma columna)
  if (e.key === 'Tab' && e.shiftKey) {
    e.preventDefault();
    _moverNotaVertical(el, -1);
  }
}

function _moverNotaVertical(el, direccion) {
  const actId = el.dataset.actId;
  if (!actId) return;

  const tbody = document.getElementById('cal-tbody');
  if (!tbody) return;

  const filas = Array.from(tbody.querySelectorAll(':scope > tr'));
  const filaActual = filas.findIndex(tr => tr.contains(el));
  if (filaActual < 0) return;

  let f = filaActual + direccion;
  while (f >= 0 && f < filas.length) {
    const target = filas[f].querySelector(`input.input-nota[data-act-id="${CSS.escape(actId)}"]`);
    if (target) { _focusNotaInput(target); return; }
    f += direccion;
  }
}

function _focusNotaInput(el) {
  if (document.body.classList.contains('touch-mode')) {
    el.blur();
    return;
  }
  _notaActiva = true;
  // Destacar columna y fila activas
  _highlightCeldaActiva(el);
  el.focus({ preventScroll: true });
  el.select();
}

function _highlightCeldaActiva(el) {
  document.querySelectorAll('.cal-col-activa, .cal-fila-activa').forEach(e => {
    e.classList.remove('cal-col-activa', 'cal-fila-activa');
  });
  if (!el) return;
  const parts = (el.id || '').split('-'); // nota-{estId}-{actId}
  if (parts.length < 3) return;
  const estId = parts[1];
  const actId = parts.slice(2).join('-');
  const thCol = document.querySelector('.th-act[data-act-id="' + actId + '"]');
  const tdNombre = document.getElementById('nombre-' + estId);
  if (thCol) thCol.classList.add('cal-col-activa');
  if (tdNombre) tdNombre.classList.add('cal-fila-activa');
}

function _limpiarHighlightCeldas() {
  document.querySelectorAll('.cal-col-activa, .cal-fila-activa').forEach(e => {
    e.classList.remove('cal-col-activa', 'cal-fila-activa');
  });
}


// ─── Actualizar notas (usa raKey del curso activo) ──────────────

// ── Navegación de teclado en inputs de nota sin scroll ──────────

function registrarNota(estudianteId, actividadId, valor) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const raKey = _getRaKey();
  _ensureRA(curso, raKey);
  if (!curso.notas) curso.notas = {};
  if (!curso.notas[estudianteId]) curso.notas[estudianteId] = {};
  if (!curso.notas[estudianteId][raKey]) curso.notas[estudianteId][raKey] = {};
  const num = parseFloat(valor);
  if (valor === '' || isNaN(num)) {
    delete curso.notas[estudianteId][raKey][actividadId];
  } else {
    const max = (curso.ras[raKey].valores[actividadId]) || 100;
    curso.notas[estudianteId][raKey][actividadId] = Math.min(max, Math.max(0, num));
  }
  const est = curso.estudiantes?.find(e => e.id === estudianteId);
  registrarCambio(`Nota registrada: ${est?.nombre || estudianteId} → ${valor === '' ? 'borrada' : valor} pts`);
  guardarCalificaciones();
  _actualizarFilaRA(estudianteId, raKey);
  _actualizarFooterRA(raKey);
  _actualizarBadgePendientes();
  if (document.getElementById('recup-lista')) identificarEstudiantesRAsPendientes();
}

function actualizarValorActividad(actividadId, nuevoValor, inputEl) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const raKey = _getRaKey();
  _ensureRA(curso, raKey);
  const raInfo = curso.ras[raKey];
  const num = parseFloat(nuevoValor);

  // Revertir si valor inválido
  if (isNaN(num) || num <= 0) {
    if (inputEl) inputEl.value = raInfo.valores[actividadId] || '';
    return;
  }

  const valorAnterior = raInfo.valores[actividadId] || 0;
  // Suma de todas las actividades excepto la que se está editando
  const planActiva = _getPlanActivaDeCurso();
  let acts = (planActiva && planActiva.actividades) || [];
  if (acts.length === 0) acts = raInfo._actividadesSnapshot || [];
  const sumaOtras = acts.reduce((s, a) => a.id === actividadId ? s : s + (raInfo.valores[a.id] || 0), 0);
  const nuevaSuma = sumaOtras + num;
  const sumaAnterior = sumaOtras + valorAnterior;
  const valorTotal = raInfo.valorTotal;

  // Solo bloquear si excede el total del RA (advertencia, no bloqueo duro)
  if (nuevaSuma > valorTotal) {
    const disponible = Math.max(0, valorTotal - sumaOtras);
    mostrarToast(
      '⚠ La suma excede el total del RA (' + valorTotal + ' pts). '
      + 'Ajusta los demás valores.', 'warning'
    );
    // No revertir — permitir el cambio para que el docente pueda reorganizar
  }

  raInfo.valores[actividadId] = num;
  _sincronizarValorCalifEnPlanificacion(actividadId, num);
  registrarCambio(`Valor de actividad actualizado a ${num} pts`);
  guardarCalificaciones();

  if (nuevaSuma > valorTotal) {
    mostrarToast(
      'Suma actual: ' + nuevaSuma.toFixed(1) + ' pts — aún excede ' + valorTotal + ' pts. Ajusta las demás actividades.', 'warning'
    );
  } else if (Math.abs(nuevaSuma - valorTotal) > 0.01) {
    mostrarToast(
      'Faltan ' + (valorTotal - nuevaSuma).toFixed(1) + ' pts por asignar (total RA: ' + valorTotal + ' pts)', 'warning'
    );
  }

  renderizarTablaCalificaciones();
}



function exportarCalificacionesWord() {



  if (!calState.cursoActivoId) { mostrarToast('No hay curso activo', 'error'); return; }



  const tabla = document.getElementById('cal-tabla-wrap')?.innerHTML || '';



  const curso = calState.cursos[calState.cursoActivoId];



  const dg = planificacion.datosGenerales || {};



  const hoy = new Date().toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' });







  const html = `<html xmlns:o='urn:schemas-microsoft-com:office:office'



    xmlns:w='urn:schemas-microsoft-com:office:word'



    xmlns='http://www.w3.org/TR/REC-html40'>



  <head><meta charset="utf-8"/>



  <style>



    body{font-family:Calibri,Arial;font-size:11pt;margin:1.5cm;}



    h2{color:#0D47A1;} h3{color:#1565C0;}



    table{width:100%;border-collapse:collapse;margin:8pt 0;}



    th,td{border:1pt solid #bbb;padding:5pt 7pt;font-size:9pt;}



    th{background:#1565C0;color:white;font-weight:bold;}



  </style></head>



  <body>



    <h2>Calificaciones – ${escapeHTML(curso.nombre)}</h2>



    <p><strong>Módulo:</strong> ${escapeHTML(dg.moduloFormativo || '-')}</p>



    <p><strong>Docente:</strong> ${escapeHTML(dg.nombreDocente || '-')}</p>



    <p><strong>Fecha:</strong> ${hoy}</p>



    <hr/>



    ${tabla}



  </body></html>`;







  const blob = new Blob(['\ufeff', html], { type: 'application/msword' });



  const url = URL.createObjectURL(blob);



  const a = document.createElement('a');



  a.href = url;



  a.download = `Calificaciones_${(curso.nombre || '').replace(/\s+/g, '_')}.doc`;



  document.body.appendChild(a);



  a.click();



  document.body.removeChild(a);



  URL.revokeObjectURL(url);



  mostrarToast('Archivo Word descargado', 'success');



}







/** Imprime las calificaciones */



function imprimirCalificaciones() {



  // Guardar estado: ocultar todo menos el panel cal



  const stepper = document.querySelector('.stepper-container');



  const main = document.querySelector('.main-content');



  const prevStepper = stepper?.style.display;



  const prevMain = main?.style.display;



  stepper && (stepper.style.display = 'none');



  main && (main.style.display = 'none');



  window.print();



  stepper && (stepper.style.display = prevStepper || '');



  main && (main.style.display = prevMain || '');



}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: SELECTOR ALEATORIO DE ALUMNO
// ════════════════════════════════════════════════════════════════════
function elegirAlumnoAleatorio() {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !curso.estudiantes || curso.estudiantes.length === 0) {
    mostrarToast('No hay estudiantes en este curso', 'error'); return;
  }
  const lista = curso.estudiantes;
  if (lista.length === 1) { _mostrarGanador(lista[0]); return; }
  const btn = document.querySelector('[onclick="elegirAlumnoAleatorio()"]');
  if (btn) btn.disabled = true;
  let i = 0;
  const timer = setInterval(() => {
    i = (i + 1) % lista.length;
    mostrarToast('🎲 ' + lista[i].nombre, 'info', 250);
  }, 130);
  setTimeout(() => {
    clearInterval(timer);
    if (btn) btn.disabled = false;
    const elegido = lista[Math.floor(Math.random() * lista.length)];
    _mostrarGanador(elegido);
  }, 1100);
}
function _mostrarGanador(est) {
  document.getElementById('modal-title').textContent = '🎲 Estudiante seleccionado';
  document.getElementById('modal-body').innerHTML =
    '<div style="text-align:center;padding:2.5rem 1rem;">'
    + '<div style="font-size:2.2rem;font-weight:800;color:#1565C0;margin-bottom:0.5rem;">' + escapeHTML(est.nombre) + '</div>'
    + '<div style="color:#78909C;font-size:0.9rem;">Seleccionado aleatoriamente 🎉</div>'
    + '</div>';
  document.getElementById('modal-footer').innerHTML =
    '<button class="btn-secundario" onclick="cerrarModalBtn()">Cerrar</button>';
  document.getElementById('modal-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: BOLETÍN INDIVIDUAL DE NOTAS
// ════════════════════════════════════════════════════════════════════
function abrirBoletin(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = cursoId ? calState.cursos[cursoId] : null;
  if (!curso) { mostrarToast('Sin curso activo', 'error'); return; }
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;

  const planActiva = _getPlanActivaDeCurso();
  const actividades = (planActiva && planActiva.actividades) || [];
  const dg = planActiva ? (planActiva.datosGenerales || {}) : {};
  const ra = planActiva ? (planActiva.ra || {}) : {};
  const raKey = _getRaKey();
  const raInfo = _ensureRA(curso, raKey);
  const comentarios = _getComentariosEst(estId);
  const incidencias = _getIncidenciasEst(estId);
  const asist = _statsAsistencia(cursoId, estId);
  const notaFinal = _calcNotaFinal(curso, estId);
  const notaRA = _calcNotaRA(curso, estId, raKey);

  const hoy = new Date().toLocaleDateString('es-CL', { day:'2-digit', month:'long', year:'numeric' });
  const esc = s => (s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const modulo = esc(dg.moduloFormativo || 'Módulo');
  const periodo = (dg.fechaInicio || '') + (dg.fechaTermino ? ' — ' + dg.fechaTermino : '');
  const instit = esc(dg.institucion || dg.establecimiento || '');
  const raDesc = esc((ra.descripcion || '').substring(0, 120));

  let filasActs = '';
  actividades.forEach((a, idx) => {
    const nota = curso.notas?.[estId]?.[raKey]?.[a.id];
    const max = raInfo.valores[a.id] || 10;
    const pct = (nota !== undefined && nota !== null) ? Math.round((nota / max) * 100) : null;
    const color = pct === null ? '#9E9E9E' : pct >= 70 ? '#2E7D32' : pct >= 50 ? '#E65100' : '#C62828';
    const barra = pct !== null
      ? '<div style="height:8px;background:#eee;border-radius:4px;margin-top:4px;"><div style="height:8px;background:' + color + ';border-radius:4px;width:' + Math.min(100,pct) + '%;"></div></div>'
      : '';
    const enun = esc((a.enunciado||'').substring(0,55)) + (a.enunciado && a.enunciado.length>55 ? '…' : '');
    const ecCorto = esc((a.ecCodigo||'').replace('E.C.','').replace('CE',''));
    filasActs += '<tr>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;font-size:0.82rem;">Act.' + (idx+1)
      + ' <span style="color:#78909C;font-size:0.75rem;">' + ecCorto + '</span>'
      + '<br><span style="font-size:0.72rem;color:#546E7A;">' + enun + '</span></td>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center;font-weight:700;color:' + color + ';">'
      + (nota !== undefined && nota !== null ? nota : '—') + '</td>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;text-align:center;color:#546E7A;">' + max + '</td>'
      + '<td style="padding:6px 8px;border-bottom:1px solid #eee;min-width:100px;">' + barra + '</td>'
      + '</tr>';
  });
  if (!filasActs) filasActs = '<tr><td colspan="4" style="text-align:center;padding:1rem;color:#9E9E9E;">Sin actividades registradas</td></tr>';

  let secComent = '';
  if (comentarios.length) {
    secComent = '<div style="margin-top:1.5rem;"><h3 style="font-size:0.95rem;font-weight:700;color:#37474F;border-bottom:2px solid #E3F2FD;padding-bottom:4px;margin-bottom:0.75rem;">Observaciones del docente</h3>';
    comentarios.slice(0,8).forEach(c => {
      const cat = COMENT_CATEGORIAS.find(x => x.id === c.categoria) || COMENT_CATEGORIAS[COMENT_CATEGORIAS.length-1];
      const fecha = new Date(c.ts).toLocaleDateString('es-CL',{day:'2-digit',month:'short',year:'numeric'});
      secComent += '<div style="margin-bottom:0.6rem;padding:8px 10px;background:#F5F5F5;border-radius:6px;border-left:3px solid ' + cat.color + ';">'
        + '<span style="font-size:0.72rem;font-weight:600;color:' + cat.color + ';">' + esc(cat.label) + '</span>'
        + '<span style="font-size:0.72rem;color:#9E9E9E;margin-left:8px;">' + fecha + '</span>'
        + '<div style="font-size:0.83rem;color:#37474F;margin-top:4px;">' + esc(c.texto) + '</div>'
        + '</div>';
    });
    secComent += '</div>';
  }

  let secIncid = '';
  if (incidencias.length) {
    secIncid = '<div style="margin-top:1.5rem;"><h3 style="font-size:0.95rem;font-weight:700;color:#37474F;border-bottom:2px solid #E8F5E9;padding-bottom:4px;margin-bottom:0.75rem;">Registro de eventos</h3>';
    incidencias.slice(0,6).forEach(inc => {
      const tipo = INCID_TIPOS.find(t => t.id === inc.tipo) || INCID_TIPOS[INCID_TIPOS.length-1];
      secIncid += '<div style="margin-bottom:0.6rem;padding:8px 10px;background:#F5F5F5;border-radius:6px;border-left:3px solid ' + tipo.color + ';">'
        + '<span style="font-size:0.72rem;font-weight:600;color:' + tipo.color + ';">' + esc(tipo.label) + '</span>'
        + (inc.fechaEvento ? '<span style="font-size:0.72rem;color:#9E9E9E;margin-left:8px;">' + inc.fechaEvento + '</span>' : '')
        + (inc.participantes ? '<div style="font-size:0.75rem;color:#546E7A;margin-top:2px;"><b>Participantes:</b> ' + esc(inc.participantes) + '</div>' : '')
        + (inc.descripcion ? '<div style="font-size:0.83rem;color:#37474F;margin-top:4px;">' + esc(inc.descripcion) + '</div>' : '')
        + (inc.acuerdos ? '<div style="font-size:0.78rem;color:#1565C0;margin-top:4px;"><b>Acuerdos:</b> ' + esc(inc.acuerdos) + '</div>' : '')
        + '</div>';
    });
    secIncid += '</div>';
  }

  const notaFinalColor = notaFinal === null ? '#9E9E9E' : notaFinal >= 7 ? '#2E7D32' : notaFinal >= 5 ? '#E65100' : '#C62828';
  const asistColor = asist.pct === null ? '#9E9E9E' : asist.pct >= 80 ? '#2E7D32' : asist.pct >= 60 ? '#E65100' : '#C62828';
  const raColor = notaRA === null ? '#9E9E9E' : notaRA >= raInfo.valorTotal * 0.7 ? '#2E7D32' : '#E65100';

  const css = `*{box-sizing:border-box;margin:0;padding:0;}body{font-family:Arial,sans-serif;font-size:14px;color:#212121;background:#fff;}
    .page{max-width:720px;margin:0 auto;padding:2rem;}
    header{background:#1565C0;color:#fff;padding:1.2rem 1.5rem;border-radius:8px 8px 0 0;}
    h1{font-size:1.1rem;font-weight:700;}h2{font-size:0.88rem;font-weight:400;opacity:0.85;margin-top:4px;}
    .alumno-card{background:#E3F2FD;padding:1rem 1.5rem;display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:1.5rem;}
    .alumno-nombre{font-size:1.4rem;font-weight:800;color:#0D47A1;}.alumno-info{font-size:0.82rem;color:#546E7A;margin-top:4px;}
    table{width:100%;border-collapse:collapse;margin-bottom:1.5rem;}
    th{background:#1565C0;color:#fff;padding:8px;text-align:left;font-size:0.82rem;}
    .resumen{display:flex;gap:1rem;margin-bottom:1.5rem;flex-wrap:wrap;}
    .resumen-card{flex:1;min-width:120px;background:#F5F5F5;border-radius:8px;padding:0.8rem;text-align:center;}
    .resumen-val{font-size:1.6rem;font-weight:800;}.resumen-label{font-size:0.72rem;color:#78909C;margin-top:2px;}
    hr{border:none;border-top:1px solid #eee;margin:1.5rem 0;}
    .btn-print{display:block;margin:1.5rem auto 0;padding:10px 2rem;background:#1565C0;color:#fff;border:none;border-radius:8px;font-size:1rem;cursor:pointer;font-weight:600;}
    @media print{.btn-print{display:none;}.page{padding:0;}}`;

  const html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">'
    + '<title>Boletín ' + esc(est.nombre) + '</title><style>' + css + '</style></head><body><div class="page">'
    + '<header><h1>📋 Boletín de Calificaciones</h1><h2>' + modulo + (instit ? ' · ' + instit : '') + '</h2></header>'
    + '<div class="alumno-card"><div>'
    + '<div class="alumno-nombre">' + esc(est.nombre) + '</div>'
    + '<div class="alumno-info">Curso: ' + esc(curso.nombre) + (periodo ? ' &nbsp;|&nbsp; Período: ' + esc(periodo) : '') + '</div>'
    + (raDesc ? '<div class="alumno-info" style="margin-top:4px;">RA: ' + raDesc + '</div>' : '')
    + '</div><div style="text-align:right;font-size:0.78rem;color:#546E7A;">Emitido:<br>' + hoy + '</div></div>'
    + '<table><thead><tr>'
    + '<th style="width:45%;">Actividad</th><th style="width:12%;text-align:center;">Nota</th>'
    + '<th style="width:12%;text-align:center;">Máx.</th><th>Progreso</th>'
    + '</tr></thead><tbody>' + filasActs + '</tbody></table>'
    + '<div class="resumen">'
    + '<div class="resumen-card"><div class="resumen-val" style="color:' + raColor + ';">' + (notaRA !== null ? notaRA.toFixed(1) : '—') + '</div><div class="resumen-label">Total RA / ' + raInfo.valorTotal + ' pts</div></div>'
    + (localStorage.getItem('cfg_asistencia_activa') !== 'false' ? '<div class="resumen-card"><div class="resumen-val" style="color:' + asistColor + ';">' + (asist.pct !== null ? asist.pct + '%' : '—') + '</div><div class="resumen-label">Asistencia</div></div>' : '')
    + '<div class="resumen-card" style="background:#E8F5E9;"><div class="resumen-val" style="color:' + notaFinalColor + ';">' + (notaFinal !== null ? notaFinal.toFixed(1) : '—') + '</div><div class="resumen-label">NOTA FINAL</div></div>'
    + '</div>'
    + secComent + secIncid
    + '<hr><button class="btn-print" onclick="window.print()">🖨️ Imprimir / Guardar PDF</button>'
    + '</div></body></html>';

  const w = window.open('', '_blank');
  if (!w) { mostrarToast('Permite ventanas emergentes para ver el boletín', 'error'); return; }
  w.document.write(html);
  w.document.close();
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: REGISTRO DE INCIDENCIAS / REUNIONES / TUTORÍAS
// ════════════════════════════════════════════════════════════════════
const INCID_KEY = 'planificadorRA_incidencias_v1';
const INCID_TIPOS = [
  { id: 'reunion_familia', label: 'Reunión con familia', icono: 'people',        color: '#1565C0' },
  { id: 'tutoria',         label: 'Tutoría',             icono: 'school',        color: '#6A1B9A' },
  { id: 'incidencia',      label: 'Incidencia',          icono: 'warning',       color: '#C62828' },
  { id: 'seguimiento',     label: 'Seguimiento',         icono: 'track_changes', color: '#E65100' },
  { id: 'otro',            label: 'Otro',                icono: 'label',         color: '#546E7A' }
];
function cargarIncidencias() {
  try { return JSON.parse(localStorage.getItem(INCID_KEY) || '{}'); } catch { return {}; }
}
function guardarIncidencias(data) {
  localStorage.setItem(INCID_KEY, JSON.stringify(data));
  if (window._syncFirebase) _syncFirebase('incidencias', data);
}
function _getIncidenciasEst(estId) {
  const data = cargarIncidencias();
  return (data[estId] || []).slice().sort((a, b) => (b.fechaEvento || b.ts) > (a.fechaEvento || a.ts) ? 1 : -1);
}
function abrirIncidencias(estId) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso) return;
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;
  document.getElementById('inc-titulo').textContent = 'Eventos — ' + est.nombre;
  renderizarIncidencias(estId);
  document.getElementById('incidencias-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}
function cerrarIncidenciasBtn() {
  document.getElementById('incidencias-overlay').classList.add('hidden');
  document.body.style.overflow = '';
}
function cerrarIncidencias(e) {
  if (e.target === document.getElementById('incidencias-overlay')) cerrarIncidenciasBtn();
}
function renderizarIncidencias(estId) {
  const lista = _getIncidenciasEst(estId);
  const hoyISO = new Date().toISOString().split('T')[0];
  let html = '<div style="padding:1rem;">';

  if (lista.length === 0) {
    html += '<p style="color:#9E9E9E;font-size:0.88rem;text-align:center;padding:1rem 0;">No hay eventos registrados para este estudiante.</p>';
  } else {
    lista.forEach(inc => {
      const tipo = INCID_TIPOS.find(t => t.id === inc.tipo) || INCID_TIPOS[INCID_TIPOS.length-1];
      html += '<div style="background:#F8F9FA;border-radius:8px;border-left:4px solid ' + tipo.color + ';padding:10px 12px;margin-bottom:10px;">'
        + '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">'
        + '<span class="material-icons" style="font-size:16px;color:' + tipo.color + ';">' + tipo.icono + '</span>'
        + '<strong style="font-size:0.85rem;color:' + tipo.color + ';">' + escapeHTML(tipo.label) + '</strong>'
        + (inc.fechaEvento ? '<span style="font-size:0.78rem;color:#78909C;margin-left:4px;"> · ' + inc.fechaEvento + '</span>' : '')
        + '<button onclick="eliminarIncidencia(\'' + inc.id + '\',\'' + estId + '\')" style="margin-left:auto;background:none;border:none;cursor:pointer;color:#EF5350;padding:2px;" title="Eliminar"><span class="material-icons" style="font-size:16px;">delete</span></button>'
        + '</div>'
        + (inc.participantes ? '<div style="font-size:0.78rem;color:#546E7A;"><b>Participantes:</b> ' + escapeHTML(inc.participantes) + '</div>' : '')
        + (inc.descripcion ? '<div style="font-size:0.85rem;color:#37474F;margin-top:4px;">' + escapeHTML(inc.descripcion) + '</div>' : '')
        + (inc.acuerdos ? '<div style="font-size:0.8rem;color:#1565C0;margin-top:4px;"><b>Acuerdos:</b> ' + escapeHTML(inc.acuerdos) + '</div>' : '')
        + '</div>';
    });
  }

  html += '<div style="border-top:2px solid #E3F2FD;margin-top:1rem;padding-top:1rem;">'
    + '<h4 style="font-size:0.9rem;font-weight:700;color:#1565C0;margin-bottom:0.75rem;">+ Registrar nuevo evento</h4>'
    + '<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;">'
    + '<div><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Tipo</label>'
    + '<select id="inc-tipo" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;">'
    + INCID_TIPOS.map(t => '<option value="' + t.id + '">' + t.label + '</option>').join('')
    + '</select></div>'
    + '<div><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Fecha del evento</label>'
    + '<input type="date" id="inc-fecha" value="' + hoyISO + '" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;"></div>'
    + '</div>'
    + '<div style="margin-bottom:8px;"><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Participantes</label>'
    + '<input type="text" id="inc-participantes" placeholder="Ej: padre, madre, apoderado..." style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;"></div>'
    + '<div style="margin-bottom:8px;"><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Descripción</label>'
    + '<textarea id="inc-descripcion" rows="3" placeholder="¿Qué ocurrió? ¿De qué se trató?" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;resize:vertical;"></textarea></div>'
    + '<div style="margin-bottom:12px;"><label style="font-size:0.78rem;color:#546E7A;display:block;margin-bottom:3px;">Acuerdos / compromisos</label>'
    + '<textarea id="inc-acuerdos" rows="2" placeholder="¿Qué se acordó? ¿Cuáles son los próximos pasos?" style="width:100%;padding:6px 8px;border:1px solid #B0BEC5;border-radius:6px;font-size:0.85rem;resize:vertical;"></textarea></div>'
    + '<button onclick="guardarIncidenciaNueva(\'' + estId + '\')" style="width:100%;padding:10px;background:#1565C0;color:#fff;border:none;border-radius:8px;font-size:0.9rem;font-weight:600;cursor:pointer;">Guardar evento</button>'
    + '</div></div>';

  document.getElementById('inc-body').innerHTML = html;
}
function guardarIncidenciaNueva(estId) {
  const tipo = document.getElementById('inc-tipo')?.value;
  const fechaEvento = document.getElementById('inc-fecha')?.value;
  const participantes = (document.getElementById('inc-participantes')?.value || '').trim();
  const descripcion = (document.getElementById('inc-descripcion')?.value || '').trim();
  const acuerdos = (document.getElementById('inc-acuerdos')?.value || '').trim();
  if (!descripcion) { mostrarToast('Escribe al menos una descripción', 'error'); return; }
  const data = cargarIncidencias();
  if (!data[estId]) data[estId] = [];
  data[estId].push({ id: uid(), ts: Date.now(), fechaEvento, tipo, participantes, descripcion, acuerdos });
  guardarIncidencias(data);
  renderizarIncidencias(estId);
  renderizarTablaCalificaciones();
  mostrarToast('Evento registrado', 'success');
}
function eliminarIncidencia(incId, estId) {
  if (!confirm('¿Eliminar este evento?')) return;
  const data = cargarIncidencias();
  if (data[estId]) data[estId] = data[estId].filter(i => i.id !== incId);
  guardarIncidencias(data);
  renderizarIncidencias(estId);
  renderizarTablaCalificaciones();
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: VISTA DEL ESTUDIANTE (solo lectura + QR)
// ════════════════════════════════════════════════════════════════════
let _vistaEstUrl = '';
function abrirVistaEstudiante(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;

  const raKey = calState.raActivaKey || _getRaKey();
  const raInfo = curso.ras?.[raKey];
  const planActiva = _getPlanActivaDeCurso();
  let actividades = (planActiva && planActiva.actividades) || [];
  if (actividades.length === 0) actividades = raInfo?._actividadesSnapshot || [];
  const planDg = planActiva?.datosGenerales || {};
  const planRa = planActiva?.ra || {};
  const recupMap = _getRecuperacionesEst(cursoId, estId);

  const notaRA = _calcNotaRA(curso, estId, raKey);
  const notaRecupSum = actividades.reduce((sum, a) => {
    const r = recupMap[raKey + '__' + a.id];
    return sum + (r?.notaRecuperacion != null ? r.notaRecuperacion : 0);
  }, 0);
  const hasRecup = actividades.some(a => recupMap[raKey + '__' + a.id]?.notaRecuperacion != null);
  const tTotal = (notaRA !== null || hasRecup)
    ? Math.min((notaRA || 0) + notaRecupSum, raInfo?.valorTotal || 0)
    : null;

  const data = {
    n: est.nombre,
    c: curso.nombre || cursoId,
    m: (planDg.moduloFormativo || '').substring(0, 50),
    ra: (planRa.descripcion || '').substring(0, 100),
    vt: raInfo?.valorTotal || 0,
    f: new Date().toISOString().slice(0, 10),
    acts: actividades.map(a => {
      const r = recupMap[raKey + '__' + a.id];
      return {
        l: (a.enunciado || a.ecCodigo || '').substring(0, 50),
        v: raInfo?.valores?.[a.id] || 0,
        n: curso.notas?.[estId]?.[raKey]?.[a.id] ?? null,
        r: r?.notaRecuperacion ?? null,
        rs: r?.estado ?? null
      };
    }),
    tRA: notaRA,
    tTotal: tTotal,
    asist: _statsAsistencia(cursoId, estId).pct
  };

  const base = window.location.href.replace(/[#?].*$/, '').replace(/[^/]*$/, '');

  const b64Full = btoa(encodeURIComponent(JSON.stringify(data)));
  _vistaEstUrl = base + 'viewer.html#data=' + b64Full;

  document.getElementById('vista-est-titulo').textContent = est.nombre;
  document.getElementById('vista-est-url').value = _vistaEstUrl;

  document.getElementById('vista-est-overlay').classList.remove('hidden');
}
function cerrarVistaEstudianteBtn() {
  document.getElementById('vista-est-overlay').classList.add('hidden');
}
function cerrarVistaEstudiante(e) {
  if (e.target === document.getElementById('vista-est-overlay')) cerrarVistaEstudianteBtn();
}
function abrirVistaEstudianteTab() {
  window.open(_vistaEstUrl, '_blank');
}
function copiarLinkEstudiante() {
  const inp = document.getElementById('vista-est-url');
  if (navigator.clipboard && window.isSecureContext) {
    navigator.clipboard.writeText(_vistaEstUrl).then(() => {
      mostrarToast('Enlace copiado al portapapeles', 'success');
    }).catch(() => _copiarFallback(inp));
  } else {
    _copiarFallback(inp);
  }
}
function _copiarFallback(inp) {
  inp.select();
  inp.setSelectionRange(0, 99999);
  document.execCommand('copy');
  mostrarToast('Enlace copiado', 'success');
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: MODO RECUPERACIÓN / SEGUNDA OPORTUNIDAD
// ════════════════════════════════════════════════════════════════════
const RECUP_KEY = 'planificadorRA_recuperaciones_v1';
function cargarRecuperaciones() {
  try { return JSON.parse(localStorage.getItem(RECUP_KEY) || '{}'); } catch { return {}; }
}
function guardarRecuperaciones(data) {
  localStorage.setItem(RECUP_KEY, JSON.stringify(data));
  if (window._syncFirebase) _syncFirebase('recuperaciones', data);
}
function _getRecuperacionesEst(cursoId, estId) {
  return cargarRecuperaciones()[cursoId]?.[estId] || {};
}
function abrirRecuperaciones(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const est = (curso.estudiantes || []).find(e => e.id === estId);
  if (!est) return;
  // Limpiar entradas corruptas con actividadId 'undefined' (generadas antes del fix)
  const data = cargarRecuperaciones();
  let dirty = false;
  if (data[cursoId]?.[estId]) {
    Object.keys(data[cursoId][estId]).forEach(k => {
      if (k.endsWith('__undefined')) { delete data[cursoId][estId][k]; dirty = true; }
    });
    if (dirty) guardarRecuperaciones(data);
  }
  document.getElementById('recup-titulo').textContent = 'Recuperaciones — ' + est.nombre;
  document.getElementById('recuperaciones-overlay')._estId = estId;
  renderizarRecuperaciones(estId);
  document.getElementById('recuperaciones-overlay').classList.remove('hidden');
}
function cerrarRecuperacionesBtn() {
  document.getElementById('recuperaciones-overlay').classList.add('hidden');
}
function cerrarRecuperaciones(e) {
  if (e.target === document.getElementById('recuperaciones-overlay')) cerrarRecuperacionesBtn();
}
function renderizarRecuperaciones(estId) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const raKey = calState.raActivaKey || _getRaKey();
  const raInfo = curso.ras?.[raKey];
  if (!raInfo) {
    document.getElementById('recup-body').innerHTML = '<p style="padding:1rem;color:#9E9E9E;">Sin RA activo.</p>';
    return;
  }
  // Actividades como objetos {id, enunciado, ecCodigo, ...}
  const planActiva = _getPlanActivaDeCurso();
  let actividades = (planActiva && planActiva.actividades) || [];
  if (actividades.length === 0) actividades = raInfo._actividadesSnapshot || [];
  const recupMap = _getRecuperacionesEst(cursoId, estId);
  let html = '<div style="padding:12px 16px;">';
  if (actividades.length === 0) {
    html += '<p style="color:#9E9E9E;">Este RA no tiene actividades definidas.</p>';
  } else {
    actividades.forEach(a => {
      const max = raInfo.valores?.[a.id] || 100;
      const nota = curso.notas?.[estId]?.[raKey]?.[a.id];
      const notaStr = nota !== undefined ? nota.toFixed(1) : '—';
      const pct = nota !== undefined ? (nota / max) * 100 : null;
      const emoji = pct === null ? '⬜' : (pct >= 70 ? '✅' : (pct >= 50 ? '🟡' : '❌'));
      const recKey = raKey + '__' + a.id;
      const recup = recupMap[recKey];
      html += '<div style="border:1px solid #2a2a3a;border-radius:8px;padding:12px 14px;margin-bottom:10px;background:#1a1a2a;">';
      html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
        + '<span style="font-weight:600;flex:1;font-size:0.88rem;">' + escapeHTML((a.enunciado || ('Act. ' + a.id)).substring(0, 60)) + '</span>'
        + '<span style="font-size:1.1rem;">' + emoji + '</span>'
        + '<span style="color:#B0BEC5;font-size:0.82rem;white-space:nowrap;">Nota: <strong>' + notaStr + '</strong> / ' + max + '</span>'
        + '</div>';
      if (recup) {
        const isPendiente = recup.estado === 'pendiente';
        const colorEstado = isPendiente ? '#FF8F00' : '#2E7D32';
        const bgEstado = isPendiente ? 'rgba(255,143,0,0.12)' : 'rgba(46,125,50,0.12)';
        html += '<div style="background:' + bgEstado + ';border-radius:6px;padding:10px 12px;">';
        html += '<div style="display:flex;align-items:center;gap:6px;margin-bottom:8px;">'
          + '<span class="material-icons" style="font-size:15px;color:' + colorEstado + ';">' + (isPendiente ? 'schedule' : 'check_circle') + '</span>'
          + '<strong style="color:' + colorEstado + ';font-size:0.85rem;">' + (isPendiente ? 'PENDIENTE' : 'COMPLETADA') + '</strong>'
          + '<span style="color:#9E9E9E;font-size:0.8rem;margin-left:4px;">· Vence: ' + (recup.fechaLimite || '—') + '</span>'
          + '</div>';
        html += '<div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">'
          + '<label style="font-size:0.82rem;color:#CFD8DC;">Nota recuperación (0–' + max + '):</label>'
          + '<input type="number" id="recup-nota-' + a.id + '" min="0" max="' + max + '" step="0.5" placeholder="—"'
          + ' value="' + (recup.notaRecuperacion !== null && recup.notaRecuperacion !== undefined ? recup.notaRecuperacion : '') + '"'
          + ' style="width:80px;padding:4px 6px;border-radius:4px;border:1px solid #444;background:#0e0e1a;color:#fff;font-size:0.9rem;"'
          + ' onwheel="event.preventDefault()" /></div>';
        html += '<div style="display:flex;gap:8px;">'
          + '<button onclick="guardarRecuperacion(\'' + estId + '\',\'' + a.id + '\',\'' + recKey + '\')" style="padding:5px 12px;background:#1565C0;color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:13px;">save</span>Guardar nota</button>'
          + '<button onclick="quitarRecuperacion(\'' + estId + '\',\'' + recKey + '\')" style="padding:5px 12px;background:none;color:#EF5350;border:1px solid #EF5350;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:13px;">close</span>Quitar</button>'
          + '</div></div>';
      } else {
        html += '<div id="recup-form-' + a.id + '">'
          + '<button onclick="_abrirFormRecup(\'' + a.id + '\')" style="padding:5px 12px;background:none;color:#E65100;border:1px solid #E65100;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;">'
          + '<span class="material-icons" style="font-size:13px;">replay</span>Marcar para recuperar</button>'
          + '</div>';
      }
      html += '</div>';
    });
  }
  html += '</div>';
  document.getElementById('recup-body').innerHTML = html;
}
// Calcula cuántos puntos de recuperación quedan disponibles para un estudiante
// en el RA activo, excluyendo opcionalmente la actividad que se está editando.
function _calcMaxRecupPermitida(cursoId, estId, raKey, excludeActId) {
  const curso = calState.cursos[cursoId];
  const raInfo = curso?.ras?.[raKey];
  if (!raInfo) return 0;
  const notaRA = _calcNotaRA(curso, estId, raKey) || 0;
  const planActiva = _getPlanActivaDeCurso();
  let acts = (planActiva && planActiva.actividades) || [];
  if (acts.length === 0) acts = raInfo._actividadesSnapshot || [];
  const data = cargarRecuperaciones();
  const otrasRecup = acts.reduce((sum, a) => {
    if (a.id === excludeActId) return sum;
    const r = data[cursoId]?.[estId]?.[raKey + '__' + a.id];
    return sum + (r?.notaRecuperacion != null ? r.notaRecuperacion : 0);
  }, 0);
  return Math.max(0, raInfo.valorTotal - notaRA - otrasRecup);
}
function _abrirFormRecup(actId) {
  const overlay = document.getElementById('recuperaciones-overlay');
  const estId = overlay._estId;
  const cursoId = calState.cursoActivoId;
  const raKey = calState.raActivaKey || _getRaKey();
  const raInfo = calState.cursos[cursoId]?.ras?.[raKey];
  const maxRecup = _calcMaxRecupPermitida(cursoId, estId, raKey, actId);
  const hoy = new Date().toISOString().slice(0, 10);
  const div = document.getElementById('recup-form-' + actId);
  if (!div) return;
  div.innerHTML = '<div style="background:rgba(230,81,0,0.08);border:1px solid #E65100;border-radius:6px;padding:10px 12px;">'
    + '<div style="display:flex;gap:10px;align-items:flex-end;flex-wrap:wrap;margin-bottom:8px;">'
    + '<div><label style="font-size:0.78rem;color:#CFD8DC;display:block;margin-bottom:3px;">Fecha límite</label>'
    + '<input type="date" id="recup-fecha-' + actId + '" value="' + hoy + '" style="padding:4px 6px;border-radius:4px;border:1px solid #E65100;background:#0e0e1a;color:#fff;font-size:0.88rem;" /></div>'
    + '<div><label style="font-size:0.78rem;color:#CFD8DC;display:block;margin-bottom:3px;">Nota <span style="color:#FF8F00;">(máx. ' + maxRecup.toFixed(1) + ' pts)</span></label>'
    + '<input type="number" id="recup-nota-inline-' + actId + '" min="0" max="' + maxRecup + '" step="0.5" placeholder="—" style="width:80px;padding:4px 6px;border-radius:4px;border:1px solid #444;background:#0e0e1a;color:#fff;font-size:0.88rem;" onwheel="event.preventDefault()" /></div>'
    + '</div>'
    + (maxRecup <= 0 ? '<p style="color:#EF5350;font-size:0.8rem;margin:0 0 8px;">⚠ El estudiante ya alcanzó el máximo del RA. No hay margen de recuperación.</p>' : '')
    + '<div style="display:flex;gap:8px;">'
    + '<button onclick="guardarNuevaRecuperacion(\'' + estId + '\',\'' + actId + '\',\'' + (raKey + '__' + actId) + '\')" style="padding:5px 12px;background:#E65100;color:#fff;border:none;border-radius:5px;cursor:pointer;font-size:0.82rem;display:flex;align-items:center;gap:4px;"><span class="material-icons" style="font-size:13px;">save</span>Guardar</button>'
    + '<button onclick="renderizarRecuperaciones(\'' + estId + '\')" style="padding:5px 12px;background:none;color:#9E9E9E;border:1px solid #9E9E9E;border-radius:5px;cursor:pointer;font-size:0.82rem;">Cancelar</button>'
    + '</div></div>';
}
function guardarNuevaRecuperacion(estId, actId, recKey) {
  const cursoId = calState.cursoActivoId;
  const raKey = calState.raActivaKey || _getRaKey();
  const fecha = (document.getElementById('recup-fecha-' + actId)?.value || '').trim();
  const notaVal = (document.getElementById('recup-nota-inline-' + actId)?.value || '').trim();
  const nota = notaVal !== '' ? parseFloat(notaVal) : null;
  if (!fecha) { mostrarToast('Indica una fecha límite', 'error'); return; }
  if (nota !== null) {
    const maxRecup = _calcMaxRecupPermitida(cursoId, estId, raKey, actId);
    if (nota > maxRecup) {
      mostrarToast('La nota excede el límite del RA. Máximo permitido: ' + maxRecup.toFixed(1) + ' pts', 'error');
      return;
    }
  }
  const data = cargarRecuperaciones();
  if (!data[cursoId]) data[cursoId] = {};
  if (!data[cursoId][estId]) data[cursoId][estId] = {};
  data[cursoId][estId][recKey] = {
    id: recKey, actividadId: actId, raKey,
    notaRecuperacion: nota,
    fechaLimite: fecha,
    estado: nota !== null ? 'completada' : 'pendiente'
  };
  guardarRecuperaciones(data);
  renderizarRecuperaciones(estId);
  renderizarTablaCalificaciones();
  mostrarToast('Recuperación registrada', 'success');
}
function guardarRecuperacion(estId, actId, recKey) {
  const cursoId = calState.cursoActivoId;
  const raKey = calState.raActivaKey || _getRaKey();
  const notaVal = (document.getElementById('recup-nota-' + actId)?.value || '').trim();
  const nota = notaVal !== '' ? parseFloat(notaVal) : null;
  if (nota !== null) {
    const maxRecup = _calcMaxRecupPermitida(cursoId, estId, raKey, actId);
    if (nota > maxRecup) {
      mostrarToast('La nota excede el límite del RA. Máximo permitido: ' + maxRecup.toFixed(1) + ' pts', 'error');
      return;
    }
  }
  const data = cargarRecuperaciones();
  if (!data[cursoId]?.[estId]?.[recKey]) return;
  data[cursoId][estId][recKey].notaRecuperacion = nota;
  data[cursoId][estId][recKey].estado = nota !== null ? 'completada' : 'pendiente';
  guardarRecuperaciones(data);
  renderizarRecuperaciones(estId);
  renderizarTablaCalificaciones();
  mostrarToast('Nota de recuperación guardada', 'success');
}
function quitarRecuperacion(estId, recKey) {
  if (!confirm('¿Quitar esta recuperación?')) return;
  const cursoId = calState.cursoActivoId;
  const data = cargarRecuperaciones();
  if (data[cursoId]?.[estId]) {
    delete data[cursoId][estId][recKey];
    if (Object.keys(data[cursoId][estId]).length === 0) delete data[cursoId][estId];
    if (Object.keys(data[cursoId]).length === 0) delete data[cursoId];
  }
  guardarRecuperaciones(data);
  renderizarRecuperaciones(estId);
  renderizarTablaCalificaciones();
  mostrarToast('Recuperación eliminada', 'success');
}







