// Cache de avisos del director para el docente actual
let _avisosDocenteCache = [];
let _avisosDocenteCargados = false;

/** Carga los avisos del centro del docente y actualiza el badge */
async function _cargarAvisosDocente() {
  if (!window.currentUser) return;
  try {
    const perfilDoc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    const centroId = perfilDoc.exists ? perfilDoc.data().centroId : null;
    if (!centroId) return;
    const snap = await db.collection('centros').doc(centroId).collection('avisos')
      .orderBy('fecha', 'desc').limit(30).get();
    _avisosDocenteCache = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    _avisosDocenteCargados = true;
    actualizarBadgeNotificaciones();
  } catch(e) { console.warn('Error cargando avisos docente:', e); }
}

// IDs de notificaciones app ya vistas (se puebla al abrir el modal)
let _notifIdsVistos = new Set();
// IDs de avisos del director ya vistos
let _avisosIdsVistos = new Set();

/** Cuenta ítems nuevos desde que el usuario abrió la campana por última vez */
function _contarNuevosAvisosYNovedades() {
  const lastNov = localStorage.getItem('tinclass_novedades_check') || '2000-01-01';
  const nuevasNov = NOVEDADES_SISTEMA.filter(n => n.fecha > lastNov).length;
  const nuevosDir = _avisosDocenteCache.filter(a => !_avisosIdsVistos.has(a.id)).length;
  return nuevasNov + nuevosDir;
}

// Genera la lista de notificaciones activas
function _generarNotificaciones() {
  const notifs = [];
  const hoy = new Date(); hoy.setHours(0, 0, 0, 0);
  const ahora = new Date();

  // ── 1. Tareas vencidas ──────────────────────────────────────────
  const tareas = cargarTareas();
  const tvenc = tareas.filter(t => t.estado !== 'entregada' && t.fechaVencimiento &&
    new Date(t.fechaVencimiento).setHours(0, 0, 0, 0) < hoy.getTime());
  if (tvenc.length) {
    notifs.push({
      id: 'tareas_vencidas', tipo: 'error', icono: 'assignment_late',
      titulo: `${tvenc.length} tarea(s) vencida(s)`,
      detalle: tvenc.map(t => `• ${t.descripcion || 'Sin descripción'} (${t.seccion || ''})`).join('\n'),
      accion: { label: 'Ver tareas', fn: 'abrirTareas' }
    });
  }

  // ── 2. Tareas que vencen hoy ────────────────────────────────────
  const thoy = tareas.filter(t => t.estado !== 'entregada' && t.fechaVencimiento &&
    new Date(t.fechaVencimiento + 'T12:00:00').setHours(0, 0, 0, 0) === hoy.getTime());
  if (thoy.length) {
    notifs.push({
      id: 'tareas_hoy', tipo: 'warning', icono: 'alarm',
      titulo: `${thoy.length} tarea(s) vencen hoy`,
      detalle: thoy.map(t => `• ${t.descripcion || 'Sin descripción'} (${t.seccion || ''})`).join('\n'),
      accion: { label: 'Ver tareas', fn: 'abrirTareas' }
    });
  }

  // ── 3. Tareas que vencen mañana ─────────────────────────────────
  const manana = new Date(hoy); manana.setDate(manana.getDate() + 1);
  const tman = tareas.filter(t => t.estado !== 'entregada' && t.fechaVencimiento &&
    new Date(t.fechaVencimiento + 'T12:00:00').setHours(0, 0, 0, 0) === manana.getTime());
  if (tman.length) {
    notifs.push({
      id: 'tareas_manana', tipo: 'warning', icono: 'event',
      titulo: `${tman.length} tarea(s) vencen mañana`,
      detalle: tman.map(t => `• ${t.descripcion || 'Sin descripción'} (${t.seccion || ''})`).join('\n'),
      accion: { label: 'Ver tareas', fn: 'abrirTareas' }
    });
  }

  // ── 4. Cursos sin planificación asignada ────────────────────────
  const _biblioIds = new Set((cargarBiblioteca().items || []).map(i => i.id));
  const sinPlan = Object.values(calState.cursos).filter(c =>
    !(c.planIds || []).some(pid => _biblioIds.has(pid))
  );
  if (sinPlan.length) {
    notifs.push({
      id: 'cursos_sin_plan', tipo: 'info', icono: 'folder_off',
      titulo: `${sinPlan.length} curso(s) sin planificación`,
      detalle: sinPlan.map(c => `• ${c.nombre}`).join('\n'),
      accion: { label: 'Ver calificaciones', fn: 'abrirCalificaciones' }
    });
  }

  // ── 5. Asistencia no pasada hace 2+ días hábiles ────────────────
  const horario = cargarHorario().filter(e => e.materia);
  const asistData = cargarAsistencia();
  const cursosConHorario = {};
  horario.forEach(e => {
    if (e.seccion) cursosConHorario[e.seccion] = true;
  });
  const cursosAlerta = [];
  Object.values(calState.cursos).forEach(curso => {
    if (!cursosConHorario[curso.nombre]) return;
    if (!curso.estudiantes?.length) return;
    const diasAsist = Object.keys((asistData[curso.id] || {})).sort().reverse();
    if (!diasAsist.length) {
      cursosAlerta.push({ nombre: curso.nombre, dias: 'nunca' });
    } else {
      const ultima = new Date(diasAsist[0] + 'T12:00:00');
      const diffDias = Math.round((hoy - ultima) / 86400000);
      if (diffDias > 2) cursosAlerta.push({ nombre: curso.nombre, dias: diffDias });
    }
  });
  if (cursosAlerta.length) {
    notifs.push({
      id: 'asist_pendiente', tipo: 'warning', icono: 'how_to_reg',
      titulo: `Asistencia pendiente en ${cursosAlerta.length} curso(s)`,
      detalle: cursosAlerta.map(c =>
        `• ${c.nombre}: ${c.dias === 'nunca' ? 'nunca registrada' : `hace ${c.dias} días`}`
      ).join('\n'),
      accion: { label: 'Ir a calificaciones', fn: 'abrirCalificaciones' }
    });
  }

  // ── 6. Estudiantes bajo umbral de asistencia ────────────────────
  const umbral = parseInt(localStorage.getItem('asist_umbral') || '80');
  const bajosUmbral = [];
  Object.values(calState.cursos).forEach(curso => {
    (curso.estudiantes || []).forEach(est => {
      const s = _statsAsistencia(curso.id, est.id);
      if (s.pct !== null && s.pct < umbral && s.total >= 3) {
        bajosUmbral.push({ nombre: est.nombre, curso: curso.nombre, pct: s.pct });
      }
    });
  });
  if (bajosUmbral.length) {
    bajosUmbral.sort((a, b) => a.pct - b.pct);
    notifs.push({
      id: 'bajo_umbral', tipo: 'error', icono: 'person_off',
      titulo: `${bajosUmbral.length} estudiante(s) bajo ${umbral}% de asistencia`,
      detalle: bajosUmbral.slice(0, 6).map(e =>
        `• ${e.nombre} (${e.curso}): ${e.pct}%`
      ).join('\n') + (bajosUmbral.length > 6 ? `\n  …y ${bajosUmbral.length - 6} más` : ''),
      accion: { label: 'Ver asistencia', fn: 'abrirCalificaciones' }
    });
  }

  // ── 7. Clases de hoy sin actividad planificada ─────────────────
  const diasMap = [null, 'Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes'];
  const diaJS = ahora.getDay();
  if (diaJS >= 1 && diaJS <= 5) {
    const diaIdx = diaJS - 1;
    const clasesHoy = cargarHorario().filter(e => e.dia === diaIdx && e.materia);
    const biblio = cargarBiblioteca();
    const hoyISO = hoy.toISOString().split('T')[0];
    const sinPlanHoy = [];
    clasesHoy.forEach(e => {
      const tienePlan = (biblio.items || []).some(reg => {
        const cursosConReg = Object.values(calState.cursos).filter(c => (c.planIds || []).includes(reg.id));
        return cursosConReg.some(c => c.nombre === e.seccion) &&
          (reg.planificacion?.actividades || []).some(act => act.fecha === hoyISO);
      });
      if (!tienePlan) sinPlanHoy.push(`P${e.periodo}: ${e.materia}${e.seccion ? ' — ' + e.seccion : ''}`);
    });
    if (sinPlanHoy.length) {
      notifs.push({
        id: 'sin_plan_hoy', tipo: 'info', icono: 'event_note',
        titulo: `${sinPlanHoy.length} clase(s) de hoy sin actividad planificada`,
        detalle: sinPlanHoy.map(s => `• ${s}`).join('\n'),
        accion: { label: 'Ir a planificaciones', fn: 'abrirPlanificaciones' }
      });
    }
  }

  // ── 8. Notas pendientes de registrar ───────────────────────────
  let actsSinNota = 0;
  Object.values(calState.cursos).forEach(curso => {
    Object.values(curso.ras || {}).forEach(ra => {
      (ra.actividades || []).forEach(actId => {
        const hayNota = (curso.estudiantes || []).some(e => {
          const n = curso.notas?.[e.id];
          return n && Object.values(n).some(rn => rn && rn[actId] !== undefined);
        });
        if (!hayNota) actsSinNota++;
      });
    });
  });
  if (actsSinNota > 0) {
    notifs.push({
      id: 'notas_pendientes', tipo: 'info', icono: 'grading',
      titulo: `${actsSinNota} actividad(es) sin notas registradas`,
      detalle: 'Hay actividades en el libro de calificaciones que todavía no tienen notas.',
      accion: { label: 'Ir a calificaciones', fn: 'abrirCalificaciones' }
    });
  }

  return notifs;
}

// ── Actualizar badge del header ──────────────────────────────────
function actualizarBadgeNotificaciones() {
  const notifs = _generarNotificaciones();
  // Solo contar alertas de app que NO fueron vistas en la última apertura del modal
  const nuevasApp = notifs.filter(n =>
    (n.tipo === 'error' || n.tipo === 'warning') && !_notifIdsVistos.has(n.id)
  ).length;
  const extras = _contarNuevosAvisosYNovedades();
  const total = nuevasApp + extras;
  const badge = document.getElementById('notif-badge');
  if (!badge) return;
  if (total > 0) {
    badge.style.display = 'flex';
    badge.textContent = total > 9 ? '9+' : total;
  } else {
    badge.style.display = 'none';
  }
}

// ── Abrir/cerrar modal ───────────────────────────────────────────
function abrirNotificaciones() {
  const overlay = document.getElementById('notif-overlay');
  if (!overlay) return;
  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  // Marcar como leído: guardar IDs de lo que está visible ahora
  const notifActuales = _generarNotificaciones();
  _notifIdsVistos = new Set(notifActuales.map(n => n.id));
  _avisosIdsVistos = new Set(_avisosDocenteCache.map(a => a.id));
  localStorage.setItem('tinclass_novedades_check', new Date().toISOString().split('T')[0]);
  _renderizarNotificaciones();
  _renderizarAvisosYNovedades();
  setTimeout(actualizarBadgeNotificaciones, 200);
}
function cerrarNotificaciones() {
  document.getElementById('notif-overlay')?.classList.add('hidden');
  document.body.style.overflow = '';
}

/** Renderiza avisos del director + novedades del sistema en el panel superior */
async function _renderizarAvisosYNovedades() {
  const top = document.getElementById('notif-top-body');
  if (!top) return;
  top.innerHTML = '<div style="color:#90A4AE;font-size:0.78rem;padding:4px 0 8px;">Cargando avisos...</div>';

  // Cargar avisos del director si no están en caché
  if (!_avisosDocenteCargados) await _cargarAvisosDocente();

  let html = '';

  // ── Avisos del director ──────────────────────────────────────────
  if (_avisosDocenteCache.length > 0) {
    const prioColors = { urgente: '#C62828', importante: '#E65100', normal: '#4A148C' };
    const prioIcons  = { urgente: 'priority_high', importante: 'campaign', normal: 'campaign' };
    html += '<div style="margin-bottom:14px;">'
      + '<div style="font-size:0.72rem;font-weight:700;color:#4A148C;letter-spacing:.04em;text-transform:uppercase;margin-bottom:8px;display:flex;align-items:center;gap:4px;">'
      + '<span class="material-icons" style="font-size:14px;">campaign</span> Avisos del centro</div>';
    _avisosDocenteCache.slice(0, 5).forEach(a => {
      const color = prioColors[a.prioridad] || prioColors.normal;
      const icon  = prioIcons[a.prioridad]  || prioIcons.normal;
      const fecha = a.fecha ? new Date(a.fecha).toLocaleDateString('es-DO', { day:'2-digit', month:'short', year:'numeric' }) : '';
      html += '<div style="background:#F3E5F5;border-left:4px solid ' + color + ';border-radius:8px;padding:10px 12px;margin-bottom:8px;">'
        + '<div style="display:flex;align-items:center;gap:6px;margin-bottom:4px;">'
        + '<span class="material-icons" style="font-size:15px;color:' + color + ';">' + icon + '</span>'
        + '<span style="font-weight:700;font-size:0.88rem;color:#212121;flex:1;">' + escapeHTML(a.titulo || 'Aviso') + '</span>'
        + '<span style="font-size:0.72rem;color:#9E9E9E;">' + fecha + '</span>'
        + '</div>'
        + '<div style="font-size:0.82rem;color:#424242;white-space:pre-wrap;">' + escapeHTML(a.mensaje || '') + '</div>'
        + '<div style="font-size:0.7rem;color:#AB47BC;margin-top:4px;">— ' + escapeHTML(a.enviadoPor || '') + '</div>'
        + '</div>';
    });
    if (_avisosDocenteCache.length > 5) {
      html += '<div style="font-size:0.75rem;color:#9E9E9E;text-align:center;">…y ' + (_avisosDocenteCache.length - 5) + ' aviso(s) más en el Panel Director</div>';
    }
    html += '</div>';
  }

  // ── Novedades del sistema ────────────────────────────────────────
  const lastNov = localStorage.getItem('tinclass_novedades_check') || '2000-01-01';
  if (NOVEDADES_SISTEMA.length > 0) {
    html += '<div style="margin-bottom:6px;">'
      + '<div style="font-size:0.72rem;font-weight:700;color:#1565C0;letter-spacing:.04em;text-transform:uppercase;margin-bottom:8px;display:flex;align-items:center;gap:4px;">'
      + '<span class="material-icons" style="font-size:14px;">new_releases</span> Novedades del sistema</div>';
    NOVEDADES_SISTEMA.slice(0, 5).forEach(n => {
      const esNueva = n.fecha >= lastNov;
      html += '<div style="background:' + (esNueva ? '#E3F2FD' : '#FAFAFA') + ';border:1px solid ' + (esNueva ? '#90CAF9' : '#E0E0E0') + ';border-radius:8px;padding:9px 12px;margin-bottom:8px;display:flex;gap:10px;align-items:flex-start;">'
        + '<span class="material-icons" style="font-size:18px;color:' + (esNueva ? '#1565C0' : '#B0BEC5') + ';flex-shrink:0;margin-top:1px;">system_update_alt</span>'
        + '<div style="flex:1;">'
        + '<div style="font-weight:700;font-size:0.85rem;color:#212121;">' + escapeHTML(n.titulo)
        + (esNueva ? ' <span style="background:#1565C0;color:#fff;padding:0 6px;border-radius:8px;font-size:0.65rem;font-weight:700;vertical-align:middle;">NUEVO</span>' : '') + '</div>'
        + '<div style="font-size:0.78rem;color:#546E7A;margin-top:2px;">' + escapeHTML(n.desc) + '</div>'
        + '<div style="font-size:0.68rem;color:#B0BEC5;margin-top:2px;">' + n.fecha + ' · ' + n.id.split('_')[0].toUpperCase() + '</div>'
        + '</div></div>';
    });
    html += '</div>';
  }

  if (!html) {
    top.innerHTML = '';
    return;
  }
  top.innerHTML = html;
}

function _renderizarNotificaciones() {
  const body = document.getElementById('notif-modal-body');
  const header = document.getElementById('notif-count-header');
  if (!body) return;
  const notifs = _generarNotificaciones();
  if (header) header.textContent = notifs.length ? `${notifs.length} aviso(s)` : '';

  if (!notifs.length) {
    body.innerHTML = `
      <div style="text-align:center;padding:40px 20px;color:#B0BEC5;">
        <span class="material-icons" style="font-size:3rem;display:block;margin-bottom:10px;opacity:0.4;">check_circle</span>
        <p style="font-size:0.92rem;font-weight:700;color:#78909C;">Todo en orden 🎉</p>
        <p style="font-size:0.78rem;margin-top:4px;">No hay avisos ni recordatorios pendientes.</p>
      </div>`;
    return;
  }

  const COLORES = {
    error: { bg: '#FFEBEE', border: '#FFCDD2', icon: '#C62828', label: 'bg:#FFCDD2;color:#C62828' },
    warning: { bg: '#FFF8E1', border: '#FFE082', icon: '#E65100', label: 'bg:#FFF3E0;color:#E65100' },
    info: { bg: '#E3F2FD', border: '#90CAF9', icon: '#1565C0', label: 'bg:#E3F2FD;color:#1565C0' },
  };

  // Agrupar: errores primero, luego warnings, luego info
  const orden = ['error', 'warning', 'info'];
  const ordenados = orden.flatMap(tipo => notifs.filter(n => n.tipo === tipo));

  body.innerHTML = ordenados.map(n => {
    const c = COLORES[n.tipo];
    const lineas = n.detalle ? n.detalle.split('\n') : [];
    return `
    <div class="notif-item notif-tipo-${n.tipo}" style="background:${c.bg};border-color:${c.border};">
      <div class="notif-item-header">
        <span class="material-icons notif-icono" style="color:${c.icon};">${n.icono}</span>
        <span class="notif-titulo">${n.titulo}</span>
      </div>
      ${lineas.length ? `
      <div class="notif-detalle">
        ${lineas.slice(0, 5).map(l => `<div>${escapeHTML(l)}</div>`).join('')}
        ${lineas.length > 5 ? `<div style="color:#9E9E9E;font-size:0.7rem;">…y ${lineas.length - 5} más</div>` : ''}
      </div>` : ''}
      ${n.accion ? `
      <button class="notif-accion-btn" style="${n.tipo === 'error' ? 'background:#FFCDD2;color:#C62828;' : n.tipo === 'warning' ? 'background:#FFE082;color:#E65100;' : 'background:#BBDEFB;color:#1565C0;'}"
        onclick="cerrarNotificaciones();${n.accion.fn}();">
        <span class="material-icons" style="font-size:14px;">arrow_forward</span> ${n.accion.label}
      </button>` : ''}
    </div>`;
  }).join('');
}


// ════════════════════════════════════════════════════════════════════
// MÓDULO: PARTICIPACIÓN EN CLASE
// ════════════════════════════════════════════════════════════════════
const PARTICIP_KEY = 'planificadorRA_participacion_v1';
let _participPanelAbierto = false;
let _participFechaSeleccionada = null;

function cargarParticipacion() {
  try { return JSON.parse(localStorage.getItem(PARTICIP_KEY) || '{}'); } catch { return {}; }
}

function guardarParticipacion(data) {
  localStorage.setItem(PARTICIP_KEY, JSON.stringify(data));
  if (window._syncFirebase) _syncFirebase('participacion', data);
}

function toggleVistaParticipacion() {
  const panel = document.getElementById('cal-particip-panel');
  const btn = document.getElementById('btn-toggle-participacion');
  if (!panel) return;
  _participPanelAbierto = !_participPanelAbierto;
  panel.classList.toggle('hidden', !_participPanelAbierto);
  if (btn) {
    btn.style.background = _participPanelAbierto ? '#6A1B9A' : '#F3E5F5';
    btn.style.color = _participPanelAbierto ? '#fff' : '#6A1B9A';
    btn.style.borderColor = _participPanelAbierto ? '#6A1B9A' : '#CE93D8';
  }
  if (_participPanelAbierto) {
    _participFechaSeleccionada = null;
    renderizarParticipacion();
  }
}

function renderizarParticipacion() {
  const wrap = document.getElementById('cal-particip-wrap');
  if (!wrap) return;
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !(curso.estudiantes || []).length) {
    wrap.innerHTML = '<div class="asist-empty"><span class="material-icons">group_off</span><p>Sin estudiantes en este curso.</p></div>';
    return;
  }
  const hoy = new Date().toISOString().split('T')[0];
  const fecha = _participFechaSeleccionada || hoy;
  const data = cargarParticipacion();
  const diaData = (data[calState.cursoActivoId] || {})[fecha] || {};
  const fechaFmt = new Date(fecha + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
  const counts = { D: 0, P: 0, N: 0 };
  curso.estudiantes.forEach(e => { const v = diaData[e.id]; if (v) counts[v] = (counts[v] || 0) + 1; });
  const registrados = Object.keys(diaData).length;

  wrap.innerHTML = `
    <div class="asist-fecha-header">
      <span class="material-icons">today</span>
      <span>${fechaFmt}</span>
      <input type="date" value="${fecha}" onchange="_cambiarFechaParticip(this.value)"
        style="margin-left:auto;padding:5px 10px;border:1.5px solid #CE93D8;border-radius:8px;font-size:0.82rem;">
    </div>
    <div class="asist-summary-bar">
      <div class="asist-sum-item" style="color:#6A1B9A;"><span class="material-icons">star</span>${counts.D} <span>Destacado</span></div>
      <div class="asist-sum-item" style="color:#2E7D32;"><span class="material-icons">check_circle</span>${counts.P} <span>Participó</span></div>
      <div class="asist-sum-item" style="color:#C62828;"><span class="material-icons">cancel</span>${counts.N} <span>No participó</span></div>
      <div class="asist-sum-item" style="color:#546E7A;"><span class="material-icons">group</span>${registrados}/${curso.estudiantes.length} <span>Registrados</span></div>
    </div>
    <div class="asist-acciones-rapidas">
      <button class="asist-btn-todos" onclick="_marcarTodosParticip('P')" style="border-color:#A5D6A7;color:#2E7D32;">
        <span class="material-icons">done_all</span> Todos participaron
      </button>
      <button class="asist-btn-todos" onclick="_limpiarDiaParticip()" style="border-color:#E0E0E0;color:#757575;">
        <span class="material-icons">clear_all</span> Limpiar día
      </button>
      <button class="asist-btn-todos" onclick="_abrirHistorialParticipacion()" style="border-color:#90CAF9;color:#1565C0;margin-left:auto;">
        <span class="material-icons">table_chart</span> Historial
      </button>
    </div>
    <div class="asist-lista" id="particip-lista-body">
      ${curso.estudiantes.map((est, i) => {
        const v = diaData[est.id] || '';
        return `<div class="asist-fila" id="particip-fila-${est.id}">
          <div class="asist-num">${i + 1}</div>
          <div class="asist-nombre">${escapeHTML(est.nombre)}</div>
          <div class="asist-btns">
            <button class="particip-btn D ${v === 'D' ? 'activo' : ''}" onclick="marcarParticipacion('${est.id}','D')" title="Destacado">
              <span class="material-icons">star</span>Destacado
            </button>
            <button class="particip-btn P ${v === 'P' ? 'activo' : ''}" onclick="marcarParticipacion('${est.id}','P')" title="Participó">
              <span class="material-icons">check_circle</span>Participó
            </button>
            <button class="particip-btn N ${v === 'N' ? 'activo' : ''}" onclick="marcarParticipacion('${est.id}','N')" title="No participó">
              <span class="material-icons">cancel</span>No participó
            </button>
          </div>
        </div>`;
      }).join('')}
    </div>`;
}

function _cambiarFechaParticip(fecha) {
  _participFechaSeleccionada = fecha;
  renderizarParticipacion();
}

function marcarParticipacion(estudianteId, estado, fechaOverride) {
  const cursoId = calState.cursoActivoId;
  const fecha = fechaOverride || (_participFechaSeleccionada || new Date().toISOString().split('T')[0]);
  const data = cargarParticipacion();
  if (!data[cursoId]) data[cursoId] = {};
  if (!data[cursoId][fecha]) data[cursoId][fecha] = {};
  // Toggle: click mismo estado lo quita
  if (data[cursoId][fecha][estudianteId] === estado) {
    delete data[cursoId][fecha][estudianteId];
  } else {
    data[cursoId][fecha][estudianteId] = estado;
  }
  guardarParticipacion(data);
  // Actualizar fila sin re-render completo
  const fila = document.getElementById('particip-fila-' + estudianteId);
  if (fila) {
    const v = data[cursoId][fecha][estudianteId] || '';
    fila.querySelectorAll('.particip-btn').forEach(btn => {
      btn.classList.toggle('activo', btn.classList.contains(v));
    });
  }
  // Actualizar summary counts
  const diaData = (data[cursoId] || {})[fecha] || {};
  const curso = calState.cursos[cursoId];
  const counts = { D: 0, P: 0, N: 0 };
  (curso?.estudiantes || []).forEach(e => { const vv = diaData[e.id]; if (vv) counts[vv] = (counts[vv] || 0) + 1; });
  const wrap = document.getElementById('cal-particip-wrap');
  if (wrap) {
    const items = wrap.querySelectorAll('.asist-sum-item');
    if (items[0]) items[0].innerHTML = `<span class="material-icons">star</span>${counts.D} <span>Destacado</span>`;
    if (items[1]) items[1].innerHTML = `<span class="material-icons">check_circle</span>${counts.P} <span>Participó</span>`;
    if (items[2]) items[2].innerHTML = `<span class="material-icons">cancel</span>${counts.N} <span>No participó</span>`;
    if (items[3]) items[3].innerHTML = `<span class="material-icons">group</span>${Object.keys(diaData).length}/${(curso?.estudiantes || []).length} <span>Registrados</span>`;
  }
}

function _marcarTodosParticip(estado) {
  const cursoId = calState.cursoActivoId;
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const fecha = _participFechaSeleccionada || new Date().toISOString().split('T')[0];
  const data = cargarParticipacion();
  if (!data[cursoId]) data[cursoId] = {};
  if (!data[cursoId][fecha]) data[cursoId][fecha] = {};
  curso.estudiantes.forEach(e => { data[cursoId][fecha][e.id] = estado; });
  guardarParticipacion(data);
  renderizarParticipacion();
}

function _limpiarDiaParticip() {
  const cursoId = calState.cursoActivoId;
  const fecha = _participFechaSeleccionada || new Date().toISOString().split('T')[0];
  const data = cargarParticipacion();
  if (data[cursoId]) delete data[cursoId][fecha];
  guardarParticipacion(data);
  renderizarParticipacion();
}

function _abrirHistorialParticipacion() {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !(curso.estudiantes || []).length) {
    mostrarToast('Sin estudiantes en este curso', 'error'); return;
  }
  const data = cargarParticipacion();
  const cursoData = data[calState.cursoActivoId] || {};
  const fechas = Object.keys(cursoData).sort(); // YYYY-MM-DD orden cronológico

  // Crear o reusar overlay
  let overlay = document.getElementById('particip-historial-overlay');
  if (!overlay) {
    overlay = document.createElement('div');
    overlay.id = 'particip-historial-overlay';
    overlay.style.cssText = 'position:fixed;inset:0;z-index:9998;background:rgba(0,0,0,0.55);display:flex;align-items:flex-start;justify-content:center;overflow-y:auto;padding:16px;';
    overlay.addEventListener('click', e => { if (e.target === overlay) overlay.remove(); });
    document.body.appendChild(overlay);
  }

  const iconos = { D: '⭐', P: '✅', N: '❌', '': '—' };
  const colores = { D: '#6A1B9A', P: '#2E7D32', N: '#C62828', '': '#CFD8DC' };

  // Resumen por estudiante
  const resumen = curso.estudiantes.map(est => {
    let d = 0, p = 0, n = 0;
    fechas.forEach(f => { const v = (cursoData[f] || {})[est.id]; if (v === 'D') d++; else if (v === 'P') p++; else if (v === 'N') n++; });
    return { ...est, d, p, n, total: d + p + n };
  });

  const fechasCols = fechas.map(f => {
    const d = new Date(f + 'T12:00:00');
    return { iso: f, label: d.toLocaleDateString('es-DO', { day: '2-digit', month: 'short' }) };
  });

  const thStyle = 'padding:6px 8px;text-align:center;font-size:0.72rem;font-weight:700;border-bottom:2px solid #E0E0E0;white-space:nowrap;';
  const tdStyle = 'padding:5px 6px;text-align:center;font-size:0.8rem;border-bottom:1px solid #F0F0F0;';

  let colsFechas = fechasCols.map(f =>
    `<th style="${thStyle}color:#546E7A;">${f.label}</th>`
  ).join('');

  let filas = resumen.map((est, i) => {
    const celdas = fechasCols.map(f => {
      const v = (cursoData[f.iso] || {})[est.id] || '';
      return `<td style="${tdStyle}color:${colores[v] || colores['']};" title="${f.iso}">${iconos[v]}</td>`;
    }).join('');
    const pct = est.total > 0 ? Math.round(((est.d + est.p) / est.total) * 100) : null;
    const pctColor = pct === null ? '#90A4AE' : pct >= 80 ? '#2E7D32' : pct >= 60 ? '#E65100' : '#C62828';
    return `<tr style="background:${i % 2 === 0 ? '#fff' : '#FAFAFA'};">
      <td style="${tdStyle}text-align:left;font-weight:600;min-width:160px;">${i + 1}. ${escapeHTML(est.nombre)}</td>
      <td style="${tdStyle}color:#6A1B9A;font-weight:700;">${est.d}</td>
      <td style="${tdStyle}color:#2E7D32;font-weight:700;">${est.p}</td>
      <td style="${tdStyle}color:#C62828;font-weight:700;">${est.n}</td>
      <td style="${tdStyle}color:${pctColor};font-weight:700;">${pct !== null ? pct + '%' : '—'}</td>
      ${celdas}
    </tr>`;
  }).join('');

  if (fechas.length === 0) {
    filas = `<tr><td colspan="5" style="text-align:center;padding:24px;color:#90A4AE;">No hay registros de participación aún.</td></tr>`;
    colsFechas = '';
  }

  overlay.innerHTML = `
    <div style="background:#fff;border-radius:16px;box-shadow:0 8px 40px rgba(0,0,0,0.2);width:100%;max-width:900px;margin:auto;overflow:hidden;">
      <div style="background:linear-gradient(135deg,#4A148C,#7B1FA2);padding:16px 20px;display:flex;align-items:center;gap:10px;">
        <span class="material-icons" style="color:#fff;font-size:22px;">table_chart</span>
        <div style="flex:1;">
          <div style="font-weight:800;color:#fff;font-size:1rem;">Historial de Participación</div>
          <div style="font-size:0.78rem;color:#E1BEE7;">${escapeHTML(curso.nombre || '')} · ${fechas.length} día(s) registrado(s)</div>
        </div>
        <button onclick="document.getElementById('particip-historial-overlay').remove()"
          style="background:rgba(255,255,255,0.15);border:none;border-radius:8px;color:#fff;padding:6px 10px;cursor:pointer;display:flex;align-items:center;gap:4px;font-size:0.82rem;font-weight:600;">
          <span class="material-icons" style="font-size:16px;">close</span> Cerrar
        </button>
      </div>
      <div style="padding:16px;overflow-x:auto;">
        <table style="width:100%;border-collapse:collapse;min-width:500px;">
          <thead>
            <tr style="background:#F3E5F5;">
              <th style="${thStyle}text-align:left;color:#4A148C;">Estudiante</th>
              <th style="${thStyle}color:#6A1B9A;" title="Destacado">⭐</th>
              <th style="${thStyle}color:#2E7D32;" title="Participó">✅</th>
              <th style="${thStyle}color:#C62828;" title="No participó">❌</th>
              <th style="${thStyle}color:#1565C0;" title="% de participación">%</th>
              ${colsFechas}
            </tr>
          </thead>
          <tbody>${filas}</tbody>
        </table>
      </div>
      <div style="padding:10px 16px 14px;font-size:0.73rem;color:#90A4AE;border-top:1px solid #F0F0F0;">
        ⭐ Destacado &nbsp;·&nbsp; ✅ Participó &nbsp;·&nbsp; ❌ No participó &nbsp;·&nbsp; — Sin registrar &nbsp;·&nbsp; % = (Destacado + Participó) / Total días registrados
      </div>
    </div>`;
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: EXPORTAR ASISTENCIA A WORD / PDF
// ════════════════════════════════════════════════════════════════════

function abrirExpAsistencia() {
  const overlay = document.getElementById('exp-asist-overlay');
  if (!overlay) return;

  // Llenar select de cursos
  const sel = document.getElementById('exp-asist-curso');
  if (sel) {
    sel.innerHTML = Object.values(calState.cursos)
      .filter(c => c.estudiantes?.length)
      .map(c => `<option value="${c.id}">${escapeHTML(c.nombre)} (${c.estudiantes.length} est.)</option>`)
      .join('');
    if (!sel.options.length) sel.innerHTML = '<option value="">Sin cursos con estudiantes</option>';
  }

  // Fecha por defecto: este mes
  setExpAsistPeriodo('mes');

  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  _actualizarPreviewAsistencia();
}

function cerrarExpAsistencia() {
  document.getElementById('exp-asist-overlay')?.classList.add('hidden');
  document.body.style.overflow = '';
}

// ── OCR Escáner de columna "%" ────────────────────────────────────
function _abrirOcrAsistencia() {
  const overlay = document.getElementById('ocr-asist-overlay');
  if (!overlay) return;
  // Reset state
  const fileInput = document.getElementById('ocr-file-input');
  if (fileInput) fileInput.value = '';
  const preview = document.getElementById('ocr-img-preview');
  if (preview) { preview.innerHTML = ''; preview.style.display = 'none'; }
  const res = document.getElementById('ocr-resultados');
  if (res) res.innerHTML = '';
  const btn = document.getElementById('ocr-analizar-btn');
  if (btn) { btn.style.display = 'none'; }
  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function _cerrarOcrAsistencia() {
  document.getElementById('ocr-asist-overlay')?.classList.add('hidden');
  document.body.style.overflow = '';
}

function _ocrArchivoSeleccionado(input) {
  const file = input.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = e => {
    const preview = document.getElementById('ocr-img-preview');
    if (preview) {
      preview.innerHTML = `<img src="${e.target.result}" style="max-width:100%;max-height:280px;border-radius:8px;border:1.5px solid #E0E0E0;display:block;margin:0 auto;">`;
      preview.style.display = 'block';
    }
    const btn = document.getElementById('ocr-analizar-btn');
    if (btn) btn.style.display = 'flex';
    document.getElementById('ocr-resultados').innerHTML = '';
  };
  reader.readAsDataURL(file);
}

async function _procesarOcrAsistencia() {
  const fileInput = document.getElementById('ocr-file-input');
  const file = fileInput?.files[0];
  if (!file) return;

  const apiKey = getGeminiKey();
  if (!apiKey) {
    mostrarToast('Configura tu clave de Gemini en Ajustes para usar esta función.', 'error');
    return;
  }

  const btn = document.getElementById('ocr-analizar-btn');
  const res = document.getElementById('ocr-resultados');
  if (btn) { btn.disabled = true; btn.innerHTML = '<span class="material-icons" style="font-size:16px;animation:spin 0.7s linear infinite;">refresh</span> Analizando...'; }
  if (res) res.innerHTML = '<div style="text-align:center;padding:20px;color:#78909C;font-size:0.88rem;">Enviando imagen a Gemini Vision...</div>';

  try {
    const base64 = await new Promise((resolve, reject) => {
      const r = new FileReader();
      r.onload = e => resolve(e.target.result.split(',')[1]);
      r.onerror = reject;
      r.readAsDataURL(file);
    });

    const PROMPT_OCR = 'En esta imagen hay una hoja de un libro de asistencia físico. Hay una columna con el símbolo "%" o el encabezado "%". Extrae ÚNICAMENTE los valores numéricos que aparecen en esa columna, en el orden exacto de arriba hacia abajo, uno por línea. Responde SOLO con los números, uno por línea. Sin texto, sin encabezados, sin guiones, sin espacios extras. Si una celda está vacía o ilegible escribe 0.';
    const bodyOcr = modelo => ({
      contents: [{ parts: [{ text: PROMPT_OCR }, { inline_data: { mime_type: file.type, data: base64 } }] }],
      generationConfig: { temperature: 0.05, maxOutputTokens: 512 }
    });

    // Intenta con el modelo indicado; devuelve { resp, errJson } si falla con 429
    const _llamarModelo = async modelo => {
      const ep = `https://generativelanguage.googleapis.com/v1beta/models/${modelo}:generateContent?key=${apiKey}`;
      const r = await fetch(ep, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(bodyOcr(modelo)) });
      if (r.ok) return { resp: r, errJson: null };
      const errJson = await r.json().catch(() => ({}));
      return { resp: r, errJson };
    };

    // Probar primero gemini-2.0-flash, luego gemini-1.5-flash como fallback
    let { resp, errJson } = await _llamarModelo('gemini-2.0-flash');
    if (!resp.ok && resp.status === 429) {
      if (res) res.innerHTML = '<div style="text-align:center;padding:10px;color:#78909C;font-size:0.82rem;">⏳ Intentando con modelo alternativo...</div>';
      const fallback = await _llamarModelo('gemini-1.5-flash');
      resp = fallback.resp;
      errJson = fallback.errJson;
    }

    if (!resp.ok) {
      const msg = errJson?.error?.message || '';
      const esLimiteCero = msg.includes('limit: 0') || msg.includes('limit:0');
      if (resp.status === 429 || msg.toLowerCase().includes('quota')) {
        throw new Error(esLimiteCero ? 'BILLING_REQUERIDO' : 'CUOTA_AGOTADA');
      }
      throw new Error(msg || `Error ${resp.status}`);
    }

    const data = await resp.json();
    const rawText = data?.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
    const numeros = rawText.split('\n').map(l => l.trim()).filter(l => l !== '');

    if (!numeros.length) {
      if (res) res.innerHTML = '<div style="color:#C62828;background:#FFEBEE;border-radius:8px;padding:12px;font-size:0.85rem;">No se detectaron números en la columna %. Intenta con una foto más nítida o asegúrate de que la columna "%" esté visible.</div>';
    } else {
      const lista = numeros.map((n, i) => `<div style="display:flex;align-items:center;gap:10px;padding:6px 10px;border-bottom:1px solid #F0F0F0;">
        <span style="color:#90A4AE;font-size:0.78rem;min-width:20px;">${i + 1}</span>
        <span style="font-size:0.95rem;font-weight:700;color:#1565C0;font-variant-numeric:tabular-nums;">${escapeHTML(n)}</span>
      </div>`).join('');
      const textoCopiar = numeros.join('\n');
      if (res) res.innerHTML = `
        <div style="font-size:0.82rem;color:#546E7A;margin-bottom:8px;font-weight:600;">
          <span class="material-icons" style="font-size:14px;vertical-align:middle;color:#388E3C;">check_circle</span>
          ${numeros.length} valor${numeros.length !== 1 ? 'es' : ''} detectado${numeros.length !== 1 ? 's' : ''} en la columna %
        </div>
        <div style="border:1.5px solid #E0E0E0;border-radius:8px;overflow:hidden;max-height:300px;overflow-y:auto;">${lista}</div>
        <button onclick="navigator.clipboard.writeText(${JSON.stringify(textoCopiar)}).then(()=>mostrarToast('Números copiados','ok'))"
          style="margin-top:12px;width:100%;padding:10px;background:#E8F5E9;border:1.5px solid #A5D6A7;color:#1B5E20;
          border-radius:8px;font-size:0.88rem;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:6px;font-family:inherit;">
          <span class="material-icons" style="font-size:16px;">content_copy</span> Copiar todos los números
        </button>`;
    }
  } catch (e) {
    let html;
    if (e.message === 'BILLING_REQUERIDO') {
      html = `<div style="color:#7B3F00;background:#FFF3E0;border-radius:8px;padding:14px;font-size:0.85rem;line-height:1.5;">
        <div style="font-weight:700;margin-bottom:6px;">🔑 Clave sin cuota gratuita</div>
        Tu clave de Gemini pertenece a un proyecto que requiere <strong>facturación activada</strong> en Google.
        Esperar días no lo soluciona — el límite es permanente (limit: 0).<br><br>
        Para resolverlo:
        <ul style="margin:6px 0 0 16px;padding:0;">
          <li>Ve a <strong>aistudio.google.com</strong>, crea un nuevo proyecto y genera una clave nueva</li>
          <li>O activa la facturación en tu proyecto actual de Google Cloud</li>
          <li>Luego actualiza la clave en <strong>Ajustes → Clave de Gemini</strong></li>
        </ul>
      </div>`;
    } else if (e.message === 'CUOTA_AGOTADA' || e.message.toLowerCase().includes('quota') || e.message.toLowerCase().includes('rate')) {
      html = `<div style="color:#7B3F00;background:#FFF3E0;border-radius:8px;padding:14px;font-size:0.85rem;line-height:1.5;">
        <div style="font-weight:700;margin-bottom:6px;">⚠️ Límite de solicitudes alcanzado</div>
        Tu clave alcanzó el límite de solicitudes por minuto o por día.
        <ul style="margin:8px 0 0 16px;padding:0;">
          <li>Espera unos minutos y vuelve a intentarlo</li>
          <li>O usa una clave de pago en <strong>Ajustes → Clave de Gemini</strong></li>
        </ul>
      </div>`;
    } else {
      html = `<div style="color:#C62828;background:#FFEBEE;border-radius:8px;padding:12px;font-size:0.85rem;">
        <strong>Error:</strong> ${escapeHTML(e.message)}
      </div>`;
    }
    if (res) res.innerHTML = html;
  } finally {
    if (btn) { btn.disabled = false; btn.innerHTML = '<span class="material-icons" style="font-size:16px;">document_scanner</span> Analizar imagen'; }
  }
}

function setExpAsistPeriodo(tipo) {
  const hoy = new Date();
  const desde = document.getElementById('exp-asist-desde');
  const hasta = document.getElementById('exp-asist-hasta');
  if (!desde || !hasta) return;
  const fmt = d => d.toISOString().split('T')[0];
  if (tipo === 'mes') {
    desde.value = fmt(new Date(hoy.getFullYear(), hoy.getMonth(), 1));
    hasta.value = fmt(new Date(hoy.getFullYear(), hoy.getMonth() + 1, 0));
  } else if (tipo === 'trimestre') {
    const d3 = new Date(hoy); d3.setMonth(d3.getMonth() - 3);
    desde.value = fmt(d3);
    hasta.value = fmt(hoy);
  } else {
    desde.value = '2024-01-01';
    hasta.value = fmt(hoy);
  }
  _actualizarPreviewAsistencia();
}

function _actualizarPreviewAsistencia() {
  const preview = document.getElementById('exp-asist-preview');
  if (!preview) return;
  const cursoId = document.getElementById('exp-asist-curso')?.value;
  const desde = document.getElementById('exp-asist-desde')?.value;
  const hasta = document.getElementById('exp-asist-hasta')?.value;
  if (!cursoId) { preview.innerHTML = ''; return; }
  const curso = calState.cursos[cursoId];
  if (!curso) { preview.innerHTML = ''; return; }
  const { fechas } = _filtrarAsistencia(cursoId, desde, hasta);
  preview.innerHTML = `
    <div style="background:#F5F7FA;border-radius:8px;padding:10px 14px;border:1px solid #E0E0E0;">
      <span class="material-icons" style="font-size:14px;vertical-align:middle;color:#1565C0;">preview</span>
      <strong>${curso.nombre}</strong> · ${curso.estudiantes?.length || 0} estudiantes ·
      <strong>${fechas.length}</strong> fecha(s) en el período seleccionado
    </div>`;
}

// Filtrar datos de asistencia por rango de fechas
function _filtrarAsistencia(cursoId, desde, hasta) {
  const data = cargarAsistencia();
  const byDate = data[cursoId] || {};
  const fechas = Object.keys(byDate)
    .filter(f => (!desde || f >= desde) && (!hasta || f <= hasta))
    .sort();
  return { fechas, byDate };
}

// ── EXPORTAR A WORD ─────────────────────────────────────────────
async function generarReporteAsistenciaWord() {
  const cursoId = document.getElementById('exp-asist-curso')?.value;
  const desde = document.getElementById('exp-asist-desde')?.value;
  const hasta = document.getElementById('exp-asist-hasta')?.value;
  if (!cursoId) { mostrarToast('Selecciona un curso', 'error'); return; }
  const curso = calState.cursos[cursoId];
  if (!curso) { mostrarToast('Curso no encontrado', 'error'); return; }

  mostrarToast('Generando documento Word…', 'success');

  const { fechas, byDate } = _filtrarAsistencia(cursoId, desde, hasta);
  const estudiantes = curso.estudiantes || [];
  const umbral = parseInt(localStorage.getItem('asist_umbral') || '80');

  const {
    Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
    AlignmentType, BorderStyle, WidthType, ShadingType, VerticalAlign,
    PageOrientation
  } = docx;

  const borderThin = { style: BorderStyle.SINGLE, size: 4, color: '90CAF9' };
  const borderMed = { style: BorderStyle.SINGLE, size: 8, color: '1565C0' };
  const borders = { top: borderThin, bottom: borderThin, left: borderThin, right: borderThin };
  const bordersHead = { top: borderMed, bottom: borderMed, left: borderMed, right: borderMed };

  // Colores
  const C_HEADER = '1565C0';
  const C_PRES = 'E8F5E9';
  const C_AUS = 'FFEBEE';
  const C_TARD = 'FFF3E0';
  const C_EXCU = 'E3F2FD';
  const C_SIN = 'FAFAFA';

  function cell(text, opts = {}) {
    return new TableCell({
      borders: opts.borders || borders,
      width: opts.width ? { size: opts.width, type: WidthType.DXA } : undefined,
      shading: opts.shade ? { fill: opts.shade, type: ShadingType.CLEAR } : undefined,
      verticalAlign: VerticalAlign.CENTER,
      margins: { top: 60, bottom: 60, left: 80, right: 80 },
      children: [new Paragraph({
        alignment: opts.align || AlignmentType.CENTER,
        children: [new TextRun({
          text: String(text || ''),
          bold: opts.bold || false,
          color: opts.color || '000000',
          font: 'Arial',
          size: opts.size || 16,
        })]
      })]
    });
  }

  // TABLA DE ENCABEZADO
  const encabezado = new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [9360],
    rows: [
      new TableRow({
        children: [
          new TableCell({
            borders: bordersHead,
            width: { size: 9360, type: WidthType.DXA },
            shading: { fill: C_HEADER, type: ShadingType.CLEAR },
            margins: { top: 120, bottom: 120, left: 160, right: 160 },
            children: [
              new Paragraph({
                alignment: AlignmentType.CENTER, children: [
                  new TextRun({ text: 'REGISTRO DE ASISTENCIA', bold: true, color: 'FFFFFF', font: 'Arial', size: 28 })
                ]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER, children: [
                  new TextRun({ text: `Curso: ${curso.nombre}`, bold: true, color: 'E3F2FD', font: 'Arial', size: 22 })
                ]
              }),
              new Paragraph({
                alignment: AlignmentType.CENTER, children: [
                  new TextRun({
                    text: `Período: ${desde || 'inicio'} — ${hasta || 'hoy'}  ·  Docente: ${planificacion?.datosGenerales?.nombreDocente || '—'}`,
                    color: 'BBDEFB', font: 'Arial', size: 18
                  })
                ]
              })
            ]
          })
        ]
      })
    ]
  });

  // TABLA DE ASISTENCIA
  // Cada columna: nombre (2200) + fechas (420 c/u) + total P/A/T/E + %
  const COL_NOMBRE = 2200;
  const COL_FECHA = Math.min(420, Math.floor((9360 - COL_NOMBRE - 1200) / Math.max(fechas.length, 1)));
  const COL_TOTAL = 300;
  const COL_PCT = 380;
  const totalFechasW = COL_FECHA * fechas.length;
  const restoW = 9360 - COL_NOMBRE - totalFechasW - COL_TOTAL * 4 - COL_PCT;

  // Header de fechas
  const DIAS_ABREV = ['Do', 'Lu', 'Ma', 'Mi', 'Ju', 'Vi', 'Sa'];
  const headerRow = new TableRow({
    tableHeader: true,
    children: [
      cell('Estudiante', { shade: C_HEADER, bold: true, color: 'FFFFFF', size: 17, align: AlignmentType.LEFT, width: COL_NOMBRE, borders: bordersHead }),
      ...fechas.map(f => {
        const d = new Date(f + 'T12:00:00');
        const label = `${DIAS_ABREV[d.getDay()]}\n${d.getDate()}/${d.getMonth() + 1}`;
        return cell(label, { shade: C_HEADER, bold: true, color: 'FFFFFF', size: 14, width: COL_FECHA, borders: bordersHead });
      }),
      cell('P', { shade: C_PRES, bold: true, size: 15, width: COL_TOTAL, borders: bordersHead }),
      cell('T', { shade: C_TARD, bold: true, size: 15, width: COL_TOTAL, borders: bordersHead }),
      cell('A', { shade: C_AUS, bold: true, size: 15, width: COL_TOTAL, borders: bordersHead }),
      cell('E', { shade: C_EXCU, bold: true, size: 15, width: COL_TOTAL, borders: bordersHead }),
      cell('%', { shade: C_HEADER, bold: true, color: 'FFFFFF', size: 15, width: COL_PCT, borders: bordersHead }),
    ]
  });

  // Filas de estudiantes
  const filasEst = estudiantes.map((est, idx) => {
    let P = 0, A = 0, T = 0, E = 0;
    const celdas = fechas.map(f => {
      const v = byDate[f]?.[est.id] || '';
      const shade = v === 'P' ? C_PRES : v === 'A' ? C_AUS : v === 'T' ? C_TARD : v === 'E' ? C_EXCU : C_SIN;
      if (v === 'P') P++; else if (v === 'A') A++; else if (v === 'T') T++; else if (v === 'E') E++;
      return cell(v || '·', { shade, size: 14, width: COL_FECHA });
    });
    const total = P + A + T + E;
    const pct = total > 0 ? Math.round(((P + T * 0.5 + E) / total) * 100) : null;
    const rowShade = idx % 2 === 0 ? 'FFFFFF' : 'F5F7FA';
    const pctColor = pct === null ? '9E9E9E' : pct >= umbral ? '2E7D32' : pct >= 60 ? 'E65100' : 'C62828';
    return new TableRow({
      children: [
        cell(est.nombre, { shade: rowShade, align: AlignmentType.LEFT, width: COL_NOMBRE, size: 17 }),
        ...celdas,
        cell(P, { shade: C_PRES, bold: true, size: 15, width: COL_TOTAL }),
        cell(T, { shade: C_TARD, bold: true, size: 15, width: COL_TOTAL }),
        cell(A, { shade: C_AUS, bold: true, size: 15, width: COL_TOTAL }),
        cell(E, { shade: C_EXCU, bold: true, size: 15, width: COL_TOTAL }),
        cell(pct !== null ? pct + '%' : '—', { shade: rowShade, bold: true, color: pctColor, size: 15, width: COL_PCT }),
      ]
    });
  });

  const colWidths = [COL_NOMBRE, ...fechas.map(() => COL_FECHA), COL_TOTAL, COL_TOTAL, COL_TOTAL, COL_TOTAL, COL_PCT];
  const tablaAsistencia = new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [headerRow, ...filasEst]
  });

  // TABLA RESUMEN
  const resumenRows = [
    new TableRow({
      children: [
        cell('RESUMEN', { shade: C_HEADER, bold: true, color: 'FFFFFF', size: 18, width: 4680, borders: bordersHead }),
        cell('', { shade: C_HEADER, width: 4680, borders: bordersHead }),
      ]
    }),
    new TableRow({
      children: [
        cell('Total de clases registradas', { shade: 'F5F7FA', align: AlignmentType.LEFT, width: 4680, size: 17 }),
        cell(fechas.length, { bold: true, width: 4680, size: 17 }),
      ]
    }),
    new TableRow({
      children: [
        cell('Total de estudiantes', { shade: 'F5F7FA', align: AlignmentType.LEFT, width: 4680, size: 17 }),
        cell(estudiantes.length, { bold: true, width: 4680, size: 17 }),
      ]
    }),
    new TableRow({
      children: [
        cell(`Estudiantes bajo umbral (${umbral}%)`, { shade: 'FFEBEE', align: AlignmentType.LEFT, width: 4680, size: 17 }),
        cell(estudiantes.filter(e => {
          const s = _statsAsistencia(cursoId, e.id);
          return s.pct !== null && s.pct < umbral;
        }).length, { bold: true, shade: 'FFEBEE', color: 'C62828', width: 4680, size: 17 }),
      ]
    }),
  ];
  const tablaResumen = new Table({
    width: { size: 9360, type: WidthType.DXA },
    columnWidths: [4680, 4680],
    rows: resumenRows
  });

  const sections = fechas.length > 20
    ? [{ properties: { page: { size: { width: 12240, height: 15840, orientation: PageOrientation.LANDSCAPE }, margin: { top: 720, right: 720, bottom: 720, left: 720 } } }, children: [encabezado, new Paragraph({ text: '' }), tablaAsistencia, new Paragraph({ text: '' }), tablaResumen] }]
    : [{ properties: { page: { size: { width: 12240, height: 15840 }, margin: { top: 1080, right: 720, bottom: 1080, left: 720 } } }, children: [encabezado, new Paragraph({ text: '' }), tablaAsistencia, new Paragraph({ text: '' }), tablaResumen] }];

  const documento = new Document({ sections });
  const buffer = await Packer.toBlob(documento);
  const url = URL.createObjectURL(buffer);
  const a = document.createElement('a');
  a.href = url;
  a.download = `Asistencia_${curso.nombre.replace(/\s+/g, '_')}_${desde || 'todo'}.docx`;
  a.click();
  URL.revokeObjectURL(url);
  mostrarToast('Documento Word generado 📄', 'success');
}

// ── EXPORTAR A PDF (via ventana de impresión) ───────────────────
function generarReporteAsistenciaPDF() {
  const cursoId = document.getElementById('exp-asist-curso')?.value;
  const desde = document.getElementById('exp-asist-desde')?.value;
  const hasta = document.getElementById('exp-asist-hasta')?.value;
  if (!cursoId) { mostrarToast('Selecciona un curso', 'error'); return; }
  const curso = calState.cursos[cursoId];
  if (!curso) { mostrarToast('Curso no encontrado', 'error'); return; }

  const { fechas, byDate } = _filtrarAsistencia(cursoId, desde, hasta);
  const estudiantes = curso.estudiantes || [];
  const umbral = parseInt(localStorage.getItem('asist_umbral') || '80');
  const DIAS_ABREV = ['Do', 'Lu', 'Ma', 'Mi', 'Ju', 'Vi', 'Sa'];

  const filas = estudiantes.map((est, idx) => {
    let P = 0, A = 0, T = 0, E = 0;
    const celdas = fechas.map(f => {
      const v = byDate[f]?.[est.id] || '';
      const bg = v === 'P' ? '#C8E6C9' : v === 'A' ? '#FFCDD2' : v === 'T' ? '#FFE0B2' : v === 'E' ? '#BBDEFB' : '#F5F5F5';
      if (v === 'P') P++; else if (v === 'A') A++; else if (v === 'T') T++; else if (v === 'E') E++;
      return `<td style="background:${bg};font-size:9pt;">${v || '·'}</td>`;
    }).join('');
    const total = P + A + T + E;
    const pct = total > 0 ? Math.round(((P + T * 0.5 + E) / total) * 100) : null;
    const pctColor = pct === null ? '#9E9E9E' : pct >= umbral ? '#2E7D32' : pct >= 60 ? '#E65100' : '#C62828';
    const rowBg = idx % 2 === 0 ? '#fff' : '#F8F9FA';
    return `<tr style="background:${rowBg};">
      <td style="text-align:left;padding:4px 6px;font-size:9.5pt;">${escapeHTML(est.nombre)}</td>
      ${celdas}
      <td style="background:#C8E6C9;font-weight:700;">${P}</td>
      <td style="background:#FFE0B2;font-weight:700;">${T}</td>
      <td style="background:#FFCDD2;font-weight:700;">${A}</td>
      <td style="background:#BBDEFB;font-weight:700;">${E}</td>
      <td style="font-weight:800;color:${pctColor};">${pct !== null ? pct + '%' : '—'}</td>
    </tr>`;
  }).join('');

  const headerFechas = fechas.map(f => {
    const d = new Date(f + 'T12:00:00');
    return `<th style="background:#1565C0;color:#fff;font-size:8pt;padding:3px;">${DIAS_ABREV[d.getDay()]}<br>${d.getDate()}/${d.getMonth() + 1}</th>`;
  }).join('');

  const bajo = estudiantes.filter(e => {
    const s = _statsAsistencia(cursoId, e.id);
    return s.pct !== null && s.pct < umbral;
  }).length;

  const html = `<!DOCTYPE html><html><head>
    <meta charset="utf-8">
    <title>Asistencia — ${curso.nombre}</title>
    <style>
      @page { margin:0.6in; size:${fechas.length > 20 ? 'landscape' : 'portrait'}; }
      body { font-family:Arial,sans-serif; font-size:10pt; color:#212121; }
      h1   { font-size:16pt; color:#1565C0; margin:0 0 4px; }
      .sub { font-size:9pt; color:#546E7A; margin:0 0 12px; }
      table { border-collapse:collapse; width:100%; }
      th,td { border:1px solid #E0E0E0; text-align:center; padding:4px 3px; vertical-align:middle; }
      .resumen { margin-top:16px; border:1px solid #1565C0; border-radius:6px; padding:10px; display:inline-block; }
      .resumen td { border:none; padding:3px 14px; font-size:9.5pt; }
    </style>
  </head><body>
    <h1>Registro de Asistencia</h1>
    <p class="sub">Curso: <strong>${escapeHTML(curso.nombre)}</strong> &nbsp;·&nbsp;
      Período: ${desde || 'inicio'} — ${hasta || 'hoy'} &nbsp;·&nbsp;
      Docente: ${escapeHTML(planificacion?.datosGenerales?.nombreDocente || '—')}</p>
    <table>
      <thead><tr>
        <th style="background:#1565C0;color:#fff;text-align:left;padding:5px 8px;min-width:130px;">Estudiante</th>
        ${headerFechas}
        <th style="background:#C8E6C9;">P</th>
        <th style="background:#FFE0B2;">T</th>
        <th style="background:#FFCDD2;">A</th>
        <th style="background:#BBDEFB;">E</th>
        <th style="background:#1565C0;color:#fff;">%</th>
      </tr></thead>
      <tbody>${filas}</tbody>
    </table>
    <div class="resumen">
      <table>
        <tr><td>Clases registradas:</td><td><strong>${fechas.length}</strong></td></tr>
        <tr><td>Total estudiantes:</td><td><strong>${estudiantes.length}</strong></td></tr>
        <tr><td style="color:#C62828;">Bajo umbral (${umbral}%):</td><td style="color:#C62828;font-weight:700;">${bajo}</td></tr>
      </table>
    </div>
  </body></html>`;

  const win = window.open('', '_blank');
  win.document.write(html);
  win.document.close();
  setTimeout(() => win.print(), 600);
  mostrarToast('Ventana de impresión/PDF abierta 🖨️', 'success');
}


const HORARIO_KEY = 'planificadorRA_horario_v1';
const TAREAS_KEY = 'planificadorRA_tareas_v1';

const PERIODOS = [
  { id: 1, label: '1', hora: '8:00 – 8:50 AM' },
  { id: 2, label: '2', hora: '8:50 – 9:40 AM' },
  { id: 3, label: '3', hora: '10:00 – 10:50 AM' },
  { id: 4, label: '4', hora: '10:50 – 11:40 AM' },
  { id: 5, label: '5', hora: '12:30 – 1:20 PM' },
  { id: 6, label: '6', hora: '1:20 – 2:10 PM' },
  { id: 7, label: '7', hora: '2:20 – 3:10 PM' },
  { id: 8, label: '8', hora: '3:10 – 4:00 PM' },
];
const DIAS = ['Lunes', 'Martes', 'Miércoles', 'Jueves', 'Viernes'];
const DIAS_SHORT = ['Lu', 'Ma', 'Mi', 'Ju', 'Vi'];

// Colores para las materias
const MATERIA_COLORES = [
  '#1565C0', '#2E7D32', '#AD1457', '#E65100', '#4527A0',
  '#00695C', '#BF360C', '#37474F', '#F57F17', '#1B5E20',
  '#880E4F', '#0D47A1', '#1A237E', '#006064', '#33691E',
];

function _horarioColores() {
  const h = cargarHorario();
  const mapa = {};
  let ci = 0;
  h.forEach(e => {
    const key = (e.materia || '').trim();
    if (key && !mapa[key]) mapa[key] = MATERIA_COLORES[ci++ % MATERIA_COLORES.length];
  });
  return mapa;
}

function cargarHorario() {
  try { return JSON.parse(localStorage.getItem(HORARIO_KEY) || '[]'); } catch { return []; }
}
function guardarHorario(data) {
  localStorage.setItem(HORARIO_KEY, JSON.stringify(data));
  if (window._syncFirebase) _syncFirebase('horario', data);
}

function abrirHorario() {
  _mostrarPanel('panel-horario');
  renderizarHorario();
}
function cerrarHorario() { abrirDashboard(); }

function renderizarHorario() {
  const tabla = document.getElementById('horario-tabla');
  if (!tabla) return;
  const data = cargarHorario();
  const colores = _horarioColores();

  // Construir mapa de búsqueda: dia-periodo → entrada
  const mapa = {};
  data.forEach(e => { mapa[`${e.dia}-${e.periodo}`] = e; });

  let html = '<table class="hor-tabla"><thead><tr><th class="hor-th-dia">Día</th>';
  PERIODOS.forEach(p => {
    html += `<th class="hor-th-per"><div class="hor-per-num">${p.label}</div><div class="hor-per-hora">${p.hora}</div></th>`;
  });
  html += '</tr></thead><tbody>';

  DIAS.forEach((dia, di) => {
    html += `<tr><td class="hor-td-dia"><span>${DIAS_SHORT[di]}</span></td>`;
    PERIODOS.forEach(p => {
      const key = `${di}-${p.id}`;
      const e = mapa[key];
      const color = e && e.materia ? (colores[e.materia.trim()] || '#78909C') : null;
      const bg = color ? color + '22' : '';
      const border = color ? `2px solid ${color}` : '1px solid #E0E0E0';
      const draggable = e && e.materia ? 'draggable="true"' : '';
      const title = e && e.materia ? 'Arrastra para mover · Clic para editar' : 'Clic para agregar';
      html += `<td class="hor-td-celda" data-dia="${di}" data-periodo="${p.id}" ${draggable}
        style="border-left:${border};background:${bg};"
        onclick="editarCeldaHorario(${di},${p.id})" title="${title}">`;
      if (e && e.materia) {
        html += `<div class="hor-celda-inner">
          <div class="hor-materia" style="color:${color};">${escapeHTML(e.materia)}</div>
          ${e.seccion ? `<div class="hor-seccion">${escapeHTML(e.seccion)}</div>` : ''}
          ${e.aula ? `<div class="hor-aula"><span class="material-icons" style="font-size:11px;">room</span>${escapeHTML(e.aula)}</div>` : ''}
        </div>`;
      } else {
        html += `<div class="hor-celda-vacia"><span class="material-icons">add</span></div>`;
      }
      html += '</td>';
    });
    html += '</tr>';
  });
  html += '</tbody></table>';
  tabla.innerHTML = html;
  _initHorarioDragDrop(tabla);

  // Leyenda de materias
  const leyenda = document.getElementById('horario-leyenda');
  if (leyenda) {
    const entries = Object.entries(colores);
    if (entries.length === 0) { leyenda.innerHTML = ''; return; }
    leyenda.innerHTML = '<div class="hor-leyenda-wrap">'
      + entries.map(([mat, col]) =>
        `<span class="hor-leyenda-item" style="border-color:${col};color:${col};">
            <span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${col};margin-right:5px;"></span>
            ${escapeHTML(mat)}
          </span>`
      ).join('')
      + '</div>';
  }
}

function _initHorarioDragDrop(tabla) {
  let dragSrc = null;

  tabla.addEventListener('dragstart', ev => {
    const td = ev.target.closest('td[data-dia][data-periodo][draggable]');
    if (!td) return;
    dragSrc = { dia: +td.dataset.dia, periodo: +td.dataset.periodo };
    td.classList.add('hor-dragging');
    ev.dataTransfer.effectAllowed = 'move';
  });

  tabla.addEventListener('dragend', () => {
    tabla.querySelectorAll('.hor-dragging, .hor-drag-over').forEach(el => {
      el.classList.remove('hor-dragging', 'hor-drag-over');
    });
    dragSrc = null;
  });

  tabla.addEventListener('dragover', ev => {
    const td = ev.target.closest('td[data-dia][data-periodo]');
    if (!td || !dragSrc) return;
    ev.preventDefault();
    ev.dataTransfer.dropEffect = 'move';
    tabla.querySelectorAll('.hor-drag-over').forEach(el => el.classList.remove('hor-drag-over'));
    td.classList.add('hor-drag-over');
  });

  tabla.addEventListener('dragleave', ev => {
    const td = ev.target.closest('td[data-dia][data-periodo]');
    if (td && !td.contains(ev.relatedTarget)) td.classList.remove('hor-drag-over');
  });

  tabla.addEventListener('drop', ev => {
    ev.preventDefault();
    const td = ev.target.closest('td[data-dia][data-periodo]');
    if (!td || !dragSrc) return;
    const destDia = +td.dataset.dia;
    const destPeriodo = +td.dataset.periodo;
    if (dragSrc.dia === destDia && dragSrc.periodo === destPeriodo) return;

    const data = cargarHorario();
    const srcIdx = data.findIndex(e => e.dia === dragSrc.dia && e.periodo === dragSrc.periodo);
    if (srcIdx === -1) return;
    const srcEntry = { ...data[srcIdx] };
    const destIdx = data.findIndex(e => e.dia === destDia && e.periodo === destPeriodo);

    if (destIdx === -1) {
      // Destino vacío: mover
      data.splice(srcIdx, 1);
      data.push({ ...srcEntry, dia: destDia, periodo: destPeriodo });
    } else {
      // Ambas celdas con contenido: intercambiar
      data[srcIdx] = { ...data[destIdx], dia: dragSrc.dia, periodo: dragSrc.periodo };
      data[destIdx] = { ...srcEntry, dia: destDia, periodo: destPeriodo };
    }

    guardarHorario(data);
    renderizarHorario();
    mostrarToast('Horario actualizado', 'success');
  });
}

function editarCeldaHorario(diaIdx, periodoId) {
  const data = cargarHorario();
  const key = `${diaIdx}-${periodoId}`;
  const existente = data.find(e => e.dia === diaIdx && e.periodo === periodoId) || {};
  const periodo = PERIODOS.find(p => p.id === periodoId);

  // Obtener lista de materias ya usadas para sugerencias
  const materiasUsadas = [...new Set(data.map(e => e.materia).filter(Boolean))];
  const datalistOpts = materiasUsadas.map(m => `<option value="${escapeHTML(m)}">`).join('');

  document.getElementById('modal-title').textContent = `${DIAS[diaIdx]} — Período ${periodoId} (${periodo.hora})`;
  document.getElementById('modal-body').innerHTML = `
    <datalist id="dl-materias">${datalistOpts}</datalist>
    <div style="display:flex;flex-direction:column;gap:14px;padding:4px 0;">
      <div>
        <label style="font-size:0.78rem;font-weight:700;color:#424242;display:block;margin-bottom:5px;">
          Materia / Módulo
        </label>
        <input id="hor-inp-materia" list="dl-materias" placeholder="Ej: Diseño de Portales Web" value="${escapeHTML(existente.materia || '')}"
          style="width:100%;padding:9px 12px;border:1.5px solid #90CAF9;border-radius:8px;font-size:0.9rem;">
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
        <div>
          <label style="font-size:0.78rem;font-weight:700;color:#424242;display:block;margin-bottom:5px;">Sección</label>
          <input id="hor-inp-seccion" placeholder="Ej: 4to B" value="${escapeHTML(existente.seccion || '')}"
            style="width:100%;padding:9px 12px;border:1.5px solid #90CAF9;border-radius:8px;font-size:0.9rem;">
        </div>
        <div>
          <label style="font-size:0.78rem;font-weight:700;color:#424242;display:block;margin-bottom:5px;">Aula (opcional)</label>
          <input id="hor-inp-aula" placeholder="Ej: Lab 3" value="${escapeHTML(existente.aula || '')}"
            style="width:100%;padding:9px 12px;border:1.5px solid #90CAF9;border-radius:8px;font-size:0.9rem;">
        </div>
      </div>
      <div>
        <label style="font-size:0.78rem;font-weight:700;color:#424242;display:block;margin-bottom:5px;">Notas (opcional)</label>
        <input id="hor-inp-notas" placeholder="Ej: Trae USB" value="${escapeHTML(existente.notas || '')}"
          style="width:100%;padding:9px 12px;border:1.5px solid #90CAF9;border-radius:8px;font-size:0.9rem;">
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px;padding-top:12px;border-top:1px solid #E0E0E0;flex-wrap:wrap;">
        <button class="btn-secundario" onclick="cerrarModalBtn()">Cancelar</button>
        ${existente.materia ? `<button class="btn-secundario" style="color:#C62828;border-color:#FFCDD2;" onclick="borrarCeldaHorario(${diaIdx},${periodoId})"><span class="material-icons">delete_outline</span> Borrar</button>` : ''}
        <button class="btn-siguiente" onclick="guardarCeldaHorario(${diaIdx},${periodoId})">
          <span class="material-icons">save</span> Guardar
        </button>
      </div>
    </div>`;
  // botones en body

  document.getElementById('modal-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
  setTimeout(() => document.getElementById('hor-inp-materia')?.focus(), 80);
  document.getElementById('hor-inp-materia').addEventListener('keydown', e => {
    if (e.key === 'Enter') guardarCeldaHorario(diaIdx, periodoId);
  });
}

function guardarCeldaHorario(diaIdx, periodoId) {
  const materia = document.getElementById('hor-inp-materia')?.value.trim();
  const seccion = document.getElementById('hor-inp-seccion')?.value.trim();
  const aula = document.getElementById('hor-inp-aula')?.value.trim();
  const notas = document.getElementById('hor-inp-notas')?.value.trim();
  const data = cargarHorario().filter(e => !(e.dia === diaIdx && e.periodo === periodoId));
  if (materia) data.push({ dia: diaIdx, periodo: periodoId, materia, seccion, aula, notas });
  guardarHorario(data);
  cerrarModalBtn();
  renderizarHorario();
  mostrarToast(materia ? 'Período guardado' : 'Período borrado', 'success');
}

function borrarCeldaHorario(diaIdx, periodoId) {
  const data = cargarHorario().filter(e => !(e.dia === diaIdx && e.periodo === periodoId));
  guardarHorario(data);
  cerrarModalBtn();
  renderizarHorario();
  mostrarToast('Período borrado', 'success');
}

