// --- MÓDULO: BIBLIOTECA DE PLANIFICACIONES ---



// Guarda y carga múltiples planificaciones en localStorage.



// ================================================================







const BIBLIO_KEY = 'planificadorRA_biblioteca_v1';







/** Carga todas las planificaciones guardadas */



function cargarBiblioteca() {



  try {



    return JSON.parse(localStorage.getItem(BIBLIO_KEY) || '{"items":[]}');



  } catch (e) {



    return { items: [] };



  }



}







/** Abre modal para copiar datos generales de otra planificación guardada */
function abrirModalCopiarDatosGenerales() {
  const biblio = cargarBiblioteca();
  const items = biblio.items || [];

  if (items.length === 0) {
    mostrarToast('No hay planificaciones guardadas en la biblioteca.', 'error');
    return;
  }

  // Construir mapa planId → nombre del curso
  let planIdACurso = {};
  try {
    const cal = JSON.parse(localStorage.getItem(CAL_STORAGE_KEY) || '{"cursos":{}}');
    Object.values(cal.cursos || {}).forEach(curso => {
      (curso.planIds || []).forEach(pid => { planIdACurso[pid] = curso.nombre; });
    });
  } catch(e) {}

  const listaHTML = items.map((item, idx) => {
    const dg = item.planificacion?.datosGenerales || {};
    const modulo = dg.moduloFormativo || dg.codigoModulo || '(sin nombre)';
    const docente = dg.nombreDocente ? ` · ${dg.nombreDocente}` : '';
    const fecha = item.fechaGuardadoLabel || '';
    const cursoNombre = planIdACurso[item.id];
    const cursoTag = cursoNombre
      ? `<span style="display:inline-block;margin-top:4px;padding:2px 8px;background:#E8F5E9;color:#2E7D32;border-radius:12px;font-size:0.75rem;font-weight:600;">
           <span class="material-icons" style="font-size:0.75rem;vertical-align:middle;">school</span> ${cursoNombre}
         </span>`
      : `<span style="display:inline-block;margin-top:4px;padding:2px 8px;background:#F5F5F5;color:#9E9E9E;border-radius:12px;font-size:0.75rem;">Sin curso asignado</span>`;
    return `
      <div onclick="_confirmarCopiarDatosGenerales(${idx})" style="
        padding:12px 16px;border:1.5px solid #E0E0E0;border-radius:8px;cursor:pointer;
        margin-bottom:8px;transition:border-color .15s,background .15s;"
        onmouseover="this.style.borderColor='#1565C0';this.style.background='#E3F2FD';"
        onmouseout="this.style.borderColor='#E0E0E0';this.style.background='';">
        <div style="font-weight:700;color:#1A237E;font-size:0.9rem;">${modulo}${docente}</div>
        <div style="margin-top:2px;">${cursoTag}</div>
        <div style="font-size:0.78rem;color:#757575;margin-top:4px;">${fecha}</div>
      </div>`;
  }).join('');

  document.getElementById('modal-title').textContent = 'Copiar datos generales de otra planificación';
  document.getElementById('modal-body').innerHTML = `
    <p style="font-size:0.85rem;color:#555;margin-bottom:12px;">
      Selecciona una planificación guardada. Se copiarán: Familia Profesional, Código FP,
      Nombre del Bachillerato Técnico, Código del Título, Módulo Formativo, Código del Módulo,
      Nombre del Docente, Unidad de Competencia, Código UC, Cantidad de RA, Horas por Semana y Días de Clase por Semana.
    </p>
    <div style="max-height:400px;overflow-y:auto;">${listaHTML}</div>`;
  _usarFooterDinamico(`<button class="btn-secundario" onclick="cerrarModalBtn()">Cancelar</button>`);
  document.getElementById('modal-overlay').classList.remove('hidden');
  document.body.style.overflow = 'hidden';

  // Guardar items en variable temporal para acceso desde el confirm
  window._copiarDGItems = items;
}

function _confirmarCopiarDatosGenerales(idx) {
  const item = (window._copiarDGItems || [])[idx];
  if (!item) return;
  const dg = item.planificacion?.datosGenerales || {};

  const setVal = (id, val) => {
    const el = document.getElementById(id);
    if (el && val !== undefined && val !== null) el.value = val;
  };

  setVal('familia-profesional', dg.familiaProfesional);
  setVal('codigo-fp', dg.codigoFP);
  setVal('nombre-bachillerato', dg.nombreBachillerato);
  setVal('codigo-titulo', dg.codigoTitulo);
  setVal('modulo-formativo', dg.moduloFormativo);
  setVal('codigo-modulo', dg.codigoModulo);
  setVal('nombre-docente', dg.nombreDocente);
  setVal('unidad-competencia', dg.unidadCompetencia);
  setVal('codigo-uc', dg.codigoUC);
  setVal('cantidad-ra', dg.cantidadRA);
  setVal('horas-semana', dg.horasSemana);

  // Copiar días de clase
  if (dg.diasClase) {
    Object.entries(dg.diasClase).forEach(([dia, cfg]) => {
      const checkbox = document.getElementById('dia-' + dia);
      if (!checkbox) return;
      checkbox.checked = cfg.activo;
      const wrap = document.getElementById('horas-' + dia + '-wrap');
      const horasInput = document.getElementById('horas-' + dia);
      const card = document.getElementById('dia-card-' + dia);
      if (cfg.activo) {
        if (wrap) wrap.classList.remove('hidden');
        if (horasInput) horasInput.value = cfg.horas;
        if (card) card.classList.add('seleccionado');
      } else {
        if (wrap) wrap.classList.add('hidden');
        if (card) card.classList.remove('seleccionado');
      }
    });
  }

  cerrarModalBtn();
  mostrarToast('Datos generales copiados correctamente ✓', 'success');
  window._copiarDGItems = null;
}

/** Guarda el estado de la biblioteca */



function persistirBiblioteca(biblio) {
  localStorage.setItem(BIBLIO_KEY, JSON.stringify(biblio));
  return _syncBibliotecaFirebase(biblio);
}

async function _syncBibliotecaFirebase(biblio) {
  if (!window._guardarBibliotecaChunks) return;
  try {
    await window._guardarBibliotecaChunks(biblio);
  } catch (e) {
    console.warn('Error sync biblioteca chunks:', e);
    mostrarToast('⚠ Error al sincronizar biblioteca con la nube.', 'warning');
  }
}







/** Guarda la planificación actual en la biblioteca */



async function guardarPlanificacionActual(silencioso = false) {



  const dg = planificacion.datosGenerales || {};



  const ra = planificacion.ra || {};







  if (!dg.moduloFormativo && !ra.descripcion) {



    mostrarToast('No hay datos suficientes para guardar. Completa al menos el Paso 1.', 'error');



    return;



  }







  guardarDatosFormulario(); // asegurar que lo último del form esté en el estado







  // Guardar diarias desde el DOM antes de persistir (para no perder contenido editado)
  guardarTodasDiarias();

  // Asegurar que todas las actividades tienen IDs únicos (fix bug IDs genéricos ACT-X-X)
  // Excluir el plan actual (_id) para que sus propios IDs no se consideren duplicados
  const _idsExistentes = new Set(
    (cargarBiblioteca().items || [])
      .filter(it => it.id !== planificacion._id)
      .flatMap(it => (it.planificacion?.actividades || []).map(a => a.id))
  );
  (planificacion.actividades || []).forEach(a => {
    if (!a.id || _idsExistentes.has(a.id)) {
      const oldId = a.id;
      a.id = 'act-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
      _idsExistentes.add(a.id);
      // Migrar la sesión diaria al nuevo ID para no perder el contenido generado
      if (oldId && estadoDiarias.sesiones[oldId]) {
        estadoDiarias.sesiones[a.id] = estadoDiarias.sesiones[oldId];
        delete estadoDiarias.sesiones[oldId];
      }
    }
  });
  // Si hubo migraciones, persistir diarias con los nuevos IDs
  persistirDiarias();

  const biblio = cargarBiblioteca();



  const id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);



  const ahora = new Date();







  const registro = {



    id,



    fechaGuardado: ahora.toISOString(),



    fechaGuardadoLabel: ahora.toLocaleDateString('es-DO', {



      day: '2-digit', month: 'long', year: 'numeric',



      hour: '2-digit', minute: '2-digit'



    }),



    nombre: (dg.moduloFormativo || 'Sin módulo') + ' — ' + (dg.nombreDocente || 'Sin docente'),



    planificacion: JSON.parse(JSON.stringify(planificacion, (k, v) =>



      v instanceof Date ? v.toISOString() : v



    ))



  };







  // Si tiene _id (fue cargada de biblioteca), actualizar directamente
  const existingId = planificacion._id;
  const idxById = existingId ? biblio.items.findIndex(i => i.id === existingId) : -1;
  if (idxById >= 0) {
    registro.id = existingId;
    biblio.items[idxById] = registro;
    mostrarToast('Planificación actualizada', 'success');
  } else {
    // Guardar siempre como nueva — mismo módulo puede tener varios RA/planes
    biblio.items.unshift(registro);
    mostrarToast('Planificación guardada correctamente', 'success');
  }
  planificacion._id = registro.id;

  // Guardar localmente primero (síncrono)
  localStorage.setItem('planificadorRA_biblioteca_v1', JSON.stringify(biblio));

  // Mostrar indicador de guardado en Firebase
  const btnGuardar = document.querySelector('[onclick*="guardarPlanificacionActual"]');
  if (btnGuardar) { btnGuardar.disabled = true; btnGuardar.dataset._origText = btnGuardar.innerHTML; btnGuardar.textContent = 'Guardando…'; }

  try {
    await _syncBibliotecaFirebase(biblio);
  } finally {
    if (btnGuardar) { btnGuardar.disabled = false; if (btnGuardar.dataset._origText) btnGuardar.innerHTML = btnGuardar.dataset._origText; }
  }

  // Asignar al curso seleccionado en Paso 1
  const finalId = registro.id;
  const cursosExist = Object.values(calState.cursos);
  const selCurso = document.getElementById('sel-curso-paso1');
  const cursoIdSel = selCurso ? selCurso.value : '';

  if (cursosExist.length > 0) {
    const yaAsignada = cursosExist.some(c => (c.planIds || []).includes(finalId));
    if (!yaAsignada) {
      if (!silencioso && !cursoIdSel) {
        // Advertir que falta seleccionar curso (sin bloquear el guardado)
        const aviso = document.getElementById('aviso-curso-paso1');
        if (aviso) {
          aviso.style.display = '';
          setTimeout(() => { aviso.style.display = 'none'; }, 5000);
        }
        selCurso?.focus();
      } else if (cursoIdSel && calState.cursos[cursoIdSel]) {
        const curso = calState.cursos[cursoIdSel];
        if (!curso.planIds) curso.planIds = [];
        if (!curso.planIds.includes(finalId)) {
          curso.planIds.push(finalId);
          if (!curso.planActivaId) curso.planActivaId = finalId;
          guardarCalificaciones();
          if (!silencioso) mostrarToast('Planificación guardada y asignada al curso "' + curso.nombre + '"', 'success');
        }
        const aviso = document.getElementById('aviso-curso-paso1');
        if (aviso) aviso.style.display = 'none';
      }
    }
  }
}

function _asignarDesdeGuardar(planId) {
  const cursoId = document.getElementById('modal-sel-curso-guardar')?.value;
  cerrarModalBtn();
  if (!cursoId || !calState.cursos[cursoId]) return;
  const curso = calState.cursos[cursoId];
  if (!curso.planIds) curso.planIds = [];
  if (!curso.planIds.includes(planId)) {
    curso.planIds.push(planId);
    if (!curso.planActivaId) curso.planActivaId = planId;
    guardarCalificaciones();
    mostrarToast('Planificación asignada al curso "' + curso.nombre + '"', 'success');
  }
}

/** Carga una planificación guardada y la restaura como activa */



function cargarPlanificacionGuardada(id) {



  const biblio = cargarBiblioteca();



  const registro = biblio.items.find(i => i.id === id);



  if (!registro) return;







  if (!confirm('¿Cargar la planificación "' + registro.nombre +



    '"? Los datos actuales no guardados se perderán.')) return;







  // Restaurar estado global



  planificacion = JSON.parse(JSON.stringify(registro.planificacion));
  planificacion._id = registro.id;







  // Restaurar fechas



  if (planificacion.actividades) {



    planificacion.actividades.forEach(a => {



      if (a.fecha && typeof a.fecha === 'string') a.fecha = new Date(a.fecha);



    });



  }



  if (planificacion.fechasClase) {



    planificacion.fechasClase.forEach(f => {



      if (f.fecha && typeof f.fecha === 'string') f.fecha = new Date(f.fecha);



    });



  }







  // Repoblar el formulario



  poblarFormularioDesdeEstado();







  // Regenerar vistas de EC y actividades si hay datos



  if (planificacion.elementosCapacidad?.length) {



    renderizarEC(planificacion.elementosCapacidad);



    renderizarActividades(planificacion.actividades);



    document.getElementById('btn-paso2-siguiente').disabled = false;



  }







  guardarBorrador(); // sincronizar con borrador activo







  // Cerrar panel de biblioteca y abrir el wizard en paso 1 (Datos Generales)
  _ocultarPaneles();
  irAlPaso(1, false);
  mostrarToast('Planificación "' + registro.nombre + '" cargada', 'success');
}

/** Carga una planificación completa en el editor y va directo al paso 5 (Planificaciones Diarias) */
function cargarPlanEnPaso1(planId) {
  const biblio = cargarBiblioteca();
  const registro = biblio.items.find(i => i.id === planId);
  if (!registro) { mostrarToast('Planificación no encontrada', 'error'); return; }
  planificacion = JSON.parse(JSON.stringify(registro.planificacion));
  planificacion._id = registro.id;
  if (planificacion.actividades) {
    planificacion.actividades.forEach(a => {
      if (a.fecha && typeof a.fecha === 'string') a.fecha = new Date(a.fecha);
    });
  }
  if (planificacion.fechasClase) {
    planificacion.fechasClase.forEach(f => {
      if (f.fecha && typeof f.fecha === 'string') f.fecha = new Date(f.fecha);
    });
  }
  poblarFormularioDesdeEstado();
  if (planificacion.elementosCapacidad?.length) {
    renderizarEC(planificacion.elementosCapacidad);
    renderizarActividades(planificacion.actividades);
    document.getElementById('btn-paso2-siguiente').disabled = false;
  }
  guardarBorrador();
  _ocultarPaneles();
  irAlPaso(1, false);
  mostrarToast('Planificación "' + registro.nombre + '" cargada', 'success');
}

function cargarPlanEnPaso5(planId) {
  const biblio = cargarBiblioteca();
  const registro = biblio.items.find(i => i.id === planId);
  if (!registro) { mostrarToast('Planificación no encontrada', 'error'); return; }

  planificacion = JSON.parse(JSON.stringify(registro.planificacion));
  planificacion._id = registro.id;

  if (planificacion.actividades) {
    planificacion.actividades.forEach(a => {
      if (a.fecha && typeof a.fecha === 'string') a.fecha = new Date(a.fecha);
    });
  }
  if (planificacion.fechasClase) {
    planificacion.fechasClase.forEach(f => {
      if (f.fecha && typeof f.fecha === 'string') f.fecha = new Date(f.fecha);
    });
  }

  poblarFormularioDesdeEstado();

  if (planificacion.elementosCapacidad?.length) {
    renderizarEC(planificacion.elementosCapacidad);
    renderizarActividades(planificacion.actividades);
    document.getElementById('btn-paso2-siguiente').disabled = false;
  }

  guardarBorrador();
  _ocultarPaneles();
  irAlPaso(5, false);
  mostrarToast('Planificación "' + registro.nombre + '" cargada', 'success');
}







/** Elimina una planificación de la biblioteca */




// ════════════════════════════════════════════════════════════════════
// EXPORTAR PLANIFICACIÓN DESDE LISTADO (sin cargarla)
// ════════════════════════════════════════════════════════════════════
async function exportarPlanDesdeListado(id) {
  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === id);
  if (!reg || !reg.planificacion) { mostrarToast('Planificación no encontrada', 'error'); return; }

  // Guardar estado actual y poner temporalmente la planificación a exportar
  const backupPlan = planificacion;
  try {
    planificacion = JSON.parse(JSON.stringify(reg.planificacion));
    mostrarToast('Exportando a Word...', 'info');
    await _exportarConPlantillaCentro() || _exportarWordHTML();
  } catch (e) {
    console.warn('[ExportListado] Error:', e);
    mostrarToast('Error al exportar: ' + e.message, 'error');
  } finally {
    planificacion = backupPlan;
  }
}

async function exportarDiariasDesdeListado(id) {
  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === id);
  if (!reg || !reg.planificacion) { mostrarToast('Planificación no encontrada', 'error'); return; }

  const acts = reg.planificacion.actividades || [];
  if (!acts.length) { mostrarToast('Esta planificación no tiene actividades/sesiones', 'error'); return; }

  // Verificar que hay sesiones diarias para estas actividades
  const diarias = JSON.parse(localStorage.getItem(DIARIAS_KEY) || '{"sesiones":{}}');
  const tieneSesiones = acts.some(a => diarias.sesiones && diarias.sesiones[a.id]);
  if (!tieneSesiones) {
    mostrarToast('No hay planificaciones diarias generadas para esta planificación. Cárgala primero y genera las sesiones.', 'warning');
    return;
  }

  // Swap temporal
  const backupPlan = planificacion;
  const backupDiarias = estadoDiarias;
  try {
    planificacion = JSON.parse(JSON.stringify(reg.planificacion));
    // estadoDiarias ya tiene las sesiones en localStorage, solo recargar
    cargarDiarias();
    mostrarToast('Exportando diarias a Word...', 'info');
    await exportarDiariasWord();
  } catch (e) {
    console.warn('[ExportDiariasListado] Error:', e);
    mostrarToast('Error al exportar diarias: ' + e.message, 'error');
  } finally {
    planificacion = backupPlan;
    estadoDiarias = backupDiarias;
  }
}

function _exportarWordHTML() {
  // Generar vista previa temporal para export HTML-Word
  const dg = planificacion.datosGenerales || {};
  const ra = planificacion.ra || {};
  const ec = planificacion.elementosCapacidad || [];
  const acts = planificacion.actividades || [];
  const nivelLabel = { conocimiento: 'Conocimiento', comprension: 'Comprensión', aplicacion: 'Aplicación', actitudinal: 'Actitudinal' };

  // Tabla EC
  let tablaEC = '<table border="1" cellpadding="4" cellspacing="0" style="width:100%;border-collapse:collapse;">';
  tablaEC += '<tr style="background:#1565C0;color:#fff;"><th>Código</th><th>Enunciado del EC</th><th>Nivel</th><th>Horas</th></tr>';
  ec.forEach(e => {
    tablaEC += '<tr><td>' + (e.codigo || '') + '</td><td>' + (e.enunciado || '') + '</td><td>' + (nivelLabel[e.nivel] || '') + '</td><td>' + (e.horasAsignadas || '') + 'h</td></tr>';
  });
  tablaEC += '</table>';

  // Tabla Actividades agrupada por EC
  const _seq = {};
  const groups = [];
  const gmap = {};
  acts.filter(a => !a.esComplementario).forEach(a => {
    const c = a.ecCodigo || '';
    if (!gmap[c]) { gmap[c] = { code: c, acts: [] }; groups.push(gmap[c]); }
    _seq[c] = (_seq[c] || 0);
    gmap[c].acts.push({ ...a, num: _getActNumero(c, _seq[c]) });
    _seq[c]++;
  });
  let tablaActs = '<table border="1" cellpadding="4" cellspacing="0" style="width:100%;border-collapse:collapse;">';
  tablaActs += '<tr style="background:#1565C0;color:#fff;"><th>Elemento de Capacidad (EC)</th><th>Nivel de Dominio</th><th>Enunciado de Actividad</th><th>Fecha</th><th>Instrumento</th></tr>';
  groups.forEach(g => {
    const ecInfo = ec.find(e => e.codigo === g.code);
    g.acts.forEach((a, i) => {
      tablaActs += '<tr>';
      if (i === 0) {
        tablaActs += '<td rowspan="' + g.acts.length + '" style="vertical-align:top;font-weight:bold;">' + (g.code || '') + '<br>' + (ecInfo?.enunciado || '') + '</td>';
        tablaActs += '<td rowspan="' + g.acts.length + '" style="vertical-align:middle;text-align:center;">' + (nivelLabel[ecInfo?.nivel] || '') + '</td>';
      }
      tablaActs += '<td>' + a.num + ': ' + (a.enunciado || '') + '</td>';
      tablaActs += '<td>' + (a.fechaStr || '') + '</td>';
      tablaActs += '<td>' + (a.instrumento?.tipoLabel || '') + '</td>';
      tablaActs += '</tr>';
    });
  });
  tablaActs += '</table>';

  const contenido = '<h2 style="text-align:center;">Planificación por RA</h2>'
    + '<p><b>Módulo Formativo:</b> ' + (dg.moduloFormativo || '') + '</p>'
    + '<p><b>Docente:</b> ' + (dg.nombreDocente || '') + '</p>'
    + '<p><b>RA:</b> ' + (ra.descripcion || '') + '</p>'
    + '<h3>Elementos de Capacidad</h3>' + tablaEC
    + '<h3>Actividades de Enseñanza/Aprendizaje</h3>' + tablaActs;

  const html = '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:w="urn:schemas-microsoft-com:office:word" xmlns="http://www.w3.org/TR/REC-html40"><head><meta charset="utf-8"/><style>body{font-family:Calibri,Arial;font-size:11pt;margin:2cm;}table{width:100%;border-collapse:collapse;}th,td{border:1pt solid #999;padding:6pt;font-size:10pt;}th{background:#1565C0;color:#fff;}</style></head><body>' + contenido + '</body></html>';
  const blob = new Blob(['\ufeff', html], { type: 'application/msword' });
  const nombre = _nombreArchivoRA('doc');
  const link = document.createElement('a');
  link.href = URL.createObjectURL(blob);
  link.download = nombre;
  link.click();
  URL.revokeObjectURL(link.href);
  mostrarToast('Planificación exportada', 'success');
  return true;
}

// ════════════════════════════════════════════════════════════════════
// DUPLICAR PLANIFICACIÓN
// ════════════════════════════════════════════════════════════════════
let _dupPlanId = null; // id del registro original a duplicar

/** Devuelve el ISO date del próximo día de clase ≥ desde, según diasClase */
function _proximoDiaClaseDesde(diasClase, desde) {
  const diasActivos = new Set(
    Object.entries(diasClase || {})
      .filter(([, v]) => v && v.activo)
      .map(([d]) => _FP_MAPA_DIA[d])
      .filter(n => n !== undefined)
  );
  if (!diasActivos.size) return _isoDate(desde);
  const d = new Date(_isoDate(desde) + 'T12:00:00');
  for (let i = 0; i < 14; i++) {
    if (diasActivos.has(d.getDay())) return _isoDate(d);
    d.setDate(d.getDate() + 1);
  }
  return _isoDate(desde);
}

/** Actualiza el input de fecha de inicio en el modal de duplicar al próximo día de clase del curso destino */
function _actualizarFechaInicioDup() {
  const inputFecha = document.getElementById('dup-plan-fecha-inicio');
  if (!inputFecha) return;
  const cursoId = document.getElementById('dup-plan-curso')?.value;
  const cursoDest = cursoId ? calState.cursos[cursoId] : null;
  if (!cursoDest) { inputFecha.value = _isoDate(new Date()); return; }
  const biblio = cargarBiblioteca();
  const planIds = [...new Set(cursoDest.planIds || [])];
  // Replicar la misma lógica de _actualizarAvisoDesdeSel para encontrar diasClase
  const planesCurso = planIds
    .map(pid => (biblio.items || []).find(i => i.id === pid))
    .filter(p => p?.planificacion?.datosGenerales?.diasClase);
  const horarioSel = document.getElementById('dup-plan-horario-origen');
  const horarioWrap = document.getElementById('dup-plan-horario-wrap');
  const refPlanId = (horarioWrap?.style.display !== 'none' && horarioSel?.value)
    ? horarioSel.value : cursoDest.planActivaId;
  const planRef = refPlanId
    ? (biblio.items || []).find(i => i.id === refPlanId)
    : planesCurso[0];
  const diasClase = planRef?.planificacion?.datosGenerales?.diasClase
    || planesCurso[0]?.planificacion?.datosGenerales?.diasClase
    || null;
  inputFecha.value = _proximoDiaClaseDesde(diasClase, new Date());
}

function abrirDuplicarPlan(id) {
  const biblio = cargarBiblioteca();
  const reg = (biblio.items || []).find(i => i.id === id);
  if (!reg) return;
  _dupPlanId = id;

  const dg = reg.planificacion?.datosGenerales || {};

  // Mostrar info del original
  const origen = document.getElementById('dup-plan-origen');
  if (origen) origen.innerHTML =
    `<strong>Original:</strong> ${escHTML(dg.moduloFormativo || reg.nombre || 'Sin nombre')}` +
    (dg.nombreBachillerato ? ` · ${escHTML(dg.nombreBachillerato)}` : '') +
    `<br><span style="color:#9E9E9E;">Guardada el ${escHTML(reg.fechaGuardadoLabel || reg.fechaGuardado || '—')}</span>`;

  // Nombre por defecto: "Copia de X"
  const inputNombre = document.getElementById('dup-plan-nombre');
  if (inputNombre) inputNombre.value = `Copia de ${dg.moduloFormativo || reg.nombre || 'planificación'}`;

  // Llenar select de cursos
  const sel = document.getElementById('dup-plan-curso');
  if (sel) {
    sel.innerHTML = '<option value="">Sin asignar (puedo hacerlo después)</option>' +
      Object.values(calState.cursos).map(c =>
        `<option value="${c.id}">${escHTML(c.nombre)}</option>`
      ).join('');
    // Pre-seleccionar el curso activo si existe
    if (calState.cursoActivoId) sel.value = calState.cursoActivoId;
    sel.addEventListener('change', () => {
      _actualizarAvisHorarioCurso(reg);
      _actualizarFechaInicioDup();
      document.getElementById('dup-plan-fecha-inicio')?.dispatchEvent(new Event('input'));
    });
  }
  // Mostrar aviso de horario inicial
  _actualizarAvisHorarioCurso(reg);

  // Calcular fechas de actividades del original (normalizar a ISO string)
  const actividades = reg.planificacion?.actividades || [];
  const fechasActs = actividades.map(a => {
    if (!a.fecha) return null;
    if (a.fecha instanceof Date) return a.fecha.toISOString().split('T')[0];
    const s = String(a.fecha);
    // Si ya es YYYY-MM-DD
    if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
    // Si es ISO con T
    if (s.includes('T')) return s.split('T')[0];
    // Intentar parsear
    const d = new Date(s);
    return isNaN(d.getTime()) ? null : d.toISOString().split('T')[0];
  }).filter(Boolean).sort();
  const primerFecha = fechasActs[0] || null;
  const ultimaFecha = fechasActs[fechasActs.length - 1] || null;

  // Fecha de inicio por defecto: próximo día de clase del curso destino (o hoy si no hay horario)
  _actualizarFechaInicioDup();
  const inputFecha = document.getElementById('dup-plan-fecha-inicio');

  // Preview de fechas
  _actualizarPreviewDupFechas(primerFecha, ultimaFecha, fechasActs.length);

  // Esconder/mostrar según toggle
  const toggle = document.getElementById('dup-plan-ajustar-fechas');
  if (toggle) toggleDupFechas(toggle.checked);

  // Guardar contexto de fechas en el input (como data attrs accesibles)
  if (inputFecha) {
    inputFecha.dataset.primeraOriginal = primerFecha || '';
    inputFecha.dataset.ultimaOriginal = ultimaFecha || '';
    inputFecha.dataset.totalActs = fechasActs.length;
    inputFecha.oninput = () => _actualizarPreviewDupFechas(primerFecha, ultimaFecha, fechasActs.length);
  }

  document.getElementById('dup-plan-overlay')?.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function cerrarDuplicarPlan() {
  document.getElementById('dup-plan-overlay')?.classList.add('hidden');
  document.body.style.overflow = '';
  _dupPlanId = null;
}

function toggleDupFechas(on) {
  const wrap = document.getElementById('dup-plan-fechas-wrap');
  if (wrap) wrap.style.display = on ? 'block' : 'none';
}

function _actualizarPreviewDupFechas(primeraOriginal, ultimaOriginal, totalActs) {
  const preview = document.getElementById('dup-plan-fechas-preview');
  const inputVal = document.getElementById('dup-plan-fecha-inicio')?.value;
  if (!preview) return;
  if (!primeraOriginal || !totalActs) {
    preview.innerHTML = '<span style="color:#B0BEC5;">Las actividades no tienen fechas asignadas.</span>';
    return;
  }
  if (!inputVal) { preview.innerHTML = ''; return; }
  // Calcular el desplazamiento en días
  const orig = new Date(primeraOriginal + 'T12:00:00');
  const nueva = new Date(inputVal + 'T12:00:00');
  const diffMs = nueva - orig;
  const diffDias = Math.round(diffMs / 86400000);
  const signo = diffDias >= 0 ? '+' : '';
  // Calcular nueva fecha final
  const nuevaFin = ultimaOriginal
    ? new Date(new Date(ultimaOriginal + 'T12:00:00').getTime() + diffMs).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' })
    : '—';
  preview.innerHTML = `
    <span class="material-icons" style="font-size:12px;vertical-align:middle;color:#1565C0;">info</span>
    Se moverán <strong>${totalActs}</strong> actividad(es) <strong>${signo}${diffDias} días</strong>.
    Nueva fecha de cierre: <strong>${nuevaFin}</strong>.`;
}

function _actualizarAvisHorarioCurso(regOriginal) {
  const aviso = document.getElementById('dup-plan-aviso-horario');
  const horarioWrap = document.getElementById('dup-plan-horario-wrap');
  const horarioSel = document.getElementById('dup-plan-horario-origen');
  if (!aviso) return;

  const cursoId = document.getElementById('dup-plan-curso')?.value;
  if (!cursoId) {
    aviso.style.display = 'none';
    if (horarioWrap) horarioWrap.style.display = 'none';
    return;
  }

  const cursoDest = calState.cursos[cursoId];
  const biblio = cargarBiblioteca();
  // Deduplicar planIds
  const planIds = [...new Set(cursoDest?.planIds || [])];

  // Obtener planificaciones únicas del curso que tengan diasClase
  const planesCurso = planIds
    .map(pid => (biblio.items || []).find(i => i.id === pid))
    .filter(p => p && p.planificacion?.datosGenerales?.diasClase);

  // Agrupar por horario único (evitar opciones duplicadas por mismo módulo con mismo horario)
  const _normDia = s => s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  const resumenDiasKey = (dias) => Object.entries(dias)
    .filter(([, v]) => v.activo)
    .map(([d, v]) => `${_normDia(d)}:${v.horas}`)
    .sort().join('|');

  const vistosHorario = new Set();
  const planesCursoUnicos = planesCurso.filter(p => {
    const key = resumenDiasKey(p.planificacion.datosGenerales.diasClase);
    if (vistosHorario.has(key)) return false;
    vistosHorario.add(key);
    return true;
  });

  // Construir selector solo si hay múltiples horarios distintos
  if (planesCursoUnicos.length > 1 && horarioWrap && horarioSel) {
    if (horarioSel.dataset.cursoId !== cursoId) {
      horarioSel.innerHTML = planesCursoUnicos.map(p => {
        const dg = p.planificacion.datosGenerales;
        const resumen = Object.entries(dg.diasClase)
          .filter(([, v]) => v.activo)
          .map(([d, v]) => `${d.charAt(0).toUpperCase() + d.slice(1)} (${v.horas}h)`)
          .join(', ');
        const modulo = dg.moduloFormativo || p.nombre || p.id;
        return `<option value="${p.id}">${escHTML(modulo)} — ${escHTML(resumen)}</option>`;
      }).join('');
      horarioSel.dataset.cursoId = cursoId;
      if (cursoDest.planActivaId) horarioSel.value = cursoDest.planActivaId;
      // Si planActivaId no está en los únicos, usar el primero
      if (!horarioSel.value) horarioSel.value = planesCursoUnicos[0].id;
    }
    horarioWrap.style.display = 'block';
  } else {
    if (horarioWrap) { horarioWrap.style.display = 'none'; if (horarioSel) horarioSel.dataset.cursoId = ''; }
  }

  // Actualizar aviso con la planificación actualmente seleccionada en el selector
  _actualizarAvisoDesdeSel(regOriginal, cursoDest, biblio, planesCurso);
}

function _actualizarAvisoDesdeSel(regOriginal, cursoDest, biblio, planesCurso) {
  const aviso = document.getElementById('dup-plan-aviso-horario');
  const horarioSel = document.getElementById('dup-plan-horario-origen');
  const horarioWrap = document.getElementById('dup-plan-horario-wrap');
  if (!aviso || !cursoDest) return;

  const refPlanId = (horarioWrap?.style.display !== 'none' && horarioSel?.value)
    ? horarioSel.value
    : cursoDest?.planActivaId;
  const planRef = refPlanId ? (biblio.items || []).find(i => i.id === refPlanId) : (planesCurso || [])[0];
  const diasDestino = planRef?.planificacion?.datosGenerales?.diasClase;
  const diasOrigen  = regOriginal?.planificacion?.datosGenerales?.diasClase;

  if (!diasDestino) { aviso.style.display = 'none'; return; }

  const resumenDias = (dias) => Object.entries(dias)
    .filter(([, v]) => v.activo)
    .map(([d, v]) => `${d.charAt(0).toUpperCase() + d.slice(1)} (${v.horas}h)`)
    .join(', ');

  const strDestino = resumenDias(diasDestino);
  const strOrigen  = diasOrigen ? resumenDias(diasOrigen) : '';

  if (strDestino !== strOrigen) {
    aviso.style.display = 'block';
    aviso.innerHTML = `<span class="material-icons" style="font-size:14px;vertical-align:middle;color:#E65100;">swap_horiz</span>
      <strong>Horario diferente detectado.</strong> Las fechas se recalcularán según el horario de <strong>${escHTML(cursoDest.nombre)}</strong>:
      <br><span style="color:#1565C0;">${escHTML(strDestino)}</span>`;
  } else {
    aviso.style.display = 'none';
  }
}

function _actualizarAvisHorarioCursoConSel() {
  // Llamado al cambiar la selección del horario — solo actualiza el aviso
  const aviso = document.getElementById('dup-plan-aviso-horario');
  if (!aviso) return;

  const biblio = cargarBiblioteca();
  const regOrig = _dupPlanId ? (biblio.items || []).find(i => i.id === _dupPlanId) : null;
  const cursoId = document.getElementById('dup-plan-curso')?.value;
  const cursoDest = cursoId ? calState.cursos[cursoId] : null;
  const horarioSelId = document.getElementById('dup-plan-horario-origen')?.value;

  if (!regOrig || !cursoDest || !horarioSelId) return;

  const planSel = (biblio.items || []).find(i => i.id === horarioSelId);
  const diasDestino = planSel?.planificacion?.datosGenerales?.diasClase;
  const diasOrigen  = regOrig?.planificacion?.datosGenerales?.diasClase;

  if (!diasDestino) { aviso.style.display = 'none'; return; }

  const resumenDias = (dias) => Object.entries(dias)
    .filter(([, v]) => v.activo)
    .map(([d, v]) => `${d.charAt(0).toUpperCase() + d.slice(1)} (${v.horas}h)`)
    .join(', ');

  const strDestino = resumenDias(diasDestino);
  const strOrigen  = diasOrigen ? resumenDias(diasOrigen) : '';

  if (strDestino !== strOrigen) {
    aviso.style.display = 'block';
    aviso.innerHTML = `<span class="material-icons" style="font-size:14px;vertical-align:middle;color:#E65100;">swap_horiz</span>
      <strong>Horario diferente detectado.</strong> Las fechas se recalcularán con este horario:
      <br><span style="color:#1565C0;">${escHTML(strDestino)}</span>`;
  } else {
    aviso.style.display = 'none';
  }
}

async function confirmarDuplicarPlan() {
  if (!_dupPlanId) return;
  const biblio = cargarBiblioteca();
  const original = (biblio.items || []).find(i => i.id === _dupPlanId);
  if (!original) { mostrarToast('Planificación no encontrada', 'error'); return; }

  // Clonar profundamente
  const copia = JSON.parse(JSON.stringify(original));

  // Nuevo id y fecha de guardado
  const ahora = new Date();
  copia.id = Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
  copia.fechaGuardado = ahora.toISOString();
  copia.fechaGuardadoLabel = ahora.toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' });

  // Nombre personalizado
  const inputNombre = document.getElementById('dup-plan-nombre')?.value?.trim();
  copia.nombre = inputNombre || `Copia de ${original.nombre}`;
  if (copia.planificacion?.datosGenerales) {
    copia.planificacion.datosGenerales.moduloFormativo =
      inputNombre || `Copia de ${original.planificacion.datosGenerales.moduloFormativo || original.nombre}`;
  }

  // Ajustar fechas de actividades
  const ajustar = document.getElementById('dup-plan-ajustar-fechas')?.checked;
  const inputFecha = document.getElementById('dup-plan-fecha-inicio');
  const cursoId = document.getElementById('dup-plan-curso')?.value;

  if (ajustar && inputFecha?.value) {
    const nuevaFechaInicio = inputFecha.value; // YYYY-MM-DD

    // Obtener horario del curso destino: usar el selector si hay múltiples, si no la activa
    const cursoDest = cursoId ? calState.cursos[cursoId] : null;
    const biblio2 = cargarBiblioteca();
    const horarioSelId = document.getElementById('dup-plan-horario-origen')?.value;
    const horarioWrapVisible = document.getElementById('dup-plan-horario-wrap')?.style.display !== 'none';
    const planRefId = (horarioWrapVisible && horarioSelId) ? horarioSelId : cursoDest?.planActivaId;
    const planActiva = planRefId ? (biblio2.items || []).find(i => i.id === planRefId) : null;
    const diasClaseCurso = planActiva?.planificacion?.datosGenerales?.diasClase;
    const diasClaseOrigen = copia.planificacion?.datosGenerales?.diasClase;

    // Verificar si el curso destino tiene un horario diferente al origen
    const diasDestino = diasClaseCurso
      ? Object.entries(diasClaseCurso).filter(([, v]) => v.activo).map(([d]) => d).sort().join(',')
      : null;
    const diasOrigen = diasClaseOrigen
      ? Object.entries(diasClaseOrigen).filter(([, v]) => v.activo).map(([d]) => d).sort().join(',')
      : null;
    const horarioDiferente = diasDestino && diasDestino !== diasOrigen;

    const acts = copia.planificacion?.actividades || [];

    if (horarioDiferente && diasClaseCurso) {
      // Recalcular fechas usando el horario del curso destino
      const dgCopia = copia.planificacion.datosGenerales;
      const fechaFin = dgCopia.fechaTermino || null;

      // Actualizar diasClase y fechaInicio en la copia
      dgCopia.diasClase = diasClaseCurso;
      dgCopia.fechaInicio = nuevaFechaInicio;

      const festivosAdmin = typeof _calEscGetFestivosAdmin === 'function' ? _calEscGetFestivosAdmin() : [];
      const nuevasFechas = calcularFechasClase(diasClaseCurso, nuevaFechaInicio, fechaFin || nuevaFechaInicio, festivosAdmin);

      // Asignar nueva fecha a cada actividad en orden
      acts.forEach((act, i) => {
        const fechaObj = nuevasFechas[i] || nuevasFechas[nuevasFechas.length - 1] || null;
        if (fechaObj) {
          act.fecha = fechaObj.fecha;
          act.fechaStr = fechaObj.fechaStr;
        }
      });

      mostrarToast('📅 Fechas recalculadas según el horario del curso destino.', 'info');
    } else {
      // Mismo horario o sin horario destino: desplazar fechas proporcionalmente
      const primeraOriginal = inputFecha?.dataset?.primeraOriginal || '';
      if (primeraOriginal.length === 10) {
        const orig = new Date(primeraOriginal + 'T12:00:00');
        const nueva = new Date(nuevaFechaInicio + 'T12:00:00');
        const diffMs = nueva - orig;
        acts.forEach(act => {
          if (act.fecha) {
            try {
              const s = String(act.fecha);
              let fechaISO = /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : s.includes('T') ? s.split('T')[0] : null;
              if (!fechaISO) { const d = new Date(s); fechaISO = isNaN(d.getTime()) ? null : d.toISOString().split('T')[0]; }
              if (fechaISO) {
                const nuevaFecha = new Date(new Date(fechaISO + 'T12:00:00').getTime() + diffMs);
                if (!isNaN(nuevaFecha.getTime())) {
                  act.fecha = nuevaFecha.toISOString().split('T')[0];
                  act.fechaStr = nuevaFecha.toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
                }
              }
            } catch (e) { /* conservar fecha original */ }
          }
        });
      }
    }
  }

  // Asignar a curso si se seleccionó
  if (cursoId && calState.cursos[cursoId]) {
    const curso = calState.cursos[cursoId];
    if (!curso.planIds) curso.planIds = [];
    if (!curso.planIds.includes(copia.id)) {
      curso.planIds.push(copia.id);
      if (!curso.planActivaId) curso.planActivaId = copia.id;
    }
    guardarCalificaciones();
  }

  // Guardar la copia en la biblioteca (al inicio de la lista)
  biblio.items.unshift(copia);

  // Guardar localmente primero
  localStorage.setItem('planificadorRA_biblioteca_v1', JSON.stringify(biblio));

  // Mostrar indicador mientras guarda en Firebase
  const btnConfirmar = document.getElementById('btn-confirmar-duplicar');
  if (btnConfirmar) { btnConfirmar.disabled = true; btnConfirmar.textContent = 'Guardando…'; }

  try {
    await _syncBibliotecaFirebase(biblio);
  } finally {
    if (btnConfirmar) { btnConfirmar.disabled = false; btnConfirmar.innerHTML = '<span class="material-icons" style="font-size:16px;">content_copy</span> Duplicar'; }
  }

  cerrarDuplicarPlan();
  renderizarBiblioteca();
  mostrarToast(`✅ Planificación duplicada y guardada: "${copia.nombre}"`, 'success');
}

function eliminarPlanificacionGuardada(id) {



  const biblio = cargarBiblioteca();



  const reg = biblio.items.find(i => i.id === id);



  if (!reg) return;



  if (!confirm('¿Eliminar la planificación "' + reg.nombre + '"? Esta acción no se puede deshacer.')) return;







  biblio.items = biblio.items.filter(i => i.id !== id);

  // Limpiar el ID eliminado de todos los cursos en calificaciones
  Object.values(calState.cursos).forEach(curso => {
    if ((curso.planIds || []).includes(id)) {
      curso.planIds = curso.planIds.filter(pid => pid !== id);
      if (curso.planActivaId === id) curso.planActivaId = curso.planIds[0] || null;
    }
  });
  guardarCalificaciones();

  persistirBiblioteca(biblio);



  renderizarBiblioteca();



  registrarCambio(`Planificación eliminada: "${reg.nombre}"`);
  mostrarToast('Planificación eliminada', 'info');



}







/** Filtra las tarjetas según el texto del buscador */



function filtrarPlanificaciones() {



  const q = (document.getElementById('pln-buscador')?.value || '').toLowerCase();



  document.querySelectorAll('.pln-card').forEach(card => {



    const texto = card.dataset.busqueda || '';



    card.style.display = texto.includes(q) ? '' : 'none';



  });



}







