function guardarApiKey() {
  const groqKey = document.getElementById('input-groq-key')?.value?.trim();
  const geminiKey = document.getElementById('input-gemini-key')?.value?.trim();
  const openrouterKey = document.getElementById('input-openrouter-key')?.value?.trim();

  if (!groqKey && !geminiKey && !openrouterKey) { mostrarToast('Ingresa al menos una clave', 'error'); return; }
  if (groqKey && !groqKey.startsWith('gsk_')) { mostrarToast('La clave de Groq debe comenzar con "gsk_..."', 'error'); return; }
  if (geminiKey && !geminiKey.startsWith('AIza')) { mostrarToast('La clave de Gemini debe comenzar con "AIza..."', 'error'); return; }
  if (openrouterKey && !openrouterKey.startsWith('sk-or-')) { mostrarToast('La clave de OpenRouter debe comenzar con "sk-or-..."', 'error'); return; }

  if (groqKey) localStorage.setItem(GROQ_KEY_STORAGE, groqKey);
  else localStorage.removeItem(GROQ_KEY_STORAGE);

  if (geminiKey) localStorage.setItem(GEMINI_KEY_STORAGE, geminiKey);
  else localStorage.removeItem(GEMINI_KEY_STORAGE);

  if (openrouterKey) localStorage.setItem(OPENROUTER_KEY_STORAGE, openrouterKey);
  else localStorage.removeItem(OPENROUTER_KEY_STORAGE);

  // Sincronizar claves con Firebase
  if (window._syncFirebase) {
    window._syncFirebase('groqKey', groqKey || '');
    window._syncFirebase('geminiKey', geminiKey || '');
    window._syncFirebase('openrouterKey', openrouterKey || '');
  }

  actualizarBtnConfigIA();
  cerrarModalBtn();
  const proveedores = [groqKey && 'Groq', geminiKey && 'Gemini', openrouterKey && 'OpenRouter'].filter(Boolean).join(' + ');
  mostrarToast(`Claves guardadas (${proveedores}). La IA está lista.`, 'success');
}

function borrarApiKey() {
  localStorage.removeItem(GROQ_KEY_STORAGE);
  localStorage.removeItem(GEMINI_KEY_STORAGE);
  localStorage.removeItem(OPENROUTER_KEY_STORAGE);
  if (window._syncFirebase) {
    window._syncFirebase('groqKey', '');
    window._syncFirebase('geminiKey', '');
    window._syncFirebase('openrouterKey', '');
  }
  actualizarBtnConfigIA();
  cerrarModalBtn();
  mostrarToast('Claves eliminadas. Se usará generación local.', 'info');
}

function actualizarBtnConfigIA() {
  const btn = document.getElementById('btn-config-ia');
  if (!btn) return;
  if (getGroqKey() || getGeminiKey() || getOpenRouterKey()) {
    btn.classList.add('ia-activa');
    btn.title = 'IA configurada ✓ — clic para cambiar las claves';
  } else {
    btn.classList.remove('ia-activa');
    btn.title = 'Configurar claves de IA';
  }
}

// ─────────────────────────────────────────────────────────────
// CONSTRUCTOR DEL PROMPT
// ─────────────────────────────────────────────────────────────

async function construirPromptBase(dg, ra) {
  const diasClaseObj = dg.diasClase || {};
  const diasArr = Object.entries(diasClaseObj)
    .filter(([_k, v]) => v && v.activo)
    .map(([dia, v]) => `${dia} (${v.horas}h)`);
  const diasStr = diasArr.length > 0 ? diasArr.join(', ') : (dg.horasSemana + ' hrs/semana');

  const cantEC = parseInt(dg.cantidadEC) || 4;
  const actsPorEC = parseInt(dg.cantidadActPorEC) || 1;
  const totalActs = cantEC * actsPorEC;

  // Niveles de Bloom cíclicos para los EC
  const nivelesBloom = ['conocimiento', 'comprension', 'aplicacion', 'actitudinal'];
  const verbosNivel = {
    conocimiento: 'Verbo conocimiento (Identificar, Reconocer, Clasificar...)',
    comprension: 'Verbo comprensión (Explicar, Describir, Comparar...)',
    aplicacion: 'Verbo aplicación (Aplicar, Implementar, Ejecutar...)',
    actitudinal: 'Verbo actitudinal (Valorar, Asumir, Demostrar compromiso...)'
  };

  // Generar lista de ECs esperados
  const ecCodigos = [];
  for (let i = 0; i < cantEC; i++) {
    const nivel = nivelesBloom[i % nivelesBloom.length];
    ecCodigos.push({ codigo: `E.C.${i + 1}.1.1`, nivel });
  }

  // Generar lista de actividades esperadas
  const instrumentos = ['cotejo', 'rubrica', 'valoracion', 'estimativa', 'rango', 'diario'];
  const actEsperadas = [];
  let actIdx = 0;
  for (let i = 0; i < cantEC; i++) {
    for (let j = 0; j < actsPorEC; j++) {
      actEsperadas.push({ ecCodigo: `E.C.${i + 1}.1.1`, inst: instrumentos[actIdx % instrumentos.length] });
      actIdx++;
    }
  }

  const ecCodigosLista = ecCodigos.map(e => `   - ${e.codigo} → nivel: ${e.nivel}`).join('\n');
  const ecCodigosJSON = ecCodigos.map(e => `    {"codigo":"${e.codigo}","nivel":"${e.nivel}","nivelBloom":"${e.nivel}","enunciado":"VERBO + OBJETO + MODO DE HACER"}`).join(',\n');
  const actEsperadasJSON = actEsperadas.map(a => `    {"ecCodigo":"${a.ecCodigo}","enunciado":"Tipo: actividad concreta y específica","instrumento":"${a.inst}"}`).join(',\n');

  return _getPromptResuelto('prompt_base', {
    moduloFormativo: dg.moduloFormativo || '',
    familiaProfesional: dg.familiaProfesional || '',
    diasStr,
    raDescripcion: ra.descripcion || '',
    raCriterios: ra.criterios || 'No especificados',
    raRecursos: ra.recursosDid || 'Pizarrón, guías',
    contenidosBloque: _buildContenidosBloque(ra),
    cantEC, actsPorEC, totalActs,
    ecCodigosLista, ecCodigosJSON, actEsperadasJSON
  });
}

async function construirPromptInstrumentos(dg, ra, actividades, elementosCapacidad) {
  const acts = actividades.map((a, i) => {
    const ec = elementosCapacidad.find(e => e.codigo === a.ecCodigo) || {};
    return `${i + 1}. [${a.ecCodigo}] Actividad: "${a.enunciado}" | EC: "${ec.enunciado || ''}" | tipo instrumento: ${a.instrumento} | nivel Bloom: ${ec.nivel || ''}`;
  }).join('\n');

  return _getPromptResuelto('prompt_instrumentos', {
    moduloFormativo: dg.moduloFormativo || '',
    raDescripcion: ra.descripcion || '',
    actividadesLista: acts
  });
}

