function iniciarTour() {
  _tourPaso = 0;
  _tourOriginalOverflow = document.body.style.overflow;
  document.getElementById('tour-overlay').classList.remove('hidden');
  _tourRenderizarPaso(_tourPaso);
}

function _tourVerificarAutoInicio() {
  if (!localStorage.getItem(TOUR_KEY)) {
    setTimeout(iniciarTour, 900);
  }
}

function _tourRenderizarPaso(n) {
  const paso = TOUR_PASOS[n];
  const total = TOUR_PASOS.length;
  document.getElementById('tour-icono').textContent = paso.icono;
  document.getElementById('tour-titulo').textContent = paso.titulo;
  document.getElementById('tour-desc').textContent = paso.desc;
  document.getElementById('tour-paso-label').textContent = `Paso ${n + 1} de ${total}`;

  document.getElementById('tour-dots').innerHTML = TOUR_PASOS.map((_, i) =>
    `<div class="tour-dot ${i === n ? 'activo' : ''}"></div>`
  ).join('');

  const btnAnt = document.getElementById('tour-btn-ant');
  const btnSig = document.getElementById('tour-btn-sig');
  if (btnAnt) btnAnt.style.display = n === 0 ? 'none' : '';
  if (btnSig) btnSig.textContent = n === total - 1 ? '¡Listo! ✓' : 'Siguiente →';

  const targetEl = paso.target ? document.querySelector(paso.target) : null;
  _tourPosicionarCaja(targetEl);
}

function _tourPosicionarCaja(targetEl) {
  const spotlight = document.getElementById('tour-spotlight');
  const caja = document.getElementById('tour-caja');
  if (!spotlight || !caja) return;

  const _centrar = () => {
    spotlight.style.cssText = 'position:fixed;width:0;height:0;top:50%;left:50%;box-shadow:0 0 0 9999px rgba(0,0,0,0.72);border-radius:0;z-index:9001;pointer-events:none;';
    caja.style.cssText = 'position:fixed;z-index:9002;top:50%;left:50%;transform:translate(-50%,-50%);opacity:1;';
  };

  if (!targetEl || targetEl.offsetParent === null) {
    _centrar();
    return;
  }

  // Ocultar tarjeta mientras scrolleamos para que no "vuele" por la pantalla
  caja.style.opacity = '0';

  // Scroll al elemento para que esté visible en pantalla
  targetEl.scrollIntoView({ behavior: 'smooth', block: 'center' });

  // Esperar a que el scroll termine, luego posicionar
  setTimeout(() => {
    const rect = targetEl.getBoundingClientRect();
    const pad = 10;

    spotlight.style.cssText = [
      'position:fixed;',
      `top:${rect.top - pad}px;`,
      `left:${rect.left - pad}px;`,
      `width:${rect.width + pad * 2}px;`,
      `height:${rect.height + pad * 2}px;`,
      'border-radius:12px;',
      'box-shadow:0 0 0 9999px rgba(0,0,0,0.72);',
      'z-index:9001;',
      'pointer-events:none;',
    ].join('');

    const cajaW = Math.min(360, window.innerWidth - 32);
    const cajaH = 270;
    let top, left;

    if (rect.bottom + pad + cajaH + 16 < window.innerHeight) {
      top = rect.bottom + pad + 8;
    } else {
      top = rect.top - pad - cajaH - 8;
      if (top < 16) top = 16;
    }

    left = rect.left + rect.width / 2 - cajaW / 2;
    left = Math.max(16, Math.min(left, window.innerWidth - cajaW - 16));

    caja.style.cssText = [
      'position:fixed;',
      'z-index:9002;',
      `top:${top}px;`,
      `left:${left}px;`,
      'transform:none;',
      'opacity:1;',
      'transition:opacity 0.25s ease;',
    ].join('');
  }, 420);
}

function _tourSiguiente() {
  if (_tourPaso >= TOUR_PASOS.length - 1) { _tourFin(); return; }
  _tourPaso++;
  _tourRenderizarPaso(_tourPaso);
}

function _tourAnterior() {
  if (_tourPaso <= 0) return;
  _tourPaso--;
  _tourRenderizarPaso(_tourPaso);
}

function _tourSaltar() { _tourFin(); }

function _tourFin() {
  localStorage.setItem(TOUR_KEY, '1');
  const overlay = document.getElementById('tour-overlay');
  if (overlay) overlay.classList.add('hidden');
  document.body.style.overflow = _tourOriginalOverflow;
}

// ─────────────────────────────────────────────────────────────
// _arrancarApp: llamado por auth.js tras confirmar sesión, o en DOMContentLoaded si no hay Firebase
function _ocultarSplash() {
  const el = document.getElementById('splash-loader');
  if (!el) return;
  el.classList.add('oculto');
  setTimeout(() => { if (el.parentNode) el.parentNode.removeChild(el); }, 500);
}

function _arrancarApp() {
  if (window._appArranada) return;
  window._appArranada = true;
  _ocultarSplash();

  // Limpiar planIds duplicados al arrancar (limpia datos existentes en Firebase)
  let hayCambios = false;
  Object.values(calState.cursos || {}).forEach(curso => {
    if (curso.planIds) {
      const antes = curso.planIds.length;
      curso.planIds = [...new Set(curso.planIds)];
      if (curso.planIds.length !== antes) hayCambios = true;
    }
  });
  if (hayCambios) guardarCalificaciones();
  if (sessionStorage.getItem('planificador_goto') === 'step1') {
    sessionStorage.removeItem('planificador_goto');
    irAlHomeBase();
  } else {
    abrirDashboard();
  }
  actualizarBadgeNotificaciones();
  // Cargar avisos del director en segundo plano para el badge
  setTimeout(_cargarAvisosDocente, 3000);
  _tourVerificarAutoInicio();
  _iniciarVigilanciaInactividad();
  // Si al recargar corresponde bloquear (flag explícito O inactividad acumulada) → bloquear
  if (_debeBloquearsePorRefresco()) {
    _pantallaBloqueada = false; // resetear bandera para que _bloquearPantalla no la ignore
    _bloquearPantalla();
    return;
  }
  // Registrar la actividad inicial para que el timestamp quede guardado desde el primer momento
  sessionStorage.setItem(_LAST_ACT_KEY, String(Date.now()));
  registrarCambio('Sesión iniciada — ' + (window.currentUser?.email || ''));
}

document.addEventListener('DOMContentLoaded', () => {
  actualizarBtnConfigIA();
  const mf = document.querySelector('.modal-footer');
  if (mf && !mf.id) mf.id = 'modal-footer';
  // Aplicar preferencias de apariencia antes de mostrar
  _aplicarPreferencias();
  // Si Firebase no está configurado (firebase-config sin datos reales), arrancar directamente
  setTimeout(() => {
    const cfg = (typeof firebaseConfig !== 'undefined') ? firebaseConfig : {};
    const sinConfigurar = !cfg.apiKey || cfg.apiKey.startsWith('PEGA_');
    if (sinConfigurar) _arrancarApp();
  }, 200);
});

