var impState = {
  paso: 1,
  totalPasos: 4,
  datos: {
    dg: {}, ra: {},
    ecs: [],      // [{codigo, enunciado, nivel, horasAsignadas}]
    actividades: [] // [{ecCodigo, enunciado, fecha, instrumento}]
  }
};

function abrirImportarPlanificacion() {
  impState.paso = 1;
  impState.datos = { dg: {}, ra: {}, ecs: [], actividades: [] };
  document.getElementById('imp-overlay').classList.remove('hidden');
  imp_renderizarPaso();
}

function imp_cerrar() {
  document.getElementById('imp-overlay').classList.add('hidden');
}

function imp_cerrarSiClick(e) {
  if (e.target === document.getElementById('imp-overlay')) imp_cerrar();
}

function imp_renderizarTabs() {
  const bar = document.getElementById('imp-steps-bar');
  const labels = ['1. Datos Generales', '2. RA y Criterios', '3. EC y Actividades', '4. Confirmar'];
  bar.innerHTML = '';
  labels.forEach((lbl, i) => {
    const n = i + 1;
    const div = document.createElement('div');
    div.className = 'imp-step-tab' +
      (n === impState.paso ? ' activo' : '') +
      (n < impState.paso ? ' completado' : '');
    div.textContent = (n < impState.paso ? '✓ ' : '') + lbl;
    bar.appendChild(div);
  });

  const btnPrev = document.getElementById('imp-btn-prev');
  const btnNext = document.getElementById('imp-btn-next');
  btnPrev.style.display = impState.paso > 1 ? 'inline-flex' : 'none';
  if (impState.paso === impState.totalPasos) {
    btnNext.innerHTML = '<span class="material-icons">save</span> Guardar planificación';
  } else {
    btnNext.innerHTML = 'Siguiente <span class="material-icons">arrow_forward</span>';
  }
}

function imp_renderizarPaso() {
  imp_renderizarTabs();
  const body = document.getElementById('imp-body');
  if (impState.paso === 1) body.innerHTML = imp_htmlPaso1();
  else if (impState.paso === 2) body.innerHTML = imp_htmlPaso2();
  else if (impState.paso === 3) body.innerHTML = imp_htmlPaso3();
  else body.innerHTML = imp_htmlPaso4();
  // Restaurar valores guardados
  if (impState.paso === 1) imp_poblarPaso1();
  else if (impState.paso === 2) imp_poblarPaso2();
  else if (impState.paso === 3) imp_poblarPaso3();
}

// ─── PASO 1: DATOS GENERALES ───────────────────────────────────
function imp_htmlPaso1() {
  return `
  <div class="imp-section" id="imp-sec-curso">
    <div class="imp-section-title"><span class="material-icons">class</span>Curso al que pertenece</div>
    <div class="imp-grid-2">
      <div class="imp-field full" id="imp-curso-field">
        <!-- Se genera dinámicamente en imp_poblarPaso1 -->
      </div>
    </div>
  </div>
  <div class="imp-section">
    <div class="imp-section-title"><span class="material-icons">school</span>Institución y Módulo</div>
    <div class="imp-grid-2">
      <div class="imp-field"><label>Familia Profesional</label><input id="imp-familiaProfesional" placeholder="Ej: Informática y Comunicaciones"></div>
      <div class="imp-field"><label>Código FP</label><input id="imp-codigoFP" placeholder="Ej: IFC"></div>
      <div class="imp-field"><label>Nombre del Bachillerato</label><input id="imp-nombreBachillerato" placeholder="Ej: Técnico en Desarrollo de Aplicaciones Web"></div>
      <div class="imp-field"><label>Código Título</label><input id="imp-codigoTitulo" placeholder="Ej: T-IFC-001"></div>
      <div class="imp-field full"><label>Módulo Formativo</label><input id="imp-moduloFormativo" placeholder="Ej: Programación Web en Entorno Cliente"></div>
      <div class="imp-field"><label>Código del Módulo</label><input id="imp-codigoModulo" placeholder="Ej: MF0491_3"></div>
      <div class="imp-field"><label>Nombre del Docente</label><input id="imp-nombreDocente" placeholder="Ej: Lic. Ana Torres"></div>
    </div>
  </div>

  <div class="imp-section">
    <div class="imp-section-title"><span class="material-icons">calendar_today</span>Horario y Fechas</div>
    <div class="imp-grid-2">
      <div class="imp-field"><label>Cantidad de RA en el módulo</label><input id="imp-cantidadRA" type="number" min="1" max="20" placeholder="Ej: 3"></div>
      <div class="imp-field"><label>Valor de este RA (puntos)</label><input id="imp-valorRA" type="number" min="1" max="100" step="0.5" placeholder="Ej: 10"></div>
      <div class="imp-field"><label>Horas semanales totales</label><input id="imp-horasSemana" type="number" min="1" max="40" placeholder="Ej: 6"></div>
      <div class="imp-field"></div>
      <div class="imp-field"><label>Fecha de inicio</label><input id="imp-fechaInicio" type="date"></div>
      <div class="imp-field"><label>Fecha de término</label><input id="imp-fechaTermino" type="date"></div>
    </div>
    <div style="margin-top:12px;">
      <label class="imp-field-label-dias">Días de clase y horas por día:</label>
      <div class="imp-dias-grid">
        ${['lunes', 'martes', 'miercoles', 'jueves', 'viernes'].map(d => `
          <div class="imp-dia-item">
            <label><input type="checkbox" id="imp-dia-${d}" style="margin-right:4px;">${d.charAt(0).toUpperCase() + d.slice(1)}</label>
            <input type="number" id="imp-hrs-${d}" min="1" max="8" value="2" title="Horas ese día">
            <span style="font-size:0.7rem;color:#9E9E9E;">hrs</span>
          </div>`).join('')}
      </div>
    </div>
  </div>`;
}

function imp_poblarPaso1() {
  const dg = impState.datos.dg;
  const set = (id, val) => { const el = document.getElementById(id); if (el && val !== undefined) el.value = val; };
  // Renderizar selector de curso
  const cf = document.getElementById('imp-curso-field');
  if (cf) {
    const cursos = Object.values(calState.cursos);
    if (cursos.length === 0) {
      cf.innerHTML = '<p style="font-size:0.85rem;color:#78909C;margin:0;">No tienes cursos creados. Podrás asignar esta planificación a un curso desde el <strong>Libro de Calificaciones</strong> después de guardarla.</p>';
    } else {
      const opts = '<option value="">— Sin asignar —</option>' + cursos.map(c =>
        `<option value="${c.id}" ${impState.datos.cursoId === c.id ? 'selected' : ''}>${escHTML(c.nombre)}</option>`
      ).join('');
      cf.innerHTML = '<label>Asignar al curso</label>'
        + '<select id="imp-cursoId" style="padding:8px 12px;border:1.5px solid #90CAF9;border-radius:8px;font-size:0.9rem;width:100%;">' + opts + '</select>'
        + '<p style="font-size:0.75rem;color:#78909C;margin:4px 0 0;">Las actividades de esta planificación aparecerán en el libro de calificaciones de ese curso.</p>';
    }
  }
  set('imp-familiaProfesional', dg.familiaProfesional);
  set('imp-codigoFP', dg.codigoFP);
  set('imp-nombreBachillerato', dg.nombreBachillerato);
  set('imp-codigoTitulo', dg.codigoTitulo);
  set('imp-moduloFormativo', dg.moduloFormativo);
  set('imp-codigoModulo', dg.codigoModulo);
  set('imp-nombreDocente', dg.nombreDocente);
  set('imp-cantidadRA', dg.cantidadRA);
  set('imp-valorRA', dg.valorRA);
  set('imp-horasSemana', dg.horasSemana);
  set('imp-fechaInicio', dg.fechaInicio);
  set('imp-fechaTermino', dg.fechaTermino);
  if (dg.diasClase) {
    ['lunes', 'martes', 'miercoles', 'jueves', 'viernes'].forEach(d => {
      const cfg = dg.diasClase[d];
      if (!cfg) return;
      const cb = document.getElementById('imp-dia-' + d);
      const hr = document.getElementById('imp-hrs-' + d);
      if (cb) cb.checked = cfg.activo;
      if (hr) hr.value = cfg.horas || 2;
    });
  }
}

function imp_leerPaso1() {
  const get = id => { const el = document.getElementById(id); return el ? el.value.trim() : ''; };
  impState.datos.cursoId = document.getElementById('imp-cursoId')?.value || null;
  const diasClase = {};
  ['lunes', 'martes', 'miercoles', 'jueves', 'viernes'].forEach(d => {
    const cb = document.getElementById('imp-dia-' + d);
    const hr = document.getElementById('imp-hrs-' + d);
    diasClase[d] = { activo: cb ? cb.checked : false, horas: parseInt(hr?.value || '2', 10) };
  });
  impState.datos.dg = {
    familiaProfesional: get('imp-familiaProfesional'),
    codigoFP: get('imp-codigoFP'),
    nombreBachillerato: get('imp-nombreBachillerato'),
    codigoTitulo: get('imp-codigoTitulo'),
    moduloFormativo: get('imp-moduloFormativo'),
    codigoModulo: get('imp-codigoModulo'),
    nombreDocente: get('imp-nombreDocente'),
    cantidadRA: get('imp-cantidadRA'),
    valorRA: get('imp-valorRA'),
    horasSemana: get('imp-horasSemana'),
    fechaInicio: get('imp-fechaInicio'),
    fechaTermino: get('imp-fechaTermino'),
    diasClase
  };
}

function imp_validarPaso1() {
  const dg = impState.datos.dg;
  if (!dg.moduloFormativo) { mostrarToast('El Módulo Formativo es obligatorio', 'error'); return false; }
  if (!dg.nombreDocente) { mostrarToast('El Nombre del Docente es obligatorio', 'error'); return false; }
  if (!dg.fechaInicio) { mostrarToast('La Fecha de inicio es obligatoria', 'error'); return false; }
  const diasActivos = Object.values(dg.diasClase || {}).filter(d => d.activo);
  if (diasActivos.length === 0) { mostrarToast('Selecciona al menos un día de clase', 'error'); return false; }
  return true;
}

// ─── PASO 2: RA Y CRITERIOS ────────────────────────────────────
function imp_htmlPaso2() {
  return `
  <div class="imp-section">
    <div class="imp-section-title"><span class="material-icons">psychology</span>Resultado de Aprendizaje (RA)</div>
    <div style="display:flex;flex-direction:column;gap:12px;">
      <div class="imp-field">
        <label>Descripción completa del RA</label>
        <textarea id="imp-ra-descripcion" rows="4" placeholder="Ej: Elabora aplicaciones web en el entorno cliente aplicando lenguajes de marcas y estándares web con criterios de usabilidad y accesibilidad…"></textarea>
      </div>
      <div class="imp-field">
        <label>Criterios de evaluación / temas de referencia (uno por línea)</label>
        <textarea id="imp-ra-criterios" rows="5" placeholder="CE1. Identifica las herramientas de diseño web y su función
CE2. Describe la estructura básica de HTML y sus etiquetas principales
CE3. Aplica estilos CSS para dar formato visual a páginas web
CE4. Desarrolla páginas web accesibles siguiendo estándares W3C"></textarea>
      </div>
      <div class="imp-field">
        <label>Recursos didácticos disponibles</label>
        <input id="imp-ra-recursos" placeholder="Ej: Computadoras con internet, proyector, guías de trabajo, VS Code">
      </div>
      <div class="imp-field">
        <label>Nivel de Bloom predominante del RA</label>
        <select id="imp-ra-nivel" onchange="imp_onBloomChange()">
          <option value="conocimiento">Conocimiento – Identificar, Reconocer, Nombrar</option>
          <option value="comprension">Comprensión – Explicar, Describir, Interpretar</option>
          <option value="aplicacion" selected>Aplicación – Aplicar, Demostrar, Ejecutar</option>
          <option value="analisis">Análisis – Analizar, Comparar, Diferenciar</option>
          <option value="evaluacion">Evaluación – Evaluar, Juzgar, Justificar</option>
          <option value="creacion">Creación – Crear, Diseñar, Construir</option>
          <option value="actitudinal">Actitudinal – Valorar, Comprometerse, Respetar</option>
          <option value="otro">Otro (escribir abajo)…</option>
        </select>
        <input id="imp-ra-nivel-otro" placeholder="Especifica el nivel de Bloom…"
          style="display:none;margin-top:6px;" onchange="imp_onBloomOtroChange()">
    </div>
  </div>`;
}

function imp_poblarPaso2() {
  const ra = impState.datos.ra;
  // Resolver bloom personalizado
  if (ra.nivelBloom === 'otro') {
    ra.nivelBloom = document.getElementById('imp-ra-nivel-otro')?.value.trim() || 'otro';
  }
  const set = (id, val) => { const el = document.getElementById(id); if (el && val) el.value = val; };
  set('imp-ra-descripcion', ra.descripcion);
  set('imp-ra-criterios', ra.criterios);
  set('imp-ra-recursos', ra.recursos);
  set('imp-ra-nivel', ra.nivelBloom && ['conocimiento', 'comprension', 'aplicacion', 'analisis', 'evaluacion', 'creacion', 'actitudinal'].includes(ra.nivelBloom) ? ra.nivelBloom : (ra.nivelBloom ? 'otro' : 'aplicacion'));
  if (ra.nivelBloom && !['conocimiento', 'comprension', 'aplicacion', 'analisis', 'evaluacion', 'creacion', 'actitudinal'].includes(ra.nivelBloom)) {
    const otrEl = document.getElementById('imp-ra-nivel-otro');
    if (otrEl) { otrEl.value = ra.nivelBloom; otrEl.style.display = ''; }
  }
}

function imp_leerPaso2() {
  const get = id => { const el = document.getElementById(id); return el ? el.value.trim() : ''; };
  impState.datos.ra = {
    descripcion: get('imp-ra-descripcion'),
    criterios: get('imp-ra-criterios'),
    recursos: get('imp-ra-recursos'),
    nivelBloom: (function () {
      const v = get('imp-ra-nivel');
      return v === 'otro' ? (document.getElementById('imp-ra-nivel-otro')?.value.trim() || 'otro') : v;
    })()
  };
}

function imp_validarPaso2() {
  if (!impState.datos.ra.descripcion) { mostrarToast('La descripción del RA es obligatoria', 'error'); return false; }
  return true;
}

// ─── PASO 3: EC Y ACTIVIDADES ──────────────────────────────────
function imp_htmlPaso3() {
  // Si no hay ECs creados aún, inicializar con 1 vacío
  if (impState.datos.ecs.length === 0) {
    impState.datos.ecs = [{ codigo: 'CE1', enunciado: '', nivel: impState.datos.ra.nivelBloom || 'aplicacion', horasAsignadas: 2 }];
    impState.datos.actividades = [[]]; // un array de actividades por EC
  }

  let html = `
  <div style="margin-bottom:12px;display:flex;align-items:center;justify-content:space-between;">
    <div style="font-size:0.88rem;color:#616161;">Define los Elementos de Capacidad (EC) y las actividades de evaluación de tu planificación.</div>
    <button class="btn-siguiente" style="padding:7px 14px;font-size:0.82rem;" onclick="imp_agregarEC()">
      <span class="material-icons" style="font-size:16px;">add</span> Agregar EC
    </button>
  </div>`;

  impState.datos.ecs.forEach((ec, i) => {
    const acts = impState.datos.actividades[i] || [];
    html += `
    <div class="imp-ec-card" id="imp-ec-card-${i}">
      <div class="imp-ec-card-header">
        <span class="material-icons" style="font-size:18px;color:#1565C0;">task_alt</span>
        Elemento de Capacidad ${i + 1}
        ${impState.datos.ecs.length > 1 ? `<button onclick="imp_eliminarEC(${i})" style="margin-left:auto;background:none;border:none;cursor:pointer;color:#C62828;display:flex;align-items:center;" title="Eliminar EC"><span class="material-icons" style="font-size:18px;">delete</span></button>` : ''}
      </div>
      <div class="imp-ec-grid">
        <div class="imp-field">
          <label>Código del EC</label>
          <input id="imp-ec-cod-${i}" value="${escHTML(ec.codigo || '')}" placeholder="Ej: CE1" onchange="imp_actualizarEC(${i})">
        </div>
        <div class="imp-field">
          <label>Nivel Bloom</label>
          <select id="imp-ec-nivel-${i}" onchange="imp_actualizarEC(${i})">
            ${['conocimiento', 'comprension', 'aplicacion', 'actitudinal'].map(n =>
      `<option value="${n}" ${ec.nivel === n ? 'selected' : ''}>${n.charAt(0).toUpperCase() + n.slice(1)}</option>`
    ).join('')}
          </select>
        </div>
        <div class="imp-field" style="grid-column:1/-1;">
          <label>Enunciado del Elemento de Capacidad</label>
          <textarea id="imp-ec-enun-${i}" rows="2" placeholder="Ej: Selecciona herramientas de desarrollo web según sus características y caso de uso…" onchange="imp_actualizarEC(${i})">${escHTML(ec.enunciado || '')}</textarea>
        </div>
        <div class="imp-field">
          <label>Horas asignadas a este EC</label>
          <input id="imp-ec-hrs-${i}" type="number" min="1" max="100" value="${ec.horasAsignadas || 2}" onchange="imp_actualizarEC(${i})">
        </div>
      </div>

      <div style="margin-top:8px;font-size:0.78rem;font-weight:700;color:#4527A0;margin-bottom:6px;">
        <span class="material-icons" style="font-size:14px;vertical-align:middle;">assignment</span>
        Actividades de evaluación
      </div>
      <div id="imp-acts-${i}">
        ${acts.map((act, j) => imp_htmlActRow(i, j, act)).join('')}
      </div>
      <button class="imp-add-act-btn" onclick="imp_agregarActividad(${i})">
        <span class="material-icons" style="font-size:16px;">add</span> Agregar actividad
      </button>
    </div>`;
  });

  return html;
}

function imp_htmlActRow(ecIdx, actIdx, act) {
  const INST_OPTS = [
    { v: 'cotejo', l: 'Lista de Cotejo' },
    { v: 'rubrica', l: 'Rúbrica' },
  ];
  const instSel = (v) => INST_OPTS.map(o =>
    `<option value="${o.v}" ${(act && act.instrumento) === o.v ? 'selected' : ''}>${o.l}</option>`
  ).join('');
  return `<div class="imp-act-row" id="imp-act-${ecIdx}-${actIdx}">
    <div class="imp-act-num">Act.${actIdx + 1}</div>
    <textarea rows="2" id="imp-act-enun-${ecIdx}-${actIdx}" placeholder="Describe la actividad de evaluación…"
      onchange="imp_actualizarAct(${ecIdx},${actIdx})">${escHTML((act && act.enunciado) || '')}</textarea>
    <input type="date" id="imp-act-fecha-${ecIdx}-${actIdx}" value="${(act && act.fecha) || ''}"
      onchange="imp_actualizarAct(${ecIdx},${actIdx})" title="Fecha de la sesión">
    <select id="imp-act-inst-${ecIdx}-${actIdx}" onchange="imp_actualizarAct(${ecIdx},${actIdx})"
      title="Instrumento de evaluación" style="font-size:0.78rem;padding:4px 6px;border-radius:6px;border:1.5px solid #90CAF9;">
      ${instSel()}
    </select>
    <input type="number" id="imp-act-valor-${ecIdx}-${actIdx}"
      value="${(act && act.valor) || ''}" min="0.5" max="100" step="0.5" placeholder="pts"
      onchange="imp_actualizarAct(${ecIdx},${actIdx})"
      title="Valor en puntos de esta actividad"
      style="width:52px;font-size:0.78rem;padding:4px 6px;border-radius:6px;border:1.5px solid #90CAF9;text-align:center;">
    <button class="btn-del-act" onclick="imp_eliminarActividad(${ecIdx},${actIdx})" title="Eliminar">
      <span class="material-icons" style="font-size:16px;">close</span>
    </button>
  </div>`;
}

function imp_actualizarEC(i) {
  const ec = impState.datos.ecs[i];
  if (!ec) return;
  ec.codigo = document.getElementById('imp-ec-cod-' + i)?.value.trim() || ec.codigo;
  ec.enunciado = document.getElementById('imp-ec-enun-' + i)?.value.trim() || ec.enunciado;
  ec.nivel = document.getElementById('imp-ec-nivel-' + i)?.value || ec.nivel;
  ec.horasAsignadas = parseFloat(document.getElementById('imp-ec-hrs-' + i)?.value) || ec.horasAsignadas;
}

function imp_actualizarAct(ecIdx, actIdx) {
  if (!impState.datos.actividades[ecIdx]) return;
  const act = impState.datos.actividades[ecIdx][actIdx] || {};
  act.enunciado = document.getElementById(`imp-act-enun-${ecIdx}-${actIdx}`)?.value.trim() || '';
  act.fecha = document.getElementById(`imp-act-fecha-${ecIdx}-${actIdx}`)?.value || '';
  act.instrumento = document.getElementById(`imp-act-inst-${ecIdx}-${actIdx}`)?.value || 'cotejo';
  const valRaw = document.getElementById(`imp-act-valor-${ecIdx}-${actIdx}`)?.value;
  act.valor = valRaw !== '' && !isNaN(parseFloat(valRaw)) ? parseFloat(valRaw) : null;
  impState.datos.actividades[ecIdx][actIdx] = act;
}

function imp_onBloomChange() {
  const sel = document.getElementById('imp-ra-nivel');
  const inp = document.getElementById('imp-ra-nivel-otro');
  if (!sel || !inp) return;
  inp.style.display = sel.value === 'otro' ? '' : 'none';
  if (sel.value !== 'otro') inp.value = '';
}

function imp_onBloomOtroChange() {
  const inp = document.getElementById('imp-ra-nivel-otro');
  if (impState.datos.ra) impState.datos.ra.nivelBloom = inp?.value.trim() || 'otro';
}

function imp_agregarEC() {
  imp_leerPaso3();
  const n = impState.datos.ecs.length + 1;
  impState.datos.ecs.push({ codigo: 'CE' + n, enunciado: '', nivel: 'aplicacion', horasAsignadas: 2 });
  impState.datos.actividades.push([]);
  document.getElementById('imp-body').innerHTML = imp_htmlPaso3();
}

function imp_eliminarEC(i) {
  imp_leerPaso3();
  if (impState.datos.ecs.length <= 1) { mostrarToast('Debe haber al menos 1 EC', 'error'); return; }
  impState.datos.ecs.splice(i, 1);
  impState.datos.actividades.splice(i, 1);
  document.getElementById('imp-body').innerHTML = imp_htmlPaso3();
}

function imp_agregarActividad(ecIdx) {
  imp_leerPaso3();
  if (!impState.datos.actividades[ecIdx]) impState.datos.actividades[ecIdx] = [];
  impState.datos.actividades[ecIdx].push({ enunciado: '', fecha: '', instrumento: 'cotejo', valor: null });
  document.getElementById('imp-body').innerHTML = imp_htmlPaso3();
}

function imp_eliminarActividad(ecIdx, actIdx) {
  imp_leerPaso3();
  impState.datos.actividades[ecIdx].splice(actIdx, 1);
  document.getElementById('imp-body').innerHTML = imp_htmlPaso3();
}

function imp_leerPaso3() {
  impState.datos.ecs.forEach((ec, i) => {
    ec.codigo = document.getElementById('imp-ec-cod-' + i)?.value.trim() || ec.codigo;
    ec.enunciado = document.getElementById('imp-ec-enun-' + i)?.value.trim() || '';
    ec.nivel = document.getElementById('imp-ec-nivel-' + i)?.value || 'aplicacion';
    ec.horasAsignadas = parseFloat(document.getElementById('imp-ec-hrs-' + i)?.value) || 2;
    if (!impState.datos.actividades[i]) impState.datos.actividades[i] = [];
    impState.datos.actividades[i].forEach((act, j) => {
      act.enunciado = document.getElementById(`imp-act-enun-${i}-${j}`)?.value.trim() || '';
      act.fecha = document.getElementById(`imp-act-fecha-${i}-${j}`)?.value || '';
      act.instrumento = document.getElementById(`imp-act-inst-${i}-${j}`)?.value || 'cotejo';
      const valRaw = document.getElementById(`imp-act-valor-${i}-${j}`)?.value;
      act.valor = valRaw !== '' && !isNaN(parseFloat(valRaw)) ? parseFloat(valRaw) : null;
    });
  });
}

function imp_validarPaso3() {
  imp_leerPaso3();
  for (let i = 0; i < impState.datos.ecs.length; i++) {
    if (!impState.datos.ecs[i].enunciado) {
      mostrarToast(`El EC ${i + 1} necesita un enunciado`, 'error'); return false;
    }
    const acts = impState.datos.actividades[i] || [];
    if (acts.length === 0) {
      mostrarToast(`El EC ${i + 1} debe tener al menos 1 actividad`, 'error'); return false;
    }
    for (let j = 0; j < acts.length; j++) {
      if (!acts[j].enunciado) {
        mostrarToast(`La actividad ${j + 1} del EC ${i + 1} necesita descripción`, 'error'); return false;
      }
    }
  }
  return true;
}

// ─── PASO 4: RESUMEN / CONFIRMACIÓN ───────────────────────────
function imp_htmlPaso4() {
  const dg = impState.datos.dg;
  const ra = impState.datos.ra;
  const ecs = impState.datos.ecs;
  const acts = impState.datos.actividades;
  const totalActs = acts.reduce((sum, arr) => sum + (arr ? arr.length : 0), 0);
  const diasActivos = Object.entries(dg.diasClase || {}).filter(([, v]) => v.activo).map(([k]) => k).join(', ');

  let ecResumen = ecs.map((ec, i) => {
    const aa = (acts[i] || []);
    return `<div style="margin:6px 0 2px;font-size:0.82rem;">
      <span style="font-weight:700;color:#1565C0;">${escHTML(ec.codigo)}</span>
      <span style="color:#616161;"> · ${ec.nivel} · ${ec.horasAsignadas}h</span><br>
      <span style="color:#424242;">${escHTML((ec.enunciado || '').substring(0, 80))}${ec.enunciado.length > 80 ? '…' : ''}</span>
      <span style="font-size:0.75rem;color:#9E9E9E;"> (${aa.length} actividad${aa.length !== 1 ? 'es' : ''})</span>
    </div>`;
  }).join('');

  return `
  <div style="background:#E8F5E9;border-radius:10px;padding:14px 16px;margin-bottom:16px;display:flex;gap:10px;align-items:flex-start;">
    <span class="material-icons" style="color:#2E7D32;font-size:28px;">check_circle</span>
    <div>
      <div style="font-weight:700;color:#1B5E20;margin-bottom:4px;">¡Planificación lista para guardar!</div>
      <div style="font-size:0.82rem;color:#2E7D32;">Revisa el resumen y confirma. Quedará guardada en tu biblioteca.</div>
    </div>
  </div>

  <div class="imp-resumen-card">
    <h4><span class="material-icons" style="font-size:16px;">assignment</span>Datos Generales</h4>
    <div class="imp-resumen-row"><strong>Módulo:</strong><span>${escHTML(dg.moduloFormativo || '—')}</span></div>
    <div class="imp-resumen-row"><strong>Bachillerato:</strong><span>${escHTML(dg.nombreBachillerato || '—')}</span></div>
    <div class="imp-resumen-row"><strong>Familia Profesional:</strong><span>${escHTML(dg.familiaProfesional || '—')}</span></div>
    <div class="imp-resumen-row"><strong>Docente:</strong><span>${escHTML(dg.nombreDocente || '—')}</span></div>
    <div class="imp-resumen-row"><strong>Período:</strong><span>${dg.fechaInicio || '—'} → ${dg.fechaTermino || '—'}</span></div>
    <div class="imp-resumen-row"><strong>Días de clase:</strong><span>${diasActivos || '—'}</span></div>
    <div class="imp-resumen-row"><strong>Horas semanales:</strong><span>${dg.horasSemana || '—'}</span></div>
    <div class="imp-resumen-row"><strong>Valor del RA:</strong><span>${dg.valorRA || '—'} pts</span></div>
  </div>

  <div class="imp-resumen-card">
    <h4><span class="material-icons" style="font-size:16px;">psychology</span>Resultado de Aprendizaje</h4>
    <div style="font-size:0.82rem;color:#424242;line-height:1.5;">${escHTML((ra.descripcion || '—').substring(0, 200))}${(ra.descripcion || '').length > 200 ? '…' : ''}</div>
    <div class="imp-resumen-row" style="margin-top:8px;"><strong>Nivel Bloom:</strong><span>${ra.nivelBloom || '—'}</span></div>
  </div>

  <div class="imp-resumen-card">
    <h4><span class="material-icons" style="font-size:16px;">task_alt</span>${ecs.length} Elemento${ecs.length !== 1 ? 's' : ''} de Capacidad · ${totalActs} Actividad${totalActs !== 1 ? 'es' : ''}</h4>
    ${ecResumen}
  </div>`;
}

// ─── NAVEGACIÓN ────────────────────────────────────────────────
function imp_siguiente() {
  if (impState.paso === 1) {
    imp_leerPaso1();
    if (!imp_validarPaso1()) return;
  } else if (impState.paso === 2) {
    imp_leerPaso2();
    if (!imp_validarPaso2()) return;
  } else if (impState.paso === 3) {
    if (!imp_validarPaso3()) return;
  } else if (impState.paso === 4) {
    imp_guardar();
    return;
  }
  impState.paso++;
  imp_renderizarPaso();
  document.getElementById('imp-body').scrollTop = 0;
}

function imp_anterior() {
  if (impState.paso <= 1) return;
  // Guardar estado actual antes de retroceder
  if (impState.paso === 2) imp_leerPaso2();
  else if (impState.paso === 3) imp_leerPaso3();
  impState.paso--;
  imp_renderizarPaso();
  document.getElementById('imp-body').scrollTop = 0;
}

// ─── GUARDAR ───────────────────────────────────────────────────
function imp_guardar() {
  const dg = impState.datos.dg;
  const ra = impState.datos.ra;
  const ecs = impState.datos.ecs;

  // Construir elementosCapacidad
  const elementosCapacidad = ecs.map((ec, i) => ({
    id: ec.codigo,
    codigo: ec.codigo,
    nivel: ec.nivel,
    nivelBloom: ec.nivel,
    enunciado: ec.enunciado,
    descripcion: ec.enunciado,
    horasAsignadas: ec.horasAsignadas,
    secuencia: plantillasSecuencia[ec.nivel] || plantillasSecuencia.aplicacion,
    instrumento: undefined
  }));

  // Construir actividades
  const actividades = [];
  ecs.forEach((ec, ecIdx) => {
    const actsEC = impState.datos.actividades[ecIdx] || [];
    actsEC.forEach((act, actIdx) => {
      const fechaObj = act.fecha ? new Date(act.fecha + 'T12:00:00') : null;
      const fechaStr = fechaObj
        ? fechaObj.toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' })
        : '';
      const actObj = {
        id: `ACT-IMP-${ecIdx + 1}-${actIdx + 1}-${Date.now()}`,
        ecCodigo: ec.codigo,
        ecNivel: ec.nivel,
        enunciado: act.enunciado,
        fecha: fechaObj ? fechaObj.toISOString() : null,
        fechaStr,
        horas: ec.horasAsignadas,
        valor: act.valor || null,
        _instTipo: act.instrumento || 'cotejo'
      };
      // Generar instrumento con el tipo elegido por actividad
      actObj.instrumento = generarInstrumento(actObj, ec.nivel, act.instrumento || 'cotejo');
      actividades.push(actObj);
    });
  });

  // Construir fechasClase desde diasClase y fechas
  const fechasClase = _generarFechasDesde(dg);

  // Objeto planificacion completo
  const planImportada = {
    datosGenerales: dg,
    ra: { ...ra },
    elementosCapacidad,
    actividades,
    fechasClase,
    horasTotal: elementosCapacidad.reduce((s, e) => s + (e.horasAsignadas || 0), 0),
    _importada: true
  };

  // Guardar en biblioteca
  const ahora = new Date();
  const id = 'IMP-' + ahora.getTime();
  const registro = {
    id,
    fechaGuardado: ahora.toISOString(),
    fechaGuardadoLabel: ahora.toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
    nombre: (dg.moduloFormativo || 'Sin módulo') + ' — ' + (dg.nombreDocente || 'Sin docente'),
    planificacion: planImportada
  };

  const biblio = cargarBiblioteca();
  // Siempre guardar como nueva — mismo módulo puede tener múltiples RA
  biblio.items.unshift(registro);
  mostrarToast('Planificación importada y guardada correctamente', 'success');

  persistirBiblioteca(biblio);

  // Asignar al curso elegido
  const cursoIdElegido = impState.datos.cursoId;
  if (cursoIdElegido && calState.cursos[cursoIdElegido]) {
    const cursoAsig = calState.cursos[cursoIdElegido];
    if (!cursoAsig.planIds) cursoAsig.planIds = [];
    if (!cursoAsig.planIds.includes(id)) {
      cursoAsig.planIds.push(id);
      if (!cursoAsig.planActivaId) cursoAsig.planActivaId = id;
      guardarCalificaciones();
    }
  }
  imp_cerrar();
  renderizarBiblioteca();
}

/** Genera fechas de clase a partir de diasClase + fechaInicio + fechaTermino */
function _generarFechasDesde(dg) {
  if (!dg.fechaInicio || !dg.fechaTermino) return [];
  const DIAS = { lunes: 1, martes: 2, miercoles: 3, jueves: 4, viernes: 5 };
  const activosDias = Object.entries(dg.diasClase || {})
    .filter(([, v]) => v.activo)
    .map(([k, v]) => ({ dia: DIAS[k], horas: v.horas || 2 }));
  if (activosDias.length === 0) return [];

  const inicio = new Date(dg.fechaInicio + 'T12:00:00');
  const fin = new Date(dg.fechaTermino + 'T12:00:00');
  const result = [];
  const cur = new Date(inicio);
  while (cur <= fin) {
    const dow = cur.getDay(); // 0=dom
    const cfg = activosDias.find(d => d.dia === dow);
    if (cfg) {
      const fechaStr = cur.toLocaleDateString('es-DO', { weekday: 'long', day: '2-digit', month: 'long', year: 'numeric' });
      result.push({ fecha: new Date(cur), fechaStr, horas: cfg.horas });
    }
    cur.setDate(cur.getDate() + 1);
  }
  return result;
}


// ================================================================
// BACKUP: EXPORTAR / IMPORTAR TODOS LOS DATOS
// ================================================================

var _backupFileData = null;

async function archivarCicloActual() {
  if (!window.currentUser || !window.currentUser.uid) {
    mostrarToast('Inicia sesión para archivar ciclos en Firebase', 'error');
    return;
  }
  if (!window.firebase || !firebase.firestore) {
    mostrarToast('Firebase no está disponible para archivar datos', 'error');
    return;
  }

  const currentYear = _getSchoolYearKey();
  const nextYear = _getNextSchoolYearKey();
  if (!confirm('¿Archivar el ciclo ' + currentYear + ' y dejarlo disponible en el historial?\n\nSe descargará una copia de seguridad completa (.json) de todos tus datos en tu dispositivo y se guardará el ciclo en Firebase.\n\nEl año activo se moverá a ' + nextYear + '.')) {
    return;
  }

  try {
    const snapshot = await _buildExportSnapshotAsync();

    // Descarga automática del backup completo (.json)
    const ahora = new Date();
    const json = JSON.stringify(snapshot, null, 2);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const fecha = ahora.toISOString().slice(0, 10);
    a.href = url;
    a.download = 'backup-ciclo-' + currentYear + '-' + fecha + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    // También descargar la bitácora de cambios (.txt)
    try {
      if (typeof exportarBitacora === 'function') {
        exportarBitacora();
      }
    } catch (eb) {
      console.warn('Error descargando bitácora al cerrar ciclo:', eb);
    }

    const biblio = cargarBiblioteca();
    const cal = JSON.parse(localStorage.getItem(CAL_STORAGE_KEY) || '{"cursos":{}}');
    const diarias = JSON.parse(localStorage.getItem(DIARIAS_KEY) || '{"sesiones":{}}');
    const tareas = JSON.parse(localStorage.getItem(TAREAS_KEY) || '[]');
    const asistencia = JSON.parse(localStorage.getItem(ASIST_KEY) || '{}');
    const createdAt = new Date().toISOString();

    const archiveDoc = {
      yearLabel: currentYear,
      yearId: currentYear,
      closedAt: createdAt,
      counts: {
        planificaciones: Number((biblio.items || []).length) || 0,
        cursos: Number(Object.keys(cal.cursos || {}).length) || 0,
        sesionesDiarias: Number(Object.keys(diarias.sesiones || {}).length) || 0,
        tareas: Number(Array.isArray(tareas) ? tareas.length : 0) || 0,
        registrosAsistencia: Number(Object.keys(asistencia || {}).length) || 0
      },
      remoteCounts: {
        reportesComportamiento: Number(Array.isArray(snapshot.reportesComportamiento) ? snapshot.reportesComportamiento.length : 0) || 0,
        denunciasPublicas: Number(Array.isArray(snapshot.denunciasPublicas) ? snapshot.denunciasPublicas.length : 0) || 0
      },
      createdAt,
      backupMode: 'chunked',
      chunkCount: _chunkLargeStringForFirestore(json).length,
      totalSnapshotBytes: json.length,
      remoteStorage: 'firestore-archive'
    };

    const archivedYears = _loadArchivedYears();
    const existingIndex = archivedYears.findIndex(item => item.id === currentYear);
    const entry = {
      id: currentYear,
      yearLabel: currentYear,
      closedAt: archiveDoc.closedAt,
      counts: archiveDoc.counts
    };
    if (existingIndex >= 0) archivedYears[existingIndex] = entry;
    else archivedYears.unshift(entry);

    localStorage.setItem(ACTIVE_YEAR_KEY, nextYear);
    try {
      if (window._syncFirebase) {
        window._syncFirebase('active_year', nextYear);
      }
    } catch (syncErr) {
      console.warn('No se pudo sincronizar active_year en Firebase:', syncErr);
    }
    _saveArchivedYears(archivedYears);

    let firebaseArchiveOk = false;
    try {
      const archiveRef = db.collection('users').doc(window.currentUser.uid).collection('archives').doc(currentYear);
      await _persistArchiveSnapshotToFirebase(archiveRef, json, currentYear, createdAt);
      await archiveRef.set(archiveDoc, { merge: true });
      firebaseArchiveOk = true;
    } catch (firebaseErr) {
      console.warn('No se pudo guardar el registro del ciclo en Firebase. El backup local ya quedó descargado:', firebaseErr);
    }

    if (firebaseArchiveOk) {
      mostrarToast('Ciclo ' + currentYear + ' archivado en Firebase', 'success');
    } else {
      mostrarToast('Ciclo ' + currentYear + ' descargado localmente. La sincronización en Firebase quedó pendiente.', 'warning');
    }
    abrirBackup();
  } catch (e) {
    mostrarToast('Error archivando ciclo: ' + e.message, 'error');
  }
}

async function descargarBackupArchivadoDesdeFirebase(yearId) {
  if (!yearId) {
    mostrarToast('No se indicó el ciclo a descargar.', 'error');
    return;
  }
  if (!window.currentUser || !window.currentUser.uid || !window.firebase || !firebase.firestore || !db) {
    mostrarToast('Inicia sesión para descargar backups archivados desde Firebase.', 'error');
    return;
  }

  try {
    const archiveRef = db.collection('users').doc(window.currentUser.uid).collection('archives').doc(yearId);
    const archiveDoc = await archiveRef.get();
    if (!archiveDoc.exists) {
      mostrarToast('No existe un backup remoto para este ciclo.', 'warning');
      return;
    }

    const chunksSnap = await archiveRef.collection('chunks').get();
    if (chunksSnap.empty) {
      mostrarToast('Este ciclo no tiene chunks de backup en Firebase.', 'warning');
      return;
    }

    const chunks = chunksSnap.docs
      .map(doc => ({
        index: Number(doc.data().chunkIndex),
        payload: String(doc.data().payload || '')
      }))
      .sort((a, b) => a.index - b.index);

    const json = chunks.map(c => c.payload).join('');
    try {
      JSON.parse(json);
    } catch (_e) {
      mostrarToast('El backup remoto está incompleto o corrupto.', 'error');
      return;
    }

    const fecha = new Date().toISOString().slice(0, 10);
    const blob = new Blob([json], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'backup-ciclo-' + yearId + '-firebase-' + fecha + '.json';
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    mostrarToast('Backup del ciclo ' + yearId + ' descargado desde Firebase.', 'success');
  } catch (e) {
    mostrarToast('Error descargando backup remoto: ' + (e.message || String(e)), 'error');
  }
}

function _safeParseJson(value, fallback) {
  if (typeof value === 'object' && value !== null) return value;
  try {
    return JSON.parse(value);
  } catch (e) {
    return fallback;
  }
}

function _getDescripcionRA(curso, raKey, planReg, raDescMap) {
  const cursoRa = curso?.ras?.[raKey] || {};
  return raDescMap?.[raKey]
    || planReg?.planificacion?.ra?.descripcion
    || cursoRa.descripcion
    || cursoRa.label
    || cursoRa.desc
    || cursoRa.raDescripcion
    || cursoRa.resultado
    || raKey;
}

function _getActividadesRAParaCalculo(curso, raKey, biblio) {
  const planId = (curso.planIds || []).find(pid => _getPlanIdClave(pid) === raKey);
  const planReg = planId ? (biblio.items || []).find(i => i.id === planId) : null;
  const planActs = planReg?.planificacion?.actividades || [];
  const raInfo = curso.ras?.[raKey] || {};
  const snapshotActs = raInfo._actividadesSnapshot || [];
  const actividades = planActs.length
    ? planActs
    : (snapshotActs.length ? snapshotActs : (raInfo.actividades || []).map(id => ({ id, enunciado: id })));
  return { planReg, actividades };
}

function _getValorTotalRA(curso, raKey, planReg) {
  const raInfo = curso?.ras?.[raKey] || {};
  const valores = Object.values(raInfo.valores || {})
    .map(v => parseFloat(String(v).replace(',', '.')))
    .filter(v => Number.isFinite(v));
  const valorDesdeSuma = valores.length ? valores.reduce((s, v) => s + v, 0) : null;
  const candidates = [
    raInfo.valorTotal,
    planReg?.planificacion?.datosGenerales?.valorRA,
    valorDesdeSuma,
    10
  ];
  for (const candidate of candidates) {
    const n = parseFloat(String(candidate).replace(',', '.'));
    if (Number.isFinite(n) && n > 0) return Math.round(n * 10) / 10;
  }
  return 10;
}

function _calcRAsAdeudados(cursoIdFiltro) {
  const biblio = cargarBiblioteca();
  const raDescMap = {};
  (biblio.items || []).forEach(it => {
    try {
      const key = _getPlanIdClave(it.id);
      const desc = it?.planificacion?.ra?.descripcion;
      if (key && desc) raDescMap[key] = desc;
    } catch (e) { }
  });

  const pendientes = [];
  Object.values(calState.cursos || {}).forEach(curso => {
    if (cursoIdFiltro && curso.id !== cursoIdFiltro) return;
    const estudiantes = curso.estudiantes || [];
    Object.keys(curso.ras || {}).forEach(raKey => {
      const { planReg, actividades } = _getActividadesRAParaCalculo(curso, raKey, biblio);
      if (!actividades.length) return;
      const valorTotal = _getValorTotalRA(curso, raKey, planReg);
      const minimo = Math.round(valorTotal * 0.7 * 10) / 10;
      const descripcion = _getDescripcionRA(curso, raKey, planReg, raDescMap);
      estudiantes.forEach(est => {
        const notaCalculada = _calcNotaRA(curso, est.id, raKey, actividades);
        const notaRA = notaCalculada === null ? 0 : notaCalculada;
        const porcentaje = valorTotal > 0 ? Math.round((notaRA / valorTotal) * 1000) / 10 : 0;
        if (porcentaje >= 70) return;

        const actividadesDetalle = actividades.map(act => {
          const nota = curso.notas?.[est.id]?.[raKey]?.[act.id];
          const max = curso.ras?.[raKey]?.valores?.[act.id] ?? act.valor ?? null;
          return {
            id: act.id,
            enunciado: act.enunciado || act.descripcion || act.id,
            nota: nota === undefined || nota === null ? null : nota,
            max
          };
        });

        pendientes.push({
          cursoId: curso.id,
          cursoNombre: curso.nombre || '',
          estudianteId: est.id,
          estudianteNombre: est.nombre || est.id || 'Sin nombre',
          raKey,
          raDescripcion: descripcion,
          notaRA,
          valorTotal,
          porcentaje,
          minimo,
          sinNotas: notaCalculada === null,
          actividades: actividadesDetalle,
          faltantes: [{
            raKey,
            actividadId: null,
            actividadDesc: 'Acumulado: ' + notaRA.toFixed(1) + ' / ' + valorTotal + ' pts (' + porcentaje.toFixed(1) + '%). Minimo requerido: ' + minimo + ' pts.',
            actividades: actividadesDetalle
          }]
        });
      });
    });
  });

  return pendientes.sort((a, b) =>
    a.cursoNombre.localeCompare(b.cursoNombre)
    || a.estudianteNombre.localeCompare(b.estudianteNombre)
    || a.raDescripcion.localeCompare(b.raDescripcion)
  );
}

function identificarEstudiantesRAsPendientes() {
  const listaWrap = document.getElementById('recup-lista');
  const resultadoWrap = document.getElementById('recup-resultado');
  if (!listaWrap) return;
  listaWrap.innerHTML = '<div style="color:#616161;padding:10px;border-radius:8px;background:#FAFAFA;">Buscando estudiantes con RAs adeudados…</div>';
  if (!calState || !calState.cursos) {
    listaWrap.innerHTML = '<div style="color:#C62828;">No hay datos de cursos disponibles.</div>';
    return;
  }

  const pendientes = _calcRAsAdeudados();

  if (!pendientes.length) {
    listaWrap.innerHTML = '<div style="padding:10px;border-radius:8px;background:#E8F5E9;color:#2E7D32;">No se encontraron estudiantes con RAs por debajo del 70%.</div>';
    if (resultadoWrap) resultadoWrap.innerHTML = '';
    window._recupPendientesCache = [];
    return;
  }

  let htmlList = '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">'
    + '<label style="font-weight:700;color:#1B5E20;"><input id="recup-select-all" type="checkbox" style="margin-right:8px;" checked /> Seleccionar todo</label>'
    + '<span style="font-size:0.78rem;color:#546E7A;font-weight:700;">' + pendientes.length + ' RA' + (pendientes.length !== 1 ? 's' : '') + ' adeudado' + (pendientes.length !== 1 ? 's' : '') + '</span>'
    + '</div>';

  htmlList += pendientes.map((p, idx) => {
    const pctColor = p.porcentaje >= 50 ? '#E65100' : '#C62828';
    const pctBg = p.porcentaje >= 50 ? '#FFF3E0' : '#FFEBEE';
    const actividades = (p.actividades || []).slice(0, 4).map(a => {
      const notaTxt = a.nota === null ? 'sin nota' : (a.nota + (a.max ? ' / ' + a.max : ''));
      return '<span style="display:inline-flex;align-items:center;gap:4px;background:#FAFAFA;border:1px solid #ECEFF1;border-radius:6px;padding:3px 7px;font-size:0.74rem;color:#455A64;">'
        + escapeHTML((a.enunciado || '').substring(0, 34)) + (a.enunciado && a.enunciado.length > 34 ? '…' : '')
        + ' <strong style="color:#263238;">' + escapeHTML(String(notaTxt)) + '</strong></span>';
    }).join('');
    return '<div style="padding:11px;border-radius:8px;background:#fff;border:1px solid #DDE7DE;display:flex;align-items:flex-start;gap:10px;">'
      + '<input type="checkbox" data-idx="' + idx + '" class="recup-item" style="margin-top:6px;" checked />'
      + '<div style="flex:1;">'
        + '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:10px;flex-wrap:wrap;">'
          + '<div>'
            + '<div style="font-weight:800;color:#1A237E;">' + escapeHTML(p.estudianteNombre) + ' — ' + escapeHTML(p.cursoNombre) + '</div>'
            + '<div style="font-size:0.82rem;color:#37474F;margin-top:4px;"><strong>RA:</strong> ' + escapeHTML(p.raDescripcion) + '</div>'
          + '</div>'
          + '<div style="background:' + pctBg + ';color:' + pctColor + ';border-radius:8px;padding:5px 9px;font-size:0.78rem;font-weight:800;white-space:nowrap;">'
            + p.notaRA.toFixed(1) + ' / ' + p.valorTotal + ' pts · ' + p.porcentaje.toFixed(1) + '%'
          + '</div>'
        + '</div>'
        + '<div style="margin-top:6px;font-size:0.78rem;color:#546E7A;">Necesita al menos <strong>' + p.minimo + ' pts</strong> para aprobar este RA.' + (p.sinNotas ? ' Sin calificaciones registradas todavía.' : '') + '</div>'
        + (actividades ? '<div style="margin-top:8px;display:flex;gap:5px;flex-wrap:wrap;">' + actividades + '</div>' : '')
      + '</div>'
    + '</div>';
  }).join('');

  listaWrap.innerHTML = htmlList;

  // attach select-all behavior
  const masterCb = document.getElementById('recup-select-all');
  if (masterCb) {
    masterCb.addEventListener('change', function () {
      const itemCbs = listaWrap.querySelectorAll('input.recup-item');
      itemCbs.forEach(cb => cb.checked = masterCb.checked);
    });
  }
  // update master checkbox state when items change
  const itemCbs = listaWrap.querySelectorAll('input.recup-item');
  itemCbs.forEach(cb => cb.addEventListener('change', function () {
    const all = Array.from(listaWrap.querySelectorAll('input.recup-item'));
    const checkedCount = all.filter(x => x.checked).length;
    if (!masterCb) return;
    masterCb.checked = checkedCount === all.length;
    masterCb.indeterminate = checkedCount > 0 && checkedCount < all.length;
  }));

  window._recupPendientesCache = pendientes;
  if (resultadoWrap) resultadoWrap.innerHTML = '';
}

async function generarRecuperacionesIA() {
  const tipo = (document.getElementById('recup-tipo-select') || {}).value || 'actividad';
  const listaWrap = document.getElementById('recup-lista');
  const resultadoWrap = document.getElementById('recup-resultado');
  if (!window._recupPendientesCache || !window._recupPendientesCache.length) {
    mostrarToast('No hay estudiantes seleccionados. Ejecuta la búsqueda primero.', 'error');
    return;
  }

  const seleccionados = [];
  const itemCheckboxes = listaWrap.querySelectorAll('input.recup-item');
  if (!itemCheckboxes.length) {
    console.log('[IA RECUP] no se encontraron checkboxes en recup-lista');
    mostrarToast('No se encontraron casillas de selección. Ejecuta la búsqueda de nuevo.', 'error');
    return;
  }
  itemCheckboxes.forEach(cb => {
    const idx = parseInt(cb.dataset.idx, 10);
    if (cb.checked && !Number.isNaN(idx) && window._recupPendientesCache && window._recupPendientesCache[idx]) {
      seleccionados.push(window._recupPendientesCache[idx]);
    }
  });
  console.log('[IA RECUP] checkboxes encontrados:', itemCheckboxes.length, 'seleccionados:', seleccionados.length);
  if (!seleccionados.length) {
    console.log('[IA RECUP] ningun estudiante seleccionado, ver cache:', window._recupPendientesCache);
    mostrarToast('Selecciona al menos un estudiante.', 'error');
    return;
  }

  const biblio = cargarBiblioteca();
  const raDescMap = {};
  (biblio.items || []).forEach(it => {
    try {
      const key = _getPlanIdClave(it.id);
      const desc = it?.planificacion?.ra?.descripcion;
      if (key && desc) raDescMap[key] = desc;
    } catch (e) { }
  });

  resultadoWrap.innerHTML = '<div style="padding:10px;border-radius:8px;background:#FFF3E0;color:#E65100;">Generando recursos con IA…</div>';

  let prompt = `Generame un ${tipo} de estos resultados de aprendizaje y acts correspondientes:\n\n`;
  prompt += 'Para cada RA, utiliza la descripción completa del resultado de aprendizaje. No devuelvas solo el código ra_plan_... ni generes títulos inventados.\n';
  prompt += 'Incluye en cada pendiente un arreglo de actividades bajo la clave "actividades". Si no se puede identificar la actividad exacta, usa "Actividad no especificada" en la lista.\n\n';

  seleccionados.forEach(s => {
    prompt += `Estudiante: ${s.estudianteNombre} — Curso: ${s.cursoNombre}\n`;
    const curso = calState.cursos?.[s.cursoId] || {};
    const raAgrupadas = {};
    s.faltantes.forEach(f => {
      const key = f.raKey || 'RA';
      const cursoRa = curso.ras?.[key] || {};
      const raDesc = raDescMap[key]
        || cursoRa.descripcion
        || cursoRa.label
        || cursoRa.desc
        || cursoRa.raDescripcion
        || cursoRa.resultado
        || key;
      const actividadDesc = f.actividadDesc
        || cursoRa._actividadesSnapshot?.find(a => a.id === f.actividadId)?.enunciado
        || 'Actividad pendiente asociada al RA';
      if (!raAgrupadas[key]) {
        raAgrupadas[key] = { codigo: key, descripcion: raDesc, actividades: [] };
      }
      if (Array.isArray(f.actividades) && f.actividades.length) {
        f.actividades.forEach(act => {
          const notaTxt = act.nota === null || act.nota === undefined ? 'sin nota' : String(act.nota);
          const maxTxt = act.max ? ' / ' + act.max + ' pts' : '';
          raAgrupadas[key].actividades.push((act.enunciado || act.id || 'Actividad') + ' — ' + notaTxt + maxTxt);
        });
      } else {
        raAgrupadas[key].actividades.push(actividadDesc);
      }
    });

    Object.values(raAgrupadas).forEach(ra => {
      prompt += `RA: ${ra.codigo}\nDescripción: ${ra.descripcion}\n`;
      if (ra.actividades.length) {
        prompt += 'Actividades:\n';
        ra.actividades.forEach(act => {
          prompt += `- ${act}\n`;
        });
      }
      prompt += '\n';
    });
  });

  prompt += 'Devuelve exclusivamente un JSON válido con este formato:\n'
    + '[{\n'
    + '  "estudiante": "...",\n'
    + '  "curso": "...",\n'
    + '  "pendientes": [{\n'
    + '    "codigo": "...",\n'
    + '    "descripcion": "...",\n'
    + '    "actividades": ["..." ]\n'
    + '  }],\n'
    + '  "sugerencias": [{\n'
    + '    "tipo": "...",\n'
    + '    "descripcion": "...",\n'
    + '    "pasos": ["..."],\n'
    + '    "tiempoAprox": "..."\n'
    + '  }]\n'
    + '}]\n'
    + `No agregues comentarios adicionales, solo retorna el JSON. Tipo solicitado: ${tipo}.`;

  console.log('[IA RECUP] prompt generado:', prompt);
  console.log('[IA RECUP] claves disponibles — Groq:', !!getGroqKey(), 'Gemini:', !!getGeminiKey(), 'OpenRouter:', !!getOpenRouterKey());

  try {
    let data = null;
    if (getGroqKey()) {
      mostrarToast('🧠 Generando con Groq...', 'info');
      data = await _llamarGroqConFallback(prompt, 'Generando recuperaciones', 2048);
      console.log('[IA RECUP] Groq respuesta:', data);
    }
    if (!data && getGeminiKey()) {
      mostrarToast('🟡 Generando con Gemini...', 'info');
      data = await _llamarGemini(prompt, 2048);
      console.log('[IA RECUP] Gemini respuesta:', data);
    }
    if (!data && getOpenRouterKey()) {
      mostrarToast('🔵 Generando con OpenRouter...', 'info');
      data = await _llamarOpenRouterConFallback(prompt, getOpenRouterKey(), 'Generando recuperaciones', 2048, 45000);
      console.log('[IA RECUP] OpenRouter respuesta:', data);
    }
    if (!data) {
      console.log('[IA RECUP] no se obtuvo data de ningun proveedor');
      throw new Error('Sin respuesta de IA');
    }

    const text = typeof data === 'string' ? data : (data.text || JSON.stringify(data));

    // Try to parse JSON result (best-effort)
    let parsed = null;
    try {
      parsed = JSON.parse(text);
    } catch (e) {
      // try to extract JSON substring between first { or [ and last } or ]
      const first = Math.min(...['{','['].map(c => { const i = text.indexOf(c); return i===-1?Infinity:i;}));
      const last = Math.max(...['}',']'].map(c => { const i = text.lastIndexOf(c); return i===-1?-Infinity:i;}));
      if (first !== Infinity && last !== -Infinity && last > first) {
        try { parsed = JSON.parse(text.substring(first, last+1)); } catch (e2) { parsed = null; }
      }
    }

    let outHtml = '';
    if (parsed && (Array.isArray(parsed) || typeof parsed === 'object')) {
      const entries = Array.isArray(parsed) ? parsed : (parsed.resultados || parsed.items || parsed.recuperaciones || [parsed]);
      outHtml += '<div style="display:flex;gap:8px;flex-direction:column;">';
      entries.forEach((ent, i) => {
        const est = ent.estudiante || ent.student || ent.name || ent.nombre || ('Estudiante ' + (i+1));
        const curso = ent.curso || ent.course || '';
        outHtml += '<div style="padding:12px;border-radius:8px;border:1px solid #E0E0E0;background:#fff;">';
        outHtml += '<div style="font-weight:800;color:#1A237E;margin-bottom:6px;">' + escapeHTML(String(est)) + (curso ? ' — ' + escapeHTML(String(curso)) : '') + '</div>';
        if (ent.pendientes && Array.isArray(ent.pendientes)) {
          outHtml += '<div style="font-size:0.92rem;color:#424242;margin-bottom:6px;"><strong>Pendientes:</strong><ul>' + ent.pendientes.map(p => {
            const codigo = escapeHTML((p.codigo||p.raKey||p).toString());
            const descripcion = escapeHTML((p.descripcion||p.actividadDesc||'').toString().substring(0,200));
            const actividades = Array.isArray(p.actividades) ? p.actividades : (p.actividad ? [p.actividad] : []);
            const actividadesHtml = actividades.length
              ? '<ul style="margin:4px 0 0 16px;padding-left:16px;color:#424242;">' + actividades.map(a => '<li>' + escapeHTML(a.toString()) + '</li>').join('') + '</ul>'
              : '';
            return '<li style="margin-bottom:8px;">' + codigo + ': ' + descripcion + actividadesHtml + '</li>';
          }).join('') + '</ul></div>';
        }
        if (ent.sugerencias && Array.isArray(ent.sugerencias)) {
          outHtml += '<div style="font-size:0.92rem;color:#424242;"><strong>Sugerencias:</strong>' + ent.sugerencias.map(s => '<div style="margin-top:6px;padding:8px;border-radius:6px;background:#FAFAFA;">' + '<strong>' + escapeHTML(s.tipo || '') + '</strong>: ' + escapeHTML((s.descripcion || s.texto || '').toString().substring(0,600)) + (s.pasos ? '<div style="margin-top:6px;"><em>Pasos:</em><ol>' + (Array.isArray(s.pasos) ? s.pasos.map(ps => '<li>' + escapeHTML(ps) + '</li>').join('') : ('<li>' + escapeHTML(String(s.pasos)) + '</li>')) + '</ol></div>' : '') + '</div>').join('') + '</div>';
        }
        outHtml += '</div>';
      });
      outHtml += '</div>';
      outHtml = '<div style="padding:10px;border-radius:8px;background:#ECEFF1;color:#263238;">' + outHtml + '</div>';
    } else {
      outHtml = '<div style="padding:10px;border-radius:8px;background:#ECEFF1;color:#263238;white-space:pre-wrap;">' + escapeHTML(text) + '</div>';
    }

    outHtml += '<div style="margin-top:8px;display:flex;gap:8px;flex-wrap:wrap;">'
      + '<button class="btn-siguiente" onclick="_crearPlanesRecuperacionDesdeResultado()">Crear plan(es) en Biblioteca</button>'
      + '<button class="btn-secundario" onclick="copiarResultadoRecuperaciones()">Copiar resultado</button>'
      + '<button class="btn-secundario" onclick="descargarResultadoRecuperaciones(\'json\')">Descargar JSON</button>'
      + '<button class="btn-secundario" onclick="descargarResultadoRecuperaciones(\'txt\')">Descargar TXT</button>'
      + '<button class="btn-secundario" onclick="descargarResultadoRecuperaciones(\'docx\')">Descargar Word</button>'
      + '</div>';

    resultadoWrap.innerHTML = outHtml;
    resultadoWrap.style.display = 'block';
    resultadoWrap.scrollIntoView({ behavior: 'smooth', block: 'start' });
    console.log('[IA RECUP] renderizado en pantalla, contenido largo:', outHtml.length);
    if (!resultadoWrap.innerHTML || resultadoWrap.innerHTML.trim().length === 0) {
      console.log('[IA RECUP] cuerpo de resultado vacío, mostrando texto raw');
      resultadoWrap.innerHTML = '<pre style="white-space:pre-wrap;word-break:break-word;background:#FFF3E0;padding:10px;border-radius:8px;">' + escapeHTML(text) + '</pre>';
    }
    window._recupGeneradoUltimo = text;
  } catch (e) {
    console.error('[IA RECUP] Error IA recuperaciones:', e);
    resultadoWrap.innerHTML = '<div style="padding:10px;border-radius:8px;background:#FFEBEE;color:#C62828;">Error al generar: ' + escapeHTML(e.message || String(e)) + '</div>';
  }
}

function _crearPlanesRecuperacionDesdeResultado() {
  const txt = window._recupGeneradoUltimo;
  if (!txt) { mostrarToast('No hay generación previa para crear.', 'error'); return; }
  try {
    const biblio = cargarBiblioteca();
    const id = 'RECUP-' + Date.now();
    const newPlan = {
      id,
      fechaGuardado: Date.now(),
      fechaGuardadoLabel: new Date().toLocaleString(),
      planificacion: {
        datosGenerales: { moduloFormativo: 'Recuperación IA', nombreDocente: (window.currentUser?.displayName || '') },
        actividades: [],
        ra: { descripcion: 'Recuperación generada por IA', nivelBloom: '', cantidadRA: 1 }
      },
      contenidoIA: txt
    };
    biblio.items = biblio.items || [];
    biblio.items.unshift(newPlan);
    persistirBiblioteca(biblio);
    mostrarToast('Plan de recuperación creado en Biblioteca', 'success');
  } catch (e) { mostrarToast('Error creando plan: ' + e.message, 'error'); }
}

function copiarResultadoRecuperaciones() {
  if (!window._recupGeneradoUltimo) {
    mostrarToast('No hay texto para copiar.', 'error');
    return;
  }
  navigator.clipboard.writeText(window._recupGeneradoUltimo).then(() => {
    mostrarToast('Resultado copiado al portapapeles', 'success');
  }, () => {
    mostrarToast('No se pudo copiar el resultado', 'error');
  });
}

async function descargarResultadoRecuperaciones(tipo) {
  const txt = window._recupGeneradoUltimo;
  if (!txt) { mostrarToast('No hay generación previa para descargar.', 'error'); return; }

  try {
    if (tipo === 'docx') {
      if (typeof window.docx === 'undefined' || !window.docx.Document || !window.docx.Packer || !window.docx.Paragraph || !window.docx.TextRun) {
        mostrarToast('No se puede generar Word: la librería docx no está disponible.', 'error');
        return;
      }
      const { Document, Packer, Paragraph, TextRun } = window.docx;
      let docItems = [];

      const parsedText = (() => {
        try { return JSON.parse(txt); } catch (_e) { return null; }
      })();

      if (parsedText && (Array.isArray(parsedText) || typeof parsedText === 'object')) {
        const entries = Array.isArray(parsedText) ? parsedText : (parsedText.resultados || parsedText.items || parsedText.recuperaciones || [parsedText]);
        entries.forEach((ent, idx) => {
          docItems.push(new Paragraph({ children: [new TextRun({ text: `Estudiante: ${ent.estudiante || ent.name || ''}`, bold: true })] }));
          docItems.push(new Paragraph({ children: [new TextRun({ text: `Curso: ${ent.curso || ent.course || ''}` })] }));
          docItems.push(new Paragraph({ children: [new TextRun({ text: '' })] }));

          if (Array.isArray(ent.pendientes) && ent.pendientes.length) {
            docItems.push(new Paragraph({ children: [new TextRun({ text: 'Pendientes:', bold: true })] }));
            ent.pendientes.forEach(p => {
              const codigo = p.codigo || p.raKey || '';
              const desc = p.descripcion || p.actividadDesc || '';
              docItems.push(new Paragraph({ children: [new TextRun({ text: `- ${codigo}: ${desc}` })] }));
              const actividades = Array.isArray(p.actividades) ? p.actividades : (p.actividad ? [p.actividad] : []);
              actividades.forEach(act => {
                docItems.push(new Paragraph({ children: [new TextRun({ text: `    • ${act}` })] }));
              });
            });
            docItems.push(new Paragraph({ children: [new TextRun({ text: '' })] }));
          }

          if (Array.isArray(ent.sugerencias) && ent.sugerencias.length) {
            docItems.push(new Paragraph({ children: [new TextRun({ text: 'Sugerencias:', bold: true })] }));
            ent.sugerencias.forEach(s => {
              docItems.push(new Paragraph({ children: [new TextRun({ text: `- ${s.tipo || ''}: ${s.descripcion || ''}` })] }));
              if (Array.isArray(s.pasos) && s.pasos.length) {
                s.pasos.forEach(paso => {
                  docItems.push(new Paragraph({ children: [new TextRun({ text: `    • ${paso}` })] }));
                });
              }
              if (s.tiempoAprox) {
                docItems.push(new Paragraph({ children: [new TextRun({ text: `    Tiempo aproximado: ${s.tiempoAprox}` })] }));
              }
            });
          }

          if (idx < entries.length - 1) {
            docItems.push(new Paragraph({ children: [new TextRun({ text: ' ' })] }));
          }
        });
      } else {
        const lines = txt.split(/\r?\n/);
        lines.forEach(line => {
          docItems.push(new Paragraph({ children: [new TextRun({ text: line || ' ' })] }));
        });
      }

      const doc = new Document({ sections: [{ properties: {}, children: docItems }] });
      const blob = await Packer.toBlob(doc);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'recuperaciones.docx';
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
      mostrarToast('Descarga de Word iniciada', 'success');
      return;
    }

    const mime = tipo === 'json' ? 'application/json' : 'text/plain';
    const ext = tipo === 'json' ? 'json' : 'txt';
    const blob = new Blob([txt], { type: mime + ';charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'recuperaciones.' + ext;
    document.body.appendChild(a); a.click(); a.remove();
    URL.revokeObjectURL(url);
    mostrarToast('Descarga iniciada', 'success');
  } catch (e) {
    mostrarToast('Error al descargar: ' + (e.message || String(e)), 'error');
  }
}

function abrirRecuperacionesDashboard() {
  _mostrarPanel('panel-recuperaciones');
  identificarEstudiantesRAsPendientes();
}

function cerrarRecuperacionesDashboard() {
  abrirDashboard();
}

