window.identificarEstudiantesRAsPendientes = identificarEstudiantesRAsPendientes;
window.generarRecuperacionesIA = generarRecuperacionesIA;
window._crearPlanesRecuperacionDesdeResultado = _crearPlanesRecuperacionDesdeResultado;
window.copiarResultadoRecuperaciones = copiarResultadoRecuperaciones;
window.descargarResultadoRecuperaciones = descargarResultadoRecuperaciones;
window.abrirRecuperacionesDashboard = abrirRecuperacionesDashboard;
window.cerrarRecuperacionesDashboard = cerrarRecuperacionesDashboard;

async function verCicloArchivado(yearId) {
  const detailContent = document.getElementById('backup-archivos-detalle-contenido');
  if (!detailContent) return;

  const localArchivedYears = _loadArchivedYears();
  const localArchive = localArchivedYears.find(item => item.id === yearId) || null;
  const renderLocalArchiveCard = (title, subtitle, counts, closedAt) => {
    const displayFecha = closedAt ? new Date(closedAt).toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
    detailContent.innerHTML = '<div style="display:flex;flex-direction:column;gap:10px;">' +
      '<div style="padding:12px 13px;border-radius:10px;background:#fff;border:1px solid #E1BEE7;">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;">' +
          '<div>' +
            '<div style="font-size:0.74rem;font-weight:800;color:#6A1B9A;text-transform:uppercase;letter-spacing:.08em;">Ciclo archivado</div>' +
            '<div style="font-size:1.02rem;font-weight:800;color:#4A148C;margin-top:2px;">' + escapeHTML(title || yearId) + '</div>' +
          '</div>' +
          '<div style="font-size:0.72rem;color:#616161;background:#F3E5F5;border-radius:999px;padding:4px 10px;font-weight:800;">Archivado: ' + escapeHTML(displayFecha) + '</div>' +
        '</div>' +
      '</div>' +
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;">' +
        '<div style="padding:10px 11px;border-radius:10px;background:#E8F5E9;color:#1B5E20;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Planificaciones</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.planificaciones || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#E3F2FD;color:#0D47A1;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Cursos</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.cursos || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#FFF3E0;color:#E65100;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Sesiones diarias</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.sesionesDiarias || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#F1F8E9;color:#2E7D32;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Tareas</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.tareas || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#F3E5F5;color:#6A1B9A;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Asistencia</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.registrosAsistencia || 0) + '</div>' +
        '</div>' +
      '</div>' +
      '<div style="padding:12px 13px;border-radius:10px;background:#E8F5E9;border:1px solid #C8E6C9;display:flex;align-items:flex-start;gap:10px;">' +
        '<span class="material-icons" style="color:#2E7D32;font-size:20px;margin-top:1px;">download_done</span>' +
        '<div>' +
          '<div style="font-size:0.78rem;font-weight:800;color:#1B5E20;margin-bottom:3px;">Backup completo disponible localmente</div>' +
          '<div style="font-size:0.73rem;color:#388E3C;">' + escapeHTML(subtitle) + '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  };

  if (!localArchive) {
    detailContent.innerHTML = '<div style="padding:12px;border-radius:10px;background:#FFF3E0;color:#EF6C00;font-size:0.78rem;">No se encontró una entrada local para el ciclo ' + escapeHTML(yearId) + '.</div>';
    return;
  }

  detailContent.innerHTML = '<div style="padding:12px;border-radius:10px;background:#F3E5F5;color:#6A1B9A;font-size:0.78rem;">Cargando snapshot archivado…</div>';

  const fallbackInfo = {
    title: localArchive.yearLabel || yearId,
    subtitle: 'El backup completo (.json) y la bitácora (.txt) se descargaron automáticamente en tu dispositivo. El registro remoto no estaba disponible en este momento.',
    counts: localArchive.counts || {},
    closedAt: localArchive.closedAt || null
  };

  try {
    if (!window.currentUser || !window.currentUser.uid || !window.firebase || !firebase.firestore) {
      renderLocalArchiveCard(fallbackInfo.title, fallbackInfo.subtitle, fallbackInfo.counts, fallbackInfo.closedAt);
      return;
    }

    const archiveDoc = await db.collection('users').doc(window.currentUser.uid).collection('archives').doc(yearId).get();
    if (!archiveDoc.exists) {
      renderLocalArchiveCard(fallbackInfo.title, fallbackInfo.subtitle, fallbackInfo.counts, fallbackInfo.closedAt);
      return;
    }

    const data = archiveDoc.data() || {};
    const counts = data.counts || {};
    const fecha = data.closedAt ? new Date(data.closedAt).toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—';
    const subtitle = 'Al archivar este ciclo, el backup completo (.json) y la bitácora (.txt) se descargaron automáticamente en tu dispositivo. Usa la sección "Importar backup" para restaurar estos datos si lo necesitas.';

    detailContent.innerHTML = '<div style="display:flex;flex-direction:column;gap:10px;">' +
      '<div style="padding:12px 13px;border-radius:10px;background:#fff;border:1px solid #E1BEE7;">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;">' +
          '<div>' +
            '<div style="font-size:0.74rem;font-weight:800;color:#6A1B9A;text-transform:uppercase;letter-spacing:.08em;">Ciclo archivado</div>' +
            '<div style="font-size:1.02rem;font-weight:800;color:#4A148C;margin-top:2px;">' + escapeHTML(data.yearLabel || yearId) + '</div>' +
          '</div>' +
          '<div style="font-size:0.72rem;color:#616161;background:#F3E5F5;border-radius:999px;padding:4px 10px;font-weight:800;">Archivado: ' + escapeHTML(fecha) + '</div>' +
        '</div>' +
      '</div>' +
      '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:8px;">' +
        '<div style="padding:10px 11px;border-radius:10px;background:#E8F5E9;color:#1B5E20;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Planificaciones</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.planificaciones || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#E3F2FD;color:#0D47A1;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Cursos</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.cursos || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#FFF3E0;color:#E65100;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Sesiones diarias</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.sesionesDiarias || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#F1F8E9;color:#2E7D32;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Tareas</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.tareas || 0) + '</div>' +
        '</div>' +
        '<div style="padding:10px 11px;border-radius:10px;background:#F3E5F5;color:#6A1B9A;">' +
          '<div style="font-size:0.68rem;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.78;">Asistencia</div>' +
          '<div style="font-size:1.16rem;font-weight:800;margin-top:5px;">' + (counts.registrosAsistencia || 0) + '</div>' +
        '</div>' +
      '</div>' +
      '<div style="padding:12px 13px;border-radius:10px;background:#E8F5E9;border:1px solid #C8E6C9;display:flex;align-items:flex-start;gap:10px;">' +
        '<span class="material-icons" style="color:#2E7D32;font-size:20px;margin-top:1px;">download_done</span>' +
        '<div>' +
          '<div style="font-size:0.78rem;font-weight:800;color:#1B5E20;margin-bottom:3px;">Backup completo disponible localmente</div>' +
          '<div style="font-size:0.73rem;color:#388E3C;">' + escapeHTML(subtitle) + '</div>' +
        '</div>' +
      '</div>' +
    '</div>';
  } catch (e) {
    renderLocalArchiveCard(fallbackInfo.title, fallbackInfo.subtitle, fallbackInfo.counts, fallbackInfo.closedAt);
  }
}

function renderizarCiclosAcademicos() {
  const activeYear = localStorage.getItem(ACTIVE_YEAR_KEY) || _getSchoolYearKey();
  const archivedYears = _loadArchivedYears();

  const activeEl = document.getElementById('backup-active-year');
  if (activeEl) activeEl.textContent = activeYear;

  const listEl = document.getElementById('backup-archivos-lista');
  if (!listEl) return;

  const detailContent = document.getElementById('backup-archivos-detalle-contenido');
  if (detailContent && !archivedYears.length) {
    detailContent.innerHTML = '<div style="padding:12px;border-radius:10px;background:#FAFAFA;border:1px dashed #BDBDBD;color:#78909C;font-size:0.78rem;">Selecciona un ciclo archivado para revisar su snapshot completo.</div>';
  }

  if (!archivedYears.length) {
    listEl.innerHTML = '<div style="border:1.5px dashed #E0E0E0;border-radius:10px;padding:12px;text-align:center;color:#78909C;font-size:0.82rem;">Aún no hay ciclos archivados. Cierra el ciclo actual para guardar su historial.</div>';
    return;
  }

  listEl.innerHTML = archivedYears.map(item => {
    const counts = item.counts || {};
    const fecha = item.closedAt ? new Date(item.closedAt).toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' }) : '—';
    const badge = item.id === activeYear ? '<span style="display:inline-flex;align-items:center;padding:2px 8px;background:#E8F5E9;color:#2E7D32;border-radius:999px;font-size:0.68rem;font-weight:800;">Activo</span>' : '';
    return '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:12px 13px;border:1px solid #E0E0E0;border-radius:10px;background:#fff;margin-bottom:8px;">' +
      '<div style="flex:1;">' +
        '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;">' +
          '<div style="font-size:0.95rem;font-weight:800;color:#1565C0;">' + escapeHTML(item.yearLabel) + '</div>' +
          badge +
        '</div>' +
        '<div style="font-size:0.74rem;color:#78909C;margin-bottom:6px;">Archivado: ' + escapeHTML(fecha) + '</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:8px;font-size:0.72rem;color:#616161;margin-bottom:10px;">' +
          '<span style="background:#F1F8E9;color:#2E7D32;border-radius:999px;padding:3px 8px;font-weight:700;">' + (counts.planificaciones || 0) + ' planificaciones</span>' +
          '<span style="background:#E3F2FD;color:#1565C0;border-radius:999px;padding:3px 8px;font-weight:700;">' + (counts.cursos || 0) + ' cursos</span>' +
          '<span style="background:#FFF3E0;color:#E65100;border-radius:999px;padding:3px 8px;font-weight:700;">' + (counts.sesionesDiarias || 0) + ' sesiones diarias</span>' +
        '</div>' +
        '<div style="display:flex;gap:8px;flex-wrap:wrap;">' +
          '<button type="button" data-action="ver-archivo" data-year="' + escapeHTML(item.id) + '" style="border:none;border-radius:999px;background:#6A1B9A;color:#fff;font-size:0.72rem;font-weight:800;padding:8px 10px;cursor:pointer;">Revisar snapshot</button>' +
          '<button type="button" data-action="descargar-archivo-nube" data-year="' + escapeHTML(item.id) + '" style="border:none;border-radius:999px;background:#1565C0;color:#fff;font-size:0.72rem;font-weight:800;padding:8px 10px;cursor:pointer;">Descargar backup nube</button>' +
        '</div>' +
      '</div>' +
      '<span class="material-icons" style="color:#90A4AE;font-size:20px;">history</span>' +
    '</div>';
  }).join('');

  listEl.querySelectorAll('[data-action="ver-archivo"]').forEach(button => {
    button.addEventListener('click', (e) => {
      const yearId = e.currentTarget.dataset.year;
      verCicloArchivado(yearId);
    });
  });

  listEl.querySelectorAll('[data-action="descargar-archivo-nube"]').forEach(button => {
    button.addEventListener('click', async (e) => {
      const yearId = e.currentTarget.dataset.year;
      await descargarBackupArchivadoDesdeFirebase(yearId);
    });
  });
}

function abrirBackup() {
  _backupFileData = null;
  document.getElementById('backup-overlay').classList.remove('hidden');
  document.getElementById('backup-file-name').textContent = 'Seleccionar archivo .json';
  document.getElementById('backup-preview').classList.add('hidden');
  document.getElementById('backup-preview').innerHTML = '';
  document.getElementById('backup-btn-importar').style.display = 'none';
  document.getElementById('backup-file-input').value = '';

  const archiveBtn = document.getElementById('backup-archivar-btn');
  if (archiveBtn) archiveBtn.disabled = !window.currentUser;

  renderizarCiclosAcademicos();

  // Inicializar panel de recuperaciones IA
  const recupLista = document.getElementById('recup-lista');
  if (recupLista) recupLista.innerHTML = 'Pulsa "Buscar RAs pendientes" para iniciar.';

  // Resumen de datos actuales
  const biblio = cargarBiblioteca();
  const nPlans = (biblio.items || []).length;
  const cal = JSON.parse(localStorage.getItem(CAL_STORAGE_KEY) || '{"cursos":{}}');
  const nCursos = Object.keys(cal.cursos || {}).length;
  const diarias = JSON.parse(localStorage.getItem(DIARIAS_KEY) || '{"sesiones":{}}');
  const nSesiones = Object.keys(diarias.sesiones || {}).length;
  const tieneKey = !!getGroqKey();

  document.getElementById('backup-resumen').innerHTML =
    '<div style="background:#F1F8E9;border-radius:8px;padding:10px 12px;display:flex;gap:16px;flex-wrap:wrap;">' +
    '<span><strong>' + nPlans + '</strong> planificacion' + (nPlans !== 1 ? 'es' : '') + '</span>' +
    '<span><strong>' + nCursos + '</strong> curso' + (nCursos !== 1 ? 's' : '') + '</span>' +
    '<span><strong>' + nSesiones + '</strong> sesion' + (nSesiones !== 1 ? 'es' : '') + ' diarias</span>' +
    '<span>' + (tieneKey ? '✓ API Key guardada' : 'Sin API Key') + '</span>' +
    '</div>';

  // Backups automáticos de calificaciones
  const backups = JSON.parse(localStorage.getItem(CAL_BACKUP_KEY) || '[]');
  const backupEl = document.getElementById('backup-cal-historial');
  if (backupEl) {
    if (!backups.length) {
      backupEl.innerHTML = '<p style="color:#9E9E9E;font-size:0.82rem;text-align:center;padding:8px;">Aún no hay copias de seguridad automáticas.<br>Se generan cada vez que guardas calificaciones.</p>';
    } else {
      backupEl.innerHTML = backups.map((b, i) => {
        let cal; try { cal = JSON.parse(b.data); } catch { cal = { cursos: {} }; }
        const nc = Object.keys(cal.cursos || {}).length;
        return '<div style="display:flex;align-items:center;gap:10px;padding:8px 12px;background:#fff;border:1.5px solid #E0E0E0;border-radius:8px;margin-bottom:6px;">' +
          '<span class="material-icons" style="color:#1565C0;font-size:20px;">history</span>' +
          '<div style="flex:1;">' +
          '<div style="font-size:0.85rem;font-weight:600;color:#212121;">' + escapeHTML(b.label) + (i === 0 ? ' <span style="background:#E8F5E9;color:#2E7D32;border-radius:8px;padding:1px 7px;font-size:0.7rem;font-weight:700;">Más reciente</span>' : '') + '</div>' +
          '<div style="font-size:0.75rem;color:#78909C;">' + nc + ' curso' + (nc !== 1 ? 's' : '') + '</div>' +
          '</div>' +
          '<button onclick="restaurarBackupCalificaciones(' + i + ')" style="background:#E3F2FD;color:#1565C0;border:1px solid #90CAF9;border-radius:6px;padding:5px 12px;font-size:0.78rem;font-weight:600;cursor:pointer;white-space:nowrap;">Restaurar</button>' +
          '</div>';
      }).join('');
    }
  }
}

function cerrarBackup() {
  document.getElementById('backup-overlay').classList.add('hidden');
}
