function abrirConfiguracion() {
  const overlay = document.getElementById('config-overlay');
  if (!overlay) return;
  // Cargar valores guardados en los toggles
  const dark = localStorage.getItem('cfg_dark_mode') === 'true';
  const grande = localStorage.getItem('cfg_fuente_grande') === 'true';
  const alertas = localStorage.getItem('cfg_alertas') !== 'false';
  const manana = localStorage.getItem('cfg_manana') !== 'false';
  const umbral = localStorage.getItem('asist_umbral') || '80';
  const cfgDark = document.getElementById('cfg-dark-mode');
  const cfgGrande = document.getElementById('cfg-fuente-grande');
  const cfgAlert = document.getElementById('cfg-alertas');
  const cfgMan = document.getElementById('cfg-manana');
  const cfgUmbral = document.getElementById('cfg-umbral-asist');
  const tactil = localStorage.getItem('planificadorRA_touchMode_v1') === 'true';
  if (cfgDark) cfgDark.checked = dark;
  if (cfgGrande) cfgGrande.checked = grande;
  if (cfgAlert) cfgAlert.checked = alertas;
  if (cfgMan) cfgMan.checked = manana;
  if (cfgUmbral) cfgUmbral.value = umbral;
  const cfgUmbralRiesgo = document.getElementById('cfg-umbral-riesgo');
  if (cfgUmbralRiesgo) cfgUmbralRiesgo.value = localStorage.getItem('cfg_umbral_riesgo') || '70';
  const cfgUmbralActs = document.getElementById('cfg-umbral-acts');
  if (cfgUmbralActs) cfgUmbralActs.value = localStorage.getItem('cfg_umbral_acts') || '3';
  const cfgTouch = document.getElementById('cfg-touch-mode');
  if (cfgTouch) cfgTouch.checked = tactil;
  // Asistencia activa
  const cfgAsist = document.getElementById('cfg-asistencia-activa');
  if (cfgAsist) cfgAsist.checked = localStorage.getItem('cfg_asistencia_activa') !== 'false';
  const umbralRow = document.getElementById('cfg-asistencia-umbral-row');
  if (umbralRow) umbralRow.style.display = (localStorage.getItem('cfg_asistencia_activa') !== 'false') ? '' : 'none';
  // Mostrar código de invitación activo
  const inviteLbl = document.getElementById('cfg-invite-code-actual');
  if (inviteLbl) {
    const codigoActual = localStorage.getItem('tinclass_invite_code')
      || (typeof TINCLASS_INVITE_CODE_DEFAULT !== 'undefined' ? TINCLASS_INVITE_CODE_DEFAULT : 'TINCLASS2026');
    inviteLbl.textContent = 'Código activo: ' + codigoActual;
  }
  _cfgActualizarEstadoPin();
  overlay.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}
function cerrarConfiguracion() {
  document.getElementById('config-overlay')?.classList.add('hidden');
  document.body.style.overflow = '';
}

function _syncPreferencias() {
  if (!window._syncFirebase) return;
  const keys = ['cfg_dark_mode','cfg_fuente_grande','cfg_alertas','cfg_manana',
                 'cfg_asistencia_activa','cfg_umbral_riesgo','cfg_umbral_acts','asist_umbral',
                 'planificadorRA_touchMode_v1'];
  const data = {};
  keys.forEach(k => { const v = localStorage.getItem(k); if (v !== null) data[k] = v; });
  _syncFirebase('preferencias', data);
}

function toggleDarkMode(on) {
  localStorage.setItem('cfg_dark_mode', on);
  document.body.classList.toggle('dark-mode', on);
  mostrarToast(on ? 'Modo oscuro activado 🌙' : 'Modo claro activado ☀️', 'success');
  _syncPreferencias();
}

function toggleFuenteGrande(on) {
  localStorage.setItem('cfg_fuente_grande', on);
  document.body.classList.toggle('fuente-grande', on);
  mostrarToast(on ? 'Fuente grande activada' : 'Fuente normal activada', 'success');
  _syncPreferencias();
}

function limpiarTodosDatos() {
  localStorage.clear();
  mostrarToast('Todos los datos borrados. Recargando…', 'error');
  setTimeout(() => location.reload(), 1500);
}

function _aplicarPreferencias() {
  if (localStorage.getItem('cfg_dark_mode') === 'true') document.body.classList.add('dark-mode');
  if (localStorage.getItem('cfg_fuente_grande') === 'true') document.body.classList.add('fuente-grande');
  if (localStorage.getItem('planificadorRA_touchMode_v1') === 'true') {
    document.body.classList.add('touch-mode');
    _inyectarCSSTouch(true);
  }
  _aplicarAsistenciaActiva();
}

function _aplicarAsistenciaActiva() {
  // 'true' o null → activo; 'false' → desactivado
  const activa = localStorage.getItem('cfg_asistencia_activa') !== 'false';

  // Sincronizar checkbox en config
  const chk = document.getElementById('cfg-asistencia-activa');
  if (chk) chk.checked = activa;

  // Mostrar/ocultar fila de umbral
  const umbralRow = document.getElementById('cfg-asistencia-umbral-row');
  if (umbralRow) umbralRow.style.display = activa ? '' : 'none';

  // Mostrar/ocultar botón de asistencia en el libro de calificaciones
  const btnToggle = document.getElementById('btn-toggle-asistencia');
  if (btnToggle) btnToggle.style.display = activa ? '' : 'none';

  // Si está desactivada y la vista de asistencia está abierta, ocultarla
  if (!activa) {
    const panelAsist = document.getElementById('panel-asistencia') ||
                       document.querySelector('.asistencia-panel');
    if (panelAsist) panelAsist.classList.add('hidden');
  }
}

