function toggleModoTactil(on) {
  localStorage.setItem('planificadorRA_touchMode_v1', on ? 'true' : 'false');
  document.body.classList.toggle('touch-mode', on);
  _inyectarCSSTouch(on);
  renderizarTablaCalificaciones();
  mostrarToast(on ? 'Modo táctil activado ✋' : 'Modo táctil desactivado', 'success');
  _syncPreferencias();
}

function _inyectarCSSTouch(activo) {
  let el = document.getElementById('touch-mode-css');
  if (activo && !el) {
    el = document.createElement('style');
    el.id = 'touch-mode-css';
    el.textContent = `
      body.touch-mode .input-nota {
        height:54px!important;font-size:1.2rem!important;
        cursor:pointer!important;caret-color:transparent;
        user-select:none;-webkit-user-select:none;
      }
      body.touch-mode .btn-coment-est {
        width:38px!important;height:38px!important;min-width:38px!important;
      }
      body.touch-mode .btn-del-estudiante {
        width:36px!important;height:36px!important;
      }
      body.touch-mode .btn-accion, body.touch-mode .btn-export, body.touch-mode .btn-sm {
        padding:12px 18px!important;font-size:0.95rem!important;min-height:46px!important;
      }
      body.touch-mode .asist-btn-estado {
        padding:14px 20px!important;font-size:1.05rem!important;min-width:58px!important;gap:6px!important;
      }
      body.touch-mode .asist-row { padding:14px 12px!important;min-height:64px!important; }
      body.touch-mode button { touch-action:manipulation;-webkit-tap-highlight-color:rgba(21,101,192,0.15); }
      body.touch-mode *:hover { transform:none!important; }
      body.touch-mode .th-act .input-valor-act { width:58px!important;height:34px!important;font-size:0.88rem!important; }
      body.touch-mode .td-nombre { min-width:180px!important; }
      body.touch-mode .tab-curso { padding:10px 14px!important;font-size:0.9rem!important; }
    `;
    document.head.appendChild(el);
  } else if (!activo && el) {
    el.remove();
  }
}

// ─── Teclado numérico en pantalla ─────────────────────────────────
let _tecladoInputActivo = null;
let _tecladoValor = '';

function abrirTecladoNotas(inputEl) {
  _tecladoInputActivo = inputEl;
  _tecladoValor = (inputEl.value !== undefined && inputEl.value !== '') ? String(inputEl.value) : '';
  document.getElementById('teclado-display').textContent = _tecladoValor || '—';
  document.getElementById('teclado-max-label').textContent = 'Máx: ' + (inputEl.max || '100') + ' pts';
  document.getElementById('teclado-notas-overlay').classList.remove('hidden');
}

function cerrarTecladoNotas() {
  document.getElementById('teclado-notas-overlay').classList.add('hidden');
  _tecladoInputActivo = null;
  _tecladoValor = '';
}

function tecladoPresionar(val) {
  if (val === 'DEL') {
    _tecladoValor = _tecladoValor.slice(0, -1);
  } else if (val === 'AC') {
    _tecladoValor = '';
  } else if (val === '.') {
    if (!_tecladoValor.includes('.')) _tecladoValor += (_tecladoValor === '' ? '0.' : '.');
  } else {
    // No permitir más de 5 dígitos total
    if (_tecladoValor.replace('.', '').length >= 5) return;
    _tecladoValor = (_tecladoValor === '0') ? val : _tecladoValor + val;
  }
  document.getElementById('teclado-display').textContent = _tecladoValor || '—';
}

function tecladoConfirmar() {
  if (!_tecladoInputActivo) { cerrarTecladoNotas(); return; }
  if (_tecladoValor === '' || _tecladoValor === null) {
    _tecladoInputActivo.value = '';
    _tecladoInputActivo.dispatchEvent(new Event('input', { bubbles: true }));
    _tecladoInputActivo.dispatchEvent(new Event('change', { bubbles: true }));
    cerrarTecladoNotas();
    return;
  }
  const num = parseFloat(_tecladoValor);
  const max = parseFloat(_tecladoInputActivo.max) || 100;
  if (isNaN(num) || num < 0) { mostrarToast('Valor inválido', 'error'); return; }
  if (num > max) { mostrarToast('La nota no puede superar ' + max + ' pts', 'error'); return; }
  _tecladoInputActivo.value = num;
  _tecladoInputActivo.dispatchEvent(new Event('input', { bubbles: true }));
  _tecladoInputActivo.dispatchEvent(new Event('change', { bubbles: true }));
  cerrarTecladoNotas();
}

// ─── Interceptar toque en inputs de nota para mostrar teclado táctil ──
document.addEventListener('touchstart', function (e) {
  if (!document.body.classList.contains('touch-mode')) return;
  const target = e.target.closest('.input-nota');
  if (!target) return;
  e.preventDefault();
  abrirTecladoNotas(target);
}, { passive: false });

// ─── Swipe horizontal en el wizard ────────────────────────────────
(function _initWizardSwipe() {
  let _sx = null, _sy = null;
  document.addEventListener('touchstart', function (e) {
    _sx = e.touches[0].clientX;
    _sy = e.touches[0].clientY;
  }, { passive: true });
  document.addEventListener('touchend', function (e) {
    if (_sx === null) return;
    const dx = e.changedTouches[0].clientX - _sx;
    const dy = e.changedTouches[0].clientY - _sy;
    _sx = null; _sy = null;
    if (!document.body.classList.contains('touch-mode')) return;
    // Solo swipe horizontal marcado (>70px y más ancho que alto)
    if (Math.abs(dx) < 70 || Math.abs(dx) < Math.abs(dy) * 1.5) return;
    // Solo si el wizard está visible
    const wizardPanel = document.getElementById('panel-planificacion');
    if (!wizardPanel || wizardPanel.classList.contains('hidden')) return;
    if (typeof irAlPaso !== 'function') return;
    if (dx < 0) irAlPaso(pasoActual + 1, true);   // swipe ← → siguiente
    else         irAlPaso(pasoActual - 1, false);  // swipe → ← anterior
  }, { passive: true });
})();

// MÓDULO: ACERCA DE
// ════════════════════════════════════════════════════════════════════
function abrirAcercaDe() {
  document.getElementById('acercade-overlay')?.classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function cerrarAcercaDe() {
  document.getElementById('acercade-overlay')?.classList.add('hidden');
  document.body.style.overflow = '';
}



function exportarDatos() {
  const ahora = new Date();
  const backup = _buildExportSnapshot();

  const json = JSON.stringify(backup, null, 2);
  const blob = new Blob([json], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  const fecha = ahora.toISOString().slice(0, 10);
  a.href = url;
  a.download = 'backup-planificador-' + fecha + '.json';
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  URL.revokeObjectURL(url);

  // También descargar la bitácora de cambios (.txt)
  setTimeout(() => { exportarBitacora(); }, 500);

  mostrarToast('Backup descargado correctamente', 'success');
}

function onBackupFileSelected(input) {
  const file = input.files[0];
  if (!file) return;
  document.getElementById('backup-file-name').textContent = file.name;

  const reader = new FileReader();
  reader.onload = function (e) {
    try {
      const data = JSON.parse(e.target.result);

      // Validar que es un backup válido
      if (!data._meta || !data.biblioteca) {
        mostrarToast('El archivo no parece ser un backup válido', 'error');
        return;
      }

      _backupFileData = data;

      // Generar preview
      const biblio = JSON.parse(data.biblioteca || '{"items":[]}');
      const cal = JSON.parse(data.calificaciones || '{"cursos":{}}');
      const nPlans = (biblio.items || []).length;
      const nCursos = Object.keys(cal.cursos || {}).length;
      const diariasData = JSON.parse(data.diarias || '{"sesiones":{}}');
      const nSes = Object.keys(diariasData.sesiones || {}).length;

      document.getElementById('backup-preview').innerHTML =
        '<div style="font-weight:700;margin-bottom:6px;color:#0D47A1;">Contenido del backup:</div>' +
        '<div style="display:flex;gap:14px;flex-wrap:wrap;">' +
        '<span>📅 <strong>' + data._meta.exportadoLabel + '</strong></span>' +
        '<span>📁 <strong>' + nPlans + '</strong> planificacion' + (nPlans !== 1 ? 'es' : '') + '</span>' +
        '<span>🏫 <strong>' + nCursos + '</strong> curso' + (nCursos !== 1 ? 's' : '') + '</span>' +
        '<span>📝 <strong>' + nSes + '</strong> sesiones diarias</span>' +
        (data.groqKey ? '<span>🔑 API Key incluida</span>' : '') +
        '</div>';
      document.getElementById('backup-preview').classList.remove('hidden');
      document.getElementById('backup-btn-importar').style.display = 'flex';

    } catch (err) {
      mostrarToast('Error al leer el archivo: ' + err.message, 'error');
    }
  };
  reader.readAsText(file);
}

function importarDatos() {
  if (!_backupFileData) return;

  if (!confirm(
    '¿Restaurar este backup?\n\n' +
    'Esto reemplazará TODOS tus datos actuales (planificaciones, calificaciones y sesiones diarias) ' +
    'con los del archivo seleccionado.\n\n' +
    'Esta acción no se puede deshacer.'
  )) return;

  try {
    const d = _backupFileData;

    if (d.biblioteca) localStorage.setItem(BIBLIO_KEY, d.biblioteca);
    if (d.calificaciones) localStorage.setItem(CAL_STORAGE_KEY, d.calificaciones);
    if (d.horario) localStorage.setItem(HORARIO_KEY, d.horario);
    if (d.tareas) localStorage.setItem(TAREAS_KEY, d.tareas);
    if (d.asistencia) localStorage.setItem(ASIST_KEY, d.asistencia);
    if (d.comentarios) localStorage.setItem(COMENT_KEY, d.comentarios);
    if (d.notasClase) {
      try {
        const nc = JSON.parse(d.notasClase);
        Object.entries(nc).forEach(([k, v]) => localStorage.setItem(k, v));
      } catch { }
    }
    if (d.obsEstudiantes) {
      try {
        const obs = JSON.parse(d.obsEstudiantes);
        Object.entries(obs).forEach(([k, v]) => localStorage.setItem(k, v));
      } catch { }
    }
    if (d.diarias) localStorage.setItem(DIARIAS_KEY, d.diarias);
    if (d.incidencias) localStorage.setItem(INCID_KEY, d.incidencias);
    if (d.recuperaciones) localStorage.setItem(RECUP_KEY, d.recuperaciones);
    if (d.borrador && d.borrador !== 'null') localStorage.setItem(STORAGE_KEY, d.borrador);
    if (d.notasDocente) localStorage.setItem(NOTAS_DOCENTE_KEY, d.notasDocente);
    if (d.libreta) localStorage.setItem(LIBRETA_KEY, d.libreta);
    if (d.evalFormas) {
      try {
        const ef = JSON.parse(d.evalFormas);
        Object.entries(ef).forEach(([k, v]) => localStorage.setItem(k, v));
      } catch { }
    }
    if (d.groqKey) localStorage.setItem(GROQ_KEY_STORAGE, d.groqKey);
    if (d.openrouterKey) localStorage.setItem(OPENROUTER_KEY_STORAGE, d.openrouterKey);
    if (d.cuentasEstudiantes) localStorage.setItem(CUENTAS_EST_KEY, d.cuentasEstudiantes);
    if (d.bitacora) localStorage.setItem(BITACORA_KEY, d.bitacora);
    if (d.participacion) localStorage.setItem(PARTICIP_KEY, d.participacion);
    if (d.blog) localStorage.setItem(BLOG_KEY, d.blog);
    if (d.reportes) localStorage.setItem(REPORTES_KEY, d.reportes);
    if (d.calendarioEscolar) localStorage.setItem(CAL_ESC_KEY, d.calendarioEscolar);
    if (d.stickies) localStorage.setItem(STICKIES_KEY, d.stickies);
    if (d.calBackups) localStorage.setItem(CAL_BACKUP_KEY, d.calBackups);
    if (d.geminiKey) localStorage.setItem(GEMINI_KEY_STORAGE, d.geminiKey);
    if (d.preferencias) {
      try {
        const pref = JSON.parse(d.preferencias);
        Object.entries(pref).forEach(([k, v]) => {
          if (v !== null && v !== undefined) localStorage.setItem(k, v);
        });
      } catch { }
    }
    if (d._meta && d._meta.schoolYear) {
      localStorage.setItem(ACTIVE_YEAR_KEY, d._meta.schoolYear);
      if (window._syncFirebase) {
        window._syncFirebase('active_year', d._meta.schoolYear);
      }
    }

    mostrarToast('¡Datos restaurados correctamente! Recargando...', 'success');
    cerrarBackup();

    // Recargar la página para que todo se inicialice desde localStorage
    setTimeout(() => location.reload(), 1200);

  } catch (err) {
    mostrarToast('Error al restaurar: ' + err.message, 'error');
  }
}

