  const blog = cargarBlog();
  const post = id ? (blog.posts || []).find(p => p.id === id) : null;
  const cursos = Object.values(calState.cursos || {}).sort((a, b) => a.nombre.localeCompare(b.nombre));
  const opsCursos = cursos.map(c =>
    `<option value="${escapeHTML(c.id)}" ${post?.cursoId === c.id ? 'selected' : ''}>${escapeHTML(c.nombre)}</option>`
  ).join('');

  window._blogTempAdjuntos = (post?.adjuntos || []).map(a => ({ ...a }));

  document.getElementById('modal-title').textContent = post ? 'Editar post' : 'Nuevo post';
  document.getElementById('modal-body').innerHTML = `
  <div style="display:flex;flex-direction:column;gap:14px;padding:4px 0;">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <div>
        <label style="font-size:0.82rem;font-weight:600;color:#616161;display:block;margin-bottom:4px;">Curso *</label>
        <select id="bp-curso" onchange="_blogActualizarRAs()"
          style="width:100%;padding:8px;border:1.5px solid #E0E0E0;border-radius:8px;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);box-sizing:border-box;">
          <option value="">— Selecciona —</option>${opsCursos}
        </select>
      </div>
      <div>
        <label style="font-size:0.82rem;font-weight:600;color:#616161;display:block;margin-bottom:4px;">RA / Planificación *</label>
        <select id="bp-plan"
          style="width:100%;padding:8px;border:1.5px solid #E0E0E0;border-radius:8px;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);box-sizing:border-box;">
          <option value="">— Primero elige curso —</option>
        </select>
      </div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
      <div>
        <label style="font-size:0.82rem;font-weight:600;color:#616161;display:block;margin-bottom:4px;">Tipo *</label>
        <select id="bp-tipo"
          style="width:100%;padding:8px;border:1.5px solid #E0E0E0;border-radius:8px;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);box-sizing:border-box;">
          <option value="pc"       ${post?.tipo === 'pc'       ? 'selected' : ''}>🖥️ Tarea en PC</option>
          <option value="cuaderno" ${post?.tipo === 'cuaderno' ? 'selected' : ''}>📓 Tarea en cuaderno</option>
          <option value="info"     ${post?.tipo === 'info'     ? 'selected' : ''}>ℹ️ Información</option>
        </select>
      </div>
      <div>
        <label style="font-size:0.82rem;font-weight:600;color:#616161;display:block;margin-bottom:4px;">Fecha límite</label>
        <input type="date" id="bp-fecha" value="${post?.fechaLimite || ''}"
          style="width:100%;padding:8px;border:1.5px solid #E0E0E0;border-radius:8px;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);box-sizing:border-box;">
      </div>
    </div>
    <div>
      <label style="font-size:0.82rem;font-weight:600;color:#616161;display:block;margin-bottom:4px;">Título *</label>
      <input type="text" id="bp-titulo" value="${escapeHTML(post?.titulo || '')}"
        placeholder="Ej: Actividad 3 — Diagrama de flujo"
        style="width:100%;padding:8px;border:1.5px solid #E0E0E0;border-radius:8px;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);box-sizing:border-box;">
    </div>
    <div>
      <label style="font-size:0.82rem;font-weight:600;color:#616161;display:block;margin-bottom:4px;">Instrucciones / Contenido *</label>
      <textarea id="bp-contenido" rows="5"
        placeholder="Escribe las instrucciones de la tarea o la información a compartir..."
        style="width:100%;padding:8px;border:1.5px solid #E0E0E0;border-radius:8px;resize:vertical;font-family:inherit;background:var(--color-superficie,#fff);color:var(--color-texto-primario,#212121);box-sizing:border-box;">${escapeHTML(post?.contenido || '')}</textarea>
    </div>
    <div>
      <label style="font-size:0.82rem;font-weight:600;color:#616161;display:block;margin-bottom:4px;">
        Archivos adjuntos <span style="font-weight:400;color:#9E9E9E;">(máx. 3 · 400 KB c/u)</span>
      </label>
      <input type="file" id="bp-adjunto-input" multiple onchange="_blogAgregarAdjuntos(event)" style="display:none;">
      <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:4px;">
        <button type="button" onclick="document.getElementById('bp-adjunto-input').click()"
          style="background:#F5F5F5;border:1.5px dashed #BDBDBD;border-radius:8px;padding:6px 14px;font-size:0.82rem;cursor:pointer;color:#616161;display:inline-flex;align-items:center;gap:4px;">
          <span class="material-icons" style="font-size:16px;">attach_file</span> Adjuntar
        </button>
        <div id="bp-adjuntos-lista" style="display:flex;gap:6px;flex-wrap:wrap;">
          ${window._blogTempAdjuntos.map((a, i) =>
            `<span class="blog-adjunto-chip">${escapeHTML(a.nombre)}
              <button onclick="_blogQuitarAdjunto(${i})" style="background:none;border:none;cursor:pointer;color:#C62828;padding:0 2px;line-height:1;">✕</button>
            </span>`).join('')}
        </div>
      </div>
    </div>
    <div style="display:flex;gap:8px;justify-content:flex-end;padding-top:8px;border-top:1px solid #E0E0E0;">
      <button class="btn-secundario" onclick="cerrarModalBtn()">Cancelar</button>
      <button class="btn-siguiente" onclick="_guardarPost('${id || ''}')">
        <span class="material-icons">save</span> Guardar
      </button>
    </div>
  </div>`;

  if (post) _blogActualizarRAs(post.planId);
  document.getElementById('modal-overlay').classList.remove('hidden');
