function _blogActualizarRAs(selectedPlanId) {
  const cursoId = document.getElementById('bp-curso')?.value;
  const selPlan = document.getElementById('bp-plan');
  if (!selPlan) return;
  if (!cursoId) { selPlan.innerHTML = '<option value="">— Primero elige curso —</option>'; return; }
  const curso = calState.cursos[cursoId];
  if (!curso) return;
  const biblio = cargarBiblioteca().items || [];
  // Mantener orden de planIds para asignar RA1, RA2…
  const planIds = curso.planIds || [];
  const plans = planIds.map(pid => biblio.find(i => i.id === pid)).filter(Boolean);
  selPlan.innerHTML = '<option value="">— Selecciona RA —</option>'
    + plans.map((pl, idx) => {
        const raDescRaw = pl.planificacion?.ra?.descripcion || '';
        const raMatchNum = raDescRaw.match(/RA\s*(\d+)/i);
        const raNum  = raMatchNum ? 'RA' + raMatchNum[1] : 'RA' + (idx + 1);
        const modulo = pl.planificacion?.datosGenerales?.moduloFormativo || '';
        // Buscar descripción del RA en curso.ras si ya fue inicializado
        const raKey  = 'ra_plan_' + String(pl.id).replace(/[^a-zA-Z0-9]/g, '_').substring(0, 20);
        const raDesc = (curso.ras || {})[raKey]?.label || raDescRaw || '';
        // Label: "RA1 — Módulo · Descripción RA"
        let display = raNum;
        if (modulo) display += ' — ' + modulo.substring(0, 45);
        if (raDesc && raDesc !== modulo) display += ' · ' + raDesc.substring(0, 35);
        return `<option value="${escapeHTML(pl.id)}" ${(selectedPlanId || '') === pl.id ? 'selected' : ''}>${escapeHTML(display)}</option>`;
      }).join('');
}

function _blogAgregarAdjuntos(event) {
  const files = Array.from(event.target.files || []);
  for (const file of files) {
    if ((window._blogTempAdjuntos || []).length >= 3) { mostrarToast('Máximo 3 archivos', 'warning'); break; }
    if (file.size > 400 * 1024) { mostrarToast(file.name + ' supera los 400 KB', 'warning'); continue; }
    const reader = new FileReader();
    reader.onload = function(e) {
      window._blogTempAdjuntos = window._blogTempAdjuntos || [];
      window._blogTempAdjuntos.push({ nombre: file.name, datos: e.target.result });
      _blogRefrescarListaAdjuntos();
    };
    reader.readAsDataURL(file);
  }
  event.target.value = '';
}

function _blogQuitarAdjunto(idx) {
  (window._blogTempAdjuntos = window._blogTempAdjuntos || []).splice(idx, 1);
  _blogRefrescarListaAdjuntos();
}

function _blogRefrescarListaAdjuntos() {
  const lista = document.getElementById('bp-adjuntos-lista');
  if (!lista) return;
  lista.innerHTML = (window._blogTempAdjuntos || []).map((a, i) =>
    `<span class="blog-adjunto-chip">${escapeHTML(a.nombre)}
      <button onclick="_blogQuitarAdjunto(${i})" style="background:none;border:none;cursor:pointer;color:#C62828;padding:0 2px;line-height:1;">✕</button>
    </span>`
  ).join('');
}

function _guardarPost(id) {
  const cursoId   = document.getElementById('bp-curso')?.value.trim();
  const planId    = document.getElementById('bp-plan')?.value.trim();
  const tipo      = document.getElementById('bp-tipo')?.value || 'info';
  const titulo    = document.getElementById('bp-titulo')?.value.trim();
  const contenido = document.getElementById('bp-contenido')?.value.trim();
  const fechaLimite = document.getElementById('bp-fecha')?.value || null;
  if (!cursoId)   { mostrarToast('Selecciona un curso', 'error'); return; }
  if (!planId)    { mostrarToast('Selecciona un RA', 'error'); return; }
  if (!titulo)    { mostrarToast('Escribe un título', 'error'); return; }
  if (!contenido) { mostrarToast('Escribe el contenido', 'error'); return; }

  const curso   = calState.cursos[cursoId];
  const biblio  = cargarBiblioteca().items || [];
  const plan    = biblio.find(i => i.id === planId);
  const raIdx   = (curso?.planIds || []).indexOf(planId);
  const raDesc  = plan?.planificacion?.ra?.descripcion || '';
  const raMatch = raDesc.match(/RA\s*(\d+)/i);
  const raNum   = raMatch ? 'RA' + raMatch[1] : (raIdx >= 0 ? 'RA' + (raIdx + 1) : 'RA');
  const modulo  = plan?.planificacion?.datosGenerales?.moduloFormativo || '';
  const raLabel = raNum + (modulo ? ' — ' + modulo : '') || planId;
  const blog    = cargarBlog();
  const ahora   = new Date().toISOString();
  const adjuntos = window._blogTempAdjuntos || [];

  if (id) {
    const idx = (blog.posts || []).findIndex(p => p.id === id);
    if (idx >= 0) {
      const wasPublicado = blog.posts[idx].publicado;
      blog.posts[idx] = { ...blog.posts[idx], cursoId, cursoNombre: curso?.nombre || '', planId, raLabel, tipo, titulo, contenido, fechaLimite, adjuntos, actualizadoEn: ahora };
      guardarBlog(blog);
      if (wasPublicado) _blogPublicarEnFirestore(blog.posts[idx]);
    }
  } else {
    const nuevo = { id: 'blog-' + Date.now(), cursoId, cursoNombre: curso?.nombre || '', planId, raLabel, tipo, titulo, contenido, fechaLimite, adjuntos, publicado: false, creadoEn: ahora };
    (blog.posts = blog.posts || []).push(nuevo);
    guardarBlog(blog);
  }
  cerrarModalBtn();
  renderizarBlog();
  mostrarToast(id ? 'Post actualizado' : 'Post guardado como borrador', 'success');
}

function _duplicarPostACurso(postId) {
  cargarCalificaciones();
  const blog = cargarBlog();
  const post = (blog.posts || []).find(p => p.id === postId);
  if (!post) return;
  const cursos = Object.values(calState.cursos || {}).sort((a, b) => a.nombre.localeCompare(b.nombre));
  if (!cursos.length) { mostrarToast('No hay cursos disponibles', 'error'); return; }

  const opciones = cursos
    .filter(c => c.id !== post.cursoId)
    .map(c => `<label style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:8px;cursor:pointer;transition:background 0.15s;">
      <input type="checkbox" value="${c.id}" data-nombre="${escapeHTML(c.nombre)}" style="accent-color:#1565C0;">
      <span style="font-size:0.9rem;">${escapeHTML(c.nombre)}</span>
    </label>`).join('');

  document.getElementById('modal-title').textContent = 'Duplicar post a otros cursos';
  document.getElementById('modal-body').innerHTML = `
    <div style="padding:8px 0;">
      <div style="font-size:0.85rem;color:#546E7A;margin-bottom:10px;">
        <strong>${escapeHTML(post.titulo)}</strong><br>
        Selecciona los cursos donde quieres duplicar este post:
      </div>
      <div id="dup-cursos-list" style="max-height:300px;overflow-y:auto;display:flex;flex-direction:column;gap:2px;border:1px solid #E0E0E0;border-radius:10px;padding:8px;">
        ${opciones || '<div style="color:#9E9E9E;padding:12px;text-align:center;">No hay otros cursos disponibles</div>'}
      </div>
      <div style="margin-top:14px;display:flex;gap:10px;justify-content:flex-end;">
        <button onclick="cerrarModalBtn()" style="padding:8px 18px;border:1px solid #E0E0E0;border-radius:8px;background:#fff;cursor:pointer;">Cancelar</button>
        <button onclick="_ejecutarDuplicarPost('${postId}')" style="padding:8px 18px;border:none;border-radius:8px;background:#1565C0;color:#fff;cursor:pointer;font-weight:600;">
          <span class="material-icons" style="font-size:16px;vertical-align:middle;">content_copy</span> Duplicar
        </button>
      </div>
    </div>`;
  document.getElementById('modal-overlay').classList.remove('hidden');
}

function _ejecutarDuplicarPost(postId) {
  const blog = cargarBlog();
  const post = (blog.posts || []).find(p => p.id === postId);
  if (!post) return;
  const checks = document.querySelectorAll('#dup-cursos-list input[type="checkbox"]:checked');
  if (!checks.length) { mostrarToast('Selecciona al menos un curso', 'error'); return; }

  let count = 0;
  checks.forEach(chk => {
    const cursoId = chk.value;
    const cursoNombre = chk.dataset.nombre || '';
    const copia = {
      ...post,
      id: 'blog-' + Date.now() + '-' + (++count),
      cursoId,
      cursoNombre,
      publicado: false,
      creadoEn: new Date().toISOString(),
    };
    delete copia.actualizadoEn;
    (blog.posts = blog.posts || []).push(copia);
  });

  guardarBlog(blog);
  cerrarModalBtn();
  renderizarBlog();
  mostrarToast(`Post duplicado a ${count} curso${count > 1 ? 's' : ''} como borrador`, 'success');
}

function publicarPost(id) {
  const blog = cargarBlog();
  const post = (blog.posts || []).find(p => p.id === id);
  if (!post) return;
  post.publicado = true;
  guardarBlog(blog);
  _blogPublicarEnFirestore(post);
  renderizarBlog();
  mostrarToast('Post publicado ✓', 'success');
}

function despublicarPost(id) {
  const blog = cargarBlog();
  const post = (blog.posts || []).find(p => p.id === id);
  if (!post) return;
  post.publicado = false;
  guardarBlog(blog);
  _blogDespublicarEnFirestore(id);
  renderizarBlog();
  mostrarToast('Post despublicado', 'info');
}

function eliminarPost(id) {
  if (!confirm('¿Eliminar este post? Esta acción no se puede deshacer.')) return;
  const blog = cargarBlog();
  const post = (blog.posts || []).find(p => p.id === id);
  if (post?.publicado) _blogDespublicarEnFirestore(id);
  blog.posts = (blog.posts || []).filter(p => p.id !== id);
  guardarBlog(blog);
  renderizarBlog();
  mostrarToast('Post eliminado', 'info');
}

function _blogPublicarEnFirestore(post) {
  if (!window.currentUser || typeof db === 'undefined') return;
  const uid = window.currentUser.uid;
  db.collection('public_blogs').doc(uid).collection('posts').doc(post.id)
    .set({ ...post })
    .catch(e => console.warn('Error publicando post en Firestore:', e));
}

function _blogDespublicarEnFirestore(postId) {
  if (!window.currentUser || typeof db === 'undefined') return;
  const uid = window.currentUser.uid;
  db.collection('public_blogs').doc(uid).collection('posts').doc(postId)
    .delete()
    .catch(e => console.warn('Error despublicando post:', e));
}

function copiarLinkBlog() {
  const filtro = document.getElementById('blog-filtro-curso')?.value || '';
  if (!filtro) { mostrarToast('Selecciona un curso para copiar su link', 'info'); return; }
  const url = document.getElementById('blog-link-url')?.textContent?.trim();
  if (!url) return;
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url)
      .then(() => mostrarToast('Link copiado al portapapeles', 'success'))
      .catch(() => _copiarFallback(url));
  } else {
    _copiarFallback(url);
  }
}
function _copiarFallback(text) {
  const ta = document.createElement('textarea');
  ta.value = text;
  ta.style.cssText = 'position:fixed;opacity:0;';
  document.body.appendChild(ta);
  ta.select();
  try {
    document.execCommand('copy');
    mostrarToast('Link copiado al portapapeles', 'success');
  } catch {
    mostrarToast('No se pudo copiar. Cópialo manualmente.', 'error');
  }
  document.body.removeChild(ta);
}

function verEntregasPost(postId) {
  if (!window.currentUser || typeof db === 'undefined') return;
  const uid = window.currentUser.uid;
  document.getElementById('modal-title').textContent = 'Entregas de estudiantes';
  document.getElementById('modal-body').innerHTML = `
    <div style="text-align:center;padding:24px;">
      <span class="material-icons" style="font-size:36px;color:#BDBDBD;display:block;margin-bottom:8px;">hourglass_empty</span>
      <p style="color:#9E9E9E;font-size:0.85rem;">Cargando entregas...</p>
    </div>`;
  document.getElementById('modal-overlay').classList.remove('hidden');

  db.collection('public_blogs').doc(uid).collection('submissions')
    .where('postId', '==', postId)
    .orderBy('fecha', 'desc')
    .get()
    .then(snap => {
      const docs = snap.docs.map(d => d.data());
      const body = document.getElementById('modal-body');
      if (!body) return;
      if (docs.length === 0) {
        body.innerHTML = '<div style="text-align:center;padding:24px;color:#9E9E9E;">'
          + '<span class="material-icons" style="font-size:40px;display:block;margin-bottom:8px;">inbox</span>'
          + '<p>Ningún estudiante ha entregado aún.</p></div>';
        return;
      }
      body.innerHTML = `<div style="font-size:0.82rem;color:#616161;margin-bottom:12px;">${docs.length} entrega(s)</div>`
        + docs.map((s, idx) => `
          <div style="border:1px solid #E0E0E0;border-radius:8px;padding:12px 14px;margin-bottom:10px;">
            <div style="font-weight:700;font-size:0.9rem;margin-bottom:4px;">${escapeHTML(s.nombre || 'Sin nombre')}</div>
            ${s.comentario ? `<div style="font-size:0.82rem;color:#424242;margin-bottom:8px;">${escapeHTML(s.comentario)}</div>` : ''}
            ${s.archivo
              ? `<button onclick="_descargarEntrega(window._blogEntregas[${idx}].archivo.datos,'${escapeHTML(s.archivo.nombre)}')"
                  style="background:#E3F2FD;border:1.5px solid #90CAF9;border-radius:6px;padding:5px 12px;font-size:0.78rem;cursor:pointer;color:#1565C0;display:inline-flex;align-items:center;gap:4px;margin-bottom:6px;">
                  <span class="material-icons" style="font-size:14px;">download</span> ${escapeHTML(s.archivo.nombre)}
                </button>`
              : '<span style="font-size:0.78rem;color:#9E9E9E;">Sin archivo adjunto</span>'}
            <div style="font-size:0.72rem;color:#9E9E9E;margin-top:4px;">${new Date(s.fecha).toLocaleString('es')}</div>
          </div>`).join('');
      window._blogEntregas = docs;
    })
    .catch(e => {
      const body = document.getElementById('modal-body');
      if (body) body.innerHTML = `<div style="color:#C62828;padding:16px;">Error: ${escapeHTML(e.message)}</div>`;
    });
}

function _descargarEntrega(datos, nombre) {
  const a = document.createElement('a');
  a.href = datos;
  a.download = nombre;
  a.click();
}

// ════════════════════════════════════════════════════════════════════
// TEMPORIZADOR DE CLASE
// ════════════════════════════════════════════════════════════════════

const TIMER_CIRCUM = 2 * Math.PI * 52; // ≈ 326.73

const _timerState = {
  total:     0,
  remaining: 0,
  running:   false,
  interval:  null
};

function toggleTimerPanel() {
  const panel = document.getElementById('timer-panel');
  if (!panel) return;
  const hidden = panel.classList.contains('hidden');
  if (hidden) {
    panel.classList.remove('hidden');
    _timerActualizarDisplay();
    _timerActualizarUI();
  } else {
    panel.classList.add('hidden');
  }
}

function _timerPreset(minutes) {
  if (_timerState.running) return;
  const secs = minutes * 60;
  _timerState.total     = secs;
  _timerState.remaining = secs;
  // Actualizar inputs
  const inMin = document.getElementById('timer-input-min');
  const inSeg = document.getElementById('timer-input-seg');
  if (inMin) inMin.value = minutes;
  if (inSeg) inSeg.value = 0;
  // Highlight preset activo
  document.querySelectorAll('.timer-preset-btn').forEach(b => {
    b.classList.toggle('activo', parseInt(b.textContent) === minutes);
  });
  _timerActualizarDisplay();
  _timerActualizarUI();
}

function _timerToggle() {
  if (_timerState.running) {
    _timerParar();
  } else {
    _timerIniciar();
  }
}

function _timerIniciar() {
  // Si no hay tiempo cargado, leer de los inputs
  if (_timerState.total === 0 || _timerState.remaining === 0) {
    const inMin = document.getElementById('timer-input-min');
    const inSeg = document.getElementById('timer-input-seg');
    const m = Math.max(0, parseInt(inMin?.value || '0'));
    const s = Math.max(0, Math.min(59, parseInt(inSeg?.value || '0')));
    const total = m * 60 + s;
    if (total <= 0) return;
    _timerState.total     = total;
    _timerState.remaining = total;
  }
  if (_timerState.remaining <= 0) return;
  _timerState.running  = true;
  _timerState.interval = setInterval(_timerTick, 1000);
  _timerActualizarDisplay();
  _timerActualizarUI();
}

function _timerParar() {
  _timerState.running = false;
  clearInterval(_timerState.interval);
  _timerState.interval = null;
  _timerActualizarUI();
}

function _timerReset() {
  _timerParar();
  _timerState.total     = 0;
  _timerState.remaining = 0;
  // Limpiar clases de estado
  const fab  = document.getElementById('timer-fab');
  const ring = document.getElementById('timer-ring-prog');
  if (fab)  { fab.classList.remove('timer-fab-running', 'timer-fab-fin'); }
  if (ring) { ring.classList.remove('timer-running', 'timer-fin'); }
  // Limpiar preset activo
  document.querySelectorAll('.timer-preset-btn').forEach(b => b.classList.remove('activo'));
  // Limpiar inputs
  const inMin = document.getElementById('timer-input-min');
  const inSeg = document.getElementById('timer-input-seg');
  if (inMin) inMin.value = 0;
  if (inSeg) inSeg.value = 0;
  _timerActualizarDisplay();
  _timerActualizarUI();
}

function _timerTick() {
  if (_timerState.remaining > 0) {
    _timerState.remaining--;
    _timerActualizarDisplay();
    if (_timerState.remaining === 0) {
      _timerFin();
    }
  }
}

function _timerFin() {
  _timerParar();
  _timerBeep();
  const fab  = document.getElementById('timer-fab');
  const ring = document.getElementById('timer-ring-prog');
  if (fab)  { fab.classList.remove('timer-fab-running'); fab.classList.add('timer-fab-fin'); }
  if (ring) { ring.classList.remove('timer-running'); ring.classList.add('timer-fin'); }
  _timerActualizarDisplay();
  _timerActualizarUI();
  // Quitar clases de fin después de 6 s
  setTimeout(() => {
    if (fab)  fab.classList.remove('timer-fab-fin');
    if (ring) ring.classList.remove('timer-fin');
  }, 6000);
}

function _timerActualizarDisplay() {
  const rem  = Math.max(0, _timerState.remaining);
  const tot  = Math.max(1, _timerState.total);
  const mm   = String(Math.floor(rem / 60)).padStart(2, '0');
  const ss   = String(rem % 60).padStart(2, '0');
  const txt  = mm + ':' + ss;

  // Texto central del anillo
  const disp = document.getElementById('timer-display');
  if (disp) disp.textContent = tot === 1 && rem === 0 ? '00:00' : txt;

  // Anillo SVG
  const ring = document.getElementById('timer-ring-prog');
  if (ring) {
    const frac   = _timerState.total > 0 ? rem / tot : 0;
    const offset = TIMER_CIRCUM * (1 - frac);
    ring.style.strokeDashoffset = offset;
  }

  // FAB: icono vs tiempo
  const fabIcon = document.getElementById('timer-fab-icon');
  const fabTime = document.getElementById('timer-fab-time');
  if (_timerState.total > 0) {
    if (fabIcon) fabIcon.classList.add('hidden');
    if (fabTime) { fabTime.classList.remove('hidden'); fabTime.textContent = txt; }
  } else {
    if (fabIcon) fabIcon.classList.remove('hidden');
    if (fabTime) fabTime.classList.add('hidden');
  }
}

function _timerActualizarUI() {
  const playBtn = document.getElementById('timer-btn-play');
  const fab     = document.getElementById('timer-fab');
  const ring    = document.getElementById('timer-ring-prog');
  if (playBtn) {
    const icon = playBtn.querySelector('.material-icons');
    if (icon) icon.textContent = _timerState.running ? 'pause' : 'play_arrow';
  }
  if (fab) {
    if (_timerState.running) {
      fab.classList.add('timer-fab-running');
      fab.classList.remove('timer-fab-fin');
    } else {
      fab.classList.remove('timer-fab-running');
    }
  }
  if (ring) {
    ring.classList.toggle('timer-running', _timerState.running);
  }
}

function _timerBeep() {
  try {
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const beepOnce = (startAt) => {
      const osc  = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type            = 'sine';
      osc.frequency.value = 880;
      gain.gain.setValueAtTime(0.5, startAt);
      gain.gain.exponentialRampToValueAtTime(0.001, startAt + 0.3);
      osc.start(startAt);
      osc.stop(startAt + 0.35);
    };
    beepOnce(ctx.currentTime);
    beepOnce(ctx.currentTime + 0.45);
    beepOnce(ctx.currentTime + 0.90);
  } catch (e) { /* sin audio disponible */ }
}

// ================================================================
// HISTORIAL DE SESIONES
// ================================================================
async function abrirHistorialSesiones() {
  const user = window.currentUser;
  if (!user) return;
  document.getElementById('sesiones-overlay')?.classList.remove('hidden');
  document.getElementById('sesiones-loading')?.classList.remove('hidden');
  document.getElementById('sesiones-lista')?.classList.add('hidden');

  try {
    const snap = await db.collection('users').doc(user.uid)
                         .collection('sessions')
                         .orderBy('timestamp', 'desc')
                         .limit(50)
                         .get();

    const lista = document.getElementById('sesiones-lista');
    if (!lista) return;

    if (snap.empty) {
      lista.innerHTML = '<p style="text-align:center;color:var(--color-texto-sec,#757575);padding:32px 0;">No hay sesiones registradas aún.</p>';
    } else {
      let html = '';
      snap.forEach(doc => {
        const d = doc.data();
        const ts = d.timestamp ? d.timestamp.toDate() : null;
        const fechaStr = ts ? ts.toLocaleDateString('es-ES', { weekday:'short', day:'2-digit', month:'short', year:'numeric' }) : '—';
        const horaStr  = ts ? ts.toLocaleTimeString('es-ES', { hour:'2-digit', minute:'2-digit' }) : '—';

        const deviceIcon = d.device === 'Escritorio' ? 'computer' : 'smartphone';
        const browserIcon = { Chrome:'language', Firefox:'language', Safari:'language', Edge:'language', Opera:'language' }[d.browser] || 'public';

        html += `<div class="sesion-entry">
          <div class="sesion-entry-icon"><span class="material-icons">${deviceIcon}</span></div>
          <div class="sesion-entry-info">
            <div class="sesion-entry-titulo">${escapeHTML(d.browser)} · ${escapeHTML(d.os)}</div>
            <div class="sesion-entry-meta">${escapeHTML(d.device)} &nbsp;·&nbsp; ${escapeHTML(d.resolution)} &nbsp;·&nbsp; ${escapeHTML(d.language)}</div>
            <div class="sesion-entry-fecha">${fechaStr} &nbsp;–&nbsp; ${horaStr}</div>
          </div>
        </div>`;
      });
      lista.innerHTML = html;
    }

    document.getElementById('sesiones-loading')?.classList.add('hidden');
    lista.classList.remove('hidden');
  } catch (e) {
    const lista = document.getElementById('sesiones-lista');
    if (lista) {
      lista.innerHTML = '<p style="text-align:center;color:#C62828;padding:32px 0;">Error al cargar el historial.</p>';
      lista.classList.remove('hidden');
    }
    document.getElementById('sesiones-loading')?.classList.add('hidden');
  }
}

function cerrarHistorialSesiones() {
  document.getElementById('sesiones-overlay')?.classList.add('hidden');
}

async function limpiarHistorialSesiones() {
  const user = window.currentUser;
  if (!user) return;
  if (!confirm('¿Eliminar todo el historial de sesiones?')) return;
  try {
    const snap = await db.collection('users').doc(user.uid).collection('sessions').get();
    const batch = db.batch();
    snap.forEach(d => batch.delete(d.ref));
    await batch.commit();
    registrarCambio('Historial de sesiones eliminado');
    abrirHistorialSesiones(); // re-carga (mostrará vacío)
  } catch (e) {
    mostrarToast('Error al limpiar historial', 'error');
  }
}

// ================================================================
// MÓDULO REPORTES ACADÉMICOS Y DISCIPLINARIOS
// ================================================================
const REPORTES_KEY = 'planificadorRA_reportes_v1';
let _repEstId   = null;
let _repCursoId = null;

function cargarReportes() {
  try { return JSON.parse(localStorage.getItem(REPORTES_KEY)) || {}; } catch(e) { return {}; }
}
function guardarReportes(data) {
  localStorage.setItem(REPORTES_KEY, JSON.stringify(data));
  _syncFirebase('reportes', data);
  // Sincronizar al portal de padres y psicología en Firestore
  _syncDatosPadreReportes(data);
  // Actualizar cada estudiante modificado en datos_padre (para psicología)
  Object.entries(data).forEach(([estId, reportes]) => _syncReportePsicologia(estId, reportes));
}

function _syncDatosPadreReportes(data) {
  if (typeof db === 'undefined' || !firebase.auth().currentUser) return;
  const uid = firebase.auth().currentUser.uid;
  const batch = db.batch();
  Object.entries(data).forEach(([estId, items]) => {
    const ref = db.collection('public_blogs').doc(uid)
      .collection('datos_padre').doc(estId);
    batch.set(ref, { reportes: items }, { merge: true });
  });
  batch.commit().catch(e => console.warn('sync datos_padre reportes:', e));
}
function _getReportesEst(estId) {
  const data = cargarReportes();
  return (data[estId] || []).slice().sort((a, b) => b.ts - a.ts);
}

function abrirReportes(estId, cursoId) {
  _repEstId   = estId;
  _repCursoId = cursoId;
  const curso = calState.cursos[cursoId];
  const est   = curso && curso.estudiantes.find(e => e.id === estId);
  const elNombre = document.getElementById('rep-est-nombre');
  if (elNombre) elNombre.textContent = est ? est.nombre : '—';
  renderizarReportes(estId);
  document.getElementById('reportes-overlay')?.classList.remove('hidden');
}

function cerrarReportesBtn() {
  document.getElementById('reportes-overlay')?.classList.add('hidden');
  _repEstId = null; _repCursoId = null;
}
function cerrarReportes(e) {
  if (e.target.id === 'reportes-overlay') cerrarReportesBtn();
}

function renderizarReportes(estId) {
  const body = document.getElementById('rep-body');
  if (!body) return;
  const reportes    = _getReportesEst(estId);
  const curso       = calState.cursos[_repCursoId];
  const est         = curso && curso.estudiantes.find(e => e.id === estId);
  const cursoNombre = curso ? curso.nombre : '';
  const hoy         = new Date().toISOString().split('T')[0];

  // ── Lista de reportes guardados ──
  let listaHtml = '';
  if (reportes.length) {
    listaHtml = '<div style="padding:16px 20px 0;">' +
      '<div style="font-size:0.75rem;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#546E7A;margin-bottom:10px;">Reportes guardados</div>';
    reportes.forEach(r => {
      const fecha = r.fechaReporte
        ? new Date(r.fechaReporte + 'T12:00:00').toLocaleDateString('es-ES', {weekday:'short',day:'2-digit',month:'short',year:'numeric'})
        : '—';
      const resumen = (r.detallesEvento || '').substring(0, 70) + (r.detallesEvento && r.detallesEvento.length > 70 ? '…' : '');
      listaHtml +=
        '<div style="display:flex;align-items:center;gap:8px;padding:10px 12px;border-radius:8px;' +
        'border:1px solid var(--color-borde,#E0E0E0);margin-bottom:8px;background:var(--color-fondo-card,#FAFAFA);">' +
          '<span class="material-icons" style="font-size:20px;color:#B71C1C;flex-shrink:0;">description</span>' +
          '<div style="flex:1;min-width:0;">' +
            '<div style="font-size:0.88rem;font-weight:600;color:var(--color-texto,#212121);">' + escapeHTML(fecha) + '</div>' +
            '<div style="font-size:0.78rem;color:#757575;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + escapeHTML(resumen) + '</div>' +
          '</div>' +
          '<button class="btn-icon-sm" title="Imprimir reporte" onclick="imprimirReporte(\'' + r.id + '\',\'' + estId + '\')" style="color:#1565C0;">' +
            '<span class="material-icons" style="font-size:16px;">print</span>' +
          '</button>' +
          '<button class="btn-icon-sm" title="Eliminar reporte" onclick="eliminarReporte(\'' + r.id + '\',\'' + estId + '\')" style="color:#C62828;">' +
            '<span class="material-icons" style="font-size:16px;">delete</span>' +
          '</button>' +
        '</div>';
    });
    listaHtml += '</div><hr style="border:none;border-top:1px solid var(--color-borde,#E0E0E0);margin:0;">';
  }

  // ── Estilos reutilizables ──
  const fld = 'width:100%;box-sizing:border-box;padding:8px 10px;border:1px solid var(--color-borde,#BDBDBD);' +
              'border-radius:6px;font-size:0.9rem;background:var(--color-fondo,#fff);color:var(--color-texto,#212121);font-family:inherit;';
  const ta  = fld + 'resize:vertical;min-height:80px;';
  const lbl = 'display:block;font-size:0.78rem;font-weight:700;color:#546E7A;margin-bottom:4px;margin-top:12px;';

  // ── Formulario nuevo reporte ──
  const formHtml =
    '<div style="padding:16px 20px 20px;">' +
    '<div style="font-size:0.75rem;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#546E7A;margin-bottom:12px;">Nuevo reporte</div>' +

    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">' +
      '<div><label style="' + lbl + '">Nombre del estudiante</label>' +
        '<input id="rep-f-nombre" style="' + fld + '" type="text" value="' + escapeHTML(est ? est.nombre : '') + '"></div>' +
      '<div><label style="' + lbl + '">Grado / Curso</label>' +
        '<input id="rep-f-grado" style="' + fld + '" type="text" value="' + escapeHTML(cursoNombre) + '"></div>' +
    '</div>' +

    '<label style="' + lbl + '">Fecha</label>' +
    '<input id="rep-f-fecha" style="' + fld + '" type="date" value="' + hoy + '">' +

    '<label style="' + lbl + '">Detalles del evento *</label>' +
    '<textarea id="rep-f-detalles" style="' + ta + '" placeholder="Describe el evento o situación académica/disciplinaria..."></textarea>' +

    '<label style="' + lbl + '">Medidas trabajadas por el docente en el aula</label>' +
    '<textarea id="rep-f-medidas" style="' + ta + '" placeholder="Acciones y estrategias aplicadas por el docente..."></textarea>' +

    '<label style="' + lbl + '">Si la falta es repetitiva, amerita seguimiento de Coordinación o Psicología — especificar:</label>' +
    '<textarea id="rep-f-seguimiento" style="' + ta + '" placeholder="Describir si aplica seguimiento institucional..."></textarea>' +

    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:4px;">' +
      '<div><label style="' + lbl + '">Firma estudiante (nombre)</label>' +
        '<input id="rep-f-firma-est" style="' + fld + '" type="text" placeholder="Nombre del estudiante"></div>' +
      '<div><label style="' + lbl + '">Número celular estudiante</label>' +
        '<input id="rep-f-cel-est" style="' + fld + '" type="tel" placeholder="Ej: 0999-000-000"></div>' +
    '</div>' +

    '<hr style="border:none;border-top:1px dashed var(--color-borde,#BDBDBD);margin:16px 0 4px;">' +
    '<div style="font-size:0.75rem;font-weight:700;color:#546E7A;margin-bottom:4px;">Firmas institucionales</div>' +

    '<label style="' + lbl + '">Firma del docente</label>' +
    '<input id="rep-f-firma-doc" style="' + fld + '" type="text" placeholder="Nombre del docente">' +

    '<label style="' + lbl + '">Firma de coordinación pedagógica</label>' +
    '<input id="rep-f-firma-coord" style="' + fld + '" type="text" placeholder="Nombre del coordinador">' +

    '<label style="' + lbl + '">Firma de psicología</label>' +
    '<input id="rep-f-firma-psico" style="' + fld + '" type="text" placeholder="Nombre del psicólogo (si aplica)">' +

    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">' +
      '<div><label style="' + lbl + '">Firma del padre, madre o tutor</label>' +
        '<input id="rep-f-firma-tutor" style="' + fld + '" type="text" placeholder="Nombre del tutor"></div>' +
      '<div><label style="' + lbl + '">Teléfono del padre, madre o tutor</label>' +
        '<input id="rep-f-tel-tutor" style="' + fld + '" type="tel" placeholder="Ej: 0988-000-000"></div>' +
    '</div>' +

    '<div id="rep-error" style="color:#C62828;font-size:0.82rem;margin-top:8px;min-height:18px;"></div>' +

    '<button class="auth-btn-primary" style="margin-top:14px;width:100%;" onclick="guardarReporteNuevo(\'' + estId + '\')">' +
      '<span class="material-icons">save</span> Guardar reporte' +
    '</button>' +
    '</div>';

  body.innerHTML = listaHtml + formHtml;
}

function guardarReporteNuevo(estId) {
  const detalles = (document.getElementById('rep-f-detalles')?.value || '').trim();
  const errEl = document.getElementById('rep-error');
  if (!detalles) {
    if (errEl) errEl.textContent = 'Los detalles del evento son obligatorios.';
    return;
  }
  if (errEl) errEl.textContent = '';

  const nuevo = {
    id:                    uid(),
    ts:                    Date.now(),
    fechaReporte:          document.getElementById('rep-f-fecha')?.value || new Date().toISOString().split('T')[0],
    cursoNombre:           (document.getElementById('rep-f-grado')?.value || '').trim(),
    estudianteNombre:      (document.getElementById('rep-f-nombre')?.value || '').trim(),
    gradoCursa:            (document.getElementById('rep-f-grado')?.value || '').trim(),
    detallesEvento:        detalles,
    medidasDocente:        (document.getElementById('rep-f-medidas')?.value || '').trim(),
    seguimientoRepetitiva: (document.getElementById('rep-f-seguimiento')?.value || '').trim(),
    firmaEstudiante:       (document.getElementById('rep-f-firma-est')?.value || '').trim(),
    celularEstudiante:     (document.getElementById('rep-f-cel-est')?.value || '').trim(),
    firmaDocente:          (document.getElementById('rep-f-firma-doc')?.value || '').trim(),
    firmaCoordenacion:     (document.getElementById('rep-f-firma-coord')?.value || '').trim(),
    firmaPsicologia:       (document.getElementById('rep-f-firma-psico')?.value || '').trim(),
    firmaTutor:            (document.getElementById('rep-f-firma-tutor')?.value || '').trim(),
    telefonoTutor:         (document.getElementById('rep-f-tel-tutor')?.value || '').trim()
  };

  const data = cargarReportes();
  if (!data[estId]) data[estId] = [];
  data[estId].push(nuevo);
  guardarReportes(data);
  registrarCambio('Reporte académico guardado — ' + nuevo.estudianteNombre);
  mostrarToast('Reporte guardado', 'success');
  renderizarReportes(estId);
}

function eliminarReporte(id, estId) {
  if (!confirm('¿Eliminar este reporte? No se puede deshacer.')) return;
  const data = cargarReportes();
  if (data[estId]) data[estId] = data[estId].filter(r => r.id !== id);
  guardarReportes(data);
  registrarCambio('Reporte académico eliminado');
  renderizarReportes(estId);
}

function imprimirReporte(id, estId) {
  const data = cargarReportes();
  const rep  = (data[estId] || []).find(r => r.id === id);
  if (!rep) return;

  const fecha = rep.fechaReporte
    ? new Date(rep.fechaReporte + 'T12:00:00').toLocaleDateString('es-ES', { day:'2-digit', month:'long', year:'numeric' })
    : '—';

  const esc = escapeHTML;

  const html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">' +
    '<title>Reporte — ' + esc(rep.estudianteNombre) + '</title>' +
    '<style>body{font-family:Arial,sans-serif;margin:18mm 18mm 14mm;font-size:11pt;}' +
    'table{width:100%;border-collapse:collapse;}' +
    'td{border:1px solid #000;padding:5px 8px;font-size:11pt;vertical-align:top;}' +
    'h3{text-align:center;font-size:13pt;margin-bottom:14px;}' +
    '.area{min-height:70px;border:1px solid #000;padding:5px 6px;font-size:11pt;margin-top:3px;}' +
    'b{font-size:10pt;}' +
    '@media print{.no-print{display:none!important;}}</style></head><body>' +
    '<div class="no-print" style="text-align:center;margin-bottom:14px;">' +
      '<button onclick="window.print()" style="padding:9px 26px;background:#1565C0;color:#fff;border:none;border-radius:6px;font-size:13px;cursor:pointer;">' +
        'Imprimir / Guardar PDF' +
      '</button>' +
    '</div>' +
    '<h3>Reporte acad&eacute;mico y/o situaciones especiales de disciplina.</h3>' +
    '<table>' +
      '<tr><td style="width:43%;"><b>Nombre y apellido de estudiante</b></td><td>' + esc(rep.estudianteNombre) + '</td></tr>' +
      '<tr><td><b>Grado que cursa el estudiante</b></td><td>' + esc(rep.gradoCursa) + '</td></tr>' +
      '<tr><td><b>Fecha</b></td><td>' + esc(fecha) + '</td></tr>' +
      '<tr><td colspan="2"><b>Detalles del evento:</b><div class="area">' + esc(rep.detallesEvento).replace(/\n/g,'<br>') + '</div></td></tr>' +
      '<tr><td colspan="2"><b>Medidas trabajadas por el docente en el aula:</b><div class="area">' + esc(rep.medidasDocente || '').replace(/\n/g,'<br>') + '</div></td></tr>' +
      '<tr><td colspan="2"><b>Si la falta cometida por el estudiante es repetitiva, la cual amerita seguimiento de Coordinaci&oacute;n o psicolog&iacute;a, especificar la misma:</b>' +
        '<div class="area">' + esc(rep.seguimientoRepetitiva || '').replace(/\n/g,'<br>') + '</div></td></tr>' +
      '<tr><td><b>Firma estudiante</b><br><br>' + esc(rep.firmaEstudiante) + '</td><td></td></tr>' +
      '<tr><td><b>N&uacute;mero celular</b></td><td>' + esc(rep.celularEstudiante) + '</td></tr>' +
    '</table>' +
    '<table style="margin-top:16px;">' +
      '<tr><td style="width:43%;"><b>Firma del docente</b><br><br>' + esc(rep.firmaDocente) + '</td><td></td></tr>' +
      '<tr><td><b>Firma de coordinaci&oacute;n pedag&oacute;gica</b><br><br>' + esc(rep.firmaCoordenacion) + '</td><td></td></tr>' +
      '<tr><td><b>Firma de psicolog&iacute;a</b><br><br>' + esc(rep.firmaPsicologia) + '</td><td></td></tr>' +
      '<tr><td><b>Firma del padre, madre o tutor</b><br><br>' + esc(rep.firmaTutor) + '</td><td></td></tr>' +
      '<tr><td><b>Tel&eacute;fono del padre, madre o tutor</b></td><td>' + esc(rep.telefonoTutor) + '</td></tr>' +
    '</table>' +
    '<script>window.onload=function(){setTimeout(function(){window.print();},400);};<\/script>' +
    '</body></html>';

  const win = window.open('', '_blank', 'width=820,height=950');
  if (win) { win.document.write(html); win.document.close(); }
}

// ================================================================
// MODO PRESENTACIÓN — Vista limpia para proyector/pizarra
// ================================================================
const _PRES_HORAS = { 1:480, 2:530, 3:600, 4:650, 5:750, 6:800, 7:860, 8:910 };
const _PRES_PERIODOS_LABEL = {
  1:'8:00 – 8:50 AM', 2:'8:50 – 9:40 AM', 3:'10:00 – 10:50 AM', 4:'10:50 – 11:40 AM',
  5:'12:30 – 1:20 PM', 6:'1:20 – 2:10 PM', 7:'2:20 – 3:10 PM', 8:'3:10 – 4:00 PM'
};

let _presState = {
  cursoId: null, periodoId: null, periodFinMin: null,
  clockInterval: null,
  timerTotal: 0, timerRem: 0, timerRunning: false, timerInterval: null
};

function abrirModoPresent() {
  document.getElementById('pres-overlay')?.classList.remove('hidden');
  cargarCalificaciones(); // Asegura que calState.cursos esté poblado antes de detectar
  const detectado = _presDetectarClase();
  if (detectado) {
    _presCargarCurso(detectado.cursoId, detectado.periodoId, detectado.slot);
  } else {
    _presCargarCurso(null, null, null);
    abrirPresPicker();
  }
  _presIniciarReloj();
  registrarCambio('Modo presentación iniciado');
}

function cerrarModoPresent() {
  clearInterval(_presState.clockInterval);
  clearInterval(_presState.timerInterval);
  _presState = { cursoId:null, periodoId:null, periodFinMin:null,
    clockInterval:null, timerTotal:0, timerRem:0, timerRunning:false, timerInterval:null };
  document.getElementById('pres-overlay')?.classList.add('hidden');
  if (document.fullscreenElement) document.exitFullscreen().catch(()=>{});
}

function _presDetectarClase() {
  const horario = cargarHorario();
  if (!horario || !horario.length) return null;
  const now = new Date();
  const diaSem = now.getDay() - 1; // 0=Lun...4=Vie
  if (diaSem < 0 || diaSem > 4) return null;
  const minActual = now.getHours() * 60 + now.getMinutes();

  // Recopilar todos los slots activos ahora (puede haber varios períodos en la misma hora)
  const slotsActivos = horario.filter(e => {
    if (e.dia !== diaSem) return false;
    const ini = _PRES_HORAS[e.periodo];
    // Duraciones reales: P3 y P5 tienen 60 min de pausa antes, períodos duran 50 min
    return ini !== undefined && minActual >= ini && minActual < ini + 50;
  });
  if (!slotsActivos.length) return null;

  const _norm = s => (s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();

  // Para cada slot, buscar el curso que coincida
  for (const slot of slotsActivos) {
    const materiaNorm = _norm(slot.materia);
    const seccionNorm = _norm(slot.seccion);

    const cursoId = Object.keys(calState.cursos || {}).find(id => {
      const c = calState.cursos[id];
      const nombreNorm = _norm(c.nombre);
      const seccionCursoNorm = _norm(c.seccion);
      // Coincidencia por nombre
      if (nombreNorm && materiaNorm && (nombreNorm.includes(materiaNorm) || materiaNorm.includes(nombreNorm))) return true;
      // Coincidencia por sección si hay
      if (seccionNorm && seccionCursoNorm && seccionNorm === seccionCursoNorm) return true;
      return false;
    });
    if (cursoId) return { cursoId, periodoId: slot.periodo, slot };
  }
  return null;
}

function _presGetPlanDeCurso(cursoId) {
  const curso = calState.cursos[cursoId];
  if (!curso || !curso.planActivaId) return null;
  const biblio = cargarBiblioteca();
  const reg = biblio.items.find(i => i.id === curso.planActivaId);
  return reg ? reg.planificacion : null;
}

function _presCargarCurso(cursoId, periodoId, slotForzado) {
  _presState.cursoId = cursoId;
  _presState.periodoId = periodoId;

  // Calcular fin del período
  if (periodoId && _PRES_HORAS[periodoId] !== undefined) {
    _presState.periodFinMin = _PRES_HORAS[periodoId] + 50;
  } else {
    _presState.periodFinMin = null;
  }

  // Si no hay cursoId pero sí hay un slot activo en el horario, mostrar info básica del horario
  if (!cursoId) {
    if (slotForzado) {
      const elNombre = document.getElementById('pres-curso-nombre');
      const elPer    = document.getElementById('pres-periodo-info');
      if (elNombre) elNombre.textContent = slotForzado.materia || 'Clase activa';
      if (elPer) {
        const partes = [];
        if (slotForzado.periodo) partes.push('Período ' + slotForzado.periodo + ' · ' + (_PRES_PERIODOS_LABEL[slotForzado.periodo] || ''));
        if (slotForzado.aula) partes.push('Aula ' + slotForzado.aula);
        if (slotForzado.seccion) partes.push(slotForzado.seccion);
        elPer.textContent = partes.join('  ·  ') || 'Sin curso vinculado — ve a Cursos para asignar esta materia';
      }
      const objWrap = document.getElementById('pres-objetivo-wrap');
      if (objWrap) objWrap.innerHTML = '<div class="pres-section-label">Objetivo de aprendizaje</div>' +
        '<p style="opacity:0.4;font-style:italic;font-size:0.9rem;">Este horario no tiene un curso vinculado. Asigna el curso desde el panel de Calificaciones.</p>';
      const seqWrap = document.getElementById('pres-secuencia-wrap');
      if (seqWrap) seqWrap.innerHTML = '';
      const actWrap = document.getElementById('pres-actividades-wrap');
      if (actWrap) actWrap.innerHTML = '';
      _presRenderizarTimer();
      return;
    }
    _presRenderizarVacio(); return;
  }

  const curso = calState.cursos[cursoId];
  const plan  = _presGetPlanDeCurso(cursoId);

  // Header
  const horario = cargarHorario();
  const slot = slotForzado || (periodoId
    ? horario.find(e => e.dia === (new Date().getDay()-1) && e.periodo === periodoId)
    : null);

  const elNombre = document.getElementById('pres-curso-nombre');
  const elPer    = document.getElementById('pres-periodo-info');
  if (elNombre) elNombre.textContent = curso ? curso.nombre : '—';
  if (elPer) {
    const partes = [];
    if (periodoId) partes.push('Período ' + periodoId + ' · ' + (_PRES_PERIODOS_LABEL[periodoId] || ''));
    if (slot && slot.aula) partes.push('Aula ' + slot.aula);
    if (slot && slot.seccion) partes.push(slot.seccion);
    elPer.textContent = partes.join('  ·  ');
  }

  // Objetivo
  const objWrap = document.getElementById('pres-objetivo-wrap');
  if (objWrap) {
    const ra = plan && plan.ra;
    const desc = (ra && ra.descripcion) ? ra.descripcion : '';
    const modulo = (plan && plan.datosGenerales && plan.datosGenerales.moduloFormativo) ? plan.datosGenerales.moduloFormativo : '';
    objWrap.innerHTML =
      '<div class="pres-section-label">Objetivo de aprendizaje</div>' +
      (modulo ? '<div style="font-size:0.78rem;color:#90CAF9;margin-bottom:6px;font-weight:600;">' + escapeHTML(modulo) + '</div>' : '') +
      '<div id="pres-objetivo-texto">' +
        (desc ? escapeHTML(desc) : '<span style="opacity:0.4;font-style:italic;">Sin objetivo definido en este plan</span>') +
      '</div>';
  }

  // Secuencia didáctica (primer EC)
  const seqWrap = document.getElementById('pres-secuencia-wrap');
  if (seqWrap) {
    const ecs = plan && plan.elementosCapacidad;
    const ec  = ecs && ecs.length ? ecs[0] : null;
    const seq = ec && ec.secuencia;
    if (seq && (seq.apertura || seq.desarrollo || seq.cierre)) {
      const bloques = [
        { label:'Apertura',    texto: seq.apertura   || '', color:'#FFD54F' },
        { label:'Desarrollo',  texto: seq.desarrollo || '', color:'#80CBC4' },
        { label:'Cierre',      texto: seq.cierre     || '', color:'#EF9A9A' }
      ];
      let html = '<div class="pres-section-label" style="margin-top:24px;">Secuencia didáctica</div>';
      if (ec.enunciado) html += '<div style="font-size:0.78rem;color:#90CAF9;margin-bottom:8px;">' + escapeHTML(ec.enunciado) + '</div>';
      bloques.forEach(b => {
        if (!b.texto.trim()) return;
        html += '<div class="pres-seq-blk">' +
          '<div class="pres-seq-label" style="color:' + b.color + ';">' + b.label + '</div>' +
          '<div class="pres-seq-texto">' + escapeHTML(b.texto) + '</div>' +
          '</div>';
      });
      seqWrap.innerHTML = html;
    } else {
      seqWrap.innerHTML = '';
    }
  }

  // Actividades
  const actWrap = document.getElementById('pres-actividades-wrap');
  if (actWrap) {
    const acts = (plan && plan.actividades) || [];
    const hoyStr = new Date().toDateString();
    const actHoy = acts.filter(a => a.fecha && new Date(a.fecha).toDateString() === hoyStr);
    const actMostrar = actHoy.length > 0 ? acts : acts; // muestra todas, destaca las de hoy

    if (acts.length) {
      let html = '<div class="pres-section-label">Actividades del plan</div>';
      acts.forEach(a => {
        const esHoy = a.fecha && new Date(a.fecha).toDateString() === hoyStr;
        const fechaStr = a.fecha ? new Date(a.fecha).toLocaleDateString('es-ES',{day:'2-digit',month:'short'}) : '';
        html += '<div class="pres-act-item' + (esHoy ? ' hoy' : '') + '">' +
          '<div class="pres-act-dot"></div>' +
          '<div>' +
            '<div class="pres-act-texto">' + escapeHTML(a.enunciado || a.titulo || '—') +
              (esHoy ? ' <span class="pres-act-badge-hoy">HOY</span>' : '') +
            '</div>' +
            (fechaStr ? '<div class="pres-act-fecha">' + fechaStr + '</div>' : '') +
          '</div>' +
          '</div>';
      });
      actWrap.innerHTML = html;
    } else {
      actWrap.innerHTML = '<div class="pres-section-label">Actividades del plan</div>' +
        '<p style="font-size:0.85rem;color:rgba(255,255,255,0.3);font-style:italic;">Sin actividades en este plan</p>';
    }
  }

  // Timer box
  _presRenderizarTimer();
}

function _presRenderizarVacio() {
  const elNombre = document.getElementById('pres-curso-nombre');
  const elPer    = document.getElementById('pres-periodo-info');
  if (elNombre) elNombre.textContent = 'Selecciona una clase';
  if (elPer)    elPer.textContent    = 'Sin clase activa detectada';
  const objWrap = document.getElementById('pres-objetivo-wrap');
  if (objWrap) objWrap.innerHTML = '';
  const seqWrap = document.getElementById('pres-secuencia-wrap');
  if (seqWrap) seqWrap.innerHTML = '';
  const actWrap = document.getElementById('pres-actividades-wrap');
  if (actWrap) actWrap.innerHTML = '';
  _presRenderizarTimer();
}

function _presRenderizarTimer() {
  const box = document.getElementById('pres-timer-box');
  if (!box) return;
  const rem = _presState.timerRem;
  const mm = String(Math.floor(rem / 60)).padStart(2, '0');
  const ss = String(rem % 60).padStart(2, '0');
  const finClass = rem === 0 && _presState.timerTotal > 0 ? ' fin' : '';
  box.innerHTML =
    '<div class="pres-section-label">Temporizador</div>' +
    '<div id="pres-timer-display" class="' + finClass + '">' + mm + ':' + ss + '</div>' +
    '<div class="pres-timer-row">' +
      '<button class="pres-t-btn" id="pres-btn-play" onclick="_presTimerToggle()">' +
        '<span class="material-icons" style="font-size:18px;vertical-align:middle;">' +
          (_presState.timerRunning ? 'pause' : 'play_arrow') + '</span>' +
      '</button>' +
      '<button class="pres-t-btn" onclick="_presTimerReset()">' +
        '<span class="material-icons" style="font-size:18px;vertical-align:middle;">replay</span>' +
      '</button>' +
    '</div>' +
    '<div class="pres-timer-row" style="margin-top:8px;">' +
      [5,10,15,20].map(m =>
        '<button class="pres-t-btn" onclick="_presTimerAgregar(' + m + ')">+' + m + 'm</button>'
      ).join('') +
    '</div>' +
    '<div id="pres-fin-count" style="font-size:0.78rem;color:#80DEEA;margin-top:10px;min-height:18px;"></div>';
  _presActualizarFinPeriodo();
}

function _presActualizarTimerDisplay() {
  const el = document.getElementById('pres-timer-display');
  if (!el) return;
  const rem = _presState.timerRem;
  const mm = String(Math.floor(rem / 60)).padStart(2, '0');
  const ss = String(rem % 60).padStart(2, '0');
  el.textContent = mm + ':' + ss;
  el.className = (rem === 0 && _presState.timerTotal > 0) ? 'fin' : '';
  // Actualizar icono play/pause
  const btnPlay = document.getElementById('pres-btn-play');
  if (btnPlay) {
    const ico = btnPlay.querySelector('.material-icons');
    if (ico) ico.textContent = _presState.timerRunning ? 'pause' : 'play_arrow';
  }
}

function _presTimerToggle() {
  if (_presState.timerRunning) _presTimerParar();
  else _presTimerIniciar();
}

function _presTimerIniciar() {
  if (_presState.timerRem <= 0) return;
  _presState.timerRunning = true;
  _presState.timerInterval = setInterval(_presTimerTick, 1000);
  _presActualizarTimerDisplay();
}

function _presTimerParar() {
  _presState.timerRunning = false;
  clearInterval(_presState.timerInterval);
  _presState.timerInterval = null;
  _presActualizarTimerDisplay();
}

function _presTimerReset() {
  _presTimerParar();
  _presState.timerRem   = _presState.timerTotal;
  _presState.timerRunning = false;
  _presActualizarTimerDisplay();
}

function _presTimerAgregar(min) {
  _presState.timerTotal += min * 60;
  _presState.timerRem   += min * 60;
  _presActualizarTimerDisplay();
}

function _presTimerTick() {
  if (_presState.timerRem > 0) {
    _presState.timerRem--;
    _presActualizarTimerDisplay();
  } else {
    _presTimerParar();
    // parpadeo visual (ya lo hace la clase .fin en CSS)
    _presActualizarTimerDisplay();
  }
}

function _presIniciarReloj() {
  clearInterval(_presState.clockInterval);
  const tick = () => {
    const el = document.getElementById('pres-clock');
    if (el) {
      const now = new Date();
      el.textContent = now.toLocaleTimeString('es-ES', { hour:'2-digit', minute:'2-digit', second:'2-digit' });
    }
    _presActualizarFinPeriodo();
  };
  tick();
  _presState.clockInterval = setInterval(tick, 1000);
}

function _presActualizarFinPeriodo() {
  const el = document.getElementById('pres-fin-count');
  if (!el) return;
  if (_presState.periodFinMin === null) { el.textContent = ''; return; }
  const now = new Date();
  const minActual = now.getHours() * 60 + now.getMinutes() + now.getSeconds() / 60;
  const diff = _presState.periodFinMin - minActual;
  if (diff <= 0) {
    el.textContent = 'Período finalizado';
    return;
  }
  const mm = Math.floor(diff);
  const ss = Math.round((diff - mm) * 60);
  el.textContent = 'Fin del período en ' + String(mm).padStart(2,'0') + ':' + String(ss).padStart(2,'0');
}

function _presFullscreen() {
  const el = document.documentElement;
  if (!document.fullscreenElement) {
    el.requestFullscreen().catch(() => {});
  } else {
    document.exitFullscreen().catch(() => {});
  }
}

function abrirPresPicker() {
  const body = document.getElementById('pres-picker-body');
  if (!body) return;
  const cursos = Object.values(calState.cursos || {});
  if (!cursos.length) {
    body.innerHTML = '<p style="text-align:center;color:#757575;padding:24px 0;">No hay cursos creados aún.</p>';
  } else {
    // Detectar clase activa para resaltarla
    const detectado = _presDetectarClase();
    let html = '';
    cursos.forEach(c => {
      const esActual = detectado && detectado.cursoId === c.id;
      html += '<button onclick="_presElegirCurso(\'' + c.id + '\')" style="' +
        'width:100%;text-align:left;padding:12px 14px;margin-bottom:8px;border-radius:10px;' +
        'border:2px solid ' + (esActual ? '#1565C0' : 'var(--color-borde,#E0E0E0)') + ';' +
        'background:' + (esActual ? '#EEF2FF' : 'transparent') + ';cursor:pointer;' +
        'font-size:0.95rem;font-weight:600;color:var(--color-texto-primario,#212121);">' +
        escapeHTML(c.nombre || 'Curso sin nombre') +
        (esActual ? ' <span style="font-size:0.72rem;background:#1565C0;color:#fff;' +
          'border-radius:4px;padding:1px 6px;margin-left:8px;">Ahora</span>' : '') +
        '</button>';
    });
    body.innerHTML = html;
  }
  document.getElementById('pres-picker-overlay')?.classList.remove('hidden');
}

function cerrarPresPicker() {
  document.getElementById('pres-picker-overlay')?.classList.add('hidden');
}

function _presElegirCurso(cursoId) {
  cerrarPresPicker();
  // Intentar detectar el período actual para ese curso
  const detectado = _presDetectarClase();
  const periodoId = (detectado && detectado.cursoId === cursoId) ? detectado.periodoId : null;
  _presCargarCurso(cursoId, periodoId);
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO: CALENDARIO ESCOLAR
// ════════════════════════════════════════════════════════════════════

const CAL_ESC_KEY = 'planificadorRA_calendario_escolar_v1';
const CAL_ESC_MESES = [
  'agosto','septiembre','octubre','noviembre','diciembre',
  'enero','febrero','marzo','abril','mayo','junio'
];
const CAL_ESC_MESES_LABEL = {
  agosto:'Agosto', septiembre:'Septiembre', octubre:'Octubre',
  noviembre:'Noviembre', diciembre:'Diciembre', enero:'Enero',
  febrero:'Febrero', marzo:'Marzo', abril:'Abril', mayo:'Mayo', junio:'Junio'
};

let _calEsc = {
  modo: 'admin',        // 'admin' | 'personal'
  adminDatos: null,     // datos del calendario del admin (Firestore)
  personalDatos: null,  // datos del usuario (localStorage)
  mesActivo: 'agosto',
  cargando: false,
};

function _calEscEsAdmin() {
  return !!(window.currentUser && typeof ADMIN_EMAIL !== 'undefined' && window.currentUser.email === ADMIN_EMAIL);
}

function _calEscDatosActuales() {
  return (_calEsc.modo === 'personal' && _calEsc.personalDatos)
    ? _calEsc.personalDatos
    : (_calEsc.adminDatos || _calEscDatosVacios());
}

function _calEscDatosVacios() {
  const d = {};
  CAL_ESC_MESES.forEach(m => { d[m] = { actividades: [], efemerides: [] }; });
  return { meses: d, festivos: [] };
}

// ── Cargar calendario del admin desde Firestore ──────────────────────
async function _calEscCargarAdmin() {
  if (typeof db === 'undefined') return;
  try {
    const doc = await db.collection('public_calendar').doc('main').get();
    _calEsc.adminDatos = (doc.exists && doc.data()?.meses) ? doc.data() : _calEscDatosVacios();
  } catch (e) {
    _calEsc.adminDatos = _calEscDatosVacios();
  }
}

// ── Guardar calendario del admin en Firestore ────────────────────────
async function _calEscGuardarAdmin() {
  if (!_calEscEsAdmin() || typeof db === 'undefined') return;
  try {
    await db.collection('public_calendar').doc('main').set(_calEsc.adminDatos || _calEscDatosVacios());
    mostrarToast('Calendario publicado para todos los docentes ✓', 'success');
  } catch (e) {
    console.error('[Calendario] Error Firestore:', e.code, e.message);
    if (e.code === 'permission-denied') {
      mostrarToast('Sin permisos en Firestore. Verifica las reglas de public_calendar en Firebase Console.', 'error');
    } else {
      mostrarToast('Error al guardar en Firestore: ' + (e.message || e.code), 'error');
    }
  }
}

// ── Cargar / guardar calendario personal del usuario ─────────────────
function _calEscCargarPersonal() {
  try {
    const raw = localStorage.getItem(CAL_ESC_KEY);
    _calEsc.personalDatos = raw ? JSON.parse(raw) : null;
  } catch (e) { _calEsc.personalDatos = null; }
}

function _calEscGuardarPersonal() {
  const datos = _calEsc.personalDatos || _calEscDatosVacios();
  localStorage.setItem(CAL_ESC_KEY, JSON.stringify(datos));
  if (window._syncFirebase) _syncFirebase('calendario_escolar', datos);
}

// ── Abrir panel ──────────────────────────────────────────────────────
async function abrirCalendarioEscolar() {
  _mostrarPanel('panel-calendario-escolar');
  _calEsc.cargando = true;
  const c = document.getElementById('cal-escolar-contenido');
  if (c) c.innerHTML = `<div style="text-align:center;padding:40px;color:#9E9E9E;">
    <span class="material-icons" style="font-size:36px;display:block;margin-bottom:8px;">hourglass_empty</span>
    Cargando calendario...</div>`;

  await _calEscCargarAdmin();
  _calEscCargarPersonal();

  if (_calEscEsAdmin()) {
    _calEsc.modo = 'admin';
  } else {
    _calEsc.modo = _calEsc.personalDatos ? 'personal' : 'admin';
  }

  _calEsc.cargando = false;
  _calEscRenderizar();
}

// ── Render principal ─────────────────────────────────────────────────
function _calEscRenderizar() {
  _calEscRenderizarBanner();
  _calEscRenderizarFestivos();
  _calEscRenderizarTabs();
  _calEscRenderizarMes();
  const badge = document.getElementById('cal-escolar-admin-badge');
  if (badge) badge.style.display = _calEscEsAdmin() ? 'inline' : 'none';
}

function _calEscRenderizarBanner() {
  const banner = document.getElementById('cal-escolar-banner');
  const txt    = document.getElementById('cal-escolar-banner-txt');
  const icon   = document.getElementById('cal-escolar-banner-icon');
  const btns   = document.getElementById('cal-escolar-banner-btns');
  if (!banner || !txt || !btns) return;

  if (_calEscEsAdmin()) {
    banner.style.cssText += ';background:#E8F5E9;color:#1B5E20;border-color:#A5D6A7;';
    icon.textContent = 'admin_panel_settings';
    txt.textContent  = 'Eres el administrador. Los cambios que hagas aquí se publican para todos los docentes.';
    btns.innerHTML   = `<button onclick="_calEscGuardarAdmin()"
      style="background:#2E7D32;color:#fff;border:none;border-radius:20px;padding:6px 14px;
             font-size:0.78rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;">
      <span class="material-icons" style="font-size:14px;">cloud_upload</span> Publicar cambios
    </button>`;
  } else if (_calEsc.modo === 'admin') {
    banner.style.cssText += ';background:#E3F2FD;color:#0D47A1;border-color:#90CAF9;';
    icon.textContent = 'info';
    txt.textContent  = 'Estás viendo el calendario oficial del centro. Puedes usarlo o crear el tuyo propio.';
    btns.innerHTML   = `<button onclick="_calEscUsarMiCalendario()"
      style="background:#1565C0;color:#fff;border:none;border-radius:20px;padding:6px 14px;
             font-size:0.78rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;">
      <span class="material-icons" style="font-size:14px;">edit_calendar</span> Usar mi propio calendario
    </button>`;
  } else {
    banner.style.cssText += ';background:#FFF8E1;color:#E65100;border-color:#FFD54F;';
    icon.textContent = 'edit_calendar';
    txt.textContent  = 'Estás usando tu propio calendario. Los cambios solo te afectan a ti.';
    btns.innerHTML   = `<button onclick="_calEscRestaurarAdmin()"
      style="background:#E65100;color:#fff;border:none;border-radius:20px;padding:6px 14px;
             font-size:0.78rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:5px;">
      <span class="material-icons" style="font-size:14px;">restore</span> Restaurar calendario oficial
    </button>`;
  }
}

function _calEscRenderizarTabs() {
  const tabs = document.getElementById('cal-escolar-tabs');
  if (!tabs) return;
  tabs.innerHTML = CAL_ESC_MESES.map(m => `
    <button onclick="_calEscSeleccionarMes('${m}')"
      style="padding:7px 14px;border-radius:20px;cursor:pointer;transition:all .15s;
             border:1.5px solid ${_calEsc.mesActivo===m?'#1565C0':'#E0E0E0'};
             background:${_calEsc.mesActivo===m?'#1565C0':'#fff'};
             color:${_calEsc.mesActivo===m?'#fff':'#546E7A'};
             font-size:0.8rem;font-weight:${_calEsc.mesActivo===m?'700':'500'};">
      ${CAL_ESC_MESES_LABEL[m]}
    </button>`).join('');
}

function _calEscSeleccionarMes(mes) {
  _calEsc.mesActivo = mes;
  _calEscRenderizarTabs();
  _calEscRenderizarMes();
}

// ── Render del mes activo ────────────────────────────────────────────
function _calEscRenderizarMes() {
  const c = document.getElementById('cal-escolar-contenido');
  if (!c) return;
  const datos   = _calEscDatosActuales();
  const mes     = _calEsc.mesActivo;
  const mesDatos = datos.meses?.[mes] || { actividades: [], efemerides: [] };
  const editable = _calEscEsAdmin() || _calEsc.modo === 'personal';

  c.innerHTML = `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:4px;">
      <div style="background:#F9FAFB;border-radius:12px;padding:16px;border:1.5px solid #E0E0E0;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
          <h3 style="margin:0;font-size:0.95rem;font-weight:700;color:#212121;display:flex;align-items:center;gap:6px;">
            <span class="material-icons" style="font-size:18px;color:#1565C0;">task_alt</span>Actividades
          </h3>
          ${editable ? `<button onclick="_calEscAgregarActividad('${mes}')"
            style="background:#1565C0;color:#fff;border:none;border-radius:20px;padding:5px 12px;
                   font-size:0.75rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:4px;">
            <span class="material-icons" style="font-size:14px;">add</span> Agregar
          </button>` : ''}
        </div>
        ${_calEscRenderListaActividades(mes, mesDatos.actividades, editable)}
      </div>

      <div style="background:#F9FAFB;border-radius:12px;padding:16px;border:1.5px solid #E0E0E0;">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px;">
          <h3 style="margin:0;font-size:0.95rem;font-weight:700;color:#212121;display:flex;align-items:center;gap:6px;">
            <span class="material-icons" style="font-size:18px;color:#6A1B9A;">auto_stories</span>Efemérides
          </h3>
          ${editable ? `<button onclick="_calEscAgregarEfemeride('${mes}')"
            style="background:#6A1B9A;color:#fff;border:none;border-radius:20px;padding:5px 12px;
                   font-size:0.75rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:4px;">
            <span class="material-icons" style="font-size:14px;">add</span> Agregar
          </button>` : ''}
        </div>
        ${_calEscRenderListaEfemerides(mes, mesDatos.efemerides, editable)}
      </div>
    </div>`;
}

function _calEscRenderListaActividades(mes, lista, editable) {
  if (!lista || !lista.length) return `<p style="color:#9E9E9E;font-size:0.82rem;text-align:center;padding:16px 0;">Sin actividades registradas.</p>`;
  return lista.map((a, i) => `
    <div style="display:flex;align-items:flex-start;gap:8px;padding:8px 0;border-bottom:1px solid #EEEEEE;">
      <span class="material-icons" style="font-size:15px;color:#1565C0;margin-top:2px;flex-shrink:0;">check_circle</span>
      <span style="flex:1;font-size:0.85rem;color:#37474F;word-break:break-word;">${escapeHTML(a.texto)}</span>
      ${editable ? `
        <button onclick="_calEscEditarActividad('${mes}',${i})" title="Editar"
          style="background:none;border:none;cursor:pointer;color:#78909C;padding:2px;flex-shrink:0;">
          <span class="material-icons" style="font-size:15px;">edit</span>
        </button>
        <button onclick="_calEscEliminarActividad('${mes}',${i})" title="Eliminar"
          style="background:none;border:none;cursor:pointer;color:#E53935;padding:2px;flex-shrink:0;">
          <span class="material-icons" style="font-size:15px;">delete</span>
        </button>` : ''}
    </div>`).join('');
}

function _calEscRenderListaEfemerides(mes, lista, editable) {
  if (!lista || !lista.length) return `<p style="color:#9E9E9E;font-size:0.82rem;text-align:center;padding:16px 0;">Sin efemérides registradas.</p>`;
  return [...lista].sort((a, b) => (a.dia||0)-(b.dia||0)).map((ef, i) => `
    <div style="display:flex;align-items:flex-start;gap:8px;padding:8px 0;border-bottom:1px solid #EEEEEE;">
      <div style="min-width:32px;height:32px;background:#6A1B9A;color:#fff;border-radius:8px;flex-shrink:0;
                  display:flex;align-items:center;justify-content:center;font-size:0.78rem;font-weight:800;">
        ${ef.dia || '—'}
      </div>
      <div style="flex:1;min-width:0;">
        <div style="font-size:0.85rem;font-weight:700;color:#212121;">${escapeHTML(ef.titulo)}</div>
        ${ef.descripcion ? `<div style="font-size:0.78rem;color:#78909C;margin-top:2px;">${escapeHTML(ef.descripcion)}</div>` : ''}
      </div>
      ${editable ? `
        <button onclick="_calEscEditarEfemeride('${mes}',${i})" title="Editar"
          style="background:none;border:none;cursor:pointer;color:#78909C;padding:2px;flex-shrink:0;">
          <span class="material-icons" style="font-size:15px;">edit</span>
        </button>
        <button onclick="_calEscEliminarEfemeride('${mes}',${i})" title="Eliminar"
          style="background:none;border:none;cursor:pointer;color:#E53935;padding:2px;flex-shrink:0;">
          <span class="material-icons" style="font-size:15px;">delete</span>
        </button>` : ''}
    </div>`).join('');
}

// ── Helpers de acceso a datos según modo ────────────────────────────
function _calEscGetDatosEditables() {
  if (_calEscEsAdmin()) return _calEsc.adminDatos || _calEscDatosVacios();
  return _calEsc.personalDatos || _calEscDatosVacios();
}

function _calEscSetDatosEditables(datos) {
  if (_calEscEsAdmin()) {
    _calEsc.adminDatos = datos;
  } else {
    _calEsc.personalDatos = datos;
    _calEscGuardarPersonal();
  }
}

function _calEscAsegurarMes(datos, mes) {
  if (!datos.meses) datos.meses = {};
  if (!datos.meses[mes]) datos.meses[mes] = { actividades: [], efemerides: [] };
  if (!datos.meses[mes].actividades) datos.meses[mes].actividades = [];
  if (!datos.meses[mes].efemerides) datos.meses[mes].efemerides = [];
  return datos;
}

// ── CRUD Actividades ─────────────────────────────────────────────────
function _calEscAgregarActividad(mes) {
  const texto = prompt(`Nueva actividad para ${CAL_ESC_MESES_LABEL[mes]}:`);
  if (!texto || !texto.trim()) return;
  const datos = _calEscGetDatosEditables();
  _calEscAsegurarMes(datos, mes);
  datos.meses[mes].actividades.push({ id: uid(), texto: texto.trim() });
  _calEscSetDatosEditables(datos);
  _calEscRenderizarMes();
}

function _calEscEditarActividad(mes, idx) {
  const datos = _calEscGetDatosEditables();
  _calEscAsegurarMes(datos, mes);
  const act = datos.meses[mes].actividades[idx];
  if (!act) return;
  const nuevo = prompt('Editar actividad:', act.texto);
  if (!nuevo || !nuevo.trim()) return;
  act.texto = nuevo.trim();
  _calEscSetDatosEditables(datos);
  _calEscRenderizarMes();
}

function _calEscEliminarActividad(mes, idx) {
  if (!confirm('¿Eliminar esta actividad?')) return;
  const datos = _calEscGetDatosEditables();
  _calEscAsegurarMes(datos, mes);
  datos.meses[mes].actividades.splice(idx, 1);
  _calEscSetDatosEditables(datos);
  _calEscRenderizarMes();
}

// ── CRUD Efemérides ──────────────────────────────────────────────────
function _calEscAgregarEfemeride(mes) { _calEscModalEfemeride(mes, null, null); }

function _calEscEditarEfemeride(mes, idx) {
  const datos = _calEscGetDatosEditables();
  _calEscAsegurarMes(datos, mes);
  const ef = datos.meses[mes].efemerides[idx];
  if (ef) _calEscModalEfemeride(mes, idx, ef);
}

function _calEscEliminarEfemeride(mes, idx) {
  if (!confirm('¿Eliminar esta efeméride?')) return;
  const datos = _calEscGetDatosEditables();
  _calEscAsegurarMes(datos, mes);
  datos.meses[mes].efemerides.splice(idx, 1);
  _calEscSetDatosEditables(datos);
  _calEscRenderizarMes();
}

function _calEscModalEfemeride(mes, idx, ef) {
  document.getElementById('cal-esc-modal-ef')?.remove();
  const overlay = document.createElement('div');
  overlay.id = 'cal-esc-modal-ef';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:3000;background:rgba(0,0,0,0.42);display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.innerHTML = `
    <div style="background:#fff;border-radius:16px;padding:24px;max-width:420px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,0.18);" onclick="event.stopPropagation()">
      <h3 style="margin:0 0 16px;font-size:1rem;font-weight:700;color:#212121;">
        ${idx === null ? 'Nueva efeméride' : 'Editar efeméride'} — ${CAL_ESC_MESES_LABEL[mes]}
      </h3>
      <label style="font-size:0.82rem;color:#546E7A;font-weight:600;">Día del mes</label>
      <input type="number" id="cef-dia" min="1" max="31" value="${ef?.dia || ''}"
        style="width:100%;padding:8px 12px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.9rem;margin:4px 0 12px;box-sizing:border-box;" />
      <label style="font-size:0.82rem;color:#546E7A;font-weight:600;">Título</label>
      <input type="text" id="cef-titulo" value="${ef ? escapeHTML(ef.titulo) : ''}" placeholder="Ej: Día de la Restauración"
        style="width:100%;padding:8px 12px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.9rem;margin:4px 0 12px;box-sizing:border-box;" />
      <label style="font-size:0.82rem;color:#546E7A;font-weight:600;">Descripción (opcional)</label>
      <textarea id="cef-desc" rows="2" placeholder="Breve descripción..."
        style="width:100%;padding:8px 12px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.88rem;margin:4px 0 16px;resize:vertical;box-sizing:border-box;">${ef ? escapeHTML(ef.descripcion || '') : ''}</textarea>
      <div style="display:flex;gap:8px;justify-content:flex-end;">
        <button onclick="document.getElementById('cal-esc-modal-ef').remove()"
          style="background:none;border:1.5px solid #E0E0E0;color:#616161;border-radius:20px;padding:7px 16px;font-size:0.82rem;cursor:pointer;">Cancelar</button>
        <button onclick="_calEscGuardarEfemeride('${mes}',${JSON.stringify(idx)})"
          style="background:#6A1B9A;color:#fff;border:none;border-radius:20px;padding:7px 18px;font-size:0.82rem;font-weight:700;cursor:pointer;">Guardar</button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  setTimeout(() => document.getElementById('cef-titulo')?.focus(), 50);
}

function _calEscGuardarEfemeride(mes, idx) {
  const dia    = parseInt(document.getElementById('cef-dia')?.value) || 0;
  const titulo = document.getElementById('cef-titulo')?.value.trim();
  const desc   = document.getElementById('cef-desc')?.value.trim();
  if (!titulo) { mostrarToast('El título es obligatorio', 'error'); return; }
  const datos = _calEscGetDatosEditables();
  _calEscAsegurarMes(datos, mes);
  const obj = { id: uid(), dia, titulo, descripcion: desc || '' };
  if (idx === null) {
    datos.meses[mes].efemerides.push(obj);
  } else {
    obj.id = datos.meses[mes].efemerides[idx]?.id || obj.id;
    datos.meses[mes].efemerides[idx] = obj;
  }
  _calEscSetDatosEditables(datos);
  document.getElementById('cal-esc-modal-ef')?.remove();
  _calEscRenderizarMes();
}

// ── DÍAS FESTIVOS / NO LECTIVOS ──────────────────────────────────────

function _calEscGetFestivosAdmin() {
  // Siempre retorna los festivos del calendario ADMIN (son globales para todos)
  return (_calEsc.adminDatos?.festivos || []).map(f => f.fecha);
}

function _calEscRenderizarFestivos() {
  const c = document.getElementById('cal-esc-festivos');
  if (!c) return;
  const esAdmin = _calEscEsAdmin();
  // Siempre mostrar los festivos del admin (son los oficiales)
  const festivos = (_calEsc.adminDatos?.festivos || []).slice().sort((a, b) => a.fecha.localeCompare(b.fecha));

  c.innerHTML = `
    <div style="background:#FFF8E1;border:1.5px solid #FFD54F;border-radius:12px;padding:14px 16px;">
      <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:${festivos.length || esAdmin ? '12px' : '0'};">
        <h3 style="margin:0;font-size:0.93rem;font-weight:700;color:#E65100;display:flex;align-items:center;gap:6px;">
          <span class="material-icons" style="font-size:18px;color:#FF6F00;">event_busy</span>
          Días Festivos / No Lectivos
          <span style="background:#FF6F00;color:#fff;font-size:0.68rem;font-weight:800;padding:1px 7px;border-radius:10px;margin-left:4px;">${festivos.length}</span>
        </h3>
        ${esAdmin ? `<button onclick="_calEscModalFestivo()"
          style="background:#E65100;color:#fff;border:none;border-radius:20px;padding:5px 12px;
                 font-size:0.75rem;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:4px;">
          <span class="material-icons" style="font-size:14px;">add</span> Agregar
        </button>` : ''}
      </div>
      ${festivos.length === 0
        ? `<p style="color:#9E9E9E;font-size:0.82rem;margin:0;${esAdmin ? '' : 'text-align:center;padding:4px 0;'}">
             ${esAdmin ? 'Sin días festivos registrados. Agrégalos para que se excluyan automáticamente de la planificación.' : 'No hay días festivos registrados.'}
           </p>`
        : `<div style="display:flex;flex-wrap:wrap;gap:6px;">
             ${festivos.map((f, i) => {
               const fecha = new Date(f.fecha + 'T00:00:00');
               const label = fecha.toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' });
               return `<div style="display:flex;align-items:center;gap:5px;background:#fff;border:1.5px solid #FFCC02;
                             border-radius:20px;padding:4px 10px;font-size:0.78rem;color:#212121;">
                 <span class="material-icons" style="font-size:13px;color:#E65100;">block</span>
                 <span style="font-weight:700;color:#E65100;">${label}</span>
                 ${f.motivo ? `<span style="color:#78909C;">— ${escapeHTML(f.motivo)}</span>` : ''}
                 ${esAdmin ? `<button onclick="_calEscEliminarFestivo(${i})" title="Eliminar"
                   style="background:none;border:none;cursor:pointer;color:#B71C1C;padding:0 2px;line-height:1;margin-left:2px;">
                   <span class="material-icons" style="font-size:14px;">close</span>
                 </button>` : ''}
               </div>`;
             }).join('')}
           </div>`
      }
    </div>`;
}

function _calEscModalFestivo() {
  document.getElementById('cal-esc-modal-fest')?.remove();
  const hoy = new Date().toISOString().slice(0, 10);
  const overlay = document.createElement('div');
  overlay.id = 'cal-esc-modal-fest';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:3000;background:rgba(0,0,0,0.42);display:flex;align-items:center;justify-content:center;padding:16px;';
  overlay.innerHTML = `
    <div style="background:#fff;border-radius:16px;padding:24px;max-width:420px;width:100%;box-shadow:0 8px 32px rgba(0,0,0,0.18);" onclick="event.stopPropagation()">
      <h3 style="margin:0 0 6px;font-size:1rem;font-weight:700;color:#E65100;display:flex;align-items:center;gap:6px;">
        <span class="material-icons" style="font-size:18px;">event_busy</span> Agregar días festivos / no lectivos
      </h3>
      <p style="margin:0 0 16px;font-size:0.78rem;color:#78909C;">Puedes seleccionar un rango de fechas y se agregarán todos los días de una vez.</p>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:12px;">
        <div>
          <label style="font-size:0.82rem;color:#546E7A;font-weight:600;display:block;margin-bottom:4px;">Desde</label>
          <input type="date" id="cfest-desde" value="${hoy}"
            style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.88rem;box-sizing:border-box;"
            oninput="_calEscPreviewFestivos()" />
        </div>
        <div>
          <label style="font-size:0.82rem;color:#546E7A;font-weight:600;display:block;margin-bottom:4px;">Hasta</label>
          <input type="date" id="cfest-hasta" value="${hoy}"
            style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.88rem;box-sizing:border-box;"
            oninput="_calEscPreviewFestivos()" />
        </div>
      </div>

      <div id="cfest-preview" style="min-height:32px;margin-bottom:12px;font-size:0.78rem;color:#546E7A;"></div>

      <label style="font-size:0.82rem;color:#546E7A;font-weight:600;display:block;margin-bottom:4px;">Motivo / descripción (opcional)</label>
      <input type="text" id="cfest-motivo" placeholder="Ej: Semana Santa, Vacaciones de Pascua…"
        style="width:100%;padding:8px 12px;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.9rem;margin-bottom:16px;box-sizing:border-box;" />

      <div style="display:flex;gap:8px;justify-content:flex-end;">
        <button onclick="document.getElementById('cal-esc-modal-fest').remove()"
          style="background:none;border:1.5px solid #E0E0E0;color:#616161;border-radius:20px;padding:7px 16px;font-size:0.82rem;cursor:pointer;">Cancelar</button>
        <button onclick="_calEscGuardarFestivo()"
          style="background:#E65100;color:#fff;border:none;border-radius:20px;padding:7px 18px;font-size:0.82rem;font-weight:700;cursor:pointer;">
          <span class="material-icons" style="font-size:14px;vertical-align:middle;">save</span> Guardar
        </button>
      </div>
    </div>`;
  document.body.appendChild(overlay);
  setTimeout(() => { _calEscPreviewFestivos(); document.getElementById('cfest-desde')?.focus(); }, 50);
}

function _calEscPreviewFestivos() {
  const desde  = document.getElementById('cfest-desde')?.value;
  const hasta  = document.getElementById('cfest-hasta')?.value;
  const prev   = document.getElementById('cfest-preview');
  if (!prev) return;
  if (!desde || !hasta || hasta < desde) {
    prev.innerHTML = '<span style="color:#E53935;">La fecha "Hasta" debe ser igual o posterior a "Desde".</span>';
    return;
  }
  const dias = _calEscRangoDias(desde, hasta);
  if (dias.length === 0) { prev.innerHTML = ''; return; }
  const ya = (_calEsc.adminDatos?.festivos || []).map(f => f.fecha);
  const nuevos  = dias.filter(d => !ya.includes(d));
  const repetidos = dias.length - nuevos.length;
  const etiquetas = nuevos.slice(0, 6).map(d => {
    const f = new Date(d + 'T00:00:00');
    return f.toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short' });
  });
  const mas = nuevos.length > 6 ? ` y ${nuevos.length - 6} más` : '';
  prev.innerHTML = `
    <div style="background:#FFF3E0;border-radius:8px;padding:8px 10px;border:1px solid #FFCC80;">
      <strong style="color:#E65100;">${nuevos.length} día${nuevos.length !== 1 ? 's' : ''}</strong> a agregar:
      <span style="color:#546E7A;">${etiquetas.join(', ')}${mas}</span>
      ${repetidos ? `<br><span style="color:#9E9E9E;font-size:0.74rem;">(${repetidos} ya registrado${repetidos !== 1 ? 's' : ''}, se omitirán)</span>` : ''}
    </div>`;
}

function _calEscRangoDias(desde, hasta) {
  const dias = [];
  const cursor = new Date(desde + 'T00:00:00');
  const fin    = new Date(hasta + 'T00:00:00');
  while (cursor <= fin) {
    dias.push(cursor.toISOString().slice(0, 10));
    cursor.setDate(cursor.getDate() + 1);
  }
  return dias;
}

function _calEscGuardarFestivo() {
  const desde  = document.getElementById('cfest-desde')?.value;
  const hasta  = document.getElementById('cfest-hasta')?.value;
  const motivo = document.getElementById('cfest-motivo')?.value.trim();
  if (!desde || !hasta) { mostrarToast('Selecciona las fechas', 'error'); return; }
  if (hasta < desde) { mostrarToast('La fecha "Hasta" debe ser igual o posterior a "Desde"', 'error'); return; }
  const datos = _calEsc.adminDatos || _calEscDatosVacios();
  if (!datos.festivos) datos.festivos = [];
  const ya = datos.festivos.map(f => f.fecha);
  const dias = _calEscRangoDias(desde, hasta).filter(d => !ya.includes(d));
  if (!dias.length) { mostrarToast('Todas esas fechas ya están registradas', 'error'); return; }
  dias.forEach(fecha => datos.festivos.push({ id: uid(), fecha, motivo: motivo || '' }));
  _calEsc.adminDatos = datos;
  document.getElementById('cal-esc-modal-fest')?.remove();
  _calEscRenderizarFestivos();
  mostrarToast(`${dias.length} día${dias.length !== 1 ? 's' : ''} festivo${dias.length !== 1 ? 's' : ''} agregado${dias.length !== 1 ? 's' : ''}. Recuerda publicar los cambios.`, 'success');
}

function _calEscEliminarFestivo(idx) {
  if (!confirm('¿Eliminar este día festivo?')) return;
  const datos = _calEsc.adminDatos || _calEscDatosVacios();
  if (!datos.festivos) return;
  datos.festivos.splice(idx, 1);
  _calEsc.adminDatos = datos;
  _calEscRenderizarFestivos();
  mostrarToast('Día festivo eliminado. Recuerda publicar los cambios.', 'info');
}

// ── Cambiar entre calendario admin y personal ────────────────────────
function _calEscUsarMiCalendario() {
  if (!confirm('¿Quieres usar tu propio calendario?\nSe copiará el calendario oficial como punto de partida.')) return;
  _calEsc.personalDatos = JSON.parse(JSON.stringify(_calEsc.adminDatos || _calEscDatosVacios()));
  _calEscGuardarPersonal();
  _calEsc.modo = 'personal';
  _calEscRenderizar();
  mostrarToast('Ahora estás usando tu propio calendario', 'success');
}

function _calEscRestaurarAdmin() {
  if (!confirm('¿Restaurar el calendario oficial?\nSe perderán tus cambios personales.')) return;
  _calEsc.personalDatos = null;
  localStorage.removeItem(CAL_ESC_KEY);
  if (window._syncFirebase) _syncFirebase('calendario_escolar', '');
  _calEsc.modo = 'admin';
  _calEscRenderizar();
  mostrarToast('Calendario oficial restaurado', 'success');
}

