// MÓDULO: PANEL DE PSICOLOGÍA
// ════════════════════════════════════════════════════════════════════

let _psicoDatos = []; // {docenteUid, docenteNombre, estNombre, estId, curso, reportes[]}

async function abrirPsicologia() {
  if (!window.currentUser) return;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    const rol = doc.exists ? (doc.data().rol || '') : '';
    const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
    const permitido = ['psicologia', 'psicologa', 'psicologo', 'director', 'superadmin'].includes(rol) || esSA;
    if (!permitido) { mostrarToast('No tienes acceso a este panel.', 'error'); return; }
  } catch { mostrarToast('Error verificando acceso.', 'error'); return; }
  _mostrarPanel('panel-psicologia');
  cargarReportesPsicologia();
}

async function cargarReportesPsicologia() {
  const cont = document.getElementById('psico-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:40px;color:#9E9E9E;"><span class="material-icons" style="font-size:36px;display:block;margin-bottom:10px;">hourglass_empty</span>Cargando reportes…</div>';

  try {
    // collectionGroup consulta datos_padre en TODOS los usuarios sin necesitar listar public_blogs
    const snap = await db.collectionGroup('datos_padre').get();

    const resultados = [];
    const docenteNombres = {};

    for (const doc of snap.docs) {
      const d = doc.data();
      const reportes = (d.reportes || []).filter(r => r.detallesEvento && r.detallesEvento.trim());
      if (reportes.length === 0) continue;

      // Extraer uid del path: public_blogs/{uid}/datos_padre/{estId}
      const segmentos = doc.ref.path.split('/');
      const uid = segmentos[1];

      // Obtener nombre del docente (con caché)
      if (!docenteNombres[uid]) {
        try {
          const perfil = await db.collection('perfiles').doc(uid).get();
          if (perfil.exists && perfil.data().nombre) docenteNombres[uid] = perfil.data().nombre;
          else {
            const usuario = await db.collection('usuarios').doc(uid).get();
            docenteNombres[uid] = (usuario.exists && usuario.data().nombre) ? usuario.data().nombre : uid;
          }
        } catch(e) { docenteNombres[uid] = uid; }
      }

      resultados.push({
        docenteUid: uid,
        docenteNombre: docenteNombres[uid],
        estId: doc.id,
        estNombre: d.nombre || doc.id,
        curso: d.curso || '',
        reportes: reportes.sort((a, b) => b.ts - a.ts)
      });
    }

    _psicoDatos = resultados;

    // Poblar filtros
    const docentes = [...new Set(resultados.map(r => r.docenteNombre))].sort();
    const cursos   = [...new Set(resultados.map(r => r.curso).filter(Boolean))].sort();

    const selDoc = document.getElementById('psico-filtro-docente');
    if (selDoc) {
      const prevDoc = selDoc.value;
      selDoc.innerHTML = '<option value="">Todos los docentes</option>' +
        docentes.map(d => `<option value="${escapeHTML(d)}" ${d === prevDoc ? 'selected' : ''}>${escapeHTML(d)}</option>`).join('');
    }
    const selCurso = document.getElementById('psico-filtro-curso');
    if (selCurso) {
      const prevCurso = selCurso.value;
      selCurso.innerHTML = '<option value="">Todos los cursos</option>' +
        cursos.map(c => `<option value="${escapeHTML(c)}" ${c === prevCurso ? 'selected' : ''}>${escapeHTML(c)}</option>`).join('');
    }

    renderPsicologia();

  } catch(e) {
    if (cont) cont.innerHTML = '<div style="text-align:center;padding:30px;color:#C62828;">Error al cargar: ' + escapeHTML(e.message) + '</div>';
  }
}

function renderPsicologia() {
  const cont = document.getElementById('psico-contenido');
  if (!cont) return;

  const filtroDoc    = document.getElementById('psico-filtro-docente')?.value || '';
  const filtroCurso  = document.getElementById('psico-filtro-curso')?.value   || '';
  const buscar       = (document.getElementById('psico-buscar')?.value || '').toLowerCase().trim();

  let datos = _psicoDatos;
  if (filtroDoc)   datos = datos.filter(d => d.docenteNombre === filtroDoc);
  if (filtroCurso) datos = datos.filter(d => d.curso === filtroCurso);
  if (buscar)      datos = datos.filter(d => d.estNombre.toLowerCase().includes(buscar));

  if (datos.length === 0) {
    cont.innerHTML = '<div style="text-align:center;padding:40px;color:#9E9E9E;">' +
      '<span class="material-icons" style="font-size:48px;display:block;margin-bottom:10px;">inbox</span>' +
      '<p>No se encontraron reportes con los filtros aplicados.</p></div>';
    return;
  }

  const totalRep = datos.reduce((s, d) => s + d.reportes.length, 0);
  let html = `<div style="font-size:0.78rem;color:#9E9E9E;margin-bottom:14px;">${datos.length} estudiante${datos.length !== 1 ? 's' : ''} · ${totalRep} reporte${totalRep !== 1 ? 's' : ''}</div>`;

  datos.forEach(d => {
    html += `
      <div style="background:#fff;border:1px solid #E0E0E0;border-radius:12px;margin-bottom:14px;overflow:hidden;box-shadow:0 1px 4px rgba(0,0,0,0.06);">
        <div style="background:linear-gradient(90deg,#F3E5F5,#EDE7F6);padding:10px 14px;display:flex;align-items:center;gap:10px;flex-wrap:wrap;">
          <span class="material-icons" style="color:#6A1B9A;font-size:20px;">person</span>
          <strong style="color:#4A148C;font-size:0.95rem;">${escapeHTML(d.estNombre)}</strong>
          ${d.curso ? `<span style="background:#CE93D8;color:#fff;border-radius:10px;padding:1px 9px;font-size:0.72rem;font-weight:700;">${escapeHTML(d.curso)}</span>` : ''}
          <span style="margin-left:auto;font-size:0.75rem;color:#7B1FA2;">Docente: ${escapeHTML(d.docenteNombre)}</span>
          <span style="background:#B39DDB;color:#fff;border-radius:10px;padding:1px 9px;font-size:0.72rem;font-weight:700;">${d.reportes.length} reporte${d.reportes.length !== 1 ? 's' : ''}</span>
        </div>
        <div style="padding:12px 14px;display:flex;flex-direction:column;gap:10px;">`;

    d.reportes.forEach(r => {
      const fecha = r.fechaReporte
        ? new Date(r.fechaReporte + 'T12:00:00').toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })
        : (r.ts ? new Date(r.ts).toLocaleDateString('es-DO', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' }) : '—');

      const campos = [
        { label: 'Descripción del evento',            valor: r.detallesEvento },
        { label: 'Medidas del docente',               valor: r.medidasDocente },
        { label: 'Seguimiento Coordinación/Psicología', valor: r.seguimientoRepetitiva },
      ].filter(c => c.valor && c.valor.trim());

      html += `
        <div style="border-left:3px solid #7B1FA2;padding:8px 12px;background:#FAFAFA;border-radius:0 8px 8px 0;">
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;flex-wrap:wrap;">
            <span style="background:#EDE7F6;color:#4A148C;font-size:0.72rem;font-weight:700;padding:2px 8px;border-radius:10px;display:inline-flex;align-items:center;gap:3px;">
              <span class="material-icons" style="font-size:11px;">description</span> Reporte formal
            </span>
            <span style="font-size:0.78rem;font-weight:600;color:#37474F;">${escapeHTML(fecha)}</span>
          </div>
          ${campos.map(c => `
            <div style="margin-bottom:4px;">
              <div style="font-size:0.68rem;font-weight:700;color:#7B1FA2;text-transform:uppercase;letter-spacing:0.05em;">${escapeHTML(c.label)}</div>
              <div style="font-size:0.85rem;color:#37474F;line-height:1.4;">${escapeHTML(c.valor)}</div>
            </div>`).join('')}
        </div>`;
    });

    html += '</div></div>';
  });

  cont.innerHTML = html;
}

// Sincronizar reporte nuevo a Firestore para que Psicología lo vea en tiempo real
async function _syncReportePsicologia(estId, reportes) {
  if (typeof db === 'undefined' || !firebase.auth().currentUser) return;
  const uid = firebase.auth().currentUser.uid;
  try {
    await db.collection('public_blogs').doc(uid).collection('datos_padre').doc(estId)
      .set({ reportes }, { merge: true });
  } catch(e) { console.warn('sync psicologia:', e); }
}

let _repCompTab = 'reportes';

function abrirReportesComportamiento() {
  _mostrarPanel('panel-reportes-comp');
  _repCompTab = 'reportes';
  switchTabReportes('reportes');
}

function switchTabReportes(tab) {
  _repCompTab = tab;
  const tabs = { reportes: 'tab-rep-reportes', cuentas: 'tab-rep-cuentas', enlace: 'tab-rep-enlace' };
  Object.entries(tabs).forEach(([k, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (k === tab) {
      el.style.background = '#1565C0'; el.style.color = '#fff'; el.style.borderColor = '#1565C0';
    } else {
      el.style.background = '#F5F5F5'; el.style.color = '#616161'; el.style.borderColor = '#E0E0E0';
    }
  });
  if (tab === 'reportes') _renderReportesRecibidos();
  else if (tab === 'cuentas') _renderCuentasEstudiantes();
  else if (tab === 'enlace') _renderEnlaceReportes();
}

// ── Tab: Reportes recibidos ─────────────────────────────────────
async function _renderReportesRecibidos() {
  const cont = document.getElementById('rep-comp-contenido');
  if (!cont) return;

  const user = window.currentUser;
  if (!user) { cont.innerHTML = '<p style="color:#9E9E9E;text-align:center;padding:20px;">Inicia sesión primero.</p>'; return; }

  cont.innerHTML = '<div style="text-align:center;padding:30px;color:#9E9E9E;"><span class="material-icons" style="font-size:32px;display:block;margin-bottom:8px;">hourglass_empty</span>Cargando reportes...</div>';

  try {
    const snap = await db.collection('public_blogs').doc(user.uid)
      .collection('reportes_comportamiento').get();

    const reportes = snap.docs.map(d => d.data()).sort((a, b) => new Date(b.creadoEn) - new Date(a.creadoEn));

    if (reportes.length === 0) {
      cont.innerHTML = '<div style="text-align:center;padding:40px;color:#9E9E9E;">' +
        '<span class="material-icons" style="font-size:48px;display:block;margin-bottom:10px;">inbox</span>' +
        '<p>No se han recibido reportes de comportamiento.</p>' +
        '<p style="font-size:0.78rem;margin-top:6px;">Comparte el enlace con tus estudiantes desde la pestaña "Enlace".</p></div>';
      return;
    }

    // Filtro por curso
    const cursosSet = [...new Set(reportes.map(r => r.cursoNombre || r.cursoId))];
    let filtroHTML = '';
    if (cursosSet.length > 1) {
      filtroHTML = '<div style="margin-bottom:14px;display:flex;gap:6px;flex-wrap:wrap;">' +
        '<button onclick="_filtrarRepComp(\'\')" class="rep-filtro-btn rep-filtro-activo" style="padding:4px 12px;border-radius:16px;border:1px solid #90CAF9;background:#E3F2FD;color:#1565C0;font-size:0.75rem;font-weight:600;cursor:pointer;">Todos</button>' +
        cursosSet.map(c =>
          '<button onclick="_filtrarRepComp(\'' + escapeHTML(c) + '\')" class="rep-filtro-btn" style="padding:4px 12px;border-radius:16px;border:1px solid #E0E0E0;background:#fff;color:#616161;font-size:0.75rem;font-weight:600;cursor:pointer;">' + escapeHTML(c) + '</button>'
        ).join('') + '</div>';
    }

    cont.innerHTML = filtroHTML + '<div id="rep-comp-lista">' + _buildReportesHTML(reportes) + '</div>';
    window._repCompTodos = reportes;

  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:30px;color:#C62828;">Error al cargar reportes: ' + escapeHTML(e.message) + '</div>';
  }
}

function _filtrarRepComp(curso) {
  const reportes = window._repCompTodos || [];
  const filtered = curso ? reportes.filter(r => (r.cursoNombre || r.cursoId) === curso) : reportes;
  const lista = document.getElementById('rep-comp-lista');
  if (lista) lista.innerHTML = _buildReportesHTML(filtered);

  // Actualizar estilos de filtros
  document.querySelectorAll('.rep-filtro-btn').forEach(b => {
    const esFiltro = curso ? b.textContent.trim() === curso : b.textContent.trim() === 'Todos';
    b.style.background = esFiltro ? '#E3F2FD' : '#fff';
    b.style.borderColor = esFiltro ? '#90CAF9' : '#E0E0E0';
    b.style.color = esFiltro ? '#1565C0' : '#616161';
  });
}

function _buildReportesHTML(reportes) {
  if (!reportes.length) return '<div style="text-align:center;padding:20px;color:#9E9E9E;">Sin reportes para este filtro.</div>';

  const tipoLabel = { positivo: 'Positivo', negativo: 'Negativo', neutral: 'Observación' };
  const tipoCls   = { positivo: '#E8F5E9;color:#2E7D32', negativo: '#FFEBEE;color:#C62828', neutral: '#FFF3E0;color:#E65100' };
  const tipoIcon  = { positivo: 'thumb_up', negativo: 'thumb_down', neutral: 'info' };

  return reportes.map(r => {
    const fechaStr = r.fecha
      ? new Date(r.fecha + 'T12:00:00').toLocaleDateString('es-ES', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })
      : '—';
    const tStyle = tipoCls[r.tipo] || tipoCls.neutral;
    const tIcon  = tipoIcon[r.tipo] || 'info';
    const tLabel = tipoLabel[r.tipo] || 'Observación';

    return '<div style="background:var(--color-fondo-card,#fff);border:1px solid var(--color-borde,#E0E0E0);border-radius:10px;padding:16px;margin-bottom:10px;">' +
      '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:8px;">' +
        '<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 10px;border-radius:20px;font-size:0.72rem;font-weight:700;background:' + tStyle + ';">' +
          '<span class="material-icons" style="font-size:12px;">' + tIcon + '</span> ' + tLabel +
        '</span>' +
        '<span style="font-size:0.75rem;color:#9E9E9E;display:flex;align-items:center;gap:3px;">' +
          '<span class="material-icons" style="font-size:13px;">schedule</span> ' + escapeHTML(fechaStr) +
        '</span>' +
        '<span style="font-size:0.75rem;color:#78909C;margin-left:auto;">' + escapeHTML(r.cursoNombre || '') + '</span>' +
      '</div>' +
      '<div style="font-size:0.78rem;color:#616161;display:flex;align-items:center;gap:4px;margin-bottom:6px;">' +
        '<span class="material-icons" style="font-size:14px;">people</span> <strong>Involucrados:</strong> ' + escapeHTML(r.involucrados || '') +
      '</div>' +
      '<div style="font-size:0.86rem;color:var(--color-texto,#424242);line-height:1.6;white-space:pre-wrap;word-break:break-word;">' + escapeHTML(r.descripcion || '') + '</div>' +
      '<div style="font-size:0.72rem;color:#BDBDBD;margin-top:8px;display:flex;align-items:center;gap:4px;">' +
        '<span class="material-icons" style="font-size:12px;">person</span> Reportado por: ' + escapeHTML(r.reportadoPor || r.usuario || '') +
      '</div>' +
      '<div style="margin-top:8px;text-align:right;">' +
        '<button onclick="_eliminarReporteComp(\'' + escapeHTML(r.id) + '\')" style="background:none;border:1px solid #FFCDD2;color:#C62828;border-radius:6px;padding:4px 10px;font-size:0.72rem;cursor:pointer;display:inline-flex;align-items:center;gap:3px;font-family:inherit;">' +
          '<span class="material-icons" style="font-size:14px;">delete</span> Eliminar</button>' +
      '</div>' +
    '</div>';
  }).join('');
}

async function _eliminarReporteComp(id) {
  if (!confirm('¿Eliminar este reporte? No se puede deshacer.')) return;
  const user = window.currentUser;
  if (!user) return;
  try {
    await db.collection('public_blogs').doc(user.uid)
      .collection('reportes_comportamiento').doc(id).delete();
    mostrarToast('Reporte eliminado', 'success');
    _renderReportesRecibidos();
  } catch (e) {
    mostrarToast('Error al eliminar: ' + e.message, 'error');
  }
}

// ── Tab: Cuentas de estudiantes ─────────────────────────────────
function _renderCuentasEstudiantes() {
  const cont = document.getElementById('rep-comp-contenido');
  if (!cont) return;

  const data = _cargarCuentasEst();
  const cuentas = data.cuentas || [];

  // Obtener cursos disponibles
  const cursos = Object.values(calState?.cursos || {});

  let html = '<div style="background:#E3F2FD;border:1.5px solid #90CAF9;border-radius:10px;padding:12px 16px;margin-bottom:16px;font-size:0.82rem;color:#0D47A1;display:flex;align-items:center;gap:8px;">' +
    '<span class="material-icons" style="font-size:18px;">info</span>' +
    'Crea cuentas para que los estudiantes puedan iniciar sesión en la página de reportes y enviar reportes de comportamiento.' +
    '</div>';

  // Formulario nueva cuenta
  html += '<div style="background:var(--color-fondo-card,#fff);border:1.5px solid #E3F2FD;border-radius:10px;padding:16px;margin-bottom:16px;">' +
    '<div style="font-size:0.85rem;font-weight:700;color:#1565C0;margin-bottom:12px;display:flex;align-items:center;gap:6px;">' +
      '<span class="material-icons" style="font-size:18px;">person_add</span> Nueva cuenta' +
    '</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Nombre del estudiante *</label>' +
        '<input id="ce-nombre" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;" placeholder="Ej: Juan Pérez"></div>' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Curso asignado *</label>' +
        '<select id="ce-curso" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;">' +
          (cursos.length === 0 ? '<option value="">— Sin cursos —</option>' :
           cursos.map(c => '<option value="' + escapeHTML(c.id) + '" data-nombre="' + escapeHTML(c.nombre) + '">' + escapeHTML(c.nombre) + '</option>').join('')) +
        '</select></div>' +
    '</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:10px;">' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Usuario *</label>' +
        '<input id="ce-usuario" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;" placeholder="Ej: juan.perez"></div>' +
      '<div><label style="font-size:0.75rem;font-weight:600;color:#546E7A;display:block;margin-bottom:3px;">Contraseña *</label>' +
        '<input id="ce-pass" type="text" style="width:100%;padding:8px 10px;border:1.5px solid #E0E0E0;border-radius:6px;font-size:0.85rem;font-family:inherit;" placeholder="Ej: 1234"></div>' +
    '</div>' +
    '<div id="ce-error" style="color:#C62828;font-size:0.8rem;min-height:18px;margin-top:6px;"></div>' +
    '<button onclick="_crearCuentaEstudiante()" style="margin-top:8px;background:#1565C0;color:#fff;border:none;border-radius:8px;padding:9px 18px;font-size:0.85rem;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;gap:6px;font-family:inherit;">' +
      '<span class="material-icons" style="font-size:16px;">add</span> Crear cuenta</button>' +
  '</div>';

  // Lista de cuentas existentes
  if (cuentas.length > 0) {
    html += '<div style="font-size:0.75rem;font-weight:800;text-transform:uppercase;letter-spacing:0.08em;color:#546E7A;margin-bottom:10px;">Cuentas creadas (' + cuentas.length + ')</div>';
    cuentas.forEach((c, i) => {
      const activo = c.activo !== false;
      html += '<div style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:8px;border:1px solid var(--color-borde,#E0E0E0);margin-bottom:8px;background:var(--color-fondo-card,#FAFAFA);' + (!activo ? 'opacity:0.5;' : '') + '">' +
        '<span class="material-icons" style="font-size:22px;color:' + (activo ? '#1565C0' : '#BDBDBD') + ';">account_circle</span>' +
        '<div style="flex:1;min-width:0;">' +
          '<div style="font-size:0.88rem;font-weight:600;color:var(--color-texto,#212121);">' + escapeHTML(c.nombre) + '</div>' +
          '<div style="font-size:0.75rem;color:#757575;">Usuario: <strong>' + escapeHTML(c.usuario) + '</strong> · Contraseña: <strong>' + escapeHTML(c.password) + '</strong></div>' +
          '<div style="font-size:0.72rem;color:#9E9E9E;">' + escapeHTML(c.cursoNombre || c.cursoId) + '</div>' +
        '</div>' +
        '<button onclick="_toggleCuentaEst(' + i + ')" title="' + (activo ? 'Desactivar' : 'Activar') + '" style="background:none;border:1px solid ' + (activo ? '#FFCDD2' : '#C8E6C9') + ';color:' + (activo ? '#C62828' : '#2E7D32') + ';border-radius:6px;padding:4px 8px;font-size:0.72rem;cursor:pointer;display:inline-flex;align-items:center;gap:3px;font-family:inherit;">' +
          '<span class="material-icons" style="font-size:14px;">' + (activo ? 'block' : 'check_circle') + '</span>' + (activo ? 'Desactivar' : 'Activar') +
        '</button>' +
        '<button onclick="_eliminarCuentaEst(' + i + ')" title="Eliminar" style="background:none;border:1px solid #FFCDD2;color:#C62828;border-radius:6px;padding:4px 8px;font-size:0.72rem;cursor:pointer;display:inline-flex;align-items:center;gap:3px;font-family:inherit;">' +
          '<span class="material-icons" style="font-size:14px;">delete</span>' +
        '</button>' +
      '</div>';
    });
  } else {
    html += '<div style="text-align:center;padding:20px;color:#9E9E9E;font-size:0.85rem;">' +
      '<span class="material-icons" style="font-size:32px;display:block;margin-bottom:8px;">person_off</span>' +
      'No hay cuentas de estudiantes creadas.</div>';
  }

  cont.innerHTML = html;
}

function _crearCuentaEstudiante() {
  const nombre  = (document.getElementById('ce-nombre')?.value || '').trim();
  const usuario = (document.getElementById('ce-usuario')?.value || '').trim().toLowerCase();
  const pass    = (document.getElementById('ce-pass')?.value || '').trim();
  const cursoSel = document.getElementById('ce-curso');
  const cursoId = cursoSel?.value || '';
  const cursoNombre = cursoSel?.selectedOptions[0]?.dataset?.nombre || cursoId;
  const errEl   = document.getElementById('ce-error');

  if (!nombre || !usuario || !pass || !cursoId) {
    if (errEl) errEl.textContent = 'Completa todos los campos.';
    return;
  }
  if (usuario.length < 3) {
    if (errEl) errEl.textContent = 'El usuario debe tener al menos 3 caracteres.';
    return;
  }

  const data = _cargarCuentasEst();
  // Verificar unicidad de usuario
  if (data.cuentas.some(c => c.usuario.toLowerCase() === usuario)) {
    if (errEl) errEl.textContent = 'Ya existe una cuenta con ese usuario.';
    return;
  }

  data.cuentas.push({
    id: uid(),
    nombre,
    usuario,
    password: pass,
    cursoId,
    cursoNombre,
    activo: true,
    creadoEn: new Date().toISOString()
  });
  _guardarCuentasEst(data);
  registrarCambio('Cuenta de estudiante creada: ' + nombre);
  mostrarToast('Cuenta creada para ' + nombre, 'success');
  _renderCuentasEstudiantes();
}

function _toggleCuentaEst(index) {
  const data = _cargarCuentasEst();
  if (!data.cuentas[index]) return;
  data.cuentas[index].activo = !data.cuentas[index].activo;
  _guardarCuentasEst(data);
  mostrarToast(data.cuentas[index].activo ? 'Cuenta activada' : 'Cuenta desactivada', 'success');
  _renderCuentasEstudiantes();
}

function _eliminarCuentaEst(index) {
  const data = _cargarCuentasEst();
  if (!data.cuentas[index]) return;
  if (!confirm('¿Eliminar la cuenta de ' + data.cuentas[index].nombre + '?')) return;
  const nombre = data.cuentas[index].nombre;
  data.cuentas.splice(index, 1);
  _guardarCuentasEst(data);
  registrarCambio('Cuenta de estudiante eliminada: ' + nombre);
  mostrarToast('Cuenta eliminada', 'success');
  _renderCuentasEstudiantes();
}

// ── Tab: Enlace ─────────────────────────────────────────────────
function _renderEnlaceReportes() {
  const cont = document.getElementById('rep-comp-contenido');
  if (!cont) return;
  const user = window.currentUser;
  if (!user) { cont.innerHTML = '<p style="color:#9E9E9E;text-align:center;padding:20px;">Inicia sesión primero.</p>'; return; }

  const baseUrl = window.location.origin + window.location.pathname.replace(/[^/]*$/, '') + 'reporte.html';
  const url = baseUrl + '?uid=' + encodeURIComponent(user.uid);

  cont.innerHTML =
    '<div style="text-align:center;padding:20px;">' +
      '<div style="font-size:0.85rem;color:#546E7A;margin-bottom:16px;">Comparte este enlace con tus estudiantes para que puedan acceder a la página de reportes de comportamiento.</div>' +
      '<div style="display:flex;gap:8px;max-width:500px;margin:0 auto;">' +
        '<input id="rep-comp-url" readonly value="' + escapeHTML(url) + '" style="flex:1;padding:10px 12px;background:#F5F5F5;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.82rem;color:#424242;font-family:monospace;">' +
        '<button onclick="_copiarEnlaceReportes()" style="background:#1565C0;color:#fff;border:none;border-radius:8px;padding:10px 16px;font-size:0.82rem;font-weight:600;cursor:pointer;display:flex;align-items:center;gap:4px;font-family:inherit;white-space:nowrap;">' +
          '<span class="material-icons" style="font-size:16px;">content_copy</span> Copiar' +
        '</button>' +
      '</div>' +
      '<div style="margin-top:20px;background:#FFF3E0;border:1.5px solid #FFE0B2;border-radius:10px;padding:14px 18px;text-align:left;font-size:0.82rem;color:#E65100;">' +
        '<div style="font-weight:700;margin-bottom:6px;display:flex;align-items:center;gap:6px;">' +
          '<span class="material-icons" style="font-size:16px;">warning</span> Importante</div>' +
        '<ul style="margin:0;padding-left:20px;line-height:1.8;">' +
          '<li>Primero crea las cuentas de los estudiantes en la pestaña "Cuentas de estudiantes".</li>' +
          '<li>El estudiante necesita el enlace + su usuario y contraseña para acceder.</li>' +
          '<li>Los reportes enviados aparecerán en la pestaña "Reportes recibidos".</li>' +
        '</ul>' +
      '</div>' +
    '</div>';
}

function _copiarEnlaceReportes() {
  const input = document.getElementById('rep-comp-url');
  if (!input) return;
  navigator.clipboard.writeText(input.value).then(() => {
    mostrarToast('Enlace copiado al portapapeles', 'success');
  }).catch(() => {
    input.select();
    document.execCommand('copy');
    mostrarToast('Enlace copiado', 'success');
  });
}

// ════════════════════════════════════════════════════════════════════
//  MÓDULO: BUZÓN DE DENUNCIAS (anónimas, sin login)
// ════════════════════════════════════════════════════════════════════

function abrirDenuncias() {
  _mostrarPanel('panel-denuncias');
  switchTabDenuncias('recibidas');
}

function switchTabDenuncias(tab) {
  const tabs = { recibidas: 'tab-den-recibidas', enlace: 'tab-den-enlace' };
  Object.entries(tabs).forEach(([key, id]) => {
    const btn = document.getElementById(id);
    if (!btn) return;
    if (key === tab) {
      btn.style.background = '#6A1B9A'; btn.style.color = '#fff'; btn.style.borderColor = '#6A1B9A';
    } else {
      btn.style.background = '#F5F5F5'; btn.style.color = '#616161'; btn.style.borderColor = '#E0E0E0';
    }
  });

  if (tab === 'recibidas') _renderDenunciasRecibidas();
  else if (tab === 'enlace') _renderEnlaceDenuncias();
}

async function _renderDenunciasRecibidas() {
  const cont = document.getElementById('den-contenido');
  if (!cont) return;
  const user = window.currentUser;
  if (!user) { cont.innerHTML = '<p style="color:#9E9E9E;text-align:center;padding:20px;">Inicia sesión primero.</p>'; return; }

  cont.innerHTML = '<div style="text-align:center;padding:30px;color:#9E9E9E;"><span class="material-icons" style="font-size:32px;display:block;margin-bottom:8px;animation:spin 1s linear infinite;">hourglass_empty</span>Cargando denuncias...</div>';

  try {
    const snap = await db.collection('public_blogs').doc(user.uid)
      .collection('denuncias').get();

    let denuncias = snap.docs.map(d => d.data());
    denuncias.sort((a, b) => new Date(b.creadoEn) - new Date(a.creadoEn));

    if (denuncias.length === 0) {
      cont.innerHTML = '<div style="text-align:center;padding:40px;color:#9E9E9E;">' +
        '<span class="material-icons" style="font-size:40px;display:block;margin-bottom:8px;opacity:0.4;">campaign</span>' +
        'No hay denuncias recibidas.</div>';
      return;
    }

    // Filtro por curso
    const cursos = [...new Set(denuncias.map(d => d.curso))].sort();
    let html = '<div style="display:flex;gap:6px;margin-bottom:14px;flex-wrap:wrap;">' +
      '<button onclick="_filtrarDenuncias(\'\')" class="ra-tab" style="padding:4px 12px;border-radius:16px;border:1px solid #CE93D8;background:#EDE7F6;color:#6A1B9A;font-size:0.75rem;font-weight:600;cursor:pointer;">Todos (' + denuncias.length + ')</button>';
    cursos.forEach(c => {
      const n = denuncias.filter(d => d.curso === c).length;
      html += '<button onclick="_filtrarDenuncias(\'' + escapeHTML(c) + '\')" class="ra-tab" style="padding:4px 12px;border-radius:16px;border:1px solid #E0E0E0;background:#F5F5F5;color:#616161;font-size:0.75rem;font-weight:600;cursor:pointer;">' + escapeHTML(c) + ' (' + n + ')</button>';
    });
    html += '</div>';
    html += '<div id="den-lista-items">' + _buildDenunciasHTML(denuncias) + '</div>';

    cont.innerHTML = html;
    window._denunciasCache = denuncias;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error al cargar: ' + escapeHTML(e.message) + '</div>';
  }
}

function _filtrarDenuncias(curso) {
  const items = document.getElementById('den-lista-items');
  if (!items || !window._denunciasCache) return;
  const filtered = curso ? window._denunciasCache.filter(d => d.curso === curso) : window._denunciasCache;
  items.innerHTML = _buildDenunciasHTML(filtered);
}

function _buildDenunciasHTML(denuncias) {
  if (!denuncias.length) return '<div style="text-align:center;padding:20px;color:#9E9E9E;">Sin denuncias en este filtro.</div>';

  const tipoLabels = {
    acoso: 'Acoso / Bullying', pelea: 'Pelea / Agresión', robo: 'Robo / Hurto',
    discriminacion: 'Discriminación', sustancias: 'Sustancias prohibidas',
    vandalismo: 'Vandalismo', amenaza: 'Amenaza', otro: 'Otro'
  };
  const tipoColors = {
    acoso: '#C62828', pelea: '#D84315', robo: '#E65100', discriminacion: '#AD1457',
    sustancias: '#6A1B9A', vandalismo: '#4527A0', amenaza: '#B71C1C', otro: '#546E7A'
  };

  return denuncias.map(d => {
    const color = tipoColors[d.tipo] || '#546E7A';
    const fechaStr = d.fecha
      ? new Date(d.fecha + 'T12:00:00').toLocaleDateString('es', { weekday: 'short', day: '2-digit', month: 'short', year: 'numeric' })
      : '—';
    const esAnonimo = !d.nombre || d.nombre === 'Anónimo';
    return '<div style="background:#fff;border-radius:12px;box-shadow:0 1px 4px rgba(0,0,0,0.07);padding:16px;margin-bottom:12px;border-left:4px solid ' + color + ';">' +
      '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">' +
        '<div style="display:flex;align-items:center;gap:6px;">' +
          '<span style="background:' + color + '18;color:' + color + ';padding:3px 10px;border-radius:20px;font-size:0.72rem;font-weight:700;">' +
            (tipoLabels[d.tipo] || d.tipo) + '</span>' +
          '<span style="font-size:0.72rem;color:#9E9E9E;display:flex;align-items:center;gap:3px;">' +
            '<span class="material-icons" style="font-size:13px;">schedule</span>' + escapeHTML(fechaStr) + '</span>' +
        '</div>' +
        '<button onclick="_eliminarDenuncia(\'' + d.id + '\')" title="Eliminar" style="background:none;border:none;color:#EF5350;cursor:pointer;padding:4px;">' +
          '<span class="material-icons" style="font-size:18px;">delete_outline</span></button>' +
      '</div>' +
      '<div style="font-size:0.78rem;color:#78909C;margin-bottom:4px;display:flex;align-items:center;gap:4px;">' +
        '<span class="material-icons" style="font-size:14px;">school</span> ' + escapeHTML(d.curso) +
        ' &nbsp;·&nbsp; <span class="material-icons" style="font-size:14px;">person</span> ' +
        (esAnonimo ? '<em style="color:#BDBDBD;">Anónimo</em>' : escapeHTML(d.nombre)) +
      '</div>' +
      '<div style="font-size:0.78rem;color:#616161;margin-bottom:6px;display:flex;align-items:center;gap:4px;">' +
        '<span class="material-icons" style="font-size:14px;">people</span> <strong>Involucrados:</strong> ' + escapeHTML(d.involucrados) +
      '</div>' +
      '<div style="font-size:0.85rem;color:#424242;line-height:1.6;white-space:pre-wrap;word-break:break-word;">' + escapeHTML(d.descripcion) + '</div>' +
    '</div>';
  }).join('');
}

async function _eliminarDenuncia(id) {
  if (!confirm('¿Eliminar esta denuncia?')) return;
  const user = window.currentUser;
  if (!user) return;
  try {
    await db.collection('public_blogs').doc(user.uid)
      .collection('denuncias').doc(id).delete();
    mostrarToast('Denuncia eliminada', 'success');
    _renderDenunciasRecibidas();
  } catch (e) {
    mostrarToast('Error: ' + e.message, 'error');
  }
}

function _renderEnlaceDenuncias() {
  const cont = document.getElementById('den-contenido');
  if (!cont) return;
  const user = window.currentUser;
  if (!user) { cont.innerHTML = '<p style="color:#9E9E9E;text-align:center;padding:20px;">Inicia sesión primero.</p>'; return; }

  const baseUrl = window.location.origin + window.location.pathname.replace(/[^/]*$/, '') + 'denuncia.html';
  const url = baseUrl + '?uid=' + encodeURIComponent(user.uid);

  cont.innerHTML =
    '<div style="text-align:center;padding:20px;">' +
      '<div style="font-size:0.85rem;color:#546E7A;margin-bottom:16px;">Comparte este enlace con tus estudiantes para que puedan enviar denuncias de forma anónima.</div>' +
      '<div style="display:flex;gap:8px;max-width:500px;margin:0 auto;">' +
        '<input id="den-comp-url" readonly value="' + escapeHTML(url) + '" style="flex:1;padding:10px 12px;background:#F5F5F5;border:1.5px solid #E0E0E0;border-radius:8px;font-size:0.82rem;color:#424242;font-family:monospace;">' +
        '<button onclick="_copiarEnlaceDenuncias()" style="background:#6A1B9A;color:#fff;border:none;border-radius:8px;padding:10px 16px;font-size:0.82rem;font-weight:600;cursor:pointer;display:flex;align-items:center;gap:4px;font-family:inherit;white-space:nowrap;">' +
          '<span class="material-icons" style="font-size:16px;">content_copy</span> Copiar' +
        '</button>' +
      '</div>' +
      '<div style="margin-top:20px;background:#EDE7F6;border:1.5px solid #CE93D8;border-radius:10px;padding:14px 18px;text-align:left;font-size:0.82rem;color:#6A1B9A;">' +
        '<div style="font-weight:700;margin-bottom:6px;display:flex;align-items:center;gap:6px;">' +
          '<span class="material-icons" style="font-size:16px;">info</span> Información</div>' +
        '<ul style="margin:0;padding-left:18px;line-height:1.8;">' +
          '<li>Los estudiantes <strong>no necesitan cuenta</strong> para enviar denuncias.</li>' +
          '<li>Pueden incluir su nombre o enviar de forma <strong>anónima</strong>.</li>' +
          '<li>Solo tú puedes ver las denuncias recibidas.</li>' +
        '</ul>' +
      '</div>' +
    '</div>';
}

function _copiarColumnaNotas(actId, btn) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !curso.estudiantes?.length) return;
  const raKey = _getRaKey();
  const valores = curso.estudiantes.map(est => {
    const n = curso.notas?.[est.id]?.[raKey]?.[actId];
    return (n !== undefined && n !== null) ? String(n) : '';
  });
  const texto = valores.join('\n');
  const copiar = txt => {
    if (navigator.clipboard?.writeText) {
      navigator.clipboard.writeText(txt).catch(() => _copiarFallback(txt));
    } else { _copiarFallback(txt); }
  };
  const _copiarFallback = txt => {
    const ta = document.createElement('textarea');
    ta.value = txt; ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;';
    document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta);
  };
  copiar(texto);
  if (btn) {
    const orig = btn.innerHTML;
    btn.innerHTML = '<span class="material-icons" style="font-size:13px;color:#69F0AE;">check</span>';
    setTimeout(() => { btn.innerHTML = orig; }, 1200);
  }
  mostrarToast('Notas copiadas (' + curso.estudiantes.length + ' filas)', 'success');
}

function _copiarColumnaTotal(btn) {
  const curso = calState.cursos[calState.cursoActivoId];
  if (!curso || !curso.estudiantes?.length) return;
  const raKey = _getRaKey();
  const planActiva = _getPlanActivaDeCurso();
  const actsVisibles = planActiva?.actividades?.length ? planActiva.actividades : null;
  const valores = curso.estudiantes.map(est => {
    const n = _calcNotaRA(curso, est.id, raKey, actsVisibles);
    return n !== null ? String(n) : '';
  });
  const texto = valores.join('\n');
  if (navigator.clipboard?.writeText) {
    navigator.clipboard.writeText(texto).catch(() => { const ta = document.createElement('textarea'); ta.value = texto; ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); });
  } else { const ta = document.createElement('textarea'); ta.value = texto; ta.style.cssText = 'position:fixed;top:-9999px;left:-9999px;opacity:0;'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); }
  if (btn) { const orig = btn.innerHTML; btn.innerHTML = '<span class="material-icons" style="font-size:13px;color:#69F0AE;">check</span>'; setTimeout(() => { btn.innerHTML = orig; }, 1200); }
  mostrarToast('Total RA copiado (' + curso.estudiantes.length + ' filas)', 'success');
}

function _copiarEnlaceDenuncias() {
  const input = document.getElementById('den-comp-url');
  if (!input) return;
  const texto = input.value;
  const doFeedback = () => mostrarToast('Enlace copiado al portapapeles', 'success');
  const fallback = () => {
    const ta = document.createElement('textarea');
    ta.value = texto;
    ta.style.position = 'fixed'; ta.style.top = '-9999px'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.focus(); ta.select();
    try { document.execCommand('copy'); doFeedback(); }
    catch { mostrarToast('No se pudo copiar. Selecciona el texto manualmente.', 'error'); }
    document.body.removeChild(ta);
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(texto).then(doFeedback).catch(fallback);
  } else {
    fallback();
  }
}

// ════════════════════════════════════════════════════════════════════
// ── MÓDULO: ADMIN CENTRO — GESTIÓN DE DOCENTES ───────────────────
// ════════════════════════════════════════════════════════════════════

/** Verifica si el usuario actual es admin de algún centro */
async function _esAdminDeCentro() {
  const email = window.currentUser?.email?.toLowerCase();
  if (!email) return [];
  try {
    const snap = await db.collection('centros').get();
    return snap.docs
      .filter(d => (d.data().admins || []).map(e => e.toLowerCase()).includes(email))
      .map(d => ({ id: d.id, ...d.data() }));
  } catch { return []; }
}

/** Muestra/oculta botón admin centro en dashboard */
async function _verificarAccesoAdminCentro() {
  const btn = document.getElementById('btn-dash-admin-centro');
  if (!btn) return;
  const centros = await _esAdminDeCentro();
  // Superadmins también ven este botón (gestionan todos los centros)
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  btn.style.display = (centros.length > 0 || esSA) ? '' : 'none';
}

/** Abre el panel de admin centro */
async function abrirAdminCentro() {
  _mostrarPanel('panel-admin-centro');
  const centros = await _esAdminDeCentro();
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();

  // Si es superadmin, cargar todos los centros
  let todosLosCentros = centros;
  if (esSA) {
    try {
      const snap = await db.collection('centros').orderBy('nombre').get();
      todosLosCentros = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    } catch { /* usar los del admin */ }
  }

  // Configurar selector de centro
  const selWrap = document.getElementById('ac-selector-centro');
  const sel = document.getElementById('ac-centro-sel');
  if (todosLosCentros.length > 1) {
    selWrap.style.display = '';
    sel.innerHTML = '';
    todosLosCentros.forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id;
      opt.textContent = c.nombre;
      sel.appendChild(opt);
    });
  } else if (todosLosCentros.length === 1) {
    selWrap.style.display = 'none';
    sel.innerHTML = '<option value="' + todosLosCentros[0].id + '">' + todosLosCentros[0].nombre + '</option>';
  } else {
    selWrap.style.display = 'none';
    document.getElementById('ac-contenido').innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No administras ningún centro educativo.</div>';
    return;
  }

  window._acCentros = todosLosCentros;
  switchTabAdminCentro('pendientes');
}

/** Tabs del admin centro */
function switchTabAdminCentro(tab) {
  const tabs = { pendientes: 'tab-ac-pendientes', aprobados: 'tab-ac-aprobados', rechazados: 'tab-ac-rechazados' };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#00695C'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  window._acTabActual = tab;
  _renderDocentesCentro();
}

/** Renderiza lista de docentes según tab activo */
async function _renderDocentesCentro() {
  const cont = document.getElementById('ac-contenido');
  if (!cont) return;
  const centroId = document.getElementById('ac-centro-sel')?.value;
  if (!centroId) return;
  const tab = window._acTabActual || 'pendientes';

  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando docentes...</div>';

  try {
    const estadoFiltro = tab === 'pendientes' ? 'pendiente' : tab === 'aprobados' ? 'aprobado' : 'rechazado';
    const snap = await db.collection('usuarios').where('centroId', '==', centroId).get();
    const docentes = snap.docs.map(d => ({ uid: d.id, ...d.data() })).filter(d => d.estado === estadoFiltro);

    // Actualizar badge de pendientes
    if (tab === 'pendientes') {
      const badge = document.getElementById('ac-badge-pendientes');
      if (badge) {
        badge.textContent = docentes.length;
        badge.style.display = docentes.length > 0 ? '' : 'none';
      }
    }

    if (docentes.length === 0) {
      const msgs = { pendientes: 'No hay solicitudes pendientes', aprobados: 'No hay docentes aprobados', rechazados: 'No hay docentes rechazados' };
      const icons = { pendientes: 'hourglass_empty', aprobados: 'check_circle_outline', rechazados: 'block' };
      cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">'
        + '<span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">' + icons[tab] + '</span>'
        + msgs[tab] + '</div>';
      return;
    }

    let html = '<div style="display:flex;flex-direction:column;gap:10px;">';
    docentes.forEach(d => {
      const fecha = d.createdAt ? new Date(d.createdAt).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' }) : '';
      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;">';

      // Avatar
      const inicial = (d.nombre || d.email || 'U')[0].toUpperCase();
      html += '<div style="width:44px;height:44px;border-radius:50%;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1565C0;font-size:1.1rem;">' + inicial + '</div>';

      // Info + badge de rol
      const rolBadge = d.rol === 'director'
        ? '<span style="background:#4A148C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:600;margin-left:6px;">Director</span>'
        : d.rol === 'coordinadora'
        ? '<span style="background:#00695C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:600;margin-left:6px;">Coordinadora</span>'
        : d.rol === 'admin_centro'
        ? '<span style="background:#00695C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:600;margin-left:6px;">Admin</span>'
        : '';
      html += '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + (d.nombre || 'Sin nombre') + rolBadge + '</div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + (d.email || '') + '</div>'
        + '<div style="font-size:0.75rem;color:#B0BEC5;margin-top:2px;">Registro: ' + fecha + '</div>'
        + '</div>';

      // Acciones
      html += '<div style="display:flex;gap:6px;flex-wrap:wrap;">';
      if (tab === 'pendientes') {
        html += '<button onclick="_aprobarDocente(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#2E7D32;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">check</span> Aprobar</button>';
        html += '<button onclick="_rechazarDocente(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#C62828;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">close</span> Rechazar</button>';
      } else if (tab === 'aprobados') {
        if (d.rol !== 'director') {
          html += '<button onclick="_promoverDirector(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#4A148C;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">star</span> Hacer Director</button>';
        } else {
          html += '<button onclick="_quitarDirector(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#78909C;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">star_border</span> Quitar Director</button>';
        }
        if (d.rol !== 'coordinadora') {
          html += '<button onclick="_promoverCoordinadora(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#00695C;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">supervisor_account</span> Hacer Coordinadora</button>';
        } else {
          html += '<button onclick="_quitarCoordinadora(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#78909C;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">person_remove</span> Quitar Coordinadora</button>';
        }
        html += '<button onclick="_rechazarDocente(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#E65100;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">block</span> Revocar</button>';
      } else {
        html += '<button onclick="_aprobarDocente(\'' + d.uid + '\')" style="display:inline-flex;align-items:center;gap:4px;padding:7px 14px;background:#2E7D32;color:#fff;border:none;border-radius:6px;font-size:0.82rem;font-weight:600;cursor:pointer;"><span class="material-icons" style="font-size:16px;">check</span> Aprobar</button>';
      }
      html += '</div></div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    console.error('Error cargando docentes:', e);
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error cargando docentes: ' + e.message + '</div>';
  }
}

/** Aprobar docente */
async function _aprobarDocente(uid) {
  try {
    await db.collection('usuarios').doc(uid).update({ estado: 'aprobado', approvedAt: new Date().toISOString(), approvedBy: window.currentUser?.email || '' });
    mostrarToast('Docente aprobado correctamente', 'success');
    _renderDocentesCentro();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

/** Rechazar docente */
async function _rechazarDocente(uid) {
  if (!confirm('¿Rechazar este docente? No podrá acceder al sistema.')) return;
  try {
    await db.collection('usuarios').doc(uid).update({ estado: 'rechazado', rejectedAt: new Date().toISOString(), rejectedBy: window.currentUser?.email || '' });
    mostrarToast('Docente rechazado', 'success');
    _renderDocentesCentro();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

/** Promover a director */
async function _promoverDirector(uid) {
  if (!confirm('¿Promover este usuario a Director del centro?')) return;
  try {
    await db.collection('usuarios').doc(uid).update({ rol: 'director' });
    mostrarToast('Usuario promovido a Director', 'success');
    _renderDocentesCentro();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

/** Promover a coordinadora */
async function _promoverCoordinadora(uid) {
  if (!confirm('¿Asignar el rol de Coordinadora a este usuario?')) return;
  try {
    await db.collection('usuarios').doc(uid).update({ rol: 'coordinadora' });
    mostrarToast('Usuario asignado como Coordinadora', 'success');
    _renderDocentesCentro();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

/** Quitar rol de coordinadora */
async function _quitarCoordinadora(uid) {
  if (!confirm('¿Quitar el rol de Coordinadora a este usuario?')) return;
  try {
    await db.collection('usuarios').doc(uid).update({ rol: 'docente' });
    mostrarToast('Rol de Coordinadora removido', 'success');
    _renderDocentesCentro();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

/** Quitar rol de director */
async function _quitarDirector(uid) {
  if (!confirm('¿Quitar el rol de Director a este usuario?')) return;
  try {
    await db.collection('usuarios').doc(uid).update({ rol: 'docente' });
    mostrarToast('Rol de Director removido', 'success');
    _renderDocentesCentro();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

// ════════════════════════════════════════════════════════════════════
// ── MÓDULO: DIRECTOR — AVISOS Y MONITOREO ────────────────────────
// ════════════════════════════════════════════════════════════════════

/** Verifica si el usuario actual es director */
async function _esDirector() {
  if (!window.currentUser) return false;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    return doc.exists && doc.data().rol === 'director';
  } catch { return false; }
}

/** Muestra/oculta botón director en dashboard */
async function _verificarAccesoDirector() {
  const btn = document.getElementById('btn-dash-director');
  if (!btn) return;
  const esDir = await _esDirector();
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  btn.style.display = (esDir || esSA) ? '' : 'none';
}

/** Abre panel de director */
async function abrirDirector() {
  _mostrarPanel('panel-director');
  switchTabDirector('avisos');
}

/** Tabs del director */
function switchTabDirector(tab) {
  const tabs = { avisos: 'tab-dir-avisos', docentes: 'tab-dir-docentes' };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#4A148C'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  window._dirTabActual = tab;
  if (tab === 'avisos') _renderAvisosDirector();
  else _renderMonitoreoDocentes();
}

// ── AVISOS ──────────────────────────────────────────────────────

/** Obtener centroId del director actual */
async function _getCentroDirector() {
  if (!window.currentUser) return null;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    if (doc.exists) return doc.data().centroId || null;
  } catch {}
  return null;
}

/** Renderiza la sección de avisos */
async function _renderAvisosDirector() {
  const cont = document.getElementById('dir-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando...</div>';

  const centroId = await _getCentroDirector();
  // Superadmin sin centro: mostrar selector
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  let centroFinal = centroId;

  if (!centroFinal && esSA) {
    // Usar primer centro disponible
    try {
      const snap = await db.collection('centros').limit(1).get();
      if (!snap.empty) centroFinal = snap.docs[0].id;
    } catch {}
  }

  if (!centroFinal) {
    cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No estás asignado a ningún centro.</div>';
    return;
  }

  // Cargar avisos existentes
  let avisos = [];
  try {
    const snap = await db.collection('centros').doc(centroFinal).collection('avisos').orderBy('fecha', 'desc').get();
    avisos = snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch (e) { console.warn('Error cargando avisos:', e); }

  let html = '';

  // Formulario nuevo aviso
  html += '<div style="background:#F3E5F5;border:1.5px solid #CE93D8;border-radius:12px;padding:16px;margin-bottom:20px;">'
    + '<h4 style="margin:0 0 10px;color:#4A148C;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">campaign</span> Enviar nuevo aviso</h4>'
    + '<input type="text" id="dir-aviso-titulo" placeholder="Título del aviso" style="width:100%;padding:10px 12px;border:1.5px solid #CE93D8;border-radius:8px;font-size:0.9rem;margin-bottom:8px;box-sizing:border-box;">'
    + '<textarea id="dir-aviso-mensaje" placeholder="Escribe el mensaje para todos los docentes y administradores del centro..." rows="3" style="width:100%;padding:10px 12px;border:1.5px solid #CE93D8;border-radius:8px;font-size:0.9rem;resize:vertical;box-sizing:border-box;"></textarea>'
    + '<div style="display:flex;gap:8px;margin-top:10px;align-items:center;">'
    + '<select id="dir-aviso-prioridad" style="padding:8px 12px;border:1.5px solid #CE93D8;border-radius:8px;font-size:0.85rem;background:#fff;">'
    + '<option value="normal">Normal</option><option value="importante">Importante</option><option value="urgente">Urgente</option>'
    + '</select>'
    + '<button onclick="_enviarAvisoDirector(\'' + centroFinal + '\')" style="display:inline-flex;align-items:center;gap:6px;padding:10px 20px;background:#4A148C;color:#fff;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:0.9rem;margin-left:auto;">'
    + '<span class="material-icons" style="font-size:18px;">send</span> Enviar aviso</button>'
    + '</div></div>';

  // Lista de avisos
  if (avisos.length === 0) {
    html += '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">notifications_none</span>No hay avisos enviados</div>';
  } else {
    html += '<h4 style="color:#4A148C;margin:0 0 12px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">history</span> Avisos enviados</h4>';
    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    avisos.forEach(a => {
      const fecha = a.fecha ? new Date(a.fecha).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
      const prioColors = { urgente: '#C62828', importante: '#E65100', normal: '#4A148C' };
      const prioLabels = { urgente: 'URGENTE', importante: 'IMPORTANTE', normal: 'Normal' };
      const color = prioColors[a.prioridad] || prioColors.normal;
      html += '<div style="background:#fff;border-left:4px solid ' + color + ';border-radius:8px;padding:14px;box-shadow:0 1px 4px rgba(0,0,0,0.06);">'
        + '<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;">'
        + '<span style="background:' + color + ';color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:700;">' + (prioLabels[a.prioridad] || 'Normal') + '</span>'
        + '<span style="font-size:0.78rem;color:#90A4AE;">' + fecha + '</span>'
        + '<button onclick="_eliminarAviso(\'' + centroFinal + '\',\'' + a.id + '\')" style="margin-left:auto;background:none;border:none;cursor:pointer;color:#C62828;"><span class="material-icons" style="font-size:18px;">delete</span></button>'
        + '</div>'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;margin-bottom:4px;">' + (a.titulo || 'Sin título') + '</div>'
        + '<div style="font-size:0.88rem;color:#546E7A;white-space:pre-wrap;">' + (a.mensaje || '') + '</div>'
        + '<div style="font-size:0.72rem;color:#B0BEC5;margin-top:6px;">Enviado por: ' + (a.enviadoPor || '') + '</div>'
        + '</div>';
    });
    html += '</div>';
  }

  cont.innerHTML = html;
}

/** Enviar aviso */
async function _enviarAvisoDirector(centroId) {
  const titulo = document.getElementById('dir-aviso-titulo')?.value?.trim();
  const mensaje = document.getElementById('dir-aviso-mensaje')?.value?.trim();
  const prioridad = document.getElementById('dir-aviso-prioridad')?.value || 'normal';

  if (!titulo && !mensaje) { mostrarToast('Escribe un título o mensaje', 'error'); return; }

  try {
    await db.collection('centros').doc(centroId).collection('avisos').add({
      titulo: titulo || '',
      mensaje: mensaje || '',
      prioridad,
      fecha: new Date().toISOString(),
      enviadoPor: window.currentUser?.displayName || window.currentUser?.email || '',
      enviadoPorUid: window.currentUser?.uid || ''
    });
    mostrarToast('Aviso enviado correctamente', 'success');
    _renderAvisosDirector();
  } catch (e) { mostrarToast('Error enviando aviso: ' + e.message, 'error'); }
}

/** Eliminar aviso */
async function _eliminarAviso(centroId, avisoId) {
  if (!confirm('¿Eliminar este aviso?')) return;
  try {
    await db.collection('centros').doc(centroId).collection('avisos').doc(avisoId).delete();
    mostrarToast('Aviso eliminado', 'success');
    _renderAvisosDirector();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

// ── MONITOREO DE DOCENTES ──────────────────────────────────────

/** Renderiza monitoreo: lista de docentes con su última actividad */
async function _renderMonitoreoDocentes() {
  const cont = document.getElementById('dir-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando docentes...</div>';

  let centroId = await _getCentroDirector();
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  if (!centroId && esSA) {
    try { const s = await db.collection('centros').limit(1).get(); if (!s.empty) centroId = s.docs[0].id; } catch {}
  }
  if (!centroId) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay centro asignado.</div>'; return; }

  try {
    const snap = await db.collection('usuarios').where('centroId', '==', centroId).get();
    const docentes = snap.docs.map(d => ({ uid: d.id, ...d.data() })).filter(d => d.estado === 'aprobado');

    if (docentes.length === 0) {
      cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">person_off</span>No hay docentes aprobados en este centro</div>';
      return;
    }

    // Cargar última sesión de cada docente
    const docentesConSesion = await Promise.all(docentes.map(async d => {
      try {
        const sesSnap = await db.collection('users').doc(d.uid).collection('sessions').orderBy('timestamp', 'desc').limit(1).get();
        d.ultimaSesion = sesSnap.empty ? null : sesSnap.docs[0].data();
      } catch { d.ultimaSesion = null; }
      return d;
    }));

    let html = '<h4 style="color:#4A148C;margin:0 0 12px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">monitoring</span> Actividad de docentes</h4>';
    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    docentesConSesion.forEach(d => {
      const inicial = (d.nombre || d.email || 'U')[0].toUpperCase();
      const rolBadge = d.rol === 'director'
        ? '<span style="background:#4A148C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:600;margin-left:6px;">Director</span>'
        : d.rol === 'coordinadora'
        ? '<span style="background:#00695C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.68rem;font-weight:600;margin-left:6px;">Coordinadora</span>' : '';

      let ultimaInfo = 'Sin actividad registrada';
      let statusColor = '#E0E0E0';
      if (d.ultimaSesion) {
        const ts = d.ultimaSesion.timestamp?.toDate ? d.ultimaSesion.timestamp.toDate() : new Date(d.ultimaSesion.timestamp);
        const ahora = new Date();
        const diffHoras = (ahora - ts) / (1000 * 60 * 60);
        if (diffHoras < 1) { statusColor = '#4CAF50'; ultimaInfo = 'Activo hace menos de 1 hora'; }
        else if (diffHoras < 24) { statusColor = '#FF9800'; ultimaInfo = 'Último acceso: hoy ' + ts.toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit' }); }
        else if (diffHoras < 48) { statusColor = '#FF9800'; ultimaInfo = 'Último acceso: ayer'; }
        else { statusColor = '#F44336'; ultimaInfo = 'Último acceso: ' + ts.toLocaleDateString('es-DO', { day: '2-digit', month: 'short' }); }
        ultimaInfo += ' · ' + (d.ultimaSesion.device || '') + ' · ' + (d.ultimaSesion.browser || '');
      }

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;">'
        + '<div style="position:relative;"><div style="width:44px;height:44px;border-radius:50%;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1565C0;font-size:1.1rem;">' + inicial + '</div>'
        + '<div style="position:absolute;bottom:-2px;right:-2px;width:14px;height:14px;border-radius:50%;background:' + statusColor + ';border:2px solid #fff;"></div></div>'
        + '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + (d.nombre || 'Sin nombre') + rolBadge + '</div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + (d.email || '') + '</div>'
        + '<div style="font-size:0.75rem;color:#90A4AE;margin-top:2px;">' + ultimaInfo + '</div>'
        + '</div></div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

