// ── MÓDULO: SUPERADMIN — GESTIÓN DE CENTROS EDUCATIVOS ───────────
// ════════════════════════════════════════════════════════════════════

const SUPERADMIN_EMAILS_KEY = 'tinclass_superadmin_emails';
const CENTROS_COLLECTION = 'centros';

/** Emails de superadmin por defecto — se complementan con los de Firestore */
const SUPERADMIN_DEFAULT = ['soymarcosbremont@gmail.com'];

/** Verifica si el usuario actual es superadmin */
function _esSuperadmin() {
  const email = window.currentUser?.email?.toLowerCase();
  if (!email) return false;
  if (SUPERADMIN_DEFAULT.includes(email)) return true;
  try {
    const extra = JSON.parse(localStorage.getItem(SUPERADMIN_EMAILS_KEY) || '[]');
    return extra.map(e => e.toLowerCase()).includes(email);
  } catch { return false; }
}

/** Carga lista de emails superadmin desde Firestore */
async function _cargarEmailsSuperadmin() {
  try {
    const doc = await db.collection('config').doc('superadmin').get();
    if (doc.exists) {
      const emails = doc.data().emails || [];
      localStorage.setItem(SUPERADMIN_EMAILS_KEY, JSON.stringify(emails));
      return emails;
    }
  } catch (e) { console.warn('Error cargando superadmin emails:', e); }
  return SUPERADMIN_DEFAULT;
}

/** Guarda lista de emails superadmin en Firestore */
async function _guardarEmailsSuperadmin(emails) {
  try {
    await db.collection('config').doc('superadmin').set({ emails });
    localStorage.setItem(SUPERADMIN_EMAILS_KEY, JSON.stringify(emails));
  } catch (e) { mostrarToast('Error guardando emails superadmin', 'error'); }
}

/** Muestra/oculta botón superadmin en dashboard */
function _verificarAccesoSuperadmin() {
  const btn = document.getElementById('btn-dash-superadmin');
  if (btn) btn.style.display = _esSuperadmin() ? '' : 'none';
}

/** Abre el panel de superadmin */
function abrirSuperadmin() {
  if (!_esSuperadmin()) { mostrarToast('Acceso denegado', 'error'); return; }
  _mostrarPanel('panel-superadmin');
  switchTabSuperadmin('centros');
}

/** Tabs del superadmin */
function switchTabSuperadmin(tab) {
  const tabs = { centros: 'tab-sa-centros', admins: 'tab-sa-admins', opciones: 'tab-sa-opciones', opciones_coord: 'tab-sa-opciones-coord', opciones_psico: 'tab-sa-opciones-psico', prompts: 'tab-sa-prompts' };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#B71C1C'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  if (tab === 'centros') _renderCentrosEducativos();
  else if (tab === 'admins') _renderEmailsSuperadmin();
  else if (tab === 'opciones') _renderOpcionesDocentes();
  else if (tab === 'opciones_coord') _renderOpcionesCoordinadora();
  else if (tab === 'opciones_psico') _renderOpcionesPsicologia();
  else if (tab === 'prompts') _renderPromptsIA();
}

// ── EDITOR DE PROMPTS IA ─────────────────────────────────────────

const PROMPTS_IA_DEFS = [
  {
    key: 'prompt_sesion',
    label: 'Prompt — Sesión Diaria',
    icono: 'school',
    desc: 'Prompt para generar la sesión de clase de una actividad individual. Variables disponibles: {{moduloFormativo}}, {{familiaProfesional}}, {{actividad}}, {{ecEnunciado}}, {{nivelBloom}}, {{minTotal}}, {{minInicio}}, {{minDesarrollo}}, {{minCierre}}'
  },
  {
    key: 'prompt_base',
    label: 'Prompt — Estructura Base (EC + Actividades)',
    icono: 'account_tree',
    desc: 'Prompt para generar los Elementos de Capacidad y actividades a partir del RA. Variables: {{moduloFormativo}}, {{familiaProfesional}}, {{diasStr}}, {{raDescripcion}}, {{raCriterios}}, {{raRecursos}}, {{contenidosBloque}}, {{cantEC}}, {{actsPorEC}}, {{totalActs}}, {{ecCodigosLista}}, {{actEsperadasLista}}'
  },
  {
    key: 'prompt_instrumentos',
    label: 'Prompt — Instrumentos de Evaluación',
    icono: 'checklist',
    desc: 'Prompt para generar los instrumentos de evaluación en lote. Variables: {{moduloFormativo}}, {{raDescripcion}}, {{actividadesLista}}'
  },
  {
    key: 'prompt_detalle_uno',
    label: 'Prompt — Detalle Completo (Instrumento + Sesión)',
    icono: 'description',
    desc: 'Prompt para generar el detalle completo de una sola actividad. Variables: {{moduloFormativo}}, {{familiaProfesional}}, {{raDescripcion}}, {{actividad}}, {{ecEnunciado}}, {{nivelBloom}}, {{recursos}}, {{minTotal}}, {{minInicio}}, {{minDesarrollo}}, {{minCierre}}, {{instrPrompt}}'
  }
];

let _promptsIACache = null;

async function _cargarPromptsIA() {
  if (_promptsIACache) return _promptsIACache;
  try {
    const doc = await db.collection('config').doc('prompts_ia').get();
    _promptsIACache = doc.exists ? doc.data() : {};
    return _promptsIACache;
  } catch (e) {
    console.error('[Prompts IA] Error cargando:', e);
    return {};
  }
}

async function _guardarPromptIA(key, texto) {
  try {
    await db.collection('config').doc('prompts_ia').set({ [key]: texto }, { merge: true });
    _promptsIACache = null; // invalidar cache
    mostrarToast('Prompt guardado correctamente', 'success');
  } catch (e) {
    console.error('[Prompts IA] Error guardando:', e);
    mostrarToast('Error al guardar prompt: ' + e.message, 'error');
  }
}

async function _resetearPromptIA(key) {
  try {
    await db.collection('config').doc('prompts_ia').set({ [key]: firebase.firestore.FieldValue.delete() }, { merge: true });
    _promptsIACache = null;
    mostrarToast('Prompt restaurado al valor por defecto', 'success');
    _renderPromptsIA();
  } catch (e) {
    console.error('[Prompts IA] Error reseteando:', e);
    mostrarToast('Error al restaurar prompt: ' + e.message, 'error');
  }
}

function _getPromptDefaultByKey(key) {
  if (key === 'prompt_sesion') return _DEFAULT_PROMPT_SESION;
  if (key === 'prompt_base') return _DEFAULT_PROMPT_BASE;
  if (key === 'prompt_instrumentos') return _DEFAULT_PROMPT_INSTRUMENTOS;
  if (key === 'prompt_detalle_uno') return _DEFAULT_PROMPT_DETALLE_UNO;
  return '';
}

async function _renderPromptsIA() {
  const cont = document.getElementById('sa-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando prompts...</div>';

  const saved = await _cargarPromptsIA();

  let html = `<div style="margin-bottom:12px;">
    <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px;">
      <span class="material-icons" style="color:#7C4DFF;">psychology</span>
      <h3 style="margin:0;font-size:1rem;color:#424242;">Editor de Prompts de IA</h3>
    </div>
    <p style="font-size:0.8rem;color:#78909C;margin:0 0 16px;">
      Modifica los prompts que usa la IA para generar contenido. Usa las variables entre <code>{{llaves}}</code> para insertar datos dinámicos.
      Si dejas un prompt vacío o lo restauras, se usará el valor por defecto del sistema.
    </p>
  </div>`;

  PROMPTS_IA_DEFS.forEach(p => {
    const savedVal = saved[p.key] || '';
    const defaultVal = _getPromptDefaultByKey(p.key);
    const isCustom = savedVal && savedVal !== defaultVal;
    const displayVal = savedVal || defaultVal;
    const badgeColor = isCustom ? '#E65100' : '#4CAF50';
    const badgeText = isCustom ? 'Personalizado' : 'Por defecto';

    html += `<div style="margin-bottom:20px;border:1px solid #E0E0E0;border-radius:12px;overflow:hidden;">
      <div style="display:flex;align-items:center;gap:8px;padding:12px 16px;background:#F5F5F5;cursor:pointer;"
           onclick="document.getElementById('prompt-body-${p.key}').classList.toggle('hidden');">
        <span class="material-icons" style="font-size:20px;color:#7C4DFF;">${p.icono}</span>
        <strong style="flex:1;font-size:0.88rem;">${p.label}</strong>
        <span style="font-size:0.7rem;background:${badgeColor};color:#fff;padding:2px 8px;border-radius:10px;">${badgeText}</span>
        <span class="material-icons" style="font-size:18px;color:#9E9E9E;">expand_more</span>
      </div>
      <div id="prompt-body-${p.key}" class="hidden" style="padding:12px 16px;">
        <p style="font-size:0.75rem;color:#78909C;margin:0 0 8px;">${p.desc}</p>
        <textarea id="prompt-ta-${p.key}" style="width:100%;min-height:200px;font-family:monospace;font-size:0.78rem;
          border:1px solid #CFD8DC;border-radius:8px;padding:10px;resize:vertical;line-height:1.5;
          background:#FAFAFA;box-sizing:border-box;">${_escapeHTMLForTextarea(displayVal)}</textarea>
        <div style="display:flex;gap:8px;margin-top:8px;justify-content:flex-end;flex-wrap:wrap;">
          <button onclick="_resetearPromptIA('${p.key}')"
            style="padding:6px 14px;border:1px solid #E0E0E0;border-radius:8px;background:#fff;color:#616161;font-size:0.78rem;cursor:pointer;">
            <span class="material-icons" style="font-size:14px;vertical-align:middle;">restart_alt</span> Restaurar por defecto
          </button>
          <button onclick="_guardarPromptIADesdeEditor('${p.key}')"
            style="padding:6px 14px;border:none;border-radius:8px;background:#7C4DFF;color:#fff;font-size:0.78rem;cursor:pointer;font-weight:600;">
            <span class="material-icons" style="font-size:14px;vertical-align:middle;">save</span> Guardar
          </button>
        </div>
      </div>
    </div>`;
  });

  cont.innerHTML = html;
}

function _escapeHTMLForTextarea(str) {
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function _guardarPromptIADesdeEditor(key) {
  const ta = document.getElementById('prompt-ta-' + key);
  if (!ta) return;
  const texto = ta.value.trim();
  const defaultVal = _getPromptDefaultByKey(key);
  if (!texto || texto === defaultVal) {
    _resetearPromptIA(key);
  } else {
    _guardarPromptIA(key, texto);
  }
}

// ── PROMPTS POR DEFECTO (templates con {{variables}}) ────────────

const _DEFAULT_PROMPT_SESION = `Eres un planificador educativo experto en educación técnico profesional de República Dominicana. Genera una sesión de clase DETALLADA y COMPLETA para:

Módulo: {{moduloFormativo}} | {{familiaProfesional}}
Actividad: {{actividad}}
EC: {{ecEnunciado}} (Bloom: {{nivelBloom}})
Duración total: {{minTotal}} minutos (Inicio: {{minInicio}}min, Desarrollo: {{minDesarrollo}}min, Cierre: {{minCierre}}min)

INSTRUCCIONES IMPORTANTES:
- Cada campo debe tener contenido EXTENSO y DETALLADO (mínimo 3-5 oraciones por campo).
- No escribas respuestas cortas de una línea. Desarrolla cada sección con profundidad.
- Incluye instrucciones específicas, ejemplos concretos, preguntas guía y actividades paso a paso.
- Adapta todo al contexto técnico profesional del módulo indicado.

RESPONDE SOLO JSON válido, sin markdown, sin texto extra. USA EXACTAMENTE estas 7 claves:

{
  "apertura": "Escribe una pregunta motivadora abierta que active los conocimientos previos de los estudiantes, seguida de una dinámica de inicio (lluvia de ideas, video corto, caso real, demostración). Describe paso a paso cómo iniciar la clase durante {{minInicio}} minutos. Incluye al menos 2-3 preguntas generadoras y una actividad de enganche.",
  "encuadre": "Redacta el objetivo claro de la sesión vinculado al EC. Explica los criterios de evaluación que se usarán. Describe qué competencias se desarrollarán y cómo se conecta con sesiones anteriores y posteriores. Incluye los indicadores de logro esperados.",
  "organizacion": "Describe detalladamente cómo se organizarán los estudiantes (individual, parejas, equipos), qué materiales y recursos necesitarán, cómo se distribuirá el espacio del aula/taller/laboratorio, y qué roles tendrá cada participante si es trabajo grupal.",
  "procedimental": "Desarrolla el contenido paso a paso del momento de desarrollo ({{minDesarrollo}} min). Incluye: 1) Explicación del docente con ejemplos concretos, 2) Actividad práctica guiada, 3) Actividad práctica autónoma, 4) Momentos de retroalimentación. Detalla cada paso con tiempos estimados, instrucciones claras para el docente y preguntas de verificación.",
  "conceptual": "Incluye una reflexión profunda sobre la importancia del tema en el campo profesional. Presenta un caso real o situación laboral donde se aplique lo aprendido. Conecta la teoría con la práctica profesional y explica por qué estas competencias son esenciales en el mundo laboral.",
  "sintesis": "Describe el cierre de la sesión ({{minCierre}} min): recapitulación de los puntos clave, evaluación formativa (preguntas de verificación, ticket de salida, rúbrica rápida), autoevaluación del estudiante, asignación de tarea o preparación para la próxima sesión. Incluye preguntas de metacognición.",
  "estrategias": "Enumera y describe 3-4 estrategias didácticas utilizadas en la sesión. Para cada una, explica: qué es, cómo se aplica en esta sesión específica, y por qué es efectiva para el nivel de Bloom '{{nivelBloom}}'. Ejemplos: ABP, aprendizaje cooperativo, modelamiento, aula invertida, gamificación, think-pair-share."
}`;

