async function _esCoordinadora() {
  if (!window.currentUser) return false;
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    return doc.exists && doc.data().rol === 'coordinadora';
  } catch { return false; }
}

async function _verificarAccesoPsicologia() {
  const btn = document.getElementById('btn-dash-psicologia');
  if (!btn) return;
  if (!window.currentUser) { btn.style.display = 'none'; return; }
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    const rol = doc.exists ? (doc.data().rol || '') : '';
    const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
    const visible = ['psicologia', 'psicologa', 'psicologo', 'director', 'superadmin'].includes(rol) || esSA;
    btn.style.display = visible ? '' : 'none';
  } catch { btn.style.display = 'none'; }
}

async function _verificarAccesoCoordinadora() {
  const btn = document.getElementById('btn-dash-coordinadora');
  if (!btn) return;
  const esCoord = await _esCoordinadora();
  const esDir = await _esDirector();
  const esAdmin = (await _esAdminDeCentro()).length > 0;
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();
  btn.style.display = (esCoord || esDir || esAdmin || esSA) ? '' : 'none';
}

function abrirCoordinadora() {
  window._coordCentroSeleccionado = null; // Reset para permitir cambiar centro
  _mostrarPanel('panel-coordinadora');
  switchTabCoordinadora('calificaciones');
}

function switchTabCoordinadora(tab) {
  const tabs = { calificaciones: 'tab-coord-calificaciones', planificaciones: 'tab-coord-planificaciones', resumen: 'tab-coord-resumen', avisos: 'tab-coord-avisos' };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#00695C'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  window._coordTabActual = tab;
  if (tab === 'calificaciones') _coordMonitorCalificaciones();
  else if (tab === 'planificaciones') _coordMonitorPlanificaciones();
  else if (tab === 'resumen') _coordResumenDocentes();
  else if (tab === 'avisos') _coordAvisos();
}

async function _coordGetCentroId() {
  // Si ya hay un centro seleccionado en el panel, usarlo
  if (window._coordCentroSeleccionado) return window._coordCentroSeleccionado;
  if (!window.currentUser) return null;
  // Buscar centroId del usuario
  try {
    const doc = await db.collection('usuarios').doc(window.currentUser.uid).get();
    if (doc.exists && doc.data().centroId) return doc.data().centroId;
  } catch {}
  // Admin centro: buscar en centros.admins
  try {
    const email = window.currentUser.email?.toLowerCase();
    if (email) {
      const snap = await db.collection('centros').get();
      const centro = snap.docs.find(d => (d.data().admins || []).map(e => e.toLowerCase()).includes(email));
      if (centro) return centro.id;
    }
  } catch {}
  // Superadmin/Director sin centro: mostrar selector
  return null;
}

async function _coordMostrarSelectorCentro(cont, callback) {
  try {
    const snap = await db.collection('centros').get();
    const centros = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    if (!centros.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay centros registrados.</div>'; return; }
    let html = '<div style="text-align:center;padding:30px;">'
      + '<span class="material-icons" style="font-size:48px;color:#00695C;display:block;margin-bottom:12px;">business</span>'
      + '<p style="color:#546E7A;margin-bottom:16px;">Selecciona un centro educativo para ver sus datos:</p>'
      + '<div style="display:flex;flex-wrap:wrap;gap:10px;justify-content:center;">';
    centros.forEach(c => {
      html += '<button onclick="window._coordCentroSeleccionado=\'' + c.id + '\';' + callback + '()" style="padding:12px 20px;background:#fff;border:2px solid #00695C;border-radius:12px;cursor:pointer;font-size:0.9rem;font-weight:600;color:#00695C;transition:all 0.2s;"'
        + ' onmouseover="this.style.background=\'#00695C\';this.style.color=\'#fff\'" onmouseout="this.style.background=\'#fff\';this.style.color=\'#00695C\'">'
        + '<span class="material-icons" style="font-size:16px;vertical-align:middle;margin-right:4px;">school</span>'
        + escapeHTML(c.nombre || c.id) + '</button>';
    });
    html += '</div></div>';
    cont.innerHTML = html;
  } catch (e) { cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>'; }
}

async function _coordGetDocentes(centroId) {
  // Docentes aprobados del centro
  const snap = await db.collection('usuarios').where('centroId', '==', centroId).get();
  const docentes = snap.docs.map(d => ({ uid: d.id, ...d.data() })).filter(d => d.estado === 'aprobado');
  const uids = new Set(docentes.map(d => d.uid));

  // También incluir docentes del centro sin estado (admins auto-aprobados pueden no tener estado)
  try {
    const snap2 = await db.collection('usuarios').where('centroId', '==', centroId).get();
    snap2.docs.forEach(d => {
      if (!uids.has(d.id)) {
        uids.add(d.id);
        docentes.push({ uid: d.id, ...d.data() });
      }
    });
  } catch {}

  // Agregar admins del centro (pueden tener centroId vacío o diferente)
  try {
    const centroDoc = await db.collection('centros').doc(centroId).get();
    if (centroDoc.exists) {
      const admins = centroDoc.data().admins || [];
      for (const adminEmail of admins) {
        const emailLower = adminEmail.toLowerCase().trim();
        // Buscar por email exacto y en minúsculas
        let found = false;
        for (const variant of [emailLower, adminEmail.trim()]) {
          if (found) break;
          const adminSnap = await db.collection('usuarios').where('email', '==', variant).limit(1).get();
          if (!adminSnap.empty) {
            const adminDoc = adminSnap.docs[0];
            if (!uids.has(adminDoc.id)) {
              uids.add(adminDoc.id);
              docentes.push({ uid: adminDoc.id, ...adminDoc.data() });
            }
            found = true;
          }
        }
      }
    }
  } catch (e) { console.warn('Error buscando admins para coordinadora:', e); }

  // Incluir superadmins que pertenezcan a este centro (pueden no tener centroId en su doc)
  try {
    const saDoc = await db.collection('config').doc('superadmin').get();
    const saEmails = saDoc.exists ? (saDoc.data().emails || []) : [];
    const todosEmails = [...new Set([...SUPERADMIN_DEFAULT, ...saEmails])];
    for (const saEmail of todosEmails) {
      const emailLower = saEmail.toLowerCase().trim();
      for (const variant of [emailLower, saEmail.trim()]) {
        const saSnap = await db.collection('usuarios').where('email', '==', variant).limit(1).get();
        if (!saSnap.empty) {
          const saDocUser = saSnap.docs[0];
          if (!uids.has(saDocUser.id)) {
            uids.add(saDocUser.id);
            docentes.push({ uid: saDocUser.id, ...saDocUser.data() });
          }
          break;
        }
      }
    }
  } catch (e) { console.warn('Error buscando superadmins para coordinadora:', e); }

  return docentes;
}

// ── 1. MONITOR DE CALIFICACIONES ────────────────────────────────

async function _coordMonitorCalificaciones() {
  const cont = document.getElementById('coord-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Analizando calificaciones...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordMonitorCalificaciones'); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay docentes en este centro.</div>'; return; }

    // Leer datos de calificaciones de cada docente
    const docentesData = await Promise.all(docentes.map(async d => {
      try {
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw.payload ? JSON.parse(calRaw.payload) : calRaw;
        const cursos = calData.cursos || {};
        let totalActs = 0, actsSinNota = 0, totalEstudiantes = 0;
        const cursosDetalle = [];
        Object.entries(cursos).forEach(([cId, curso]) => {
          const ests = curso.estudiantes || [];
          totalEstudiantes += ests.length;
          let cursoActs = 0, cursoSinNota = 0;
          const rasDetalle = [];
          Object.entries(curso.ras || {}).forEach(([rk, ra]) => {
            const acts = ra.actividades || [];
            cursoActs += acts.length;
            totalActs += acts.length;
            const actsDetalle = [];
            acts.forEach(actId => {
              const snap = (ra._actividadesSnapshot || []).find(a => a.id === actId);
              let calificados = 0;
              ests.forEach(est => {
                const nota = curso.notas?.[est.id]?.[ra.raKey]?.[actId];
                if (nota !== undefined && nota !== null) calificados++;
              });
              const sinNota = ests.length - calificados;
              if (sinNota > 0 && ests.length > 0) actsSinNota++;
              if (sinNota > 0 && ests.length > 0) cursoSinNota++;
              actsDetalle.push({ id: actId, nombre: snap?.enunciado || actId, max: ra.valores?.[actId] || 0, calificados, sinNota, total: ests.length });
            });
            rasDetalle.push({ raKey: rk, label: ra.label || rk, modulo: ra.modulo || '', actividades: actsDetalle });
          });
          cursosDetalle.push({ id: cId, nombre: curso.nombre || cId, estudiantes: ests, ras: rasDetalle, notas: curso.notas || {}, totalActs: cursoActs, sinNota: cursoSinNota });
        });
        return { ...d, nCursos: Object.keys(cursos).length, totalActs, actsSinNota, totalEstudiantes, cursosDetalle };
      } catch (e) { console.warn('Error cal coord:', e); return { ...d, nCursos: 0, totalActs: 0, actsSinNota: 0, totalEstudiantes: 0, cursosDetalle: [] }; }
    }));

    docentesData.sort((a, b) => b.actsSinNota - a.actsSinNota);

    let html = '<h4 style="color:#00695C;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">grade</span> Estado de Calificaciones por Docente</h4>';

    const alDia = docentesData.filter(d => d.actsSinNota === 0 && d.totalActs > 0).length;
    const atrasados = docentesData.filter(d => d.actsSinNota > 0).length;
    const sinData = docentesData.filter(d => d.totalActs === 0).length;
    html += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap;">'
      + '<div style="flex:1;min-width:120px;background:#E8F5E9;border:1.5px solid #A5D6A7;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#2E7D32;">' + alDia + '</div><div style="font-size:0.78rem;color:#388E3C;">Al día</div></div>'
      + '<div style="flex:1;min-width:120px;background:#FFF3E0;border:1.5px solid #FFB74D;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#E65100;">' + atrasados + '</div><div style="font-size:0.78rem;color:#E65100;">Con atraso</div></div>'
      + '<div style="flex:1;min-width:120px;background:#F5F5F5;border:1.5px solid #E0E0E0;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#9E9E9E;">' + sinData + '</div><div style="font-size:0.78rem;color:#9E9E9E;">Sin actividades</div></div>'
      + '</div>';

    // Guardar datos para drill-down
    window._coordCalData = docentesData;

    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    docentesData.forEach((d, idx) => {
      const pctCalificado = d.totalActs > 0 ? Math.round(((d.totalActs - d.actsSinNota) / d.totalActs) * 100) : 0;
      let statusColor, statusIcon, statusText;
      if (d.totalActs === 0) { statusColor = '#9E9E9E'; statusIcon = 'remove_circle_outline'; statusText = 'Sin actividades'; }
      else if (d.actsSinNota === 0) { statusColor = '#2E7D32'; statusIcon = 'check_circle'; statusText = 'Al día'; }
      else if (d.actsSinNota <= 2) { statusColor = '#FF9800'; statusIcon = 'warning'; statusText = d.actsSinNota + ' sin calificar'; }
      else { statusColor = '#C62828'; statusIcon = 'error'; statusText = d.actsSinNota + ' sin calificar'; }

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;transition:box-shadow 0.2s;">'
        + '<div onclick="_coordToggleDetalleCal(' + idx + ')" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;cursor:pointer;" onmouseover="this.parentElement.style.boxShadow=\'0 2px 8px rgba(0,0,0,0.1)\'" onmouseout="this.parentElement.style.boxShadow=\'none\'">'
        + '<div style="width:44px;height:44px;border-radius:50%;background:' + statusColor + '22;display:flex;align-items:center;justify-content:center;">'
        + '<span class="material-icons" style="color:' + statusColor + ';font-size:22px;">' + statusIcon + '</span></div>'
        + '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + escapeHTML(d.nombre || d.email || 'Sin nombre') + ' <span class="material-icons" style="font-size:16px;vertical-align:middle;color:#90A4AE;">expand_more</span></div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + d.nCursos + ' cursos · ' + d.totalEstudiantes + ' estudiantes · ' + d.totalActs + ' actividades</div>'
        + '</div>'
        + '<div style="text-align:right;min-width:100px;">'
        + '<div style="font-size:1.1rem;font-weight:700;color:' + statusColor + ';">' + pctCalificado + '%</div>'
        + '<div style="font-size:0.72rem;color:' + statusColor + ';">' + statusText + '</div>'
        + '</div></div>'
        + '<div id="coord-cal-detalle-' + idx + '" style="display:none;margin-top:12px;border-top:1px solid #E0E0E0;padding-top:12px;"></div>'
        + '</div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

/** Expandir/colapsar detalle de calificaciones de un docente */
function _coordToggleDetalleCal(idx) {
  const el = document.getElementById('coord-cal-detalle-' + idx);
  if (!el) return;
  if (el.style.display !== 'none') { el.style.display = 'none'; return; }
  const d = window._coordCalData?.[idx];
  if (!d || !d.cursosDetalle.length) { el.innerHTML = '<div style="color:#9E9E9E;font-size:0.85rem;">Este docente no tiene cursos registrados.</div>'; el.style.display = 'block'; return; }

  let h = '';
  d.cursosDetalle.forEach(curso => {
    h += '<div style="margin-bottom:14px;">'
      + '<div style="font-weight:700;font-size:0.9rem;color:#1565C0;margin-bottom:6px;display:flex;align-items:center;gap:6px;">'
      + '<span class="material-icons" style="font-size:18px;">school</span> ' + escapeHTML(curso.nombre)
      + ' <span style="font-weight:400;font-size:0.78rem;color:#78909C;">(' + curso.estudiantes.length + ' est. · ' + curso.totalActs + ' act.)</span></div>';

    if (!curso.ras.length) { h += '<div style="font-size:0.82rem;color:#9E9E9E;margin-left:24px;">Sin RAs asignados</div></div>'; return; }

    curso.ras.forEach(ra => {
      h += '<div style="margin-left:12px;margin-bottom:8px;">'
        + '<div style="font-size:0.82rem;font-weight:600;color:#00695C;margin-bottom:4px;">' + escapeHTML(ra.label) + (ra.modulo ? ' <span style="font-weight:400;color:#78909C;">(' + escapeHTML(ra.modulo) + ')</span>' : '') + '</div>';

      if (!ra.actividades.length) { h += '<div style="font-size:0.78rem;color:#9E9E9E;margin-left:12px;">Sin actividades</div></div>'; return; }

      // Tabla de actividades con estado de calificación
      h += '<div style="overflow-x:auto;margin-left:12px;"><table style="width:100%;border-collapse:collapse;font-size:0.78rem;min-width:300px;">'
        + '<thead><tr style="background:#F5F5F5;"><th style="text-align:left;padding:4px 8px;border:1px solid #E0E0E0;">Actividad</th>'
        + '<th style="padding:4px 8px;border:1px solid #E0E0E0;width:60px;">Valor</th>'
        + '<th style="padding:4px 8px;border:1px solid #E0E0E0;width:80px;">Calificados</th>'
        + '<th style="padding:4px 8px;border:1px solid #E0E0E0;width:80px;">Pendientes</th></tr></thead><tbody>';

      ra.actividades.forEach(act => {
        const color = act.sinNota > 0 ? '#FFF3E0' : '#E8F5E9';
        h += '<tr style="background:' + color + ';"><td style="padding:4px 8px;border:1px solid #E0E0E0;">' + escapeHTML(act.nombre) + '</td>'
          + '<td style="padding:4px 8px;border:1px solid #E0E0E0;text-align:center;">' + act.max + '</td>'
          + '<td style="padding:4px 8px;border:1px solid #E0E0E0;text-align:center;color:#2E7D32;font-weight:600;">' + act.calificados + '/' + act.total + '</td>'
          + '<td style="padding:4px 8px;border:1px solid #E0E0E0;text-align:center;color:' + (act.sinNota > 0 ? '#C62828' : '#2E7D32') + ';font-weight:600;">' + act.sinNota + '</td></tr>';
      });
      h += '</tbody></table></div></div>';
    });

    // Notas por estudiante agrupadas por RA
    if (curso.estudiantes.length && curso.ras.length) {
      h += '<details style="margin-left:12px;margin-top:6px;"><summary style="cursor:pointer;font-size:0.82rem;color:#1565C0;font-weight:600;">Ver notas por estudiante (' + curso.estudiantes.length + ')</summary>';
      h += '<div style="margin-top:8px;">';
      curso.ras.forEach(ra => {
        if (!ra.actividades.length) return;
        h += '<div style="margin-bottom:12px;">'
          + '<div style="font-size:0.8rem;font-weight:700;color:#00695C;margin-bottom:4px;padding:4px 8px;background:#E0F2F1;border-radius:6px;">'
          + escapeHTML(ra.label) + (ra.modulo ? ' — ' + escapeHTML(ra.modulo) : '') + '</div>';
        h += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:0.75rem;">'
          + '<thead><tr style="background:#E3F2FD;"><th style="text-align:left;padding:4px 6px;border:1px solid #BBDEFB;min-width:120px;">Estudiante</th>';
        ra.actividades.forEach(act => {
          const nombre = act.nombre.length > 25 ? act.nombre.substring(0, 25) + '…' : act.nombre;
          h += '<th style="padding:4px;border:1px solid #BBDEFB;font-size:0.68rem;max-width:90px;text-align:center;" title="' + escapeHTML(act.nombre) + ' (máx: ' + act.max + ')">' + escapeHTML(nombre) + '<br><span style="font-weight:400;color:#78909C;">/' + act.max + '</span></th>';
        });
        h += '</tr></thead><tbody>';
        curso.estudiantes.forEach(est => {
          h += '<tr><td style="padding:3px 6px;border:1px solid #BBDEFB;font-weight:500;">' + escapeHTML(est.nombre) + '</td>';
          ra.actividades.forEach(act => {
            const nota = curso.notas?.[est.id]?.[ra.raKey]?.[act.id];
            const tieneNota = nota !== undefined && nota !== null;
            h += '<td style="padding:3px 4px;border:1px solid #BBDEFB;text-align:center;background:' + (tieneNota ? '#E8F5E9' : '#FFEBEE') + ';color:' + (tieneNota ? '#1B5E20' : '#C62828') + ';font-weight:600;">' + (tieneNota ? nota : '—') + '</td>';
          });
          h += '</tr>';
        });
        h += '</tbody></table></div></div>';
      });
      h += '</div></details>';
    }
    h += '</div>';
  });
  el.innerHTML = h;
  el.style.display = 'block';
}

// ── 2. MONITOR DE PLANIFICACIONES ───────────────────────────────

async function _coordMonitorPlanificaciones() {
  const cont = document.getElementById('coord-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Analizando planificaciones...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordMonitorPlanificaciones'); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay docentes en este centro.</div>'; return; }

    const docentesData = await Promise.all(docentes.map(async d => {
      try {
        const biblioDoc = await db.collection('users').doc(d.uid).collection('data').doc('biblioteca_planificaciones').get();
        const biblioRaw = biblioDoc.exists ? biblioDoc.data() : {};
        const biblio = biblioRaw.payload ? JSON.parse(biblioRaw.payload) : biblioRaw;
        const items = biblio.items || [];
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw2 = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw2.payload ? JSON.parse(calRaw2.payload) : calRaw2;
        const cursos = calData.cursos || {};
        let asignadas = 0;
        const cursosConPlan = [];
        Object.entries(cursos).forEach(([cId, c]) => {
          const pIds = c.planIds || [];
          asignadas += pIds.length;
          if (pIds.length) cursosConPlan.push({ nombre: c.nombre || cId, planIds: pIds });
        });
        const sortedItems = [...items].sort((a, b) => (b.fechaGuardado || b.modificado || b.creado || '').localeCompare(a.fechaGuardado || a.modificado || a.creado || ''));
        const ultimaFecha = sortedItems[0]?.fechaGuardado || sortedItems[0]?.modificado || sortedItems[0]?.creado || null;
        return { ...d, totalPlanificaciones: items.length, asignadas, ultimaModificacion: ultimaFecha, planItems: items, cursosConPlan };
      } catch { return { ...d, totalPlanificaciones: 0, asignadas: 0, ultimaModificacion: null, planItems: [], cursosConPlan: [] }; }
    }));

    docentesData.sort((a, b) => a.totalPlanificaciones - b.totalPlanificaciones);

    // Guardar para drill-down
    window._coordPlanData = docentesData;

    let html = '<h4 style="color:#00695C;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">description</span> Estado de Planificaciones por Docente</h4>';

    const conPlan = docentesData.filter(d => d.totalPlanificaciones > 0).length;
    const sinPlan = docentesData.filter(d => d.totalPlanificaciones === 0).length;
    const sinAsignar = docentesData.filter(d => d.totalPlanificaciones > 0 && d.asignadas === 0).length;
    html += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap;">'
      + '<div style="flex:1;min-width:120px;background:#E8F5E9;border:1.5px solid #A5D6A7;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#2E7D32;">' + conPlan + '</div><div style="font-size:0.78rem;color:#388E3C;">Con planificaciones</div></div>'
      + '<div style="flex:1;min-width:120px;background:#FFEBEE;border:1.5px solid #EF9A9A;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#C62828;">' + sinPlan + '</div><div style="font-size:0.78rem;color:#C62828;">Sin planificaciones</div></div>'
      + '<div style="flex:1;min-width:120px;background:#FFF3E0;border:1.5px solid #FFB74D;border-radius:10px;padding:12px;text-align:center;">'
      + '<div style="font-size:1.4rem;font-weight:700;color:#E65100;">' + sinAsignar + '</div><div style="font-size:0.78rem;color:#E65100;">Sin asignar a cursos</div></div>'
      + '</div>';

    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    docentesData.forEach((d, idx) => {
      let statusColor, statusIcon;
      if (d.totalPlanificaciones === 0) { statusColor = '#C62828'; statusIcon = 'cancel'; }
      else if (d.asignadas === 0) { statusColor = '#FF9800'; statusIcon = 'warning'; }
      else { statusColor = '#2E7D32'; statusIcon = 'check_circle'; }

      const ultimaMod = d.ultimaModificacion ? new Date(d.ultimaModificacion).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' }) : 'Nunca';

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;transition:box-shadow 0.2s;">'
        + '<div onclick="_coordToggleDetallePlan(' + idx + ')" style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;cursor:pointer;" onmouseover="this.parentElement.style.boxShadow=\'0 2px 8px rgba(0,0,0,0.1)\'" onmouseout="this.parentElement.style.boxShadow=\'none\'">'
        + '<div style="width:44px;height:44px;border-radius:50%;background:' + statusColor + '22;display:flex;align-items:center;justify-content:center;">'
        + '<span class="material-icons" style="color:' + statusColor + ';font-size:22px;">' + statusIcon + '</span></div>'
        + '<div style="flex:1;min-width:150px;">'
        + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + escapeHTML(d.nombre || d.email || 'Sin nombre') + ' <span class="material-icons" style="font-size:16px;vertical-align:middle;color:#90A4AE;">expand_more</span></div>'
        + '<div style="font-size:0.82rem;color:#78909C;">' + d.totalPlanificaciones + ' planificaciones · ' + d.asignadas + ' asignadas a cursos</div>'
        + '<div style="font-size:0.72rem;color:#B0BEC5;">Última modificación: ' + ultimaMod + '</div>'
        + '</div></div>'
        + '<div id="coord-plan-detalle-' + idx + '" style="display:none;margin-top:12px;border-top:1px solid #E0E0E0;padding-top:12px;"></div>'
        + '</div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

/** Expandir/colapsar detalle de planificaciones de un docente */
function _coordToggleDetallePlan(idx) {
  const el = document.getElementById('coord-plan-detalle-' + idx);
  if (!el) return;
  if (el.style.display !== 'none') { el.style.display = 'none'; return; }
  const d = window._coordPlanData?.[idx];
  if (!d || !d.planItems.length) { el.innerHTML = '<div style="color:#9E9E9E;font-size:0.85rem;">Este docente no tiene planificaciones.</div>'; el.style.display = 'block'; return; }

  let h = '';

  // Cursos con planificaciones asignadas
  if (d.cursosConPlan.length) {
    h += '<div style="margin-bottom:10px;font-size:0.82rem;font-weight:600;color:#1565C0;">Cursos con planificación asignada:</div>';
    d.cursosConPlan.forEach(c => {
      h += '<div style="margin-left:12px;margin-bottom:4px;font-size:0.8rem;"><span class="material-icons" style="font-size:14px;vertical-align:middle;color:#2E7D32;">check</span> ' + escapeHTML(c.nombre) + ' <span style="color:#78909C;">(' + c.planIds.length + ' plan' + (c.planIds.length > 1 ? 'es' : '') + ')</span></div>';
    });
    h += '<div style="margin-bottom:10px;"></div>';
  }

  // Lista de planificaciones
  h += '<div style="font-size:0.82rem;font-weight:600;color:#00695C;margin-bottom:8px;">Planificaciones guardadas (' + d.planItems.length + '):</div>';
  h += '<div style="display:flex;flex-direction:column;gap:6px;">';
  d.planItems.forEach(item => {
    const plan = item.planificacion || {};
    const raDesc = plan.ra?.descripcion || '';
    const raCorto = raDesc.substring(0, 60) + (raDesc.length > 60 ? '...' : '');
    const modulo = plan.datosGenerales?.moduloFormativo || '';
    const nActs = (plan.actividades || []).length;
    const fecha = item.fechaGuardadoLabel || (item.fechaGuardado ? new Date(item.fechaGuardado).toLocaleDateString('es-DO') : '');

    h += '<div style="background:#F5F5F5;border:1px solid #E0E0E0;border-radius:8px;padding:10px;">'
      + '<div style="font-weight:600;font-size:0.85rem;color:#212121;">' + escapeHTML(item.nombre || 'Sin nombre') + '</div>';
    if (modulo) h += '<div style="font-size:0.78rem;color:#1565C0;">' + escapeHTML(modulo) + '</div>';
    if (raCorto) h += '<div style="font-size:0.75rem;color:#00695C;">' + escapeHTML(raCorto) + '</div>';
    h += '<div style="font-size:0.72rem;color:#78909C;margin-top:2px;">' + nActs + ' actividades · Guardada: ' + fecha + '</div>';

    // Detalle de actividades
    if (nActs > 0) {
      h += '<details style="margin-top:4px;"><summary style="cursor:pointer;font-size:0.75rem;color:#5C6BC0;">Ver actividades</summary>';
      h += '<div style="margin-top:4px;">';
      (plan.actividades || []).forEach((act, i) => {
        h += '<div style="font-size:0.75rem;padding:3px 0;border-bottom:1px solid #EEE;display:flex;gap:6px;align-items:flex-start;">'
          + '<span style="color:#78909C;min-width:20px;">' + (i + 1) + '.</span>'
          + '<div><span style="color:#212121;">' + escapeHTML(act.enunciado || 'Sin descripción') + '</span>';
        if (act.ecCodigo) h += ' <span style="color:#5C6BC0;font-size:0.7rem;">(' + act.ecCodigo + ')</span>';
        if (act.instrumento?.tipoLabel) h += ' <span style="color:#78909C;font-size:0.7rem;">— ' + act.instrumento.tipoLabel + '</span>';
        if (act.valor) h += ' <span style="color:#E65100;font-size:0.7rem;font-weight:600;">' + act.valor + ' pts</span>';
        h += '</div></div>';
      });
      h += '</div></details>';
    }
    h += '</div>';
  });
  h += '</div>';

  el.innerHTML = h;
  el.style.display = 'block';
}

// ── 3. RESUMEN POR DOCENTE ──────────────────────────────────────

async function _coordResumenDocentes() {
  const cont = document.getElementById('coord-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando resumen...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordResumenDocentes'); return; }

  try {
    const docentes = await _coordGetDocentes(centroId);
    if (!docentes.length) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No hay docentes en este centro.</div>'; return; }

    const docentesData = await Promise.all(docentes.map(async d => {
      try {
        // Calificaciones
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw3 = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw3.payload ? JSON.parse(calRaw3.payload) : calRaw3;
        const cursos = calData.cursos || {};
        let totalEst = 0, totalActs = 0, actsSinNota = 0, cursosArr = [];
        Object.entries(cursos).forEach(([cId, curso]) => {
          const ests = curso.estudiantes || [];
          totalEst += ests.length;
          let cursoActs = 0, cursoSinNota = 0;
          Object.values(curso.ras || {}).forEach(ra => {
            const acts = ra.actividades || [];
            cursoActs += acts.length;
            totalActs += acts.length;
            acts.forEach(actId => {
              const tiene = ests.some(est => {
                const n = curso.notas?.[est.id]?.[ra.raKey]?.[actId];
                return n !== undefined && n !== null;
              });
              if (!tiene && ests.length > 0) { actsSinNota++; cursoSinNota++; }
            });
          });
          cursosArr.push({ nombre: curso.nombre || cId, estudiantes: ests.length, actividades: cursoActs, sinNota: cursoSinNota });
        });

        // Planificaciones
        const biblioDoc = await db.collection('users').doc(d.uid).collection('data').doc('biblioteca_planificaciones').get();
        const biblioRaw3 = biblioDoc.exists ? biblioDoc.data() : {};
        const biblio3 = biblioRaw3.payload ? JSON.parse(biblioRaw3.payload) : biblioRaw3;
        const nPlan = (biblio3.items || []).length;

        // Última sesión
        let ultimaSesion = null;
        try {
          const sesSnap = await db.collection('users').doc(d.uid).collection('sessions').orderBy('timestamp', 'desc').limit(1).get();
          if (!sesSnap.empty) ultimaSesion = sesSnap.docs[0].data();
        } catch {}

        return { ...d, totalEst, totalActs, actsSinNota, cursosArr, nPlan, ultimaSesion };
      } catch { return { ...d, totalEst: 0, totalActs: 0, actsSinNota: 0, cursosArr: [], nPlan: 0, ultimaSesion: null }; }
    }));

    let html = '<h4 style="color:#00695C;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">person</span> Ficha de cada Docente</h4>';
    html += '<div style="display:flex;flex-direction:column;gap:14px;">';

    docentesData.forEach(d => {
      const pct = d.totalActs > 0 ? Math.round(((d.totalActs - d.actsSinNota) / d.totalActs) * 100) : 0;
      const barColor = pct >= 70 ? '#2E7D32' : pct >= 50 ? '#FF9800' : '#C62828';

      let sesInfo = 'Sin actividad';
      if (d.ultimaSesion) {
        const ts = d.ultimaSesion.timestamp?.toDate ? d.ultimaSesion.timestamp.toDate() : new Date(d.ultimaSesion.timestamp);
        const diff = (Date.now() - ts) / (1000 * 60 * 60);
        if (diff < 1) sesInfo = 'Activo hace menos de 1h';
        else if (diff < 24) sesInfo = 'Hoy ' + ts.toLocaleTimeString('es-DO', { hour: '2-digit', minute: '2-digit' });
        else sesInfo = ts.toLocaleDateString('es-DO', { day: '2-digit', month: 'short' });
      }

      const rolBadge = d.rol === 'director' ? ' <span style="background:#4A148C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.65rem;font-weight:600;">Director</span>'
        : d.rol === 'coordinadora' ? ' <span style="background:#00695C;color:#fff;padding:1px 8px;border-radius:10px;font-size:0.65rem;font-weight:600;">Coordinadora</span>' : '';

      html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:14px;padding:16px;box-shadow:0 2px 8px rgba(0,0,0,0.04);">'
        + '<div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">'
        + '<div style="width:48px;height:48px;border-radius:50%;background:#E3F2FD;display:flex;align-items:center;justify-content:center;font-weight:700;color:#1565C0;font-size:1.2rem;">' + (d.nombre || 'U')[0].toUpperCase() + '</div>'
        + '<div style="flex:1;">'
        + '<div style="font-weight:700;font-size:1rem;color:#212121;">' + escapeHTML(d.nombre || 'Sin nombre') + rolBadge + '</div>'
        + '<div style="font-size:0.8rem;color:#78909C;">' + escapeHTML(d.email || '') + ' · Último acceso: ' + sesInfo + '</div>'
        + '</div></div>';

      // KPIs
      html += '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;">'
        + '<div style="font-weight:700;color:#1565C0;">' + d.cursosArr.length + '</div><div style="font-size:0.7rem;color:#78909C;">Cursos</div></div>'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;">'
        + '<div style="font-weight:700;color:#1565C0;">' + d.totalEst + '</div><div style="font-size:0.7rem;color:#78909C;">Estudiantes</div></div>'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;">'
        + '<div style="font-weight:700;color:#1565C0;">' + d.nPlan + '</div><div style="font-size:0.7rem;color:#78909C;">Planificaciones</div></div>'
        + '<div style="flex:1;min-width:80px;background:#F5F5F5;border-radius:8px;padding:8px;text-align:center;">'
        + '<div style="font-weight:700;color:' + barColor + ';">' + pct + '%</div><div style="font-size:0.7rem;color:#78909C;">Calificado</div></div>'
        + '</div>';

      // Barra de progreso
      html += '<div style="background:#E0E0E0;border-radius:6px;height:8px;overflow:hidden;margin-bottom:10px;">'
        + '<div style="width:' + pct + '%;height:100%;background:' + barColor + ';border-radius:6px;transition:width 0.5s;"></div></div>';

      // Cursos detalle
      if (d.cursosArr.length) {
        html += '<div style="font-size:0.78rem;color:#546E7A;font-weight:600;margin-bottom:6px;">Cursos:</div>';
        html += '<div style="display:flex;flex-wrap:wrap;gap:6px;">';
        d.cursosArr.forEach(c => {
          const cColor = c.sinNota === 0 ? '#2E7D32' : c.sinNota <= 2 ? '#E65100' : '#C62828';
          html += '<span style="display:inline-flex;align-items:center;gap:4px;padding:4px 10px;background:' + cColor + '11;border:1px solid ' + cColor + '33;border-radius:8px;font-size:0.75rem;color:' + cColor + ';">'
            + '<span class="material-icons" style="font-size:13px;">class</span>' + escapeHTML(c.nombre) + ' (' + c.estudiantes + ' est, ' + c.actividades + ' act'
            + (c.sinNota > 0 ? ', <strong>' + c.sinNota + ' sin nota</strong>' : '') + ')</span>';
        });
        html += '</div>';
      }

      html += '</div>';
    });
    html += '</div>';
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

// ── 4. AVISOS COORDINADORA ──────────────────────────────────────

async function _coordAvisos() {
  const cont = document.getElementById('coord-contenido');
  if (!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando avisos...</div>';

  const centroId = await _coordGetCentroId();
  if (!centroId) { _coordMostrarSelectorCentro(cont, '_coordAvisos'); return; }

  let avisos = [];
  try {
    const snap = await db.collection('centros').doc(centroId).collection('avisos').orderBy('fecha', 'desc').get();
    avisos = snap.docs.map(d => ({ id: d.id, ...d.data() }));
  } catch (e) { console.warn('Error cargando avisos coordinadora:', e); }

  let html = '';
  // Formulario
  html += '<div style="background:#E0F2F1;border:1.5px solid #80CBC4;border-radius:12px;padding:16px;margin-bottom:20px;">'
    + '<h4 style="margin:0 0 10px;color:#00695C;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">campaign</span> Enviar aviso a docentes</h4>'
    + '<input type="text" id="coord-aviso-titulo" placeholder="Título del aviso" style="width:100%;padding:10px 12px;border:1.5px solid #80CBC4;border-radius:8px;font-size:0.9rem;margin-bottom:8px;box-sizing:border-box;">'
    + '<textarea id="coord-aviso-mensaje" placeholder="Escribe el mensaje..." rows="3" style="width:100%;padding:10px 12px;border:1.5px solid #80CBC4;border-radius:8px;font-size:0.9rem;resize:vertical;box-sizing:border-box;"></textarea>'
    + '<div style="display:flex;gap:8px;margin-top:10px;align-items:center;">'
    + '<select id="coord-aviso-prioridad" style="padding:8px 12px;border:1.5px solid #80CBC4;border-radius:8px;font-size:0.85rem;background:#fff;">'
    + '<option value="normal">Normal</option><option value="importante">Importante</option><option value="urgente">Urgente</option>'
    + '</select>'
    + '<button onclick="_coordEnviarAviso(\'' + centroId + '\')" style="display:inline-flex;align-items:center;gap:6px;padding:10px 20px;background:#00695C;color:#fff;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-size:0.9rem;margin-left:auto;">'
    + '<span class="material-icons" style="font-size:18px;">send</span> Enviar</button>'
    + '</div></div>';

  // Lista
  if (avisos.length === 0) {
    html += '<div style="text-align:center;padding:30px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">notifications_none</span>No hay avisos</div>';
  } else {
    html += '<div style="display:flex;flex-direction:column;gap:10px;">';
    avisos.forEach(a => {
      const prioMap = { urgente: { color: '#C62828', bg: '#FFEBEE', icon: 'priority_high' }, importante: { color: '#E65100', bg: '#FFF3E0', icon: 'warning' }, normal: { color: '#00695C', bg: '#E0F2F1', icon: 'info' } };
      const prio = prioMap[a.prioridad] || prioMap.normal;
      const fecha = a.fecha?.toDate ? a.fecha.toDate().toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
      html += '<div style="background:' + prio.bg + ';border:1.5px solid ' + prio.color + '33;border-radius:12px;padding:14px;">'
        + '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">'
        + '<span class="material-icons" style="color:' + prio.color + ';font-size:18px;">' + prio.icon + '</span>'
        + '<strong style="color:' + prio.color + ';font-size:0.95rem;">' + escapeHTML(a.titulo || 'Sin título') + '</strong>'
        + '<span style="margin-left:auto;font-size:0.72rem;color:#999;">' + fecha + '</span>'
        + '<button onclick="_coordEliminarAviso(\'' + centroId + '\',\'' + a.id + '\')" style="background:none;border:none;cursor:pointer;color:#C62828;padding:2px;"><span class="material-icons" style="font-size:16px;">delete</span></button>'
        + '</div>'
        + '<div style="font-size:0.88rem;color:#333;line-height:1.5;">' + escapeHTML(a.mensaje || '').replace(/\n/g, '<br>') + '</div>'
        + '<div style="font-size:0.72rem;color:#999;margin-top:6px;">Enviado por: ' + escapeHTML(a.autor || '') + '</div>'
        + '</div>';
    });
    html += '</div>';
  }
  cont.innerHTML = html;
}

async function _coordEnviarAviso(centroId) {
  const titulo = document.getElementById('coord-aviso-titulo')?.value.trim();
  const mensaje = document.getElementById('coord-aviso-mensaje')?.value.trim();
  const prioridad = document.getElementById('coord-aviso-prioridad')?.value || 'normal';
  if (!titulo) { mostrarToast('Escribe un título', 'error'); return; }
  if (!mensaje) { mostrarToast('Escribe el mensaje', 'error'); return; }
  try {
    await db.collection('centros').doc(centroId).collection('avisos').add({
      titulo, mensaje, prioridad,
      autor: window.currentUser?.email || 'Coordinadora',
      autorNombre: window.currentUser?.displayName || '',
      fecha: firebase.firestore.FieldValue.serverTimestamp()
    });
    mostrarToast('Aviso enviado correctamente', 'success');
    _coordAvisos();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

async function _coordEliminarAviso(centroId, avisoId) {
  if (!confirm('¿Eliminar este aviso?')) return;
  try {
    await db.collection('centros').doc(centroId).collection('avisos').doc(avisoId).delete();
    mostrarToast('Aviso eliminado', 'success');
    _coordAvisos();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

// ════════════════════════════════════════════════════════════════════
// MÓDULO DE PAGOS
// ════════════════════════════════════════════════════════════════════

/** Muestra/oculta botón Pagos en dashboard (temporalmente oculto) */
async function _verificarAccesoPagos() {
  const btn = document.getElementById('btn-dash-pagos');
  if (!btn) return;
  btn.style.display = 'none'; // oculto temporalmente
}

/** Abre el panel de pagos */
async function abrirPagos() {
  _mostrarPanel('panel-pagos');
  const centros = await _esAdminDeCentro();
  const esSA = typeof _esSuperadmin === 'function' && _esSuperadmin();

  let todosLosCentros = centros;
  if (esSA) {
    try {
      const snap = await db.collection('centros').orderBy('nombre').get();
      todosLosCentros = snap.docs.map(d => ({ id: d.id, ...d.data() }));
    } catch {}
  }

  const selWrap = document.getElementById('pagos-selector-centro');
  const sel = document.getElementById('pagos-centro-sel');
  if (todosLosCentros.length > 1) {
    selWrap.style.display = '';
    sel.innerHTML = '';
    todosLosCentros.forEach(c => {
      const opt = document.createElement('option');
      opt.value = c.id;
      opt.textContent = c.nombre;
      sel.appendChild(opt);
    });
  } else if (todosLosCentros.length === 1) {
    selWrap.style.display = 'none';
    sel.innerHTML = '<option value="' + todosLosCentros[0].id + '">' + todosLosCentros[0].nombre + '</option>';
  } else {
    selWrap.style.display = 'none';
    document.getElementById('pagos-contenido').innerHTML = '<div style="text-align:center;padding:30px;color:#999;">No administras ningún centro educativo.</div>';
    return;
  }
  window._pagosCentros = todosLosCentros;
  switchTabPagos('conceptos');
}

function _pagosGetCentroId() {
  return document.getElementById('pagos-centro-sel')?.value || '';
}

function _pagosRefreshTab() {
  switchTabPagos(window._pagosTabActual || 'conceptos');
}

/** Tabs del módulo de pagos */
function switchTabPagos(tab) {
  const tabs = { conceptos: 'tab-pagos-conceptos', estado: 'tab-pagos-estado', reportes: 'tab-pagos-reportes' };
  Object.entries(tabs).forEach(([key, id]) => {
    const el = document.getElementById(id);
    if (!el) return;
    if (key === tab) { el.classList.add('activo'); el.style.background = '#1565C0'; el.style.color = '#fff'; }
    else { el.classList.remove('activo'); el.style.background = '#F5F5F5'; el.style.color = '#616161'; }
  });
  window._pagosTabActual = tab;
  if (tab === 'conceptos') _pagosRenderConceptos();
  else if (tab === 'estado') _pagosRenderEstado();
  else if (tab === 'reportes') _pagosRenderReportes();
}

// ── CONCEPTOS DE PAGO ───────────────────────────────────────────

async function _pagosRenderConceptos() {
  const cont = document.getElementById('pagos-contenido');
  const centroId = _pagosGetCentroId();
  if (!centroId) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">Selecciona un centro.</div>'; return; }
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando conceptos...</div>';

  try {
    const doc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('conceptos').get();
    const data = doc.exists ? doc.data() : {};
    const conceptos = data.items || [];
    window._pagosConceptos = conceptos;

    let html = '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;flex-wrap:wrap;gap:8px;">'
      + '<h4 style="color:#1565C0;margin:0;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">receipt_long</span> Conceptos de Pago</h4>'
      + '<button onclick="_pagosAgregarConcepto()" style="padding:8px 16px;background:#1565C0;color:#fff;border:none;border-radius:8px;font-size:0.82rem;font-weight:600;cursor:pointer;display:flex;align-items:center;gap:4px;">'
      + '<span class="material-icons" style="font-size:16px;">add</span> Nuevo Concepto</button></div>';

    if (!conceptos.length) {
      html += '<div style="text-align:center;padding:40px;color:#9E9E9E;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">receipt_long</span>No hay conceptos de pago configurados.<br>Agrega el primer concepto para empezar.</div>';
    } else {
      html += '<div style="display:flex;flex-direction:column;gap:10px;">';
      conceptos.forEach((c, idx) => {
        const vencido = c.fechaLimite && new Date(c.fechaLimite) < new Date();
        const estadoColor = !c.activo ? '#9E9E9E' : vencido ? '#C62828' : '#2E7D32';
        const estadoTexto = !c.activo ? 'Inactivo' : vencido ? 'Vencido' : 'Activo';
        const estadoIcon = !c.activo ? 'pause_circle' : vencido ? 'error' : 'check_circle';
        const fechaStr = c.fechaLimite ? new Date(c.fechaLimite).toLocaleDateString('es-DO', { day: '2-digit', month: 'long', year: 'numeric' }) : 'Sin fecha';

        html += '<div style="background:#fff;border:1.5px solid #E0E0E0;border-radius:12px;padding:14px;display:flex;align-items:center;gap:12px;flex-wrap:wrap;">'
          + '<div style="width:44px;height:44px;border-radius:50%;background:' + estadoColor + '22;display:flex;align-items:center;justify-content:center;">'
          + '<span class="material-icons" style="color:' + estadoColor + ';font-size:22px;">' + estadoIcon + '</span></div>'
          + '<div style="flex:1;min-width:180px;">'
          + '<div style="font-weight:700;font-size:0.95rem;color:#212121;">' + escapeHTML(c.nombre) + '</div>'
          + '<div style="font-size:0.82rem;color:#78909C;">Monto: <strong style="color:#1565C0;">RD$ ' + Number(c.monto || 0).toLocaleString('es-DO') + '</strong></div>'
          + '<div style="font-size:0.78rem;color:#90A4AE;">Fecha límite: ' + fechaStr + '</div>'
          + '</div>'
          + '<div style="display:flex;gap:6px;flex-wrap:wrap;">'
          + '<span style="font-size:0.72rem;padding:3px 10px;border-radius:12px;background:' + estadoColor + '22;color:' + estadoColor + ';font-weight:600;">' + estadoTexto + '</span>'
          + '<button onclick="_pagosEditarConcepto(' + idx + ')" style="padding:4px 10px;background:#E3F2FD;color:#1565C0;border:none;border-radius:6px;font-size:0.78rem;cursor:pointer;">Editar</button>'
          + '<button onclick="_pagosEliminarConcepto(' + idx + ')" style="padding:4px 10px;background:#FFEBEE;color:#C62828;border:none;border-radius:6px;font-size:0.78rem;cursor:pointer;">Eliminar</button>'
          + '</div></div>';
      });
      html += '</div>';
    }
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

function _pagosAgregarConcepto() {
  _pagosMostrarFormConcepto(-1);
}

function _pagosEditarConcepto(idx) {
  _pagosMostrarFormConcepto(idx);
}

function _pagosMostrarFormConcepto(idx) {
  const c = idx >= 0 ? (window._pagosConceptos || [])[idx] : null;
  const titulo = c ? 'Editar Concepto' : 'Nuevo Concepto';

  const modal = document.createElement('div');
  modal.id = 'modal-pago-concepto';
  modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;z-index:10000;padding:16px;';
  modal.innerHTML = '<div style="background:#fff;border-radius:16px;padding:24px;max-width:420px;width:100%;max-height:90vh;overflow-y:auto;">'
    + '<h3 style="margin:0 0 16px;color:#1565C0;display:flex;align-items:center;gap:8px;"><span class="material-icons">receipt_long</span> ' + titulo + '</h3>'
    + '<div style="display:flex;flex-direction:column;gap:12px;">'
    + '<div><label style="font-size:0.82rem;font-weight:600;color:#37474F;display:block;margin-bottom:4px;">Nombre del concepto</label>'
    + '<input id="pago-concepto-nombre" type="text" value="' + escapeHTML(c?.nombre || '') + '" placeholder="Ej: Mensualidad Enero 2026" style="width:100%;padding:10px 12px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.9rem;box-sizing:border-box;"></div>'
    + '<div><label style="font-size:0.82rem;font-weight:600;color:#37474F;display:block;margin-bottom:4px;">Monto (RD$)</label>'
    + '<input id="pago-concepto-monto" type="number" value="' + (c?.monto || '') + '" placeholder="Ej: 5000" min="0" step="100" style="width:100%;padding:10px 12px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.9rem;box-sizing:border-box;"></div>'
    + '<div><label style="font-size:0.82rem;font-weight:600;color:#37474F;display:block;margin-bottom:4px;">Fecha límite</label>'
    + '<input id="pago-concepto-fecha" type="date" value="' + (c?.fechaLimite || '') + '" style="width:100%;padding:10px 12px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.9rem;box-sizing:border-box;"></div>'
    + '<div style="display:flex;align-items:center;gap:8px;">'
    + '<input id="pago-concepto-activo" type="checkbox" ' + (c ? (c.activo ? 'checked' : '') : 'checked') + ' style="width:18px;height:18px;">'
    + '<label style="font-size:0.85rem;color:#37474F;">Activo (visible para padres)</label></div>'
    + '</div>'
    + '<div style="display:flex;gap:8px;margin-top:20px;justify-content:flex-end;">'
    + '<button onclick="document.getElementById(\'modal-pago-concepto\').remove()" style="padding:8px 20px;background:#F5F5F5;color:#616161;border:none;border-radius:8px;font-size:0.85rem;cursor:pointer;">Cancelar</button>'
    + '<button onclick="_pagosGuardarConcepto(' + idx + ')" style="padding:8px 20px;background:#1565C0;color:#fff;border:none;border-radius:8px;font-size:0.85rem;font-weight:600;cursor:pointer;">Guardar</button>'
    + '</div></div>';
  document.body.appendChild(modal);
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
}

async function _pagosGuardarConcepto(idx) {
  const nombre = document.getElementById('pago-concepto-nombre')?.value.trim();
  const monto = parseFloat(document.getElementById('pago-concepto-monto')?.value) || 0;
  const fechaLimite = document.getElementById('pago-concepto-fecha')?.value || '';
  const activo = document.getElementById('pago-concepto-activo')?.checked ?? true;
  if (!nombre) { mostrarToast('Escribe el nombre del concepto', 'error'); return; }
  if (monto <= 0) { mostrarToast('Ingresa un monto válido', 'error'); return; }

  const centroId = _pagosGetCentroId();
  const conceptos = window._pagosConceptos || [];
  const concepto = { nombre, monto, fechaLimite, activo, id: idx >= 0 ? conceptos[idx].id : Date.now().toString(36) + Math.random().toString(36).substr(2, 5) };

  if (idx >= 0) conceptos[idx] = concepto;
  else conceptos.push(concepto);

  try {
    await db.collection('centros').doc(centroId).collection('pagos_config').doc('conceptos').set({ items: conceptos }, { merge: true });
    document.getElementById('modal-pago-concepto')?.remove();
    mostrarToast(idx >= 0 ? 'Concepto actualizado' : 'Concepto agregado', 'success');
    _pagosRenderConceptos();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

async function _pagosEliminarConcepto(idx) {
  const conceptos = window._pagosConceptos || [];
  if (!confirm('¿Eliminar "' + conceptos[idx]?.nombre + '"? Esta acción no se puede deshacer.')) return;
  conceptos.splice(idx, 1);
  const centroId = _pagosGetCentroId();
  try {
    await db.collection('centros').doc(centroId).collection('pagos_config').doc('conceptos').set({ items: conceptos }, { merge: true });
    mostrarToast('Concepto eliminado', 'success');
    _pagosRenderConceptos();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

// ── ESTADO DE PAGOS ─────────────────────────────────────────────

async function _pagosRenderEstado() {
  const cont = document.getElementById('pagos-contenido');
  const centroId = _pagosGetCentroId();
  if (!centroId) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">Selecciona un centro.</div>'; return; }
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Cargando estado de pagos...</div>';

  try {
    // Cargar conceptos
    const confDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('conceptos').get();
    const conceptos = (confDoc.exists ? confDoc.data().items : []) || [];
    if (!conceptos.length) { cont.innerHTML = '<div style="text-align:center;padding:40px;color:#999;"><span class="material-icons" style="font-size:48px;display:block;margin-bottom:8px;">receipt_long</span>No hay conceptos de pago configurados.<br>Ve a la pestaña "Conceptos" para crear uno.</div>'; return; }

    // Cargar pagos registrados y cédulas
    const pagosDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('pagos').get();
    const pagos = (pagosDoc.exists ? pagosDoc.data().registros : []) || [];
    window._pagosRegistros = pagos;

    const cedDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('cedulas').get();
    const cedulas = (cedDoc.exists ? cedDoc.data() : {}) || {};
    window._pagosCedulas = cedulas;

    // Cargar estudiantes de todos los docentes del centro
    const docentes = await _coordGetDocentes(centroId);
    let todosEstudiantes = [];
    await Promise.all(docentes.map(async d => {
      try {
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw.payload ? JSON.parse(calRaw.payload) : calRaw;
        Object.entries(calData.cursos || {}).forEach(([cId, curso]) => {
          (curso.estudiantes || []).forEach(est => {
            if (!todosEstudiantes.find(e => e.id === est.id)) {
              todosEstudiantes.push({ ...est, curso: curso.nombre || cId, docenteUid: d.uid, docenteNombre: d.nombre || d.email });
            }
          });
        });
      } catch {}
    }));
    window._pagosEstudiantes = todosEstudiantes;

    // Selector de concepto
    let html = '<h4 style="color:#1565C0;margin:0 0 14px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">fact_check</span> Estado de Pagos por Estudiante</h4>';
    html += '<div style="margin-bottom:16px;display:flex;gap:10px;align-items:center;flex-wrap:wrap;">'
      + '<select id="pagos-filtro-concepto" onchange="_pagosRenderTablaEstado()" style="padding:8px 12px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.85rem;min-width:200px;">';
    conceptos.forEach((c, i) => { html += '<option value="' + i + '">' + escapeHTML(c.nombre) + ' — RD$ ' + Number(c.monto).toLocaleString('es-DO') + '</option>'; });
    html += '</select>'
      + '<button onclick="_pagosRegistrarPagoManual()" style="padding:8px 16px;background:#2E7D32;color:#fff;border:none;border-radius:8px;font-size:0.82rem;font-weight:600;cursor:pointer;display:flex;align-items:center;gap:4px;">'
      + '<span class="material-icons" style="font-size:16px;">add_card</span> Registrar Pago</button>'
      + '</div>';

    html += '<div id="pagos-tabla-estado"></div>';
    cont.innerHTML = html;
    _pagosRenderTablaEstado();
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

function _pagosRenderTablaEstado() {
  const cont = document.getElementById('pagos-tabla-estado');
  if (!cont) return;
  const conceptoIdx = parseInt(document.getElementById('pagos-filtro-concepto')?.value || '0');
  const conceptos = window._pagosConceptos || [];
  const concepto = conceptos[conceptoIdx];
  if (!concepto) return;

  const pagos = window._pagosRegistros || [];
  const estudiantes = window._pagosEstudiantes || [];
  const hoy = new Date();
  const vencido = concepto.fechaLimite && new Date(concepto.fechaLimite) < hoy;

  // Contar estados
  let pagados = 0, pendientes = 0, vencidos = 0, totalRecaudado = 0;
  const estConEstado = estudiantes.map(est => {
    const pago = pagos.find(p => p.estudianteId === est.id && p.conceptoId === concepto.id);
    let estado, color;
    if (pago) { estado = 'Pagado'; color = '#2E7D32'; pagados++; totalRecaudado += pago.monto || concepto.monto; }
    else if (vencido) { estado = 'Vencido'; color = '#C62828'; vencidos++; }
    else { estado = 'Pendiente'; color = '#FF9800'; pendientes++; }
    return { ...est, pago, estado, color };
  });

  let html = '';
  // KPIs
  html += '<div style="display:flex;gap:10px;margin-bottom:16px;flex-wrap:wrap;">'
    + '<div style="flex:1;min-width:110px;background:#E8F5E9;border:1.5px solid #A5D6A7;border-radius:10px;padding:12px;text-align:center;">'
    + '<div style="font-size:1.3rem;font-weight:700;color:#2E7D32;">' + pagados + '</div><div style="font-size:0.75rem;color:#388E3C;">Pagados</div></div>'
    + '<div style="flex:1;min-width:110px;background:#FFF3E0;border:1.5px solid #FFB74D;border-radius:10px;padding:12px;text-align:center;">'
    + '<div style="font-size:1.3rem;font-weight:700;color:#E65100;">' + pendientes + '</div><div style="font-size:0.75rem;color:#E65100;">Pendientes</div></div>'
    + '<div style="flex:1;min-width:110px;background:#FFEBEE;border:1.5px solid #EF9A9A;border-radius:10px;padding:12px;text-align:center;">'
    + '<div style="font-size:1.3rem;font-weight:700;color:#C62828;">' + vencidos + '</div><div style="font-size:0.75rem;color:#C62828;">Vencidos</div></div>'
    + '<div style="flex:1;min-width:110px;background:#E3F2FD;border:1.5px solid #90CAF9;border-radius:10px;padding:12px;text-align:center;">'
    + '<div style="font-size:1.1rem;font-weight:700;color:#1565C0;">RD$ ' + totalRecaudado.toLocaleString('es-DO') + '</div><div style="font-size:0.75rem;color:#1565C0;">Recaudado</div></div>'
    + '</div>';

  if (!estudiantes.length) {
    html += '<div style="text-align:center;padding:30px;color:#9E9E9E;">No hay estudiantes registrados en este centro.</div>';
  } else {
    // Tabla
    const cedulas = window._pagosCedulas || {};
    html += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:0.82rem;">'
      + '<thead><tr style="background:#E3F2FD;">'
      + '<th style="text-align:left;padding:8px;border:1px solid #BBDEFB;">Estudiante</th>'
      + '<th style="text-align:left;padding:8px;border:1px solid #BBDEFB;">Curso</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Cédula Padre</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Monto</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Estado</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Fecha Pago</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Referencia</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Acción</th>'
      + '</tr></thead><tbody>';

    estConEstado.forEach(est => {
      const fechaPago = est.pago ? new Date(est.pago.fecha).toLocaleDateString('es-DO') : '—';
      const ref = est.pago?.referencia || '—';
      const cedula = cedulas[est.id] || '';
      html += '<tr style="background:' + est.color + '08;">'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;font-weight:500;">' + escapeHTML(est.nombre) + '</td>'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;font-size:0.78rem;color:#546E7A;">' + escapeHTML(est.curso) + '</td>'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;text-align:center;">'
        + '<input type="text" value="' + escapeHTML(cedula) + '" placeholder="000-0000000-0"'
        + ' onchange="_pagosGuardarCedula(\'' + est.id + '\',this.value)"'
        + ' style="width:110px;padding:3px 6px;border:1px solid #CFD8DC;border-radius:4px;font-size:0.78rem;text-align:center;">'
        + '</td>'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;text-align:center;">RD$ ' + Number(concepto.monto).toLocaleString('es-DO') + '</td>'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;text-align:center;"><span style="padding:2px 10px;border-radius:10px;background:' + est.color + '22;color:' + est.color + ';font-weight:600;font-size:0.75rem;">' + est.estado + '</span></td>'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;text-align:center;font-size:0.78rem;">' + fechaPago + '</td>'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;text-align:center;font-size:0.78rem;">' + escapeHTML(ref) + '</td>'
        + '<td style="padding:6px 8px;border:1px solid #E0E0E0;text-align:center;">';
      if (est.pago) {
        html += '<button onclick="_pagosAnularPago(\'' + est.id + '\',\'' + concepto.id + '\')" style="padding:3px 8px;background:#FFEBEE;color:#C62828;border:none;border-radius:4px;font-size:0.72rem;cursor:pointer;">Anular</button>';
      } else {
        html += '<button onclick="_pagosMarcarPagado(\'' + est.id + '\',\'' + concepto.id + '\',' + concepto.monto + ')" style="padding:3px 8px;background:#E8F5E9;color:#2E7D32;border:none;border-radius:4px;font-size:0.72rem;cursor:pointer;">Marcar Pagado</button>';
      }
      html += '</td></tr>';
    });
    html += '</tbody></table></div>';
  }
  cont.innerHTML = html;
}

async function _pagosMarcarPagado(estId, conceptoId, monto) {
  const ref = prompt('Referencia del pago (recibo, transferencia, etc.):');
  if (ref === null) return;
  const centroId = _pagosGetCentroId();
  const pagos = window._pagosRegistros || [];
  pagos.push({ estudianteId: estId, conceptoId, monto, fecha: new Date().toISOString(), referencia: ref || '', registradoPor: window.currentUser?.email || '' });
  try {
    await db.collection('centros').doc(centroId).collection('pagos_config').doc('pagos').set({ registros: pagos }, { merge: true });
    window._pagosRegistros = pagos;
    mostrarToast('Pago registrado', 'success');
    _pagosRenderTablaEstado();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

async function _pagosAnularPago(estId, conceptoId) {
  if (!confirm('¿Anular este pago?')) return;
  const centroId = _pagosGetCentroId();
  let pagos = window._pagosRegistros || [];
  pagos = pagos.filter(p => !(p.estudianteId === estId && p.conceptoId === conceptoId));
  try {
    await db.collection('centros').doc(centroId).collection('pagos_config').doc('pagos').set({ registros: pagos }, { merge: true });
    window._pagosRegistros = pagos;
    mostrarToast('Pago anulado', 'success');
    _pagosRenderTablaEstado();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

function _pagosRegistrarPagoManual() {
  const estudiantes = window._pagosEstudiantes || [];
  if (!estudiantes.length) { mostrarToast('No hay estudiantes registrados', 'error'); return; }
  const conceptoIdx = parseInt(document.getElementById('pagos-filtro-concepto')?.value || '0');
  const concepto = (window._pagosConceptos || [])[conceptoIdx];
  if (!concepto) return;

  const modal = document.createElement('div');
  modal.id = 'modal-pago-manual';
  modal.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.5);display:flex;align-items:center;justify-content:center;z-index:10000;padding:16px;';
  let optsHtml = '';
  const pagos = window._pagosRegistros || [];
  const sinPagar = estudiantes.filter(e => !pagos.find(p => p.estudianteId === e.id && p.conceptoId === concepto.id));
  sinPagar.forEach(e => { optsHtml += '<option value="' + e.id + '">' + escapeHTML(e.nombre) + ' — ' + escapeHTML(e.curso) + '</option>'; });

  modal.innerHTML = '<div style="background:#fff;border-radius:16px;padding:24px;max-width:420px;width:100%;max-height:90vh;overflow-y:auto;">'
    + '<h3 style="margin:0 0 16px;color:#2E7D32;display:flex;align-items:center;gap:8px;"><span class="material-icons">add_card</span> Registrar Pago</h3>'
    + '<div style="font-size:0.85rem;color:#78909C;margin-bottom:12px;">Concepto: <strong>' + escapeHTML(concepto.nombre) + '</strong> — RD$ ' + Number(concepto.monto).toLocaleString('es-DO') + '</div>'
    + '<div style="display:flex;flex-direction:column;gap:12px;">'
    + '<div><label style="font-size:0.82rem;font-weight:600;color:#37474F;display:block;margin-bottom:4px;">Estudiante</label>'
    + '<select id="pago-manual-est" style="width:100%;padding:10px 12px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.9rem;box-sizing:border-box;">'
    + (sinPagar.length ? optsHtml : '<option value="">Todos han pagado</option>') + '</select></div>'
    + '<div><label style="font-size:0.82rem;font-weight:600;color:#37474F;display:block;margin-bottom:4px;">Referencia (recibo, transferencia)</label>'
    + '<input id="pago-manual-ref" type="text" placeholder="Ej: Recibo #1234" style="width:100%;padding:10px 12px;border:1.5px solid #CFD8DC;border-radius:8px;font-size:0.9rem;box-sizing:border-box;"></div>'
    + '</div>'
    + '<div style="display:flex;gap:8px;margin-top:20px;justify-content:flex-end;">'
    + '<button onclick="document.getElementById(\'modal-pago-manual\').remove()" style="padding:8px 20px;background:#F5F5F5;color:#616161;border:none;border-radius:8px;font-size:0.85rem;cursor:pointer;">Cancelar</button>'
    + '<button onclick="_pagosConfirmarManual(\'' + concepto.id + '\',' + concepto.monto + ')" style="padding:8px 20px;background:#2E7D32;color:#fff;border:none;border-radius:8px;font-size:0.85rem;font-weight:600;cursor:pointer;"' + (sinPagar.length ? '' : ' disabled') + '>Confirmar Pago</button>'
    + '</div></div>';
  document.body.appendChild(modal);
  modal.addEventListener('click', e => { if (e.target === modal) modal.remove(); });
}

async function _pagosConfirmarManual(conceptoId, monto) {
  const estId = document.getElementById('pago-manual-est')?.value;
  const ref = document.getElementById('pago-manual-ref')?.value || '';
  if (!estId) { mostrarToast('Selecciona un estudiante', 'error'); return; }
  const centroId = _pagosGetCentroId();
  const pagos = window._pagosRegistros || [];
  pagos.push({ estudianteId: estId, conceptoId, monto, fecha: new Date().toISOString(), referencia: ref, registradoPor: window.currentUser?.email || '' });
  try {
    await db.collection('centros').doc(centroId).collection('pagos_config').doc('pagos').set({ registros: pagos }, { merge: true });
    window._pagosRegistros = pagos;
    document.getElementById('modal-pago-manual')?.remove();
    mostrarToast('Pago registrado', 'success');
    _pagosRenderTablaEstado();
  } catch (e) { mostrarToast('Error: ' + e.message, 'error'); }
}

// ── REPORTES DE PAGOS ───────────────────────────────────────────

async function _pagosRenderReportes() {
  const cont = document.getElementById('pagos-contenido');
  const centroId = _pagosGetCentroId();
  if (!centroId) { cont.innerHTML = '<div style="text-align:center;padding:30px;color:#999;">Selecciona un centro.</div>'; return; }
  cont.innerHTML = '<div style="text-align:center;padding:30px;"><span class="material-icons" style="animation:spin 1s linear infinite;">sync</span> Generando reportes...</div>';

  try {
    const confDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('conceptos').get();
    const conceptos = (confDoc.exists ? confDoc.data().items : []) || [];
    const pagosDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('pagos').get();
    const pagos = (pagosDoc.exists ? pagosDoc.data().registros : []) || [];

    // Cargar estudiantes
    const docentes = await _coordGetDocentes(centroId);
    let totalEst = 0;
    await Promise.all(docentes.map(async d => {
      try {
        const calDoc = await db.collection('users').doc(d.uid).collection('data').doc('calificaciones').get();
        const calRaw = calDoc.exists ? calDoc.data() : {};
        const calData = calRaw.payload ? JSON.parse(calRaw.payload) : calRaw;
        Object.values(calData.cursos || {}).forEach(curso => { totalEst += (curso.estudiantes || []).length; });
      } catch {}
    }));

    let html = '<h4 style="color:#1565C0;margin:0 0 16px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">bar_chart</span> Reportes de Pagos</h4>';

    if (!conceptos.length) {
      html += '<div style="text-align:center;padding:40px;color:#9E9E9E;">No hay conceptos de pago configurados.</div>';
      cont.innerHTML = html;
      return;
    }

    // Resumen general
    let totalEsperado = 0, totalRecaudado = 0;
    const resumenConceptos = conceptos.map(c => {
      const pagosCon = pagos.filter(p => p.conceptoId === c.id);
      const recaudado = pagosCon.reduce((sum, p) => sum + (p.monto || c.monto), 0);
      const esperado = totalEst * c.monto;
      totalEsperado += esperado;
      totalRecaudado += recaudado;
      const pct = esperado > 0 ? Math.round((recaudado / esperado) * 100) : 0;
      return { ...c, pagados: pagosCon.length, recaudado, esperado, pct };
    });

    // KPIs generales
    const pctGeneral = totalEsperado > 0 ? Math.round((totalRecaudado / totalEsperado) * 100) : 0;
    html += '<div style="display:flex;gap:10px;margin-bottom:20px;flex-wrap:wrap;">'
      + '<div style="flex:1;min-width:140px;background:#E3F2FD;border:1.5px solid #90CAF9;border-radius:10px;padding:14px;text-align:center;">'
      + '<div style="font-size:1.5rem;font-weight:700;color:#1565C0;">RD$ ' + totalRecaudado.toLocaleString('es-DO') + '</div><div style="font-size:0.78rem;color:#1565C0;">Total Recaudado</div></div>'
      + '<div style="flex:1;min-width:140px;background:#F5F5F5;border:1.5px solid #E0E0E0;border-radius:10px;padding:14px;text-align:center;">'
      + '<div style="font-size:1.5rem;font-weight:700;color:#616161;">RD$ ' + totalEsperado.toLocaleString('es-DO') + '</div><div style="font-size:0.78rem;color:#616161;">Total Esperado</div></div>'
      + '<div style="flex:1;min-width:140px;background:' + (pctGeneral >= 70 ? '#E8F5E9' : pctGeneral >= 40 ? '#FFF3E0' : '#FFEBEE') + ';border:1.5px solid ' + (pctGeneral >= 70 ? '#A5D6A7' : pctGeneral >= 40 ? '#FFB74D' : '#EF9A9A') + ';border-radius:10px;padding:14px;text-align:center;">'
      + '<div style="font-size:1.5rem;font-weight:700;color:' + (pctGeneral >= 70 ? '#2E7D32' : pctGeneral >= 40 ? '#E65100' : '#C62828') + ';">' + pctGeneral + '%</div><div style="font-size:0.78rem;color:#616161;">Recaudación</div></div>'
      + '</div>';

    // Tabla por concepto
    html += '<div style="overflow-x:auto;"><table style="width:100%;border-collapse:collapse;font-size:0.85rem;">'
      + '<thead><tr style="background:#E3F2FD;">'
      + '<th style="text-align:left;padding:8px;border:1px solid #BBDEFB;">Concepto</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Monto</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Pagados</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Recaudado</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">Esperado</th>'
      + '<th style="padding:8px;border:1px solid #BBDEFB;text-align:center;">%</th>'
      + '</tr></thead><tbody>';

    resumenConceptos.forEach(c => {
      const barColor = c.pct >= 70 ? '#4CAF50' : c.pct >= 40 ? '#FF9800' : '#F44336';
      html += '<tr><td style="padding:8px;border:1px solid #E0E0E0;font-weight:500;">' + escapeHTML(c.nombre) + '</td>'
        + '<td style="padding:8px;border:1px solid #E0E0E0;text-align:center;">RD$ ' + Number(c.monto).toLocaleString('es-DO') + '</td>'
        + '<td style="padding:8px;border:1px solid #E0E0E0;text-align:center;">' + c.pagados + '/' + totalEst + '</td>'
        + '<td style="padding:8px;border:1px solid #E0E0E0;text-align:center;font-weight:600;color:#1565C0;">RD$ ' + c.recaudado.toLocaleString('es-DO') + '</td>'
        + '<td style="padding:8px;border:1px solid #E0E0E0;text-align:center;color:#78909C;">RD$ ' + c.esperado.toLocaleString('es-DO') + '</td>'
        + '<td style="padding:8px;border:1px solid #E0E0E0;text-align:center;">'
        + '<div style="background:#E0E0E0;border-radius:8px;height:18px;overflow:hidden;min-width:60px;">'
        + '<div style="background:' + barColor + ';height:100%;width:' + c.pct + '%;border-radius:8px;display:flex;align-items:center;justify-content:center;">'
        + '<span style="font-size:0.68rem;color:#fff;font-weight:700;">' + c.pct + '%</span></div></div></td></tr>';
    });
    html += '</tbody></table></div>';

    // Estudiantes morosos (más conceptos vencidos sin pagar)
    if (window._pagosEstudiantes) {
      const estMorosos = [];
      window._pagosEstudiantes.forEach(est => {
        let deuda = 0, conceptosDeuda = 0;
        conceptos.forEach(c => {
          if (!c.activo) return;
          const vencido = c.fechaLimite && new Date(c.fechaLimite) < new Date();
          const pagado = pagos.find(p => p.estudianteId === est.id && p.conceptoId === c.id);
          if (!pagado && vencido) { deuda += c.monto; conceptosDeuda++; }
        });
        if (conceptosDeuda > 0) estMorosos.push({ ...est, deuda, conceptosDeuda });
      });
      estMorosos.sort((a, b) => b.deuda - a.deuda);

      if (estMorosos.length) {
        html += '<h4 style="color:#C62828;margin:20px 0 10px;display:flex;align-items:center;gap:6px;"><span class="material-icons" style="font-size:20px;">warning</span> Estudiantes con pagos vencidos (' + estMorosos.length + ')</h4>';
        html += '<div style="display:flex;flex-direction:column;gap:6px;">';
        estMorosos.slice(0, 20).forEach(est => {
          html += '<div style="background:#FFEBEE;border:1px solid #EF9A9A;border-radius:8px;padding:10px 14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px;">'
            + '<div><strong style="color:#212121;">' + escapeHTML(est.nombre) + '</strong> <span style="font-size:0.78rem;color:#78909C;">— ' + escapeHTML(est.curso) + '</span></div>'
            + '<div style="font-weight:700;color:#C62828;">' + est.conceptosDeuda + ' concepto(s) · RD$ ' + est.deuda.toLocaleString('es-DO') + '</div>'
            + '</div>';
        });
        html += '</div>';
      }
    }

    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:20px;color:#C62828;">Error: ' + e.message + '</div>';
  }
}

// ── Guardar cédula del padre ─────────────────────────────────────

async function _pagosGuardarCedula(estId, cedula) {
  const centroId = _pagosGetCentroId();
  if (!centroId) return;
  const cedulas = window._pagosCedulas || {};
  const val = cedula.replace(/[^0-9-]/g, '').trim();
  if (val) cedulas[estId] = val;
  else delete cedulas[estId];
  window._pagosCedulas = cedulas;
  try {
    await db.collection('centros').doc(centroId).collection('pagos_config').doc('cedulas').set(cedulas);
  } catch (e) { console.warn('Error guardando cédula:', e); }
}

// ── VISTA PÚBLICA PARA PADRES ───────────────────────────────────

function _pagosIniciarVistaPublica() {
  // Ocultar todo y mostrar la vista de consulta de pagos
  const app = document.getElementById('app-container') || document.body;
  let overlay = document.getElementById('pagos-publico-overlay');
  if (overlay) { overlay.remove(); return; }

  overlay = document.createElement('div');
  overlay.id = 'pagos-publico-overlay';
  overlay.style.cssText = 'position:fixed;top:0;left:0;right:0;bottom:0;background:linear-gradient(135deg,#1565C0 0%,#0D47A1 100%);z-index:99999;overflow-y:auto;display:flex;flex-direction:column;align-items:center;padding:20px;';
  overlay.innerHTML = '<div style="max-width:500px;width:100%;margin:auto;">'
    + '<div style="text-align:center;margin-bottom:30px;">'
    + '<span class="material-icons" style="font-size:56px;color:#fff;margin-bottom:8px;">payments</span>'
    + '<h1 style="color:#fff;margin:0;font-size:1.5rem;">Consulta de Pagos</h1>'
    + '<p style="color:rgba(255,255,255,0.8);font-size:0.85rem;margin:6px 0 0;">Ingresa la cédula del padre/madre para consultar el estado de pagos</p>'
    + '</div>'
    + '<div style="background:#fff;border-radius:16px;padding:24px;box-shadow:0 8px 32px rgba(0,0,0,0.2);">'
    + '<div style="margin-bottom:16px;">'
    + '<label style="font-size:0.85rem;font-weight:600;color:#37474F;display:block;margin-bottom:6px;">Cédula del Padre/Madre</label>'
    + '<input id="pagos-pub-cedula" type="text" placeholder="000-0000000-0" maxlength="13"'
    + ' style="width:100%;padding:14px 16px;border:2px solid #1565C0;border-radius:10px;font-size:1.1rem;text-align:center;letter-spacing:1px;box-sizing:border-box;"'
    + ' onkeyup="if(event.key===\'Enter\')_pagosConsultarPublico()">'
    + '</div>'
    + '<button onclick="_pagosConsultarPublico()" style="width:100%;padding:14px;background:#1565C0;color:#fff;border:none;border-radius:10px;font-size:1rem;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;">'
    + '<span class="material-icons">search</span> Consultar</button>'
    + '<div id="pagos-pub-resultado" style="margin-top:20px;"></div>'
    + '</div>'
    + '</div>';
  document.body.appendChild(overlay);
  document.getElementById('pagos-pub-cedula')?.focus();
}

async function _pagosConsultarPublico() {
  const cedula = (document.getElementById('pagos-pub-cedula')?.value || '').replace(/[^0-9-]/g, '').trim();
  const cont = document.getElementById('pagos-pub-resultado');
  if (!cont) return;
  if (!cedula || cedula.length < 5) { cont.innerHTML = '<div style="text-align:center;padding:12px;color:#C62828;font-size:0.85rem;">Ingresa una cédula válida.</div>'; return; }
  cont.innerHTML = '<div style="text-align:center;padding:20px;"><span class="material-icons" style="animation:spin 1s linear infinite;color:#1565C0;">sync</span><div style="font-size:0.85rem;color:#78909C;margin-top:6px;">Buscando...</div></div>';

  try {
    // Buscar en todos los centros la cédula
    const centrosSnap = await db.collection('centros').get();
    let resultados = [];

    for (const centroDoc of centrosSnap.docs) {
      const centroId = centroDoc.id;
      const centroNombre = centroDoc.data().nombre || centroId;

      // Cargar cédulas de este centro
      const cedDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('cedulas').get();
      if (!cedDoc.exists) continue;
      const cedulas = cedDoc.data() || {};

      // Buscar estudiantes con esta cédula
      const estIds = Object.entries(cedulas).filter(([_, ced]) => ced === cedula).map(([id]) => id);
      if (!estIds.length) continue;

      // Cargar conceptos y pagos
      const confDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('conceptos').get();
      const conceptos = (confDoc.exists ? confDoc.data().items : []) || [];
      const pagosDoc = await db.collection('centros').doc(centroId).collection('pagos_config').doc('pagos').get();
      const pagos = (pagosDoc.exists ? pagosDoc.data().registros : []) || [];

      // Buscar nombres de estudiantes en calificaciones de docentes
      const docentesSnap = await db.collection('usuarios').where('centroId', '==', centroId).get();
      const nombres = {};
      for (const dDoc of docentesSnap.docs) {
        try {
          const calDoc = await db.collection('users').doc(dDoc.id).collection('data').doc('calificaciones').get();
          const calRaw = calDoc.exists ? calDoc.data() : {};
          const calData = calRaw.payload ? JSON.parse(calRaw.payload) : calRaw;
          Object.values(calData.cursos || {}).forEach(curso => {
            (curso.estudiantes || []).forEach(est => {
              if (estIds.includes(est.id)) nombres[est.id] = { nombre: est.nombre, curso: curso.nombre };
            });
          });
        } catch {}
      }

      estIds.forEach(estId => {
        const info = nombres[estId] || { nombre: 'Estudiante', curso: '' };
        const pagosEst = conceptos.filter(c => c.activo).map(c => {
          const pago = pagos.find(p => p.estudianteId === estId && p.conceptoId === c.id);
          const vencido = c.fechaLimite && new Date(c.fechaLimite) < new Date();
          return { concepto: c.nombre, monto: c.monto, fechaLimite: c.fechaLimite, pagado: !!pago, fechaPago: pago?.fecha, referencia: pago?.referencia, vencido };
        });
        resultados.push({ centroNombre, nombre: info.nombre, curso: info.curso, pagos: pagosEst });
      });
    }

    if (!resultados.length) {
      cont.innerHTML = '<div style="text-align:center;padding:20px;color:#78909C;">'
        + '<span class="material-icons" style="font-size:40px;display:block;margin-bottom:8px;color:#BDBDBD;">person_off</span>'
        + 'No se encontraron estudiantes asociados a esta cédula.<br>'
        + '<span style="font-size:0.78rem;">Verifica que la cédula esté registrada en el sistema.</span></div>';
      return;
    }

    let html = '';
    resultados.forEach(r => {
      const totalPendiente = r.pagos.filter(p => !p.pagado).reduce((s, p) => s + p.monto, 0);
      html += '<div style="margin-bottom:16px;border:1.5px solid #E0E0E0;border-radius:12px;overflow:hidden;">'
        + '<div style="background:#E3F2FD;padding:12px 16px;">'
        + '<div style="font-weight:700;font-size:1rem;color:#1565C0;">' + escapeHTML(r.nombre) + '</div>'
        + '<div style="font-size:0.82rem;color:#546E7A;">' + escapeHTML(r.centroNombre) + (r.curso ? ' — ' + escapeHTML(r.curso) : '') + '</div>'
        + (totalPendiente > 0 ? '<div style="font-size:0.85rem;font-weight:600;color:#C62828;margin-top:4px;">Pendiente: RD$ ' + totalPendiente.toLocaleString('es-DO') + '</div>' : '<div style="font-size:0.85rem;font-weight:600;color:#2E7D32;margin-top:4px;">Al día</div>')
        + '</div>';

      html += '<div style="padding:0;">';
      r.pagos.forEach(p => {
        let color, icon, estado;
        if (p.pagado) { color = '#2E7D32'; icon = 'check_circle'; estado = 'Pagado'; }
        else if (p.vencido) { color = '#C62828'; icon = 'error'; estado = 'Vencido'; }
        else { color = '#FF9800'; icon = 'schedule'; estado = 'Pendiente'; }
        const fechaLim = p.fechaLimite ? new Date(p.fechaLimite).toLocaleDateString('es-DO', { day: '2-digit', month: 'short', year: 'numeric' }) : '';

        html += '<div style="padding:10px 16px;border-bottom:1px solid #F5F5F5;display:flex;align-items:center;gap:10px;">'
          + '<span class="material-icons" style="color:' + color + ';font-size:20px;">' + icon + '</span>'
          + '<div style="flex:1;">'
          + '<div style="font-weight:600;font-size:0.85rem;color:#212121;">' + escapeHTML(p.concepto) + '</div>'
          + '<div style="font-size:0.75rem;color:#90A4AE;">' + (fechaLim ? 'Límite: ' + fechaLim : '') + '</div>'
          + '</div>'
          + '<div style="text-align:right;">'
          + '<div style="font-weight:700;font-size:0.9rem;color:#212121;">RD$ ' + Number(p.monto).toLocaleString('es-DO') + '</div>'
          + '<span style="font-size:0.72rem;padding:2px 8px;border-radius:8px;background:' + color + '22;color:' + color + ';font-weight:600;">' + estado + '</span>'
          + '</div></div>';
      });
      html += '</div></div>';
    });
    cont.innerHTML = html;
  } catch (e) {
    cont.innerHTML = '<div style="text-align:center;padding:12px;color:#C62828;">Error al consultar: ' + e.message + '</div>';
  }
}

// ── Detectar hash para vista pública de pagos ───────────────────
if (window.location.hash === '#pagos' || window.location.hash === '#pagos-consulta') {
  window.addEventListener('DOMContentLoaded', () => setTimeout(_pagosIniciarVistaPublica, 500));
}
window.addEventListener('hashchange', () => {
  if (window.location.hash === '#pagos' || window.location.hash === '#pagos-consulta') _pagosIniciarVistaPublica();
});

// ── Agregar verificación de pagos al dashboard ──────────────────

const _origRenderDashboardPagos = renderizarDashboard;
renderizarDashboard = function() {
  _origRenderDashboardPagos();
  _verificarAccesoPagos();
};

